window.QA_BANK = {"generated":"2026-09-23","subjects":{"solvency":{"name":"偿付能力监管规则","short":"偿付能力","icon":"🛡️","units":[{"id":"rule-01","group":"监管规则","name":"第1号 保险公司偿付能力监管规则第1号：实际资本","qa":[{"id":"qa-01-01","difficulty":1,"q":"简述实际资本的定义，写出其计算口径，并说明实际资本评估应以何种财务报表为基础。","answer_points":[{"point":"实际资本的定义","detail":"实际资本是保险公司在持续经营或破产清算状态下可以吸收损失的财务资源，是监管衡量资本实力的核心口径。"},{"point":"计算口径","detail":"实际资本＝认可资产－认可负债，即二者余额之差，而非简单的净资产或所有者权益。"},{"point":"评估基础","detail":"实际资本评估以母公司财务报表而不以合并财务报表为基础，确保资本计量聚焦于法律主体本身。"},{"point":"适用范围","detail":"适用于境内设立的经营商业保险业务的保险公司、外国保险公司分公司以及相互保险组织。"},{"point":"监管目的","detail":"银保监会按资本吸收损失的性质与能力实行分级监管，要求公司准确计量各级资本、优化资本结构、提高资本质量。"},{"point":"评估一致性","detail":"资产与负债的评估原则应当一致，防止通过计量方法差异人为调节实际资本。"}],"framework":"定义→计算公式→评估基础→适用范围→监管目的。","memo":"记“母表、认可资产减认可负债、分级监管”。","tag":""},{"id":"qa-01-02","difficulty":1,"q":"说明认可资产与非认可资产的划分标准，并列举几项典型非认可资产（注意易错项）。","answer_points":[{"point":"划分标准","detail":"处置不受限制且可用于履行对保单持有人赔付义务的资产为认可资产；不符合前述条件的为非认可资产。"},{"point":"典型非认可资产（无形资产）","detail":"无形资产属于非认可资产，但土地使用权除外，土地使用权仍属认可资产，这是高频易错点。"},{"point":"递延所得税资产","detail":"由经营性亏损引起的递延所得税资产为非认可资产；非经营亏损引起的递延所得税资产属认可资产。"},{"point":"待摊及实物类","detail":"待摊费用和长期待摊费用、文物艺术作品和动植物标本等通常列为非认可资产。"},{"point":"处置受限资产","detail":"被依法冻结、为他人担保被质押抵押、因交易对手财务危机或当地管制导致处置受限的资产为非认可资产。"},{"point":"监管逻辑","detail":"非认可资产不能用于吸收保单持有人损失，剔除它们可防止高估资本、虚增偿付能力。"}],"framework":"标准→列举典型项→易错反例→监管逻辑。","memo":"“土地使用权认、经营亏损递延不认”。","tag":""},{"id":"qa-01-03","difficulty":2,"q":"说明保险公司资本应当符合的五项特性。","answer_points":[{"point":"存在性","detail":"资本必须真实存在、确属公司自有，不能虚假设计或重复确认。"},{"point":"永续性","detail":"资本应具有持续吸收损失的能力，如核心二级资本工具期限不低于10年、发行5年后方可赎回。"},{"point":"次级性","detail":"资本的清偿顺序应次于普通债务，体现其吸收损失的兜底属性。"},{"point":"非强制性","detail":"资本的获取不以强制摊派为前提，应基于市场化或契约化安排。"},{"point":"外生性","detail":"资本来源于公司外部而非经营活动中自然产生，确保损失吸收独立于日常盈利。"},{"point":"实务衔接","detail":"五项特性是判断一项工具能否计入实际资本及计入哪一级资本的基础门槛。"}],"framework":"五项特性逐一释义→与资本分级的衔接。","memo":"“存、永、次、非、外”五字记忆。","tag":""},{"id":"qa-01-04","difficulty":2,"q":"对比核心资本与附属资本在吸收损失能力上的差异，并说明实际资本的四级分类。","answer_points":[{"point":"核心资本定义","detail":"核心资本在持续经营状态和破产清算状态下均可以吸收损失，是质量最高的资本。"},{"point":"附属资本定义","detail":"附属资本仅在破产清算状态下可以吸收损失，持续经营时不能吸收损失，质量次之。"},{"point":"四级分类","detail":"实际资本分为核心一级资本、核心二级资本、附属一级资本、附属二级资本四个层级。"},{"point":"质量排序","detail":"核心一级＞核心二级＞附属一级＞附属二级，层级越高吸收损失的能力越稳健。"},{"point":"实务含义","detail":"分级直接决定核心偿付能力充足率与综合偿付能力充足率的口径及各类资本限额约束。"}],"framework":"定义对比→四级分类→质量排序→实务含义。","memo":"“核心两端都吸收、附属只在清算吸收”。","tag":""},{"id":"qa-01-05","difficulty":2,"q":"说明各级资本限额标准的四项比例及其监管意图。","answer_points":[{"point":"附属资本限额","detail":"附属资本不得超过核心资本的100%，防止低质量资本过度堆叠。"},{"point":"保单未来盈余限额","detail":"计入核心资本的保单未来盈余不得超过核心资本的35%，限制预期盈余对核心资本的贡献。"},{"point":"核心二级资本限额","detail":"核心二级资本不得超过核心资本的30%，约束较次级的核心资本占比。"},{"point":"附属二级资本限额","detail":"附属二级资本不得超过核心资本的25%，为最弱资本设上限。"},{"point":"超限处理","detail":"各级资本工具余额超过限额的，应确认为资本性负债，以超过限额的金额作为该负债的认可价值。"},{"point":"监管意图","detail":"通过比例上限保证资本结构的真实损失吸收能力，避免以低质量、预期性资本虚增偿付能力。"}],"framework":"四比例→超限处理→监管意图。","memo":"“附100、保35、核二30、附二25”。","tag":""},{"id":"qa-01-06","difficulty":3,"q":"综合分析保单未来盈余的资本分级规则，并说明其为负值时的处理。","answer_points":[{"point":"30年（含）以上档","detail":"按核心一级资本报酬率折现的现值计入核心一级资本，剩余部分作为附属一级资本工具。"},{"point":"10年（含）至30年档","detail":"折现现值作为核心二级资本工具，剩余部分作为附属一级资本工具。"},{"point":"5年（含）至10年档","detail":"折现现值作为附属一级资本工具，剩余部分作为附属二级资本工具。"},{"point":"5年以内档","detail":"保单剩余期限在5年以内的，保单未来盈余全部作为附属二级资本工具。"},{"point":"整体负值处理","detail":"保单未来盈余小于零的，应当直接调减核心一级资本，而非计入其他层级。"},{"point":"分组负值冲减","detail":"分组未来盈余小于零的折现前按零取值，先冲减30年（含）以上组，不足再冲减核心一级资本。"},{"point":"监管逻辑","detail":"期限越长、越稳定，资本质量越高，故长期盈余可计入更高质量的核心资本，体现审慎原则。"}],"framework":"四档期限分级→负值处理→监管逻辑。","memo":"“30核一/10核二/5附一/5内附二；负调核一”。","tag":""},{"id":"qa-01-07","difficulty":3,"q":"分析长期寿险再保险对实际资本确认与资本分级的影响条件。","answer_points":[{"point":"终止期限条件","detail":"再保险合同3年内可终止的，不得确认该再保险合同对实际资本的影响金额，防止短期安排虚增资本。"},{"point":"风险真实转移","detail":"原保险合同相关的保险风险、市场风险、信用风险等部分或全部从分出人真实转移给分入人。"},{"point":"资产真实转移","detail":"分出保费现金流真实转入分入人，且未通过佣金手续费大比例返还、存入履约保证金等方式转回。"},{"point":"资产真实转移时的分级","detail":"3年后方可终止且风险与资产真实转移的，增加的资本计入核心一级资本。"},{"point":"资产未真实转移时的分级","detail":"期限10年（含）以上、5年后方可终止的计入核心二级资本；5年（含）以上10年以内的计入附属一级资本。"},{"point":"递延支付限制","detail":"分出保费递延支付的，递延支付期限不应超过6个月，避免现金流名转实留。"},{"point":"监管逻辑","detail":"强调真实风险转移与期限约束，防止通过再保险安排人为抬高实际资本、粉饰偿付能力。"}],"framework":"终止条件→真实转移双标准→资本分级→递延限制→监管逻辑。","memo":"“3年不可终止；真转移核一、未转移核二/附一；递延≤6月”。","tag":""}],"calc":[{"id":"c-01-01","difficulty":1,"stem":"某寿险公司全部寿险业务现金价值CV为1500万元，寿险业务保险合同负债PL为1000万元，最低资本MC为350万元。请计算现金价值保证的认可价值（万元）。","blanks":[{"label":"现金价值保证的认可价值(万元)","answer":150,"tolerance":0.5}],"steps":["第1步：列示公式：现金价值保证的认可价值＝Max（CV－PL－MC，0）。","第2步：代入数据：Max（1500－1000－350，0）＝Max（150，0）。","第3步：结果取150万元。"],"formula_card":"Max（CV－PL－MC，0）","analysis":"CV=1500、PL=1000、MC=350，差额为150万元且大于0，故认可价值为150万元。该指标计量寿险保单现金价值超出负债与最低资本部分的资本属性，差额为负时取0。","trap":"必须取Max(·,0)；若CV－PL－MC为负，认可价值为0而非负值，常见错误是直接报负数。","tag":""},{"id":"c-01-02","difficulty":2,"stem":"保险公司发行有赎回条款的次级定期债务，账面价值1000万元。因赎回日前后票面利率差额超过100个基点，剩余期限按赎回日计算，赎回日距今2.5年。请计算其认可价值（万元）。","blanks":[{"label":"有赎回条款次级定期债务认可价值(万元)","answer":400,"tolerance":0.5}],"steps":["第1步：判定剩余期限口径：票面利率差额超过100个基点，剩余期限按赎回日计算，即2.5年。","第2步：对照有赎回条款认可标准，剩余期限2年以上（含）3年以内，认可价值为账面价值的40%。","第3步：计算：1000×40%＝400万元。"],"formula_card":"有赎回条款：2年(含)以上3年以内→账面价值40%","analysis":"2.5年落在[2,3)区间，适用40%比例，认可价值400万元。若误按到期日（4年）计算则会得到0，属典型易错点。","trap":"先判断是否按赎回日计算（利差>100bp或有提前赎回证据）；再选档位，2.5年属2-3年档（40%）而非1-2年档（60%）。","tag":""},{"id":"c-01-03","difficulty":3,"stem":"某保险公司核心资本为1000亿元，其中核心二级资本300亿元、核心一级资本700亿元；附属一级资本400亿元、附属二级资本200亿元；计入核心资本的保单未来盈余为300亿元。监管要求：附属资本≤核心资本100%，核心二级资本≤核心资本30%，附属二级资本≤核心资本25%，计入核心资本的保单未来盈余≤核心资本35%。请计算相关限额上限并判断是否满足资本限额要求。","blanks":[{"label":"附属资本上限(亿元)","answer":1000,"tolerance":0.5},{"label":"附属二级资本上限(亿元)","answer":250,"tolerance":0.5},{"label":"计入核心资本的保单未来盈余上限(亿元)","answer":350,"tolerance":0.5}],"steps":["第1步：附属资本上限＝核心资本×100%＝1000×100%＝1000亿元；实际附属资本＝400＋200＝600亿元≤1000，满足。","第2步：核心二级资本上限＝1000×30%＝300亿元（实际300亿元，临界满足）；附属二级资本上限＝1000×25%＝250亿元（实际200亿元≤250，满足）。","第3步：计入核心资本的保单未来盈余上限＝1000×35%＝350亿元（实际300亿元≤350，满足）。","第4步：综合判断：四项限额全部满足，该公司资本结构达标。"],"formula_card":"附属≤100%核心；核心二级≤30%核心；附属二级≤25%核心；保单未来盈余≤35%核心","analysis":"核心资本1000亿元时，四项限额依次为1000、300、250、350亿元。实际值600、300、200、300均不超上限，核心二级资本恰好等于上限仍属达标。超过限额部分应确认为资本性负债。","trap":"四个比例易混淆（附100/保35/核二30/附二25）；核心二级资本等于上限不算超限但属临界值；附属资本是附属一、二级合计。","tag":""}]},{"id":"rule-02","group":"监管规则","name":"第2号 保险公司偿付能力监管规则第2号：最低资本","qa":[{"id":"qa-02-01","difficulty":1,"q":"简述保险公司偿付能力风险的构成，并说明最低资本由哪三部分组成。","answer_points":[{"point":"风险构成","detail":"偿付能力风险由固有风险和控制风险组成，固有风险又分可资本化风险与难以资本化风险。"},{"point":"固有风险细分","detail":"可资本化风险包括保险风险、市场风险、信用风险；难以资本化风险包括操作、战略、声誉、流动性风险。"},{"point":"最低资本三部分","detail":"最低资本由可资本化风险最低资本、控制风险最低资本、附加资本三部分组成。"},{"point":"附加资本内容","detail":"附加资本包括逆周期附加资本、系统重要性保险机构的附加资本以及其他附加资本。"},{"point":"最低资本定义","detail":"最低资本是监管机构基于审慎目的，要求公司应具有的、用以应对可资本化风险的资本数额。"}],"framework":"风险构成→固有风险细分→最低资本三部分→定义。","memo":"“固+控；可资本化+控制+附加”。","tag":""},{"id":"qa-02-02","difficulty":1,"q":"区分可资本化风险与难以资本化风险分别包含哪些类别。","answer_points":[{"point":"可资本化风险","detail":"包括保险风险、市场风险、信用风险，是可量化为最低资本的风险。"},{"point":"难以资本化风险","detail":"包括操作风险、战略风险、声誉风险、流动性风险，不单独计量最低资本。"},{"point":"计量方法差异","detail":"可资本化风险采用在险价值（VaR）法计量，难以资本化风险不单独计提最低资本。"},{"point":"易错提醒","detail":"保险风险属于可资本化风险而非难以资本化；操作风险属难以资本化，二者不可混类。"}],"framework":"两类列举→计量差异→易错提醒。","memo":"“可资：保、市、信；难资：操、战、誉、流”。","tag":""},{"id":"qa-02-03","difficulty":2,"q":"说明最低资本的计量原则。","answer_points":[{"point":"风险基础","detail":"最低资本计量应以风险为基础，反映公司面临风险的资本要求。"},{"point":"风险覆盖","detail":"应涵盖保险公司面临的所有可资本化的固有风险、控制风险和系统风险。"},{"point":"分散效应","detail":"采用相关系数矩阵法反映各类风险之间的分散效应，而非简单加总。"},{"point":"统一标准","detail":"采用行业统一的方法、模型和参数，银保监会另有规定的除外。"},{"point":"风险暴露剔除","detail":"保险、市场、信用三类风险暴露不包括非认可资产和非认可负债。"},{"point":"独立账户例外","detail":"独立账户中不计提由保单持有人自行承担的市场风险、信用风险所对应的最低资本。"}],"framework":"基础→覆盖→方法→统一标准→两项例外。","memo":"“矩阵法反映分散效应、行业统一参数”。","tag":""},{"id":"qa-02-04","difficulty":2,"q":"说明财产保险公司、人身保险公司、再保险公司最低资本向量的组成及典型相关系数差异。","answer_points":[{"point":"财产险向量","detail":"由非寿险保险、市场、信用三部分组成；市场与信用ρ=0.27，非寿险与市场0.10，非寿险与信用0.15。"},{"point":"人身险向量","detail":"由寿险、非寿险、市场、信用四部分组成（含两项保险风险）；市场与信用ρ=0.35，寿险与市场0.30。"},{"point":"再保险向量","detail":"由寿险再保险、非寿险再保险、市场、信用四部分组成；市场与信用ρ=0.27，寿险再与非寿险再0.10。"},{"point":"易考差异","detail":"财产险与再保险的市场-信用ρ均为0.27，人身险为0.35；人身险向量比财产险多一项寿险保险风险。"},{"point":"监管逻辑","detail":"不同业务结构对应不同风险聚合关系，体现各类风险分散程度的差异。"}],"framework":"三机构向量组成→相关系数对比→监管逻辑。","memo":"“财/再市信0.27、人身0.35；人身多寿险风险”。","tag":""},{"id":"qa-02-05","difficulty":2,"q":"说明损失吸收效应调整（LA）的适用对象、计算上限及分红万能账户的相关系数。","answer_points":[{"point":"适用对象","detail":"损失吸收效应调整仅适用于分红保险和万能保险业务，其他业务不适用。"},{"point":"调整含义","detail":"因保单红利和结算利率可调整而具有损失吸收能力，对应最低资本予以调减。"},{"point":"上限公式","detail":"LA上限＝PV基础－PV下限，即基础情景与红利/结算利率下限情景现金流现值之差。"},{"point":"合并相关系数","detail":"分红万能账户合并计算市场与信用风险最低资本时，市场与信用ρ=0.35。"},{"point":"监管意图","detail":"认可保单持有人分担风险的能力以降低最低资本，但以PV差为上限防过度调减。"}],"framework":"适用对象→含义→上限公式→合并ρ→意图。","memo":"“LA仅分红万能；上限=PV基−PV下；合并ρ0.35”。","tag":""},{"id":"qa-02-06","difficulty":3,"q":"综合分析可资本化风险最低资本的计算公式与聚合逻辑，并说明其在最低资本中的地位。","answer_points":[{"point":"基本公式","detail":"可资本化风险最低资本＝√（MC向量×相关系数矩阵M×MC向量转置）－LA。"},{"point":"聚合逻辑","detail":"通过相关系数矩阵法将各类风险最低资本聚合，反映风险间分散效应，而非简单加总。"},{"point":"计量方法","detail":"可资本化风险最低资本采用在险价值（VaR）法计量，银保监会另有规定的除外。"},{"point":"在最低资本中的地位","detail":"可资本化风险最低资本是最主要组成部分，叠加控制风险最低资本与附加资本方为最低资本总额。"},{"point":"调整项LA","detail":"LA为分红万能等特定合同的损失吸收效应调减，须以PV差上限为界，不得超额扣减。"},{"point":"监管意义","detail":"矩阵聚合避免资本要求高估，更真实刻画多风险并存的资本占用。"}],"framework":"公式→聚合逻辑→计量方法→地位→调整项→意义。","memo":"“根号矩阵聚合减LA；VaR计量；最低资本主体”。","tag":""},{"id":"qa-02-07","difficulty":3,"q":"分析控制风险最低资本与附加资本的计量依据，以及长期寿险再保险对最低资本计量的特殊规定。","answer_points":[{"point":"控制风险计量","detail":"控制风险最低资本按《偿付能力监管规则第12号：偿付能力风险管理要求与评估》采用监管评价法计量。"},{"point":"附加资本构成","detail":"附加资本包括逆周期附加资本、系统重要性保险机构的附加资本以及其他附加资本，标准另行规定。"},{"point":"再保险终止条件","detail":"长期寿险再保险合同生效日后3年内可终止的，不得计量因再保险合同降低的最低资本。"},{"point":"双边一致性","detail":"分出人减少的最低资本与分入人增加的最低资本原则上应保持一致，防止单边调节。"},{"point":"监管逻辑","detail":"防止通过再保险不当降低最低资本，强调风险真实转移与分出、分入双边计量一致。"},{"point":"风险暴露衔接","detail":"若特定安排导致风险暴露或风险特征重大变动，银保监会可调整其最低资本要求。"}],"framework":"控制风险依据→附加资本依据→再保险规定→监管逻辑。","memo":"“控制按12号监管评价；再保3年不可减、双边一致”。","tag":""}],"calc":[{"id":"c-02-01","difficulty":1,"stem":"某保险公司分红保险账户基础情景下现金流现值PV基础为500万元，按保单红利水平假设下限重新预测的现金流现值PV下限为420万元。请计算损失吸收效应调整上限LA上限（万元）。","blanks":[{"label":"损失吸收效应调整上限LA上限(万元)","answer":80,"tolerance":0.5}],"steps":["第1步：列示公式：LA上限＝PV基础－PV下限。","第2步：代入数据：500－420＝80万元。","第3步：结果为80万元。"],"formula_card":"LA上限＝PV基础－PV下限","analysis":"损失吸收效应调整上限为80万元，反映基础情景较红利/结算利率下限情景多出的可吸收损失现金流。该调整仅适用于分红保险和万能保险业务，并以该上限为界。","trap":"LA上限是PV之差且通常取非负（若PV下限>PV基础则为0）；仅分红万能适用，不可用于其他业务。","tag":""},{"id":"c-02-02","difficulty":2,"stem":"某财产保险公司非寿险业务保险风险最低资本为240万元，市场风险最低资本为50万元，二者相关系数ρ=0.10。请计算该公司这两项风险聚合后的可资本化风险最低资本（万元，暂不考虑信用风险与其他调整）。","blanks":[{"label":"非寿险与市场风险聚合最低资本(万元)","answer":250,"tolerance":0.5}],"steps":["第1步：列示两风险聚合公式：MC＝√(MC非²＋MC市²＋2×ρ×MC非×MC市)。","第2步：代入：√(240²＋50²＋2×0.10×240×50)＝√(57600＋2500＋2400)＝√62500。","第3步：计算结果为250万元。"],"formula_card":"MC＝√(a²＋b²＋2ρab)","analysis":"两风险聚合后为250万元，明显低于简单加总290万元，体现了相关系数0.10带来的风险分散效应。财产险公司市场与信用ρ为0.27、非寿险与市场ρ为0.10。","trap":"不能直接加总（240+50=290错误）；必须用相关系数矩阵法开平方聚合；注意财产险向量不含寿险保险风险。","tag":""},{"id":"c-02-03","difficulty":3,"stem":"某人身保险公司四类风险最低资本为：寿险业务500万元、非寿险业务100万元、市场风险400万元、信用风险200万元。相关系数矩阵：寿险-非寿险0.20、寿险-市场0.30、寿险-信用0.15、非寿险-市场0.10、非寿险-信用0.10、市场-信用0.35。分红万能损失吸收效应调整LA取上限200万元（PV基础300、PV下限100），控制风险最低资本120万元，附加资本50万元，实际资本900万元。请计算可资本化风险最低资本（调整前）、损失吸收调整后的可资本化风险最低资本以及最低资本总额，并判断综合偿付能力充足率是否达标。","blanks":[{"label":"聚合后（调整前）可资本化风险最低资本(万元)","answer":835.46,"tolerance":1.0},{"label":"损失吸收调整后可资本化风险最低资本(万元)","answer":635.46,"tolerance":1.0},{"label":"最低资本总额(万元)","answer":805.46,"tolerance":1.0}],"steps":["第1步：矩阵聚合 S＝ΣMC_i²＋2Σρ_ij·MC_i·MC_j；平方和＝500²+100²+400²+200²＝460000。","第2步：交叉项＝2×0.20×500×100＋2×0.30×500×400＋2×0.15×500×200＋2×0.10×100×400＋2×0.10×100×200＋2×0.35×400×200＝20000+120000+30000+8000+4000+56000＝238000；S＝698000，√698000≈835.46万元。","第3步：损失吸收调整：835.46－200＝635.46万元。","第4步：最低资本总额＝635.46＋120＋50＝805.46万元；综合偿付能力充足率＝900÷805.46≈111.7%，高于100%，达标。"],"formula_card":"MC_cap＝√(MC向量ᵀ·M·MC向量)－LA；最低资本＝MC_cap＋控制风险＋附加资本","analysis":"聚合前可资本化风险最低资本约835.46万元，经LA调减后为635.46万元，叠加控制风险与附加资本得最低资本总额805.46万元。实际资本900万元对应综合偿付能力充足率约111.7%，满足不低于100%的监管底线。","trap":"矩阵聚合必须开平方而非简单加总；人身险市场-信用ρ为0.35（非财产险的0.27）；LA仅适用于分红万能且以PV差上限为界；充足率分母是最低资本总额而非仅可资本化部分。","tag":""}]},{"id":"rule-03","group":"监管规则","name":"第3号 寿险合同负债评估","qa":[{"id":"qa-03-01","difficulty":1,"q":"寿险合同负债由哪些部分构成？请说明未到期责任准备金、最优估计准备金、风险边际与TVOG之间的层级关系。","answer_points":[{"point":"负债两大组成：寿险合同负债＝未到期责任准备金＋未决赔款准备金","detail":"这是负债的总体构成，未到期责任准备金覆盖未届满保单的未来义务，未决赔款准备金覆盖已发生未决赔案，二者分别适用不同的计量方法。"},{"point":"未到期责任准备金＝最优估计准备金＋风险边际","detail":"最优估计反映现金流的期望值，风险边际反映估计的不确定性，二者相加才构成审慎的负债计量，契合偿付能力监管'稳健计量'的导向。"},{"point":"最优估计准备金＝现金流现值（PV）＋TVOG","detail":"现金流现值是负债主体，TVOG仅针对含选择权及保证利益的业务（分红、万能、变额年金），传统保障型业务无此类价值故TVOG为零。"},{"point":"未决赔款准备金以财务报表账面价值为认可价值","detail":"监管将其排除在本规则未来现金流折现方法之外，直接采用会计账面价值，简化计量并衔接财务报表，避免对已发生赔案重复折现。"},{"point":"短期险例外：短期寿险、短期意外险、短期健康险直接以账面价值认可","detail":"短期业务期限短、不确定性低，监管允许直接以账面价值认可而不适用本规则评估方法，从而降低评估成本。"}],"framework":"先答'两大组成'，再按'未到期→最优估计→PV+TVOG'逐级拆解，最后说明未决赔款与短期险的适用边界。","memo":"记忆钩子：负债=未到期+未决；未到期=最优+风险边际；最优=PV+TVOG。易错：TVOG非零仅限分红/万能/变额年金业务。","tag":""},{"id":"qa-03-02","difficulty":1,"q":"保险公司应如何分别处理分保前与分保后的寿险合同负债？请说明认可负债与认可资产的确认方式。","answer_points":[{"point":"分别评估分保前与分保后的寿险合同负债","detail":"再保安排改变了风险暴露，监管要求计量上区分自留与分出，以真实反映再保对偿付能力的影响，而非简单净额入账。"},{"point":"分保前的寿险合同负债确认为认可负债","detail":"认可负债按分保前（全额）计量，因为保险公司对保单持有人仍承担全部合同义务，再保只是风险转移的内部安排。"},{"point":"分保前后差额作为应收分保准备金，确认为认可资产","detail":"差额代表再保公司所承担部分，以应收分保准备金资产形式确认，体现'资产=分出风险对应的可收回金额'的对称处理。"},{"point":"该处理同时影响负债端与资产端，净效果为自留部分负债","detail":"这种对称计量避免重复或遗漏，使偿付能力充足率分母（认可负债）真实反映保险公司自留的风险水平。"}],"framework":"先说'分别评估'，再答'分保前→认可负债，差额→应收分保准备金（认可资产）'，最后说明净额的监管含义。","memo":"钩子：分保前负债=认可负债，差额=应收分保准备金（资产）。易错：认可负债用的是分保前金额而非分保后金额。","tag":""},{"id":"qa-03-03","difficulty":2,"q":"最优估计准备金的构成是什么？请说明现金流现值与TVOG各自的计量含义及适用业务。","answer_points":[{"point":"公式：最优估计准备金＝现金流现值（PV）＋TVOG","detail":"这是最优估计层级的加总，PV是核心，TVOG是补充项，仅当业务嵌入选择权或保证利益时才不为零。"},{"point":"现金流现值：预期未来现金流出现值减现金流入现值","detail":"包括保证利益、非保证利益、保单维持费用等全部合理现金流出，采用监管折现率曲线折现，是负债计量的基础。"},{"point":"TVOG含义：选择权及保证利益的时间价值","detail":"反映分红、万能、变额年金等业务中保单持有人享有的红利、结算利率等选择权与保证利益的价值，需单独量化。"},{"point":"TVOG因子按保证利率分档（单位万分之一）","detail":"保证利率越高因子越大（0~1%为16，1%~2%为19，2%~2.5%为24，2.5%~3%为38，3%~3.5%为65，高于3.5%为100），因高保证利率下保险公司承担的保证成本更高。"},{"point":"适用边界：无选择权/保证利益业务TVOG为零","detail":"实务中多数传统非分红险TVOG为零，仅分红、万能、变额年金需计算，避免对无选择权业务虚增负债。"}],"framework":"先给公式，再分别解释PV（构成与折现）和TVOG（含义、因子分档、适用业务），最后说明零值边界。","memo":"钩子：TVOG=PV账户×因子（万分之一，须÷10000）。易错：因子按保证利率分档且各档含上界（如3%落在2.5%~3%档）。","tag":""},{"id":"qa-03-04","difficulty":2,"q":"寿险合同负债评估采用的折现率曲线是如何形成的？请说明基础利率曲线的三段结构。","answer_points":[{"point":"总体形成：折现率曲线＝基础利率曲线＋综合溢价","detail":"基础利率反映无风险期限结构，综合溢价反映流动性、税收等额外补偿，二者叠加形成监管认可的折现曲线。"},{"point":"第一段：期望无风险收益率曲线，适用0＜t≤t1","detail":"短中期采用市场期望的无风险收益率，直接反映当前利率环境，构成曲线的基础部分。"},{"point":"第二段：终极利率过渡曲线，适用t1＜t≤t2","detail":"中长期由第一段向终极利率平滑过渡，避免长端利率剧烈跳跃，体现'向长期均衡收敛'的监管设想。"},{"point":"第三段：终极利率水平，适用t＞t2","detail":"超长期采用稳定的终极利率，反映经济长期均衡水平，解决长尾负债折现的利率假设难题。"},{"point":"监管意义：三段结构兼顾市场性与稳定性","detail":"统一曲线减少了评估主观性，防止公司随意设定长端折现率，使不同公司的负债具备可比性。"}],"framework":"先答'基础曲线+综合溢价'，再按t区间依次说明三段，最后点明监管意图。","memo":"钩子：折现率=基础曲线+综合溢价；三段按0~t1、t1~t2、>t2划分。易错：综合溢价是折现率曲线构成，并非基础利率曲线本身的组成段。","tag":""},{"id":"qa-03-05","difficulty":2,"q":"风险边际采用分位点法应如何计算？请说明公式与关键参数。","answer_points":[{"point":"公式：风险边际＝MC×Φ⁻¹(85%)／Φ⁻¹(99.5%)","detail":"分子分母均为标准正态分位函数，比值是一个固定常数，将保险风险最低资本转化为风险边际，体现'资本覆盖对应不确定性'的逻辑。"},{"point":"分位点概率：计提分位α＝85%，分母对应99.5%","detail":"85%是监管规定的风险边际计提分位，区别于最低资本常用的99.5%分位，风险边际的计提标准低于资本要求。"},{"point":"资本口径：MC为分保前保险风险最低资本（按第5号规则计算）","detail":"采用分保前口径与负债认可一致，确保风险边际覆盖自留及分出前全部保险风险，避免重复扣减。"},{"point":"风险边际性质：对最优估计的审慎加项","detail":"与TVOG不同，风险边际覆盖整体保险风险而非仅选择权价值，是负债审慎性的重要组成部分。"}],"framework":"先给公式，再解释分位点85%、资本口径（分保前、第5号）、风险边际定位。","memo":"钩子：风险边际=MC×Φ⁻¹(85%)/Φ⁻¹(99.5%)。易错：分位概率是85%（不是99.5%）；MC取分保前且按第5号计算。","tag":""},{"id":"qa-03-06","difficulty":3,"q":"万能保险与投资连结保险在最优估计准备金评估方法上有何重要区别？请对比说明其监管逻辑。","answer_points":[{"point":"万能险：保险部分与投资部分现金流合并评估，不拆分","detail":"万能险账户价值与保障捆绑，监管强制合并计量现金流现值，避免拆分带来的假设割裂，更贴近保单整体负债实质。"},{"point":"投连险：独立账户部分与非账户部分分别评估","detail":"投连险独立账户价值随投资波动由保户承担，须与保障（非账户）部分分开计量，以清晰区分风险归属主体。"},{"point":"独立账户负债认可：等于独立账户资产在评估日的市场价值","detail":"因独立账户资产与负债一一对应且风险由保户承担，按市值认可可消除错配，监管不要求对其折现。"},{"point":"TVOG适用性不同：万能含保证结算利率故需计TVOG，投连独立账户一般不产生","detail":"二者嵌入选择权性质不同，万能的保证结算利率产生TVOG，投连独立账户通常无保证利益，体现业务结构差异。"},{"point":"监管逻辑：区别源于风险承担主体不同","detail":"万能由保险公司承担投资结果故合并，投连由保户承担故拆分，监管通过差异化计量防止低估保险公司真实负债。"}],"framework":"对比结构：万能'合并评估'vs投连'拆分评估'，再展开独立账户认可与TVOG差异，最后点明风险归属逻辑。","memo":"钩子：万能合并、投连拆分（独立账户按市值认可）。易错：混淆二者——万能不拆分，投连独立账户负债=市场价值。","tag":""},{"id":"qa-03-07","difficulty":3,"q":"保险事故发生率假设（死亡、重疾、退保率）受到哪些约束？请综合分析上下限机制与合理性证明要求。","answer_points":[{"point":"死亡发生率：基础生命表×乘数因子×核保选择因子，非养老类乘数下限0.65、养老类上限1.00","detail":"监管通过乘数上下限框定死亡率假设范围，防止公司过度乐观或保守；基础表为《中国人寿保险业经验生命表（2010～2013）》。"},{"point":"重疾率：基础重疾表（2020）×乘数因子0.7×核保选择因子","detail":"重疾假设统一以0.7乘数为基准，系数固定减少主观调整空间，提升行业可比性。"},{"point":"核保选择因子：前3个保单年度由公司自定不受限，其他年度为1","detail":"新单核保筛选效果公司差异大，监管给予前3年自由；后续年度无筛选红利故固定为1，防止公司长期压低假设。"},{"point":"退保率约束：自身假设高于指导区间上限时采用上限作为备考退保率假设","detail":"指导区间（附件4）约束退保假设，超限部分强制采用备考值，防止公司高估退保以减少负债。"},{"point":"合理性证明：无证据则就高，采用自身费用假设须近两年实际/假设≤105%","detail":"不能证明退保率合理的，按自身与备考假设分别计算现值取较大者；费用假设门槛为105%，监管以比例门槛倒逼公司提供经验证据，无证据即从严。"}],"framework":"按险因分述（死亡/重疾/退保）的乘数与上下限，再讲核保因子前3年例外，最后讲合理性证明与'就高'原则。","memo":"钩子：死亡率有乘数上下限、重疾乘数固定0.7、退保超限取备考、无证明取现值较大者。易错：核保选择因子仅前3年不受限；费用假设门槛是105%（不是100%）。","tag":""},{"id":"qa-03-08","difficulty":3,"q":"分红保险红利假设与万能保险结算利率假设分别受到哪些下限约束？请分析其监管逻辑。","answer_points":[{"point":"分红红利下限（一）：连续36个月内不低于演示中低档红利水平且不低于0","detail":"监管强制红利假设不低于演示中低档，防止公司借'非保证'之名低估负债，36个月窗口兼顾合同近期现金流。"},{"point":"分红红利下限（二）：当年年度红利水平不得低于上年度红利的80%","detail":"该约束限制红利骤降，反映分红险'平滑机制'实质，避免公司通过压低当年红利虚减负债。"},{"point":"万能结算利率下限（一）：不得低于合同约定最低保证利率","detail":"保证利率是合同承诺底线，结算利率假设必须覆盖，否则低估保证利益负债，是刚性约束。"},{"point":"万能结算利率约束（二）：与投收利差不高于投收25%与150BP的较小值","detail":"防止公司用过高结算利率吸引业务而承担利差损，以'双限取小'控制激进定价风险。"},{"point":"万能结算利率连续性：月度不低于上月98.16%、季度94.57%、年度80%","detail":"通过复利年化下限约束利率断崖式下调，维护保单持有人利益与负债稳定。"},{"point":"监管逻辑：非保证利益也须审慎，防止利用假设弹性操纵偿付能力","detail":"两类业务均设下限，因'非保证'不代表可随意低估，监管在'非保证'与'负债审慎'间平衡。"}],"framework":"分红（36月/中低档/0、上年80%）与万能（保证利率、利差双限、连续性）分块，最后归纳'非保证也须审慎'逻辑。","memo":"钩子：分红→36月中低档&0、上年80%；万能→保证利率、利差≤min(25%,150BP)、月度98.16%。易错：万能利差是'25%与150BP较小值'，非较大值。","tag":""}],"calc":[{"id":"c-03-01","difficulty":1,"stem":"某寿险公司评估一组分红型保单的TVOG。该组保单PV（账户准备金）为20000万元，业务保证利率为0.5%（处于0（含）~1%（含）档）。请计算该组保单的TVOG（单位：万元，TVOG因子单位为万分之一，须除以10000）。","blanks":[{"label":"TVOG（万元）","answer":32,"tolerance":0.1}],"steps":["第1步：确定TVOG因子。保证利率0.5%落在0（含）~1%（含）档，对应因子为16（单位万分之一）。","第2步：计算TVOG＝PV（账户准备金）×因子÷10000＝20000×16÷10000＝32（万元）。"],"formula_card":"TVOG＝PV（账户准备金）×TVOG因子（万分之一，即÷10000）","analysis":"保证利率0.5%属于最低档（0~1%含），因子16。TVOG＝20000×16/10000＝32万元。计算表明低保证利率下选择权时间价值较小，符合'保证利率越高、因子越大'的监管设计。","trap":"TVOG因子单位是'万分之一'，必须除以10000；且各档区间含上界（1%含落在第一档而非第二档）。","tag":""},{"id":"c-03-02","difficulty":2,"stem":"某寿险公司评估一组分红险保单。已知：PV（账户准备金）＝8000万元，保证利率1.2%（落在1%~2%（含）档，因子19）；现金流现值＝10000万元；经验分析确定的风险边际＝600万元。请计算该组保单的TVOG，以及未到期责任准备金（单位：万元）。","blanks":[{"label":"TVOG（万元）","answer":15.2,"tolerance":0.1},{"label":"未到期责任准备金（万元）","answer":10615.2,"tolerance":0.1}],"steps":["第1步：计算TVOG＝PV（账户准备金）×因子÷10000＝8000×19÷10000＝15.2（万元）。","第2步：计算最优估计准备金＝现金流现值＋TVOG＝10000＋15.2＝10015.2（万元）。","第3步：计算未到期责任准备金＝最优估计准备金＋风险边际＝10015.2＋600＝10615.2（万元）。"],"formula_card":"TVOG＝PV账户×因子÷10000；未到期责任准备金＝现金流现值＋TVOG＋风险边际","analysis":"保证利率1.2%对应因子19，TVOG＝15.2万元；最优估计准备金＝10015.2万元；叠加风险边际600万元后未到期责任准备金＝10615.2万元。两步之间体现'先算TVOG，再加风险边际'的层级关系。","trap":"因子须÷10000（8000×19=152000，再÷10000才得15.2，而非152）；未到期责任准备金是在'最优估计'而非'现金流现值'基础上加风险边际。","tag":""},{"id":"c-03-03","difficulty":3,"stem":"某寿险公司评估一组分红型年金保单（非养老类业务）。已知：现金流现值＝20000万元；PV（账户准备金）＝10000万元，保证利率3.0%（落在2.5%~3%（含）档，因子38）；经验确定的风险边际＝1000万元。同时该公司该业务死亡率假设采用基础表死亡率×乘数因子0.70（非养老类下限0.65），核保选择因子第5保单年度为1。请计算：TVOG、最优估计准备金、未到期责任准备金，并判断乘数因子是否符合监管要求（单位：万元）。","blanks":[{"label":"TVOG（万元）","answer":38,"tolerance":0.1},{"label":"最优估计准备金（万元）","answer":20038,"tolerance":0.1},{"label":"未到期责任准备金（万元）","answer":21038,"tolerance":0.1}],"steps":["第1步：计算TVOG＝PV（账户准备金）×因子÷10000＝10000×38÷10000＝38（万元）。","第2步：计算最优估计准备金＝现金流现值＋TVOG＝20000＋38＝20038（万元）。","第3步：计算未到期责任准备金＝最优估计准备金＋风险边际＝20038＋1000＝21038（万元）。","第4步：判断乘数因子。非养老类业务乘数因子下限为0.65，公司采用0.70≥0.65，符合监管要求；保证利率3.0%含于2.5%~3%（含）档对应因子38，区间含上界。"],"formula_card":"TVOG＝PV账户×因子÷10000；未到期＝现金流现值＋TVOG＋风险边际；死亡率＝基础表×乘数因子×核保选择因子（非养老下限0.65）","analysis":"保证利率3.0%含于2.5%~3%（含）档，因子38，TVOG＝38万元；最优估计＝20038万元；加风险边际1000万元得未到期＝21038万元。乘数因子0.70高于非养老类下限0.65，假设合理。本题综合考查TVOG分档（含上界）、负债层级与发生率假设达标判断。","trap":"保证利率3.0%恰为2.5%~3%（含）档的上界，仍取因子38（而非下一档65）；死亡率乘数因子下限是0.65，0.70合规但不可低于0.65。","tag":""}]},{"id":"rule-04","group":"监管规则","name":"第4号 保险风险最低资本（非寿险业务）","qa":[{"id":"qa-04-01","difficulty":1,"q":"非寿险业务保险风险最低资本采用的综合因子法是如何构成的？请说明核心公式与特征因子的取值约束。","answer_points":[{"point":"核心公式：MC＝EX×RF，RF＝RF0×(1＋K)","detail":"综合因子法以风险暴露乘以风险因子计量最低资本，风险因子在基础因子上叠加特征因子调整，是各业务类型统一的计量框架。"},{"point":"K＝k1＋k2＋…＋kn，为各项特征系数之和","detail":"各特征系数ki反映业务个性（如综合成本率、分保、增速等），仅对监管明确规定并赋值的特征才计入。"},{"point":"K的取值区间：K∈[－0.25，0.25]","detail":"监管限定特征因子总调整幅度不超过±25%，防止公司通过特征系数大幅操纵最低资本，保证计量稳健。"},{"point":"无明确规定并赋值的特征系数，ki＝0","detail":"对未明确赋值的特征系数强制取0，体现'无依据不调整'的审慎原则，封堵主观调节空间。"}],"framework":"先给MC=EX×RF、RF=RF0×(1+K)公式，再解释K的构成与区间约束，最后说明ki=0的兜底规则。","memo":"钩子：MC=EX×RF0×(1+K)，K∈[-0.25,0.25]，无依据ki=0。易错：K是各ki之和，并非单一特征系数。","tag":""},{"id":"qa-04-02","difficulty":1,"q":"本规则的适用主体有哪些？非寿险业务的保险风险由哪几部分构成？","answer_points":[{"point":"适用主体：财产险、人身险、外国险分公司，不含再保险公司及其分公司","detail":"再保公司适用专门规则，本规则仅针对直保主体，避免重复或错配计量。"},{"point":"保险风险构成：保费及准备金风险＋巨灾风险","detail":"非寿险保险风险仅含此两类，不含市场、信用等风险，清晰界定了本规则的计量边界。"},{"point":"非寿险业务定义：财产保险及一年期内的短期意外、短期健康、短期寿险","detail":"以保险期间与业务性质界定范围，长期人身险不在此列（归第3号寿险负债评估规则）。"},{"point":"相互保险组织适用本规则","detail":"相互制组织同样适用，监管保持主体中性，不因组织形式差异而放宽。"}],"framework":"先答适用主体（含排除项），再答保险风险两大构成，最后补充业务定义与相互保险组织。","memo":"钩子：主体=财产/人身/外险分公司，排除再保；风险=保费及准备金+巨灾。易错：再保险公司及其分公司不适用本规则。","tag":""},{"id":"qa-04-03","difficulty":2,"q":"非寿险业务中，保费风险与准备金风险各自的风险暴露是什么？请说明其口径含义。","answer_points":[{"point":"保费风险暴露：该业务类型最近12个月的自留保费","detail":"以滚动12个月自留口径反映当前保费规模，自留剔除分保，匹配公司实际承担的风险。"},{"point":"准备金风险暴露：该业务类型的再保后未决赔款准备金","detail":"以再保后（而非计提总额）未决赔款为暴露，因再保已转移部分风险，须与保费口径的风险转移保持一致。"},{"point":"二者均采用综合因子法计量","detail":"各自乘以对应基础因子RF0并经特征因子调整，再按相关系数聚合，体现保费与准备金风险的关联性。"},{"point":"车险使用车险自身回溯偏差率，非车险统一用整体回溯偏差率","detail":"回溯偏差率确定准备金风险特征系数，车险单独、非车险合并，反映两类业务损失经验差异。"}],"framework":"分别说明保费风险（12个月自留保费）与准备金风险（再保后未决）的暴露口径，再点出共同方法与回溯偏差率使用差异。","memo":"钩子：保费暴露=近12月自留保费；准备金暴露=再保后未决赔款准备金。易错：准备金用'再保后'而非总额；车险与非车险回溯偏差率分开。","tag":""},{"id":"qa-04-04","difficulty":2,"q":"多数险种保费风险的综合成本率特征系数k1如何分档？请说明各区间对应的系数值及其监管含义。","answer_points":[{"point":"C∈[0，95%)：k1＝－0.05","detail":"综合成本率低于95%表示承保盈利较好，给予负向（降低）调整，奖励稳健定价与良好经营。"},{"point":"C∈[95%，100%)：k1＝0","detail":"接近盈亏平衡，作为基准区间不调整，既不奖也不罚。"},{"point":"C∈[100%，105%)：k1＝0.05","detail":"轻度承保亏损，正向小幅调整，提示风险上升并要求略多资本。"},{"point":"C∈[105%，＋∞)：k1＝0.1","detail":"明显承保亏损，正向较大调整，要求更多资本覆盖持续恶化的承保风险。"}],"framework":"按综合成本率C由低到高列出四档区间与对应k1值，再归纳'盈利降资本、亏损加资本'的监管导向。","memo":"钩子：k1分四档－0.05/0/0.05/0.1，分界95%、100%、105%。易错：区间为左闭右开（如100%落在第三档而非第二档）。","tag":""},{"id":"qa-04-05","difficulty":2,"q":"融资性信用保证险的最低资本计量有何特点？请说明其基础因子划分与风险暴露的计算。","answer_points":[{"point":"基础因子按贷款类型划分","detail":"个人住房抵押贷款0.052、已抵押房产追加贷款部分0.157、个人其他贷款0.078、企业类及其他贷款0.105，房贷风险最低故因子最小。"},{"point":"风险暴露EXi＝再保后贷款余额－对应再保后未决赔款准备金","detail":"以净贷款余额（扣除已发生未决）为暴露，匹配信用保证险'余额'风险的实质，而非承保保费。"},{"point":"同样采用综合因子法，K∈[－0.25，0.25]","detail":"含增速、集中度、小微企业占比、损失率等特征系数ki，与常规险种框架一致。"},{"point":"特征系数关注小额占比与交易对手集中度","detail":"个人<20万、非个人<100万小额占比越高k2越低；前十大交易对手集中度5%~100%时k3＝0.2，集中度越高资本要求越高。"}],"framework":"先列各贷款类型基础因子，再给EXi公式，最后说明特征系数（小额、集中度）的设计逻辑。","memo":"钩子：房贷0.052最小、追加0.157最大；EXi=再保后余额-再保后未决；集中度5%~100%→k3=0.2。易错：暴露是'余额'而非保费。","tag":""},{"id":"qa-04-06","difficulty":3,"q":"请对比分析车险保费风险的特征系数设计与巨灾风险最低资本的计量范围，说明二者在监管逻辑上的差异。","answer_points":[{"point":"车险保费风险特征系数多元：k1~k5","detail":"含综合成本率(k1)、成本率变动(k2)、非比例分保净分出(k3)、增速相对值(k4)、发展阶段(k5)，多维刻画车险经营质量。"},{"point":"小车险公司优惠：k5＝－0.15","detail":"上年车险原保费与分入保费之和小于20亿元的，k5给-0.15（准备金风险k2亦-0.15），扶持中小主体、避免资本过度挤压。"},{"point":"巨灾风险仅对车险与财产险计提","detail":"巨灾（台风洪水、地震）主要影响财产与车损，短期意外健康等不计提，计量边界清晰。"},{"point":"车险台风洪水计算范围受限：仅商业车险车损险及附加险","detail":"不含交强险及商业车险其他险种，因交强险无车损属性、商业三责无物理损害，防止扩大计提。"},{"point":"监管逻辑差异：特征系数调'经营质量'，巨灾应对'低频高损'","detail":"前者是保单层面非预期损失（内生），后者是外生灾害，监管以不同机制分别覆盖，避免重复或遗漏。"}],"framework":"先展开车险k1~k5（含k5小公司优惠），再讲巨灾计提范围与车险台风洪水限制，最后对比二者监管逻辑。","memo":"钩子：车险k1~k5，小车企k5=-0.15；巨灾只算车险/财产险，车险台风仅商业车损及附加。易错：k5优惠门槛是'20亿元'且含分入保费。","tag":""},{"id":"qa-04-07","difficulty":3,"q":"非寿险业务保险风险最低资本的最终聚合是如何完成的？请综合说明聚合公式、相关系数与调控性特征因子K。","answer_points":[{"point":"第一步：聚合保费及准备金风险（ρ＝0.5）","detail":"MC＝√(MC保费²＋2×0.5×MC保费×MC准备金＋MC准备金²)，同业务类型二者正相关，0.5相关系数避免简单加总高估。"},{"point":"第二步：聚合巨灾风险（ρ＝0.25）","detail":"最终＝√(MC保费及准备金²＋2×0.25×MC保费及准备金×MC巨灾＋MC巨灾²)×K，巨灾与承保风险相关性更低，分散效应进一步降低总资本。"},{"point":"调控性特征因子K：专业科技保险公司0.9，其他公司1","detail":"对专业科技险企给予10%资本减免，鼓励科技保险创新，体现差异化监管。"},{"point":"相关系数结构：车险台风与财产险台风0.65，巨灾地震与二者均为0","detail":"体现区域与灾因相关性——台风跨险种相关、地震独立，矩阵化聚合使资本更精准。"}],"framework":"按'先保费准备金聚合(ρ=0.5)、再叠巨灾聚合(ρ=0.25)、最后乘K'三步展开，并补相关系数结构。","memo":"钩子：两层级聚合ρ分别0.5与0.25；专业科技K=0.9、其他K=1；车险台风-财产台风0.65、地震0。易错：最终公式的ρ是0.25（非0.5），别与保费准备金层混淆。","tag":""},{"id":"qa-04-08","difficulty":3,"q":"巨灾风险最低资本的风险暴露与风险区域如何划分？请说明境内外差异及车险台风洪水计算的特殊限制。","answer_points":[{"point":"置信度p＝99.5%","detail":"巨灾计量采用高置信度VaR，反映极端灾害情景下的资本需求，标准高于常规分位。"},{"point":"境内风险暴露以保险金额为口径","detail":"境内财产/车损以保额为暴露，因巨灾损失与保额直接相关，保额更能刻画灾害敞口。"},{"point":"境外风险暴露以保费为口径","detail":"境外缺乏保额数据，以保费近似暴露，属务实处理，保证可操作性。"},{"point":"区域划分：境内按省（区、市），境外按亚太、北美、欧洲、其他四区","detail":"分区域计量捕捉灾害地域聚集性，避免跨区域损失自然抵消而低估风险。"},{"point":"车险台风洪水仅算商业车险车损险及附加险，且超赔再保可扣减摊回","detail":"限定范围防止扩大计提；购买巨灾超赔再保可在情景损失中扣减摊回后计算VaR，承认再保风险转移。"}],"framework":"先给置信度，再分境内（保额）/境外（保费）暴露与区域划分，最后讲车险范围限制与超赔再保处理。","memo":"钩子：境内保额、境外保费；境内分省、境外四区；车险台风仅商业车损及附加。易错：境外暴露是'保费'而非保额；区域划分境内按省、境外按四大区。","tag":""}],"calc":[{"id":"c-04-01","difficulty":1,"stem":"某财产保险公司车险业务，最近12个月自留保费（风险暴露EX）为10000万元，车险保费风险基础因子RF0＝0.103，特征因子K＝0（无明确规定特征系数）。请计算该车险保费风险最低资本（单位：万元）。","blanks":[{"label":"车险保费风险最低资本（万元）","answer":1030,"tolerance":0.1}],"steps":["第1步：风险因子RF＝RF0×(1＋K)＝0.103×(1＋0)＝0.103。","第2步：最低资本MC＝EX×RF＝10000×0.103＝1030（万元）。"],"formula_card":"MC＝EX×RF0×(1＋K)","analysis":"车险保费风险暴露为最近12个月自留保费10000万元，基础因子0.103，K=0时RF=0.103，最低资本＝1030万元。本题为综合因子法单步应用。","trap":"风险暴露是'最近12个月自留保费'而非会计年度保费；K无明确规定时取0，而非默认忽略公式中的(1+K)。","tag":""},{"id":"c-04-02","difficulty":2,"stem":"某财产保险公司车险业务：最近12个月自留保费10000万元（保费风险RF0＝0.103，K＝0），再保后未决赔款准备金5000万元（准备金风险RF0＝0.123，K＝0）。保费与准备金风险相关系数ρ＝0.5。请计算车险保费风险最低资本，以及车险保费及准备金风险最低资本（单位：万元）。","blanks":[{"label":"车险保费风险最低资本（万元）","answer":1030,"tolerance":0.1},{"label":"车险保费及准备金风险最低资本（万元）","answer":1439.6,"tolerance":0.1}],"steps":["第1步：MC保费＝10000×0.103＝1030（万元）；MC准备金＝5000×0.123＝615（万元）。","第2步：聚合MC＝√(MC保费²＋2×ρ×MC保费×MC准备金＋MC准备金²)＝√(1030²＋2×0.5×1030×615＋615²)。","第3步：计算根号内＝1,060,900＋633,450＋378,225＝2,072,575；√2,072,575≈1439.6（万元）。"],"formula_card":"MC保费及准备金＝√(MC保费²＋2×0.5×MC保费×MC准备金＋MC准备金²)","analysis":"先分别算得MC保费=1030、MC准备金=615，再按ρ=0.5聚合得1439.6万元。聚合值小于二者简单相加（1645），体现正相关下的分散效应。","trap":"聚合公式中交叉项是2×ρ×MC保费×MC准备金（ρ=0.5即等于MC保费×MC准备金）；准备金风险暴露用'再保后未决赔款准备金'而非保费。","tag":""},{"id":"c-04-03","difficulty":3,"stem":"某普通财产保险公司（非专业科技保险公司，调控性特征因子K＝1）。已知：财产险最近12个月自留保费10000万元（保费风险RF0＝0.391，K＝0），财产险再保后未决赔款准备金2000万元（准备金风险RF0＝0.561，K＝0）；保费与准备金相关系数ρ1＝0.5；该公司财产险巨灾风险最低资本（已按模板计算）为3000万元；保费及准备金与巨灾相关系数ρ2＝0.25。请计算：财产险保费及准备金风险最低资本，以及该公司非寿险业务保险风险最低资本，并判断K取值是否正确（单位：万元）。","blanks":[{"label":"财产险保费及准备金风险最低资本（万元）","answer":4575.4,"tolerance":0.5},{"label":"非寿险业务保险风险最低资本（万元）","answer":6066.1,"tolerance":0.5}],"steps":["第1步：MC保费＝10000×0.391＝3910（万元）；MC准备金＝2000×0.561＝1122（万元）。","第2步：聚合（ρ1＝0.5）：√(3910²＋3910×1122＋1122²)＝√(15,288,100＋4,387,020＋1,258,884)＝√20,934,004≈4575.4（万元）。","第3步：最终聚合（ρ2＝0.25，K＝1）：√(4575.4²＋2×0.25×4575.4×3000＋3000²)×1＝√(20,934,285＋6,863,100＋9,000,000)＝√36,797,385≈6066.1（万元）。","第4步：判断K：该公司为非专业科技保险公司，K应取1（专业科技才取0.9），取值正确。"],"formula_card":"MC保费及准备金＝√(MC保费²＋2×0.5×MC保费×MC准备金＋MC准备金²)；最终＝√(MC保费及准备金²＋2×0.25×MC保费及准备金×MC巨灾＋MC巨灾²)×K","analysis":"两级聚合：先以ρ=0.5聚合成4575.4万元，再以ρ=0.25叠加巨灾3000万元并乘K=1得6066.1万元。ρ从0.5降至0.25体现巨灾与承保风险相关性更低，分散效应更强。K=1对该普通公司正确（专业科技才0.9）。","trap":"最终聚合的相关系数是0.25（非0.5），易与保费准备金层混淆；K对普通公司取1、专业科技取0.9，不可颠倒；巨灾风险仅对车险和财产险计提。","tag":""}]},{"id":"rule-05","group":"监管规则","name":"第5号 保险风险最低资本（寿险业务）","qa":[{"id":"qa-05-01","difficulty":1,"q":"简述寿险业务保险风险最低资本采用的情景法基本公式，并说明公式中“最低资本不得为负”的监管含义。","answer_points":[{"point":"基本公式为 MC保险 = Max（PV不利情景 − PV基础情景，0）","detail":"先分别在基础情景假设和不利情景假设下计算评估日现金流现值（PV），再用不利情景现值减去基础情景现值得到最低资本；若差值为负则取0。"},{"point":"不利情景 = 基础情景 ×（1 + SF）","detail":"SF为不利情景因子，代表对基础情景假设上浮或下浮一定比例，用以模拟经验与预期发生不利偏离的情形。"},{"point":"“不得为负”体现资本要求的下限逻辑","detail":"最低资本是抵御非预期损失的资本底线，当不利情景下负债现值反而低于基础情景时，说明该风险情景未产生额外资本需求，资本要求归零而非为负。"},{"point":"PV 均需按第3号规则考虑再保因素","detail":"PV基础情景与PV不利情景都需依寿险合同负债评估规则扣减再保影响后再计算现金流现值，保证口径一致。"},{"point":"基础情景假设即最优估计准备金所用假设","detail":"基础情景采用公司在计量最优估计准备金时实际使用的精算假设，确保最低资本与准备金评估同源、可比。"}],"framework":"先写公式→解释不利情景构造→解释Max(·,0)的下限含义→补充PV口径与基础假设来源。","memo":"易错：把公式写成 PV基础−PV不利 或漏掉 Max(·,0)；SF是乘在假设上而非乘在PV上。","tag":""},{"id":"qa-05-02","difficulty":1,"q":"说明本规则（第5号）的适用范围：哪些机构适用、哪些不适用，以及寿险业务的界定边界。","answer_points":[{"point":"适用境内人身保险公司","detail":"包括依法在境内设立的健康保险公司和养老保险公司，均以人身为保险标的经营主体。"},{"point":"相互保险组织适用本规则","detail":"规则附则明确相互保险组织参照适用，体现对同类风险主体的公平监管。"},{"point":"不适用再保险公司及其分公司","detail":"再保险公司的寿险再保险业务最低资本由第6号规则另行规范，本规则仅覆盖直保寿险业务。"},{"point":"寿险业务指长期人身险","detail":"包括长期寿险（含年金）、长期健康险及长期意外险业务，以“长期”为界定核心。"},{"point":"明确排除短期业务","detail":"短期意外险、短期健康险和短期寿险不属于本规则所称寿险业务，避免与第4号非寿险业务规则重复计量。"}],"framework":"先说适用主体（含相互保险）→再说不适用主体（再保）→最后界定寿险业务范围与排除项。","memo":"易错：以为相互保险组织不适用；混淆“短期健康险”与“长期健康险”的归属。","tag":""},{"id":"qa-05-03","difficulty":2,"q":"对比死亡发生率风险与长寿风险的不利情景因子（SF）赋值方式，并说明两者监管逻辑的差异。","answer_points":[{"point":"死亡发生率风险 SF 统一上浮15%","detail":"在未来剩余保险期间内，将死亡发生率全部上浮15%，反映死亡率高于预期时年金/寿险给付增加或准备金不足的风险。"},{"point":"长寿风险 SF 为分段逐年下浮","detail":"第1—10年每年下浮3%，第11—20年每年下浮2%，第21—30年每年下浮1%，30年以上固定为累计下降水平，模拟死亡率改善（人活得更久）的风险。"},{"point":"方向相反：一个上浮、一个下浮","detail":"死亡发生率风险是死亡率“变高”的不利，长寿风险是死亡率“变低（改善）”的不利，二者方向相反，故在汇总时取负相关。"},{"point":"专属商业养老保险需额外打折","detail":"其长寿风险 SF长寿风险 = SF × 0.9，体现该类业务风险特征相对可控后的审慎折减。"},{"point":"监管逻辑：针对同一死亡率的双向偏离分别设防","detail":"寿险公司既怕死得早（给付陡增）也怕活得太久（年金给付拉长），规则用方向相反、结构不同的SF同时覆盖两种尾部风险。"}],"framework":"先列两项SF赋值→说明方向差异→点出负相关与专属养老折减→归结双向尾部风险监管逻辑。","memo":"易错：把长寿风险SF当成一次性下浮或记错分段比例（3%/2%/1%）；漏掉专属养老×0.9。","tag":""},{"id":"qa-05-04","difficulty":2,"q":"说明退保率风险中产品类型Ⅰ与类型Ⅱ的划分规则，以及为何两类采用不同的不利情景因子（SF1、SF2）。","answer_points":[{"point":"划分以现金价值回本时点为核心","detail":"先确认单一保单现金价值与累计生存金之和首次超过已交保费的整数年度；超过50%有效保单的该整数年度大于10年的计量单元归属类型Ⅰ，否则归属类型Ⅱ。"},{"point":"含万能、投连、变额年金的直接归类型Ⅱ","detail":"这类产品价值波动大、退保敏感，直接适用更严格的类型Ⅱ，且确定类型时不考虑非保证利益部分。"},{"point":"类型Ⅰ SF1=30%、SF2=−30%","detail":"类型Ⅰ（长期储蓄型、回本慢）退保压力相对缓和，上下浮动比例较小。"},{"point":"类型Ⅱ SF1=40%、SF2=−40%","detail":"类型Ⅱ（回本快或投资型）更易出现退保，故上浮与下浮幅度均扩大到40%。"},{"point":"PV不利情景取两情景现值较大者","detail":"需同时计算上浮（SF1）与下浮（SF2）两个不利情景现金流现值并取较大者，退保率以100%为上限，覆盖“退保激增”与“退保骤减致费用沉没”两种不利。"},{"point":"监管逻辑：按产品退保敏感度差异化设防","detail":"回本越快、越偏投资的产品退保弹性越大，需更高SF以充分计提退保风险最低资本。"}],"framework":"先讲划分标准（回本时点+特殊产品）→列两类SF数值→说明取Max(PVSF1,PVSF2)→归结差异化监管逻辑。","memo":"易错：记反Ⅰ/Ⅱ的SF；忘记含万能/投连直接归Ⅱ；漏掉需同时算上浮与下浮并取大。","tag":""},{"id":"qa-05-05","difficulty":2,"q":"说明费用风险的不利情景因子取值，并指出费用风险计量中“维持费用”不含哪些项目，解释其监管逻辑。","answer_points":[{"point":"费用风险 SF 赋值为10%","detail":"在未来剩余保险期间内，将各年度保单维持费用上浮10%，模拟维持费用高于预期导致非预期损失的风险。"},{"point":"维持费用不含续期佣金","detail":"续期佣金属获取成本性质，不在“维持”口径内，避免与保单获取端风险重复计量。"},{"point":"维持费用不含保险保障基金","detail":"保险保障基金为法定外部缴费，不属于公司可控的保单维持运营成本。"},{"point":"维持费用不含监管费","detail":"监管费为向监管机关缴纳的固定费用，亦非公司日常维持运营的可控费用。"},{"point":"监管逻辑：聚焦可控制的日常维持成本偏差","detail":"只将公司真正可控、与保单存续相关的维持费用纳入不利情景上浮，剔除外部性、一次性或非维持性质支出，防止资本要求失真。"}],"framework":"先给SF=10%→列出三项排除项目→逐项解释为何排除→归结“可控维持成本”的监管口径。","memo":"易错：把SF记成15%或20%；误以为续期佣金计入维持费用。","tag":""},{"id":"qa-05-06","difficulty":3,"q":"综合分析疾病风险最低资本的计算公式（含疾病发生率风险、疾病趋势风险及相关系数ρ），说明其监管逻辑与常见误用。","answer_points":[{"point":"疾病风险由发生率与趋势两类子风险构成","detail":"疾病风险包含疾病发生率风险（SF=20%）和疾病趋势风险（男性趋势因子2%、女性3%），分别捕捉水平与恶化速度两类不确定性。"},{"point":"汇总采用带相关性的聚合公式","detail":"MC疾病 = √（MC疾病发生率² + MC疾病趋势² + 2×ρ×MC疾病发生率×MC疾病趋势），而非两子风险简单相加。"},{"point":"相关系数ρ赋值为0.25","detail":"ρ=0.25反映两类子风险正相关但不完全同步，既承认其联动又保留分散效应，避免资本高估。"},{"point":"趋势因子区分性别","detail":"疾病恶化趋势实际经验高于预期的风险中，男性赋2%、女性赋3%，体现女性医疗通胀更快的实证特征。"},{"point":"监管逻辑：结构化解耦水平与速度风险","detail":"将“当下发生得多”与“未来恶化得快”拆开计量再适度聚合，比单一因子更精准地刻画疾病风险的双维度尾部。"},{"point":"常见误用：直接加总或误用ρ","detail":"实务中易把MC疾病发生率与MC疾病趋势简单相加，或把ρ错用为寿险总体汇总中的其他相关系数（如0.4、0.5）。"}],"framework":"先拆两类子风险及参数→列聚合公式与ρ=0.25→性别趋势因子→监管逻辑→点出加总/错用ρ的误区。","memo":"易错：疾病公式ρ=0.25 与 费用/退保汇总ρ=0.5、损失-费用ρ=0.4 混记；把疾病风险当单一风险加总。","tag":""},{"id":"qa-05-07","difficulty":3,"q":"综合分析寿险业务保险风险最低资本的汇总框架：（损失发生、费用、退保）向量如何通过相关系数矩阵得到最终最低资本，并说明关键相关系数取值。","answer_points":[{"point":"最终汇总向量为（MC损失发生, MC费用, MC退保）","detail":"三类风险各自先内部聚合（如损失发生内部含死亡、长寿、疾病等子风险），再以三元向量进入寿险业务总体汇总。"},{"point":"损失发生与费用相关系数0.4","detail":"赔付经验恶化往往伴随费用上升（如理赔成本、维持费用），二者正相关，取0.4。"},{"point":"损失发生与退保相关系数0","detail":"赔付不利与退保不利在统计上相互独立，故取0，不额外叠加协同效应。"},{"point":"费用与退保相关系数0.5","detail":"退保骤减会使维持费用相对沉没、退保激增也扰动费用，二者关联最强，取0.5。"},{"point":"汇总采用平方项加交叉项的平方根公式","detail":"MC = √(ΣMCi² + 2×ρ12×MC1×MC2 + 2×ρ13×MC1×MC3 + 2×ρ23×MC2×MC3)，低于简单加总，体现风险分散收益。"},{"point":"监管逻辑：分层聚合+差异化相关捕捉分散效应","detail":"先子风险、再三大类、最后总体，配合有区分度的相关系数，使资本要求既审慎又不被重复计提夸大。"}],"framework":"先列三元向量→逐条给出三对相关系数→写汇总公式→解释分散效应→归结分层聚合监管逻辑。","memo":"易错：记错三对相关数值（0.4/0/0.5）；把死亡-长寿的−0.25错当成总体汇总相关系数。","tag":""},{"id":"qa-05-08","difficulty":3,"q":"对比死亡巨灾风险与死亡发生率风险的计量差异，说明易错点及死亡巨灾风险计量单元的特殊性。","answer_points":[{"point":"死亡发生率风险用比例上浮（SF=15%）","detail":"以基础情景死亡发生率乘以（1+15%）模拟全期死亡率温和上行，属常规尾部风险。"},{"point":"死亡巨灾风险用绝对数增加0.0018","detail":"不利情景为评估日后12个月内年度死亡发生率“增加绝对数额0.0018”，是绝对量冲击而非比例上浮，针对流行病、地震、海啸等极端事件。"},{"point":"巨灾仅覆盖评估日后12个月","detail":"巨灾风险窗口限定为评估日后12个月内的年度发生率，不同于发生率风险覆盖整个剩余保险期间。"},{"point":"巨灾计量单元为全部寿险有效保单","detail":"以评估日全部寿险业务有效保单为计量单元（不细分产品），体现巨灾对全组合的统一冲击。"},{"point":"监管逻辑：区分“趋势性”与“脉冲式”死亡风险","detail":"前者缓释于长期精算假设偏差，后者需以绝对冲击+全组合口径单独设防，防止极端事件资本计提不足。"},{"point":"易错点：把巨灾0.0018当成15%比例或混淆计量单元","detail":"常误将巨灾SF与发生率SF混同，或把巨灾计量单元误用为单产品单元而非全部有效保单。"}],"framework":"先对比赋值方式（比例vs绝对）→对比时间窗口与计量单元→监管逻辑→点出两类易错混淆。","memo":"易错：巨灾是“+0.0018绝对数”不是“上浮15%”；巨灾单元是全部有效保单而非单产品。","tag":""}],"calc":[{"id":"c-05-01","difficulty":1,"stem":"某寿险产品计量单元在基础情景下的评估日现金流现值为800（万元）。按死亡发生率风险不利情景因子SF=15%上浮假设后，不利情景现金流现值为800×（1+15%）=920（万元）。求该产品的死亡发生率风险最低资本（万元）。","blanks":[{"label":"死亡发生率风险最低资本（万元）","answer":120,"tolerance":0.5}],"steps":["第1步：计算不利情景现值 PV不利 = 800 ×（1+15%）= 920（万元）。","第2步：按情景法公式 MC = Max（PV不利 − PV基础，0）= Max（920 − 800，0）= 120（万元）。"],"formula_card":"MC保险 = Max（PV不利情景 − PV基础情景，0）；不利情景 = 基础情景 ×（1 + SF），SF死亡发生率 = 15%","analysis":"基础情景现值800万元，不利情景现值920万元，差额120万元为正，故最低资本为120万元。该值为非负数，符合资本下限要求。","trap":"易把公式写成 PV基础 − PV不利 导致符号错误；或忘记取 Max(·,0) 直接相减。","tag":""},{"id":"c-05-02","difficulty":2,"stem":"某计量单元的疾病发生率风险最低资本为120（万元），疾病趋势风险最低资本为80（万元）。已知疾病发生率风险与疾病趋势风险的相关系数ρ=0.25。求该计量单元的疾病风险最低资本（万元）。","blanks":[{"label":"疾病风险最低资本（万元）","answer":160,"tolerance":0.5}],"steps":["第1步：代入聚合公式根号内 = MC发生率² + MC趋势² + 2×ρ×MC发生率×MC趋势 = 120² + 80² + 2×0.25×120×80 = 14400 + 6400 + 4800 = 25600。","第2步：开平方得 MC疾病 = √25600 = 160（万元）。"],"formula_card":"MC疾病 = √（MC疾病发生率² + MC疾病趋势² + 2×ρ×MC疾病发生率×MC疾病趋势），ρ = 0.25","analysis":"根号内三项分别为14400、6400与交叉项4800，合计25600，开平方得160万元。该值小于简单加总（200万元），体现两子风险正相关下的分散效应。","trap":"易把两子风险直接相加（120+80=200）而非用带ρ的开方公式；或误将ρ取为0.5、0.4。","tag":""},{"id":"c-05-03","difficulty":3,"stem":"某寿险业务计量单元经内部聚合后，损失发生风险最低资本MC损失=1000（万元），费用风险最低资本MC费用=400（万元），退保风险最低资本MC退保=300（万元）。寿险业务总体汇总相关系数：损失发生与费用0.4、损失发生与退保0、费用与退保0.5。求该寿险业务的保险风险最低资本（万元）。","blanks":[{"label":"寿险业务保险风险最低资本（万元）","answer":1300,"tolerance":0.5}],"steps":["第1步：列出汇总向量（MC损失=1000，MC费用=400，MC退保=300）及相关系数ρ12=0.4、ρ13=0、ρ23=0.5。","第2步：计算平方和与交叉项：1000²+400²+300² + 2×0.4×1000×400 + 2×0 + 2×0.5×400×300 = 1000000+160000+90000+320000+0+120000 = 1690000。","第3步：开平方得 MC保险 = √1690000 = 1300（万元）。"],"formula_card":"MC = √(MC1²+MC2²+MC3² + 2ρ12·MC1·MC2 + 2ρ13·MC1·MC3 + 2ρ23·MC2·MC3)；ρ(损失,费用)=0.4，ρ(损失,退保)=0，ρ(费用,退保)=0.5","analysis":"三项平方和为1250000，交叉项合计440000（其中损失-费用320000、费用-退保120000、损失-退保0），合计1690000，开平方得1300万元。该值显著低于简单加总1700万元，体现分散效应。","trap":"易把死亡-长寿的−0.25错当成总体汇总相关系数；或漏掉某项交叉项（尤其ρ13=0那一项）。","tag":""}]},{"id":"rule-06","group":"监管规则","name":"第6号 保险风险最低资本（再保险公司）","qa":[{"id":"qa-06-01","difficulty":1,"q":"说明本规则（第6号）的适用范围及“再保险公司”的定义边界，并指出何种直接保险公司可适用本规则。","answer_points":[{"point":"适用境内再保险公司及境外再保险分公司","detail":"再保险公司指依法在境内设立的经营再保险业务的再保险公司，以及境外再保险公司的分支机构。"},{"point":"规范对象是再保险业务的保险风险最低资本","detail":"本规则专门计量再保险公司再保险业务的保险风险，与直保业务规则（第4、5号）形成分工。"},{"point":"直接保险公司一般不适用本规则","detail":"境内直接保险公司本身不在适用范围内，仅在银保监会依审慎监管需要指定且满足特定条件时才适用。"},{"point":"被指定的直接保险公司延伸适用再保险规定","detail":"一旦被指定适用本规则，同时延伸适用其他偿付能力监管规则中的再保险相关规定，保持监管口径一致。"},{"point":"监管逻辑：以经营主体为界分类施策","detail":"按“是否以再保险为主业”划分规则适用，既覆盖专业再保机构，又保留对大型直保公司再保业务的审慎兜底。"}],"framework":"先给再保险公司定义→说明一般直保不适用→点出监管指定例外及延伸适用→归结分类监管逻辑。","memo":"易错：以为所有直接保险公司都适用；忽略“被指定”这一例外情形及其延伸适用效果。","tag":""},{"id":"qa-06-02","difficulty":1,"q":"说明非寿险再保险业务中保费风险与准备金风险最低资本采用的“综合因子法”公式，并解释 RF 与 K 的含义。","answer_points":[{"point":"基本公式 MC = EX × RF","detail":"以风险暴露EX乘以风险因子RF得到最低资本，是再保险业务各类型保费/准备金风险的基础计量方法。"},{"point":"RF = RF0 ×（1 + K）","detail":"RF由基础因子RF0与特征系数之和K共同决定，K反映业务个体化风险特征对基础因子的调整。"},{"point":"K 为各特征系数之和（k1+k2+…+kn）","detail":"各特征系数由偿付能力监管规则具体规定和赋值，用于刻画业务的结构性风险差异。"},{"point":"无明确规定并赋值的特征系数取0","detail":"对再保险公司而言，规则未明确赋值的特征系数直接取0，不自行假设，保证计量中性。"},{"point":"监管逻辑：标准化暴露+可调因子","detail":"以自留保费或准备金作为暴露基准，再用基础因子与特征系数微调，兼顾可比性与风险敏感度。"}],"framework":"先写 MC=EX×RF→展开 RF=RF0×(1+K)→说明K为系数和及缺省取0→归结标准化计量逻辑。","memo":"易错：把K记成乘积关系或忘记“未赋值特征系数取0”；混淆RF0与RF。","tag":""},{"id":"qa-06-03","difficulty":2,"q":"对比非寿险再保险业务中比例再保险与非比例再保险的分类，并说明非比例再保险业务巨灾风险基础因子（1.85）为何是本规则最高基础因子。","answer_points":[{"point":"非寿险再保险分13类：比例10种、非比例3种","detail":"第四条将业务划分为比例类10种加非比例类3种（非比例财产、非比例责任及短期人身、非比例特殊），对应汇总矩阵MC1至MC13。"},{"point":"比例与非比例是核心划分维度","detail":"二者在风险暴露口径、基础因子赋值与巨灾处理方式上均不同，是再保险业务风险结构的关键区分。"},{"point":"非比例巨灾风险 RF0 = 1.85 为全规则最高","detail":"非比例再保险业务巨灾风险基础因子赋值为1.85，显著高于其他各类基础因子（如非比例财产保费0.394）。"},{"point":"高因子反映巨灾损失的厚尾特征","detail":"非比例再保险在巨灾下可能触发巨额超赔赔付，损失分布极端右偏，需以最高基础因子充分计提资本。"},{"point":"巨灾风险暴露为过去12个月自留保费","detail":"其风险暴露取该巨灾业务的过去12个月自留保费；险位与巨灾混合业务以全部自留保费作为风险暴露。"}],"framework":"先给13类结构→区分比例/非比例→点出1.85最高及原因→说明巨灾暴露口径。","memo":"易错：记错13类的比例/非比例数目（10+3）；把非比例巨灾1.85与财产保费0.394混淆。","tag":""},{"id":"qa-06-04","difficulty":2,"q":"说明以“年度保证续保方式”分保的业务被认定为寿险再保险业务须满足的条件，以及“保证再保险费率浮动范围具有经济实质”的判断标准。","answer_points":[{"point":"须同时满足两个条件","detail":"以年度保证续保方式分保的业务，须同时保证续保、保证再保险费率（含费率浮动范围），方认定为寿险再保险业务，否则归为非寿险再保险业务。"},{"point":"保证续保与保证费率缺一不可","detail":"仅保证续保或仅保证费率均不满足，防止借“寿险再保”名义套用更宽松的计量规则。"},{"point":"经济实质指对交易双方有清晰可辨认影响","detail":"浮动范围须能实质影响双方经济利益，而非形式上存在却永不触发的“空”条款。"},{"point":"判断从“限制是否可被触及”出发","detail":"评估浮动范围的限制条件在实务中是否可能被实际触及，若不可触及则不具有经济实质。"},{"point":"无经济实质的可归入非寿险再保险业务","detail":"再保险公司可选择将浮动范围不具经济实质的业务归入非寿险再保险业务，且交易双方须就判断沟通并保持一致。"}],"framework":"先列两个必要条件→解释经济实质定义→给出“可否触及”判断法→点出无实质业务的归类选择。","memo":"易错：以为仅保证续保即可；忽略浮动范围需“可触及”才具经济实质。","tag":""},{"id":"qa-06-05","difficulty":2,"q":"说明非寿险再保险业务保险风险最低资本的五步计算流程，并指出数据报送的时限与对象。","answer_points":[{"point":"第一步：各类型保费风险与准备金风险","detail":"先对13类业务分别计算保费风险最低资本和准备金风险最低资本（综合因子法）。"},{"point":"第二步：各类型保费及准备金风险","detail":"对每类业务用ρ=0.5将保费与准备金风险聚合为该类业务的保费及准备金风险最低资本。"},{"point":"第三步：业务整体保费及准备金风险","detail":"通过13类业务的相关系数矩阵汇总得到整体保费及准备金风险最低资本。"},{"point":"第四步：巨灾风险最低资本","detail":"对车险和财产险再保险业务计提巨灾风险最低资本（比例适用第4号、非比例RF0=1.85）。"},{"point":"第五步：保险风险最低资本","detail":"以ρ=0.25将保费及准备金风险与巨灾风险聚合成最终非寿险再保险保险风险最低资本。"},{"point":"数据报送：每季结束后10日内报境内分入公司","detail":"分出公司应在每季度结束后10日内向境内分入公司提供计算最低资本所必需的保单与业务数据。"}],"framework":"按五步顺序逐条展开（保费/准备金→类内聚合→整体聚合→巨灾→总聚合）→补充数据报送时限与对象。","memo":"易错：记错五步顺序或漏掉巨灾步骤；把报送时限记成15日/30日。","tag":""},{"id":"qa-06-06","difficulty":3,"q":"综合分析非寿险再保险业务保险风险最低资本的分层汇总结构，说明三层相关系数（0.5、0.5、0.25）分别出现在哪一层及其监管含义。","answer_points":[{"point":"第一层：保费与准备金风险 ρ=0.5","detail":"各类业务内部，保费风险与准备金风险高度联动（赔得多则准备金也不足），取较高相关0.5。"},{"point":"第二层：比例巨灾与非比例巨灾 ρ=0.5","detail":"巨灾风险内部，比例与非比例再保的巨灾暴露受同一灾害事件驱动，取0.5反映同向冲击。"},{"point":"第三层：保费及准备金风险与巨灾风险 ρ=0.25","detail":"整体业务风险与巨灾风险相关度较低，取0.25，承认二者部分独立、存在分散空间。"},{"point":"嵌套聚合用平方根公式逐层压缩","detail":"每层均以 √(a²+2ρab+b²) 形式聚合，低于简单加总，逐层释放分散效应。"},{"point":"监管逻辑：按风险同源程度分级赋相关","detail":"同源越强的两层相关系数越高（0.5），跨维度（业务vs巨灾）相关更弱（0.25），使资本既审慎又不被高估。"},{"point":"易错：把三层ρ张冠李戴","detail":"常把业务-巨灾的0.25误用于类内或巨灾内部，或将0.5错记到其他层级。"}],"framework":"先列三层及对应ρ→逐层解释为何取该值→说明平方根聚合→归结分级赋相关逻辑与易错点。","memo":"易错：三层都是“0.5/0.25”易串；注意业务-巨灾才是0.25，类内保费-准备金与巨灾内部均0.5。","tag":""},{"id":"qa-06-07","difficulty":3,"q":"综合说明第6号规则与第5号规则在寿险再保险业务计量上的衔接关系，并说明相关的数据提供义务。","answer_points":[{"point":"寿险再保险业务计量援引第5号规则","detail":"第6号规则规定寿险再保险业务的保险风险最低资本直接适用第5号（寿险业务）规则进行计量。"},{"point":"退保率风险适用产品类型Ⅰ","detail":"衔接中明确寿险再保险业务的退保率风险不利情景因子适用类型Ⅰ（SF1=30%、SF2=−30%），而非更严的类型Ⅱ。"},{"point":"以转分保后净现金流评估负债","detail":"寿险再保险计量应以转分保后的净现金流为基础评估再保险合同负债，而非毛额，体现再保风险转移。"},{"point":"计量单元按单个原保险产品划分","detail":"涵盖多个产品的再保险合同，以单个保险产品在评估日所有有效原保险合同作为一个计量单元；需合同层面合并的（如再保手续费）应合并单元。"},{"point":"分出公司负有数据提供义务","detail":"分出公司应及时向分入公司提供计算所必需的保单信息，包括产品责任、保费、保额、保单件数等。"},{"point":"监管逻辑：避免重复立法、保持直保再保同源","detail":"通过援引第5号实现规则衔接，仅在退保类型、净现金流口径上做再保适配，确保同类风险计量可比。"}],"framework":"先说援引第5号→退保类型Ⅰ适配→净现金流口径→计量单元划分→数据义务→归结衔接监管逻辑。","memo":"易错：误以为寿险再保退保适用类型Ⅱ；忘记“转分保后净现金流”而非毛额。","tag":""},{"id":"qa-06-08","difficulty":3,"q":"说明第4号规则中哪些特征系数不适用于再保险公司比例再保险业务的保费风险计量，并解释为何作此排除。","answer_points":[{"point":"不适用项一：非比例分保净分出比例特征系数","detail":"该系数针对非比例分保结构，而比例再保险业务本身不具该结构，故不适用。"},{"point":"不适用项二：车险综合成本率变动特征系数","detail":"再保险比例业务不直接经营车险前端业务，综合成本率变动口径不适用其保费风险计量。"},{"point":"不适用项三：保费收入增速特征系数","detail":"再保险公司比例业务的增长驱动与直保公司不同，原增速系数无法刻画其风险特征。"},{"point":"不适用项四：保险公司发展阶段特征系数","detail":"发展阶段系数面向直保公司经营周期，再保险公司业务模式差异大，不适用。"},{"point":"另含融资性信用保证险最低资本相关特征系数","detail":"第十二条还明确融资性信用保证险最低资本相关特征系数同样不适用再保险公司比例再保险业务。"},{"point":"监管逻辑：沿用直保框架但剔除不匹配维度","detail":"比例再保险业务保费风险可借用第4号基础结构，但需剔除仅适用于直保前端或特定非比例结构的特征系数，防止错配计提。"}],"framework":"先列四项（及融资性信保）不适用特征系数→逐项说明为何剔除→归结“借用框架+剔除错配”逻辑。","memo":"易错：漏掉融资性信用保证险这一项；误以为比例再保可全盘套用第4号所有特征系数。","tag":""}],"calc":[{"id":"c-06-01","difficulty":1,"stem":"某再保险公司非比例财产再保险业务的过去12个月自留保费（风险暴露EX）为1000（万元），保费风险基础因子RF0=0.394，无适用特征系数（K=0）。求该业务的保费风险最低资本（万元）。","blanks":[{"label":"非比例财产再保险保费风险最低资本（万元）","answer":394,"tolerance":0.5}],"steps":["第1步：计算风险因子 RF = RF0 ×（1 + K）= 0.394 ×（1 + 0）= 0.394。","第2步：按综合因子法 MC = EX × RF = 1000 × 0.394 = 394（万元）。"],"formula_card":"MC = EX × RF；RF = RF0 ×（1 + K），非比例财产再保险保费风险 RF0 = 0.394","analysis":"风险暴露1000万元乘以基础因子0.394得394万元。因无适用特征系数，K=0，RF等于RF0，资本要求由标准化暴露直接决定。","trap":"易把EX误用为再保后未决赔款准备金（那是准备金风险的暴露）；或把RF0记成0.254/0.653。","tag":""},{"id":"c-06-02","difficulty":2,"stem":"某类非寿险再保险业务的保费风险最低资本为200（万元），准备金风险最低资本为120（万元）。已知保费风险与准备金风险的相关系数ρ=0.5。求该业务的保费及准备金风险最低资本（万元）。","blanks":[{"label":"保费及准备金风险最低资本（万元）","answer":280,"tolerance":0.5}],"steps":["第1步：代入聚合公式根号内 = MC保费² + 2×ρ×MC保费×MC准备金 + MC准备金² = 200² + 2×0.5×200×120 + 120² = 40000 + 24000 + 14400 = 78400。","第2步：开平方得 MC保费及准备金 = √78400 = 280（万元）。"],"formula_card":"MC保费及准备金i = √（MC保费i² + 2×ρ×MC保费i×MC准备金i + MC准备金i²），ρ = 0.5","analysis":"根号内为40000、交叉项24000（2×0.5×200×120）与14400，合计78400，开平方得280万元。低于简单加总320万元，体现类内分散效应。","trap":"易将保费与准备金风险直接相加（200+120=320）；或误将ρ取为0.25（那是业务-巨灾层）。","tag":""},{"id":"c-06-03","difficulty":3,"stem":"某再保险公司非寿险再保险业务中，某类业务的保费风险最低资本为500（万元）、准备金风险最低资本为300（万元）（ρ=0.5）；另经计量其巨灾风险最低资本为250（万元）。已知保费及准备金风险与巨灾风险的相关系数ρ=0.25。求该再保险公司非寿险再保险业务的保险风险最低资本（万元）。","blanks":[{"label":"非寿险再保险业务保险风险最低资本（万元）","answer":800,"tolerance":0.5}],"steps":["第1步：先聚合类内保费及准备金风险 = √(500² + 2×0.5×500×300 + 300²) = √(250000 + 150000 + 90000) = √490000 = 700（万元）。","第2步：将整体保费及准备金风险（700）与巨灾风险（250）按ρ=0.25聚合，根号内 = 700² + 2×0.25×700×250 + 250² = 490000 + 87500 + 62500 = 640000。","第3步：开平方得 MC保险 = √640000 = 800（万元）。"],"formula_card":"MC保险 = √（MC保费及准备金² + 2×ρ×MC保费及准备金×MC巨灾 + MC巨灾²），类内ρ=0.5、业务-巨灾ρ=0.25","analysis":"先得类内聚合700万元，再与巨灾250万元以ρ=0.25聚合成800万元。该值低于700+250=950的简单加总，体现跨层分散效应；结果已含达标所需的资本底线。","trap":"易把两层ρ都当成0.5或都当成0.25；或漏掉类内先聚合、直接用500/300与巨灾混合计算。","tag":""}]},{"id":"rule-07","group":"监管规则","name":"第7号 市场风险和信用风险的穿透计量","qa":[{"id":"qa-07-01","difficulty":1,"q":"简述本规则在偿二代体系中的定位、适用范围与核心目标。","answer_points":[{"point":"规则定位","detail":"本规则是《保险公司偿付能力监管规则》第7号，专门用于规范保险公司市场风险和信用风险的穿透计量。"},{"point":"适用范围","detail":"适用于境内经营商业保险业务的保险公司和外国保险公司分公司；相互保险组织也适用，但并非被定义为'保险公司'本身。"},{"point":"要解决的问题","detail":"核心是解决非基础资产无法直接计量最低资本的问题，这类资产信息不透明、风险难辨。"},{"point":"实现路径","detail":"通过识别交易结构和底层资产，将非基础资产逐层还原，从而准确计量其市场风险和信用风险最低资本。"},{"point":"规则沿革","detail":"本规则于2021年12月30日第一次发布，是偿二代二期工程新增的规则之一。"}],"framework":"定位—适用—问题—方法 四段式作答，先说清楚'管什么、管谁、为什么、怎么做'。","memo":"易错：相互保险组织是'适用'本规则，而非被规则称为'保险公司'；穿透对象是'非基础资产'。","tag":""},{"id":"qa-07-02","difficulty":1,"q":"说明基础资产与非基础资产的区别，并各举三例。","answer_points":[{"point":"基础资产定义","detail":"风险清晰、信息完备、可以直接计量最低资本的境内外资产，按第8号等规则直接计量。"},{"point":"非基础资产定义","detail":"不可以直接计量最低资本的资产，必须按本规则进行穿透后才能计量其最低资本。"},{"point":"基础资产示例","detail":"现金及存款、债券、上市普通股票、公募证券投资基金（公募REITs除外）、金融衍生品、对企业或个人的债权资产。"},{"point":"非基础资产示例","detail":"信托计划、保险资产管理产品、股权投资基金、债转股投资计划、SPV、银行理财产品、资产支持计划、不动产金融产品、公募REITs。"},{"point":"实务意义","detail":"二者计量的根本差异在于能否直接计量：基础资产走综合因子法/情景法，非基础资产必须穿透。"}],"framework":"先给定义对比，再分别举例对照，最后点明计量差异。","memo":"易错对比：普通公募证券投资基金属基础资产，而公募REITs属非基础资产，二者最易混淆。","tag":""},{"id":"qa-07-03","difficulty":2,"q":"说明非基础资产穿透计量应遵循的五项基本原则及其含义。","answer_points":[{"point":"应穿尽穿原则","detail":"对所有非基础资产都要进行穿透并计量其最低资本，不留例外、不选择性穿透。"},{"point":"穿透到底原则","detail":"将所有非基础资产逐层穿透至基础资产，或者穿透至豁免穿透的非基础资产为止。"},{"point":"风险穿透原则","detail":"按底层资产自身的风险性质，并结合交易结构风险特征来计量最低资本。"},{"point":"可靠计量原则","detail":"底层资产的风险暴露必须能够可靠计量，否则不能认定为可穿透资产。"},{"point":"信息穿透原则","detail":"保险公司应在偿付能力报告中披露交易结构、交易对手及穿透后的底层资产等信息。"}],"framework":"五项原则逐一展开，每项点出'原则名+监管意图'。","memo":"易考'应穿尽穿'（对象：所有非基础资产）与'穿透到底'（深度：逐层至底层）的区别。","tag":""},{"id":"qa-07-04","difficulty":2,"q":"说明底层资产最低资本的计算公式，并解释各参数的含义与取值规则。","answer_points":[{"point":"基本公式","detail":"MC底层资产i = EX底层资产i × RF底层资产i，即风险暴露乘以风险因子。"},{"point":"风险暴露EX","detail":"有公开活跃交易市场的按市价确定；无公开市场的按财务报表账面价值确认；无财务报表的可按投后报告投资金额确认。"},{"point":"风险因子RF","detail":"RF底层资产i = RF0 ×（1 + K + Kp），其中RF0为基础因子，K为特征系数，Kp为交易结构风险特征系数。"},{"point":"上限封顶","detail":"当RF底层资产i计算结果超过1时，取值为1，这是监管设置的安全阀，防止因子无限放大。"},{"point":"利率风险衔接","detail":"人身险公司穿透后底层固定收益类基础资产不计量利率风险；财产险公司底层境内债券和利率衍生品等仍需计量利率风险。"}],"framework":"公式—风险暴露—风险因子—封顶—与利率风险衔接 五步。","memo":"易错：RF上限为1（不是0.5）；K与Kp是不同概念，顺序不要混淆。","tag":""},{"id":"qa-07-05","difficulty":2,"q":"说明豁免穿透的条件，以及豁免后各类资产的简化计量方法。","answer_points":[{"point":"集中度条件","detail":"最大一笔底层资产账面价值不超过底层资产账面价值总和的20%，即满足集中度要求方可豁免。"},{"point":"资产支持计划附加条件","detail":"资产支持计划要豁免穿透，除20%集中度外，还要求底层资产大于100笔。"},{"point":"不受20%限制的资产","detail":"现金及流动性管理工具、政府债券、政策性银行发行的金融债券、政府支持机构债券不受该20%集中度限制。"},{"point":"组合类保险资管产品与银行理财","detail":"豁免后计量权益价格风险，因子按类型：货币/现金管理类0.01、固定收益类0.06、权益类0.28、混合及商品金融衍生品类0.23。"},{"point":"资产支持计划","detail":"豁免后计量交易对手违约风险，因子按评级：AAA0.1、AA+0.13、AA0.18、AA−0.23、A+/A/A−0.33、BBB+及以下及无评级0.45。"},{"point":"放弃豁免权","detail":"保险公司可以选择放弃豁免权，按本规则对保险资管产品和商业银行理财产品进行穿透计量。"}],"framework":"条件—例外—分类简化计量—权利 四段。","memo":"易错：20%指'最大一笔/总和'；资产支持计划额外要求底层>100笔才能豁免。","tag":""},{"id":"qa-07-06","difficulty":3,"q":"综合对比底层资产、表层资产、豁免穿透资产、无法穿透资产四类非基础资产的最低资本计量差异。","answer_points":[{"point":"底层资产","detail":"按MC=EX×RF0×(1+K+Kp)计量，体现基础风险并叠加交易结构风险特征系数Kp。"},{"point":"表层债权类资产","detail":"计量交易对手违约风险，MC=EX×RF0×(1+K表层)，风险暴露为其认可价值，基础因子按信用评级赋值。"},{"point":"豁免穿透资产","detail":"不穿透，按简化因子计量：组合类/银行理财计权益价格风险，资产支持计划计交易对手违约风险。"},{"point":"无法穿透资产","detail":"权益类（信托计划、股权投资基金等）计权益价格风险且基础因子0.6；固定收益类（债权投资计划、资产支持计划等）计交易对手违约风险且基础因子0.6。"},{"point":"部分穿透处理","detail":"可识别部分按底层+表层计量，无法穿透部分按第五章计量，二者分别处理后再汇总。"},{"point":"统一汇总出口","detail":"各类最低资本最终均按第8号规则第八章、第9号规则第五章进行汇总。"}],"framework":"四分类对照表思路，逐类说明'计量哪类风险+用什么因子'。","memo":"易错：'无法穿透'因子虽统一为0.6，但风险类别不同（权益价格风险vs交易对手违约风险）；债权投资计划作表层时K=−0.2，作无法穿透资产时因子为0.6。","tag":""},{"id":"qa-07-07","difficulty":3,"q":"分析交易结构风险特征系数Kp的确定规则，并结合债权类与其他类的差异、公募REITs特殊规定说明监管逻辑。","answer_points":[{"point":"Kp的含义","detail":"Kp衡量交易结构层数带来的额外不透明风险，作为正项叠加在基础因子之上。"},{"point":"债权类公式","detail":"债权类资产Kp =（n−1）×0.1，其中n为交易结构层数（包括表层，不包括底层）。"},{"point":"其他非基础资产公式","detail":"其他非基础资产Kp = n×0.1，与债权类相比不扣减表层的1层。"},{"point":"公募REITs特例","detail":"公开募集基础设施证券投资基金计算底层资产最低资本时设定特征系数k1=−0.2，作为风险减项，体现对基础设施投资的鼓励。"},{"point":"监管逻辑","detail":"结构层数越多、信息越不透明、风险越高，故正向上浮因子；公募REITs给予负向优惠，引导资金投向基础设施。"},{"point":"封顶约束","detail":"Kp会使RF上浮，但受'RF超过1时取值为1'的封顶限制，不会无限放大。"}],"framework":"公式—分类差异—特例—监管逻辑—封顶 五段。","memo":"易错：n'含表层不含底层'；债权类减1（因表层本身已是债权）；公募REITs负系数k1=−0.2属特例。","tag":""},{"id":"qa-07-08","difficulty":3,"q":"说明非基础资产的信息获取与披露要求，以及无法获取季度信息时应如何处理（含监管逻辑）。","answer_points":[{"point":"信息时点要求","detail":"保险公司应使用本季度相关信息进行资产穿透计量，确保风险计量的时效性与真实性。"},{"point":"上季度兜底","detail":"因客观条件限制无法获取本季度信息的，可使用上季度投后报告等相关信息作为替代。"},{"point":"两级皆无的认定","detail":"本季度和上季度信息均无法获取的，应作为无法穿透的非基础资产，按第五章规定计量最低资本。"},{"point":"信息穿透披露","detail":"应在偿付能力报告中披露非基础资产的交易结构、交易对手、穿透后的底层资产等相关信息。"},{"point":"比例直接认定","detail":"非基础资产无法穿透的部分占90%以上的，保险公司可直接将其认定为无法穿透的非基础资产。"},{"point":"制度基础","detail":"公司应建立穿透计量管理制度，及时获取信息、识别交易结构、评估风险水平、准确计量最低资本。"}],"framework":"时点—上季兜底—认定—披露—制度 六级递进逻辑。","memo":"易错：处理路径是'本季→上季→无法穿透'三级递进；'无法穿透部分占90%以上'可直接认定。","tag":""}],"calc":[{"id":"c-07-01","difficulty":1,"stem":"某保险公司持有一项债权类信托计划（非基础资产），其交易结构为：表层信托计划→1层SPV→底层基础资产，即交易结构层数n=3（包括表层，不包括底层）。求该资产的交易结构风险特征系数Kp。","blanks":[{"label":"交易结构风险特征系数Kp","answer":0.2,"tolerance":0.01}],"steps":["第1步：确认资产类别与公式。本题为债权类非基础资产，适用Kp =（n−1）×0.1。","第2步：代入层数n=3，得Kp =（3−1）×0.1 = 2×0.1 = 0.2。"],"formula_card":"债权类资产：Kp =（n−1）×0.1；n为交易结构层数（含表层、不含底层）","analysis":"债权类资产Kp公式需在层数n的基础上减1，因为表层本身已是债权，不额外计一层风险。代入n=3得Kp=0.2，即该信托计划因含2层中间结构，交易结构风险特征系数为0.2，将在底层资产风险因子中作为正项叠加。","trap":"易错点：①混淆'其他非基础资产Kp=n×0.1'与债权类'（n−1）×0.1'；②忘记n'含表层不含底层'，把底层也算进去。","tag":""},{"id":"c-07-02","difficulty":2,"stem":"某保险公司通过一项股权投资基金（其他类非基础资产，交易结构层数n=2）持有某底层资产，该底层为基础资产上市股票，认可价值（风险暴露）EX=4000万元，基础因子RF0=0.35，特征系数K=−0.05（沪深300指数成份股）。求该底层资产的风险因子RF及最低资本MC。","blanks":[{"label":"底层资产风险因子RF","answer":0.4025,"tolerance":0.001},{"label":"底层资产最低资本MC（万元）","answer":1610,"tolerance":0.5}],"steps":["第1步：计算交易结构风险特征系数Kp。其他类非基础资产Kp = n×0.1 = 2×0.1 = 0.2。","第2步：计算风险因子RF = RF0×(1 + K + Kp) = 0.35×(1 − 0.05 + 0.2) = 0.35×1.15 = 0.4025（<1，不封顶）。","第3步：计算最低资本MC = EX×RF = 4000×0.4025 = 1610（万元）。"],"formula_card":"MC底层 = EX×RF0×(1+K+Kp)；其他类Kp=n×0.1；RF>1时取1","analysis":"先由类别（其他类）和层数n=2得Kp=0.2，再与基础因子0.35、特征系数−0.05合成RF=0.4025。因沪深300成份股k2=−0.05为风险减项，RF低于基础因子0.35的水平被拉回。最终MC=4000×0.4025=1610万元。验算：0.35×1.15=0.4025，4000×0.4025=1610，无误。","trap":"易错点：①用错Kp公式（债权类才减1，其他类不减）；②忘记K=−0.05是减项；③RF=0.4025未超1，但部分人会误触发封顶。","tag":""},{"id":"c-07-03","difficulty":3,"stem":"某保险公司持有一项债权类信托计划（非基础资产），交易结构为：表层信托计划→1层SPV→底层基础资产债券，交易结构层数n=2（含表层、不含底层）。底层资产债券认可价值EX=8000万元，基础因子RF0=0.02，特征系数K=0；表层资产（信托受益权，债权类，信用评级AA）认可价值=8000万元。要求：（1）计算交易结构风险特征系数Kp；（2）计算底层资产最低资本MC底层；（3）计算表层资产交易对手违约风险最低资本MC表层（AA评级RF0=0.02，信托计划K表层=0）。","blanks":[{"label":"交易结构风险特征系数Kp","answer":0.1,"tolerance":0.01},{"label":"底层资产最低资本MC底层（万元）","answer":176,"tolerance":0.5},{"label":"表层资产最低资本MC表层（万元）","answer":160,"tolerance":0.5}],"steps":["第1步：计算Kp。债权类Kp =（n−1）×0.1 =（2−1）×0.1 = 0.1。","第2步：底层资产。RF底层 = RF0×(1+K+Kp) = 0.02×(1+0+0.1) = 0.022；MC底层 = 8000×0.022 = 176（万元）。","第3步：表层资产。AA评级RF0=0.02，信托计划（非债权投资计划）K表层=0，RF表层=0.02×(1+0)=0.02；MC表层 = 8000×0.02 = 160（万元）。"],"formula_card":"Kp(债权)=(n−1)×0.1；MC底层=EX×RF0×(1+K+Kp)；MC表层=EX×RF0×(1+K表层)，AA评级RF0=0.02","analysis":"本题综合考查'底层+表层'两步穿透计量。底层因含1层SPV使Kp=0.1，RF=0.022，MC=176万元；表层为债权类AA级，信托计划不适用债权投资计划的K=−0.2优惠，故K表层=0，RF=0.02，MC=160万元。两项应分别计量后并入汇总。验算：0.02×1.1=0.022、8000×0.022=176；0.02×1=0.02、8000×0.02=160，均无误。","trap":"易错点：①把信托计划表层误用债权投资计划的K=−0.2（实际仅'债权投资计划'作为表层时才−0.2）；②n层数把底层算入得Kp=0.2；③遗漏表层资产须单独计量交易对手违约风险。","tag":""}]},{"id":"rule-08","group":"监管规则","name":"第8号 市场风险最低资本","qa":[{"id":"qa-08-01","difficulty":1,"q":"简述市场风险的定义、六大类划分及本规则的适用范围。","answer_points":[{"point":"市场风险定义","detail":"由于利率、权益价格、房地产价格、汇率等不利变动，导致保险公司遭受非预期损失的风险。"},{"point":"六大类划分","detail":"包括利率风险、权益价格风险、房地产价格风险、境外资产价格风险、汇率风险和集中度风险。"},{"point":"适用范围","detail":"适用于境内经营商业保险业务的保险公司和外国保险公司分公司，相互保险组织也适用。"},{"point":"与第7号分工","detail":"基础资产的市场风险按本规则计量；非基础资产的市场风险按第7号规则（穿透计量）计量。"},{"point":"规则沿革","detail":"本规则于2015年2月13日第一次发布，于2021年12月30日修订发布。"}],"framework":"定义—分类—适用—分工 四段式。","memo":"易错：保险风险不属于市场风险；六大类中'集中度风险'最容易被漏掉。","tag":""},{"id":"qa-08-02","difficulty":1,"q":"说明市场风险综合因子法的基本公式，以及各参数的取值边界。","answer_points":[{"point":"基本公式","detail":"MC市场 = EX × RF，即风险暴露乘以风险因子，这是除人身险利率风险外各类市场风险统一的计量方法。"},{"point":"风险暴露EX","detail":"EX等于该项资产（负债）的认可价值；当EX≤0时，EX取值为0。"},{"point":"风险因子RF","detail":"RF = RF0 ×（1 + K），其中RF0为基础因子，K为特征系数之和；当RF≥1时，RF取值为1。"},{"point":"特征系数K区间","detail":"K = k1 + k2 + … + kn，取值区间为[−0.25, 0.25]（银保监会另有规定的除外）。"},{"point":"方法例外","detail":"除人身保险公司的利率风险最低资本采用情景法外，其他市场风险最低资本均采用综合因子法。"}],"framework":"公式—EX—RF—K 四步，最后点明情景法例外。","memo":"易错：EX是'认可价值'而非账面价值；RF封顶为1；K区间严格为±0.25。","tag":""},{"id":"qa-08-03","difficulty":2,"q":"对比财产保险公司与人身保险公司利率风险最低资本的计量方法差异。","answer_points":[{"point":"财产险：综合因子法","detail":"公司债券利率风险基础因子按修正久期D分段计算，体现久期越长利率风险越大。"},{"point":"分段公式","detail":"0<D≤5时RF0=D×(−0.001D+0.0217)；5<D≤10时RF0=D×(−0.00106D+0.022)；D>10时RF0=D×0.0114。"},{"point":"财险计量范围","detail":"含央行票据、短期融资券等债券资产，但不含可转债（可交换债），可转债计入权益价格风险（因子0.23）。"},{"point":"人身险：情景法","detail":"MC利率风险 = Max[PV(NCF)不利情景 − PV(NCF)基础情景，0]，反映利率不利变动对资产负债的综合影响。"},{"point":"人身险计量范围","detail":"含存款、债券、其他固定收益类投资资产、利率类金融衍生品、保单质押贷款，但不含上市股票。"},{"point":"折现率曲线","detail":"由基础利率曲线加综合溢价形成，基础曲线分期望无风险收益率曲线、终极利率过渡曲线、终极利率水平三段，均由银保监会确定。"}],"framework":"方法对比—财险分段—人身险情景—计量范围—折现率 六步。","memo":"易错：财险用'久期因子法'、人身险用'情景法'；可转债不计入利率风险而计入权益价格风险。","tag":""},{"id":"qa-08-04","difficulty":2,"q":"说明权益价格风险各类资产的基础因子赋值。","answer_points":[{"point":"上市普通股票","detail":"沪深主板基础因子0.35，创业板、科创板0.45；沪深300指数成份股设特征系数k2=−0.05（风险减项）。"},{"point":"未上市股权","detail":"基础因子为0.41。未上市股权没有活跃市场报价、估值透明度低且退出渠道有限，因此高于沪深主板上市股的0.35，但低于波动更大的创业板、科创板的0.45。"},{"point":"长期股权投资","detail":"对子公司、合营企业和联营企业的长期股权投资基础因子为1；例外：保险类子公司0.35，合营联营企业若为上市0.35、非上市0.41。"},{"point":"证券投资基金","detail":"债券基金0.06、股票基金0.28、混合基金及商品金融衍生品基金0.23、货币市场基金0.01。"},{"point":"可转债（可交换债）","detail":"基础因子为0.23，归入权益价格风险而非利率风险。"},{"point":"优先股与永续债","detail":"按是否带强制转换/减记条款、发行人类型及资本充足率赋值，如不带条款0.15、资本充足率未全部达标0.45、非金融机构不带强转0.10。"}],"framework":"股票—股权—长期股权—基金—可转债—优先股 六类对照。","memo":"易错：沪深300是k2=−0.05负向优惠；可转债归权益价格风险；长期股权投资基础因子通常为1而非0.35。","tag":""},{"id":"qa-08-05","difficulty":2,"q":"说明汇率风险最低资本的计量规则，包括风险暴露、币种处理与基础因子。","answer_points":[{"point":"风险暴露","detail":"为同币种资产认可价值减去同币种负债认可价值的净额的绝对值，包含外汇衍生品的价值变动。"},{"point":"分币种对冲汇总","detail":"应区分币种进行对冲后汇总，即先按币种轧差再跨币种汇总，不能直接整体轧差。"},{"point":"基础因子赋值","detail":"美元及汇率跟美元挂钩的货币为0.05；欧元、英镑为0.08；其他货币为0.15。"},{"point":"同币种认定","detail":"美元和汇率跟美元挂钩的货币之间可视为同币种计算金额，便于轧差。"},{"point":"实务含义","detail":"通过分币种净额计量，监管既认可自然对冲，又对高波动非挂钩货币施加更高因子。"}],"framework":"暴露—币种—因子—认定 四步。","memo":"易错：暴露是'净额的绝对值'而非总额；欧元英镑因子0.08而非0.15；美元挂钩货币视为同币种。","tag":""},{"id":"qa-08-06","difficulty":3,"q":"综合说明集中度风险的三类构成及其特征系数、触发条件，并结合监管逻辑分析调控性特征因子的作用。","answer_points":[{"point":"交易对手集中度","detail":"特征系数k集中度1=0.4，按穿透原则确定交易对手，阈值按总资产规模超额累退，总资产5亿元以下公司不计提。"},{"point":"大类资产集中度","detail":"特征系数k集中度2=0.2，针对同类资产风险敞口过度集中设置。"},{"point":"房地产集中度","detail":"特征系数k集中度3=0.5，当投资性房地产账面价值占总资产比例超过25%时触发。"},{"point":"豁免情形","detail":"政府债券、国有大型商业银行存款及产品、货币市场类保险资管产品、投资性房地产等可不计量交易对手集中度风险。"},{"point":"调控性特征因子","detail":"对于保险资金支持国家战略形成的投资资产，银保监会可设置调控性特征因子，体现监管支持与引导。"},{"point":"监管逻辑","detail":"集中度风险防止单一交易对手或同类资产过度集中引发连锁损失，而调控性因子则在防风险的同时引导资金服务实体经济与国家战略。"}],"framework":"三类—系数—触发—豁免—调控因子—逻辑 六段。","memo":"易错：房地产集中度阈值25%对应k3=0.5；总资产5亿元以下免交易对手集中度；调控性因子是'鼓励'而非'惩罚'。","tag":""},{"id":"qa-08-07","difficulty":3,"q":"说明市场风险最低资本的汇总方法（相关系数矩阵），并结合境外资产的相关系数说明跨市场风险分散效应。","answer_points":[{"point":"汇总公式","detail":"MC市场 = MC向量 × M相关系数 × MC向量ᵀ，即通过相关系数矩阵对六类风险进行加权汇总。"},{"point":"风险向量构成","detail":"MC向量由利率、权益价格、房地产、境外固收、境外权益及房地产、汇率六项市场风险最低资本组成。"},{"point":"境外固收相关系数","detail":"境外固收类资产中，发达市场与新兴市场之间的相关系数ρ=0.1365，相关性较弱。"},{"point":"境外权益相关系数","detail":"境外权益类资产中，发达与新兴市场之间的相关系数ρ=0.375，相关性相对更强。"},{"point":"分散效应","detail":"由于相关系数小于1，矩阵汇总结果低于各类最低资本的简单加总，体现跨市场、跨币种的风险分散。"},{"point":"监管含义","detail":"适度境外多元配置可利用分散效应降低资本占用，但新兴市场仍设k1=0.25上浮因子以反映更高风险。"}],"framework":"公式—向量—两类相关系数—分散效应—含义 五步。","memo":"易错：境外固收ρ=0.1365小于境外权益ρ=0.375；汇总用矩阵法而非简单加总；新兴市场主体k1=0.25。","tag":""},{"id":"qa-08-08","difficulty":3,"q":"分析基础资产与第7号非基础资产在市场风险计量上的衔接关系，并说明套期保值与风险缓释的监管要求。","answer_points":[{"point":"计量分工","detail":"基础资产按第8号（综合因子法/情景法）计量；非基础资产先按第7号穿透，再并入第8号框架计量。"},{"point":"利率风险衔接","detail":"非基础资产穿透后的底层固定收益类资产，人身险公司不计量利率风险，财产险公司仍需计量，体现规则衔接差异。"},{"point":"统一汇总出口","detail":"穿透计量结果最终并入第8号第八章的相关系数矩阵，与基础资产风险统一汇总。"},{"point":"套期保值要求","detail":"须符合会计准则规定的套期有效性要求，且套期期限不低于1个月，方可将衍生品空头与被套期组合合并计算最低资本。"},{"point":"风险缓释与表外","detail":"采取市场风险缓释或增强安排的计量标准，以及表外业务的市场风险计量标准，均由银保监会另行规定。"},{"point":"国债期货多头","detail":"不符合合并条件的国债期货多头应单独计量最低资本，公式为合约价值×风险因子。"}],"framework":"分工—衔接—汇总—套保—缓释—特例 六段。","memo":"易错：人身险穿透后底层固收'不计量'利率风险；套期须同时满足'有效性+期限≥1个月'；期货多头须单独计量。","tag":""}],"calc":[{"id":"c-08-01","difficulty":1,"stem":"某财产保险公司持有沪深主板上市普通股，认可价值（风险暴露）EX=2000万元，基础因子RF0=0.35，该股票非沪深300指数成份股（特征系数K=0）。求该笔股票投资的权益价格风险最低资本MC。","blanks":[{"label":"权益价格风险最低资本MC（万元）","answer":700,"tolerance":0.5}],"steps":["第1步：确定风险因子。RF = RF0×(1+K) = 0.35×(1+0) = 0.35（<1，不封顶）。","第2步：计算最低资本。MC = EX×RF = 2000×0.35 = 700（万元）。"],"formula_card":"MC = EX×RF0×(1+K)；沪深主板股票RF0=0.35，沪深300成份股k2=−0.05","analysis":"直接套用综合因子法，沪深主板普通股票基础因子0.35，非沪深300故K=0，RF=0.35未超封顶1。最终MC=2000×0.35=700万元。验算：2000×0.35=700，无误。","trap":"易错点：①误用创业板/科创板因子0.45；②忘记沪深300成份股才有k2=−0.05，本题非成份股K=0；③EX应为认可价值。","tag":""},{"id":"c-08-02","difficulty":2,"stem":"某保险公司以物权形式持有境内投资性房地产，位于境内非直辖市、非省会城市、非计划单列市地区，认可价值（风险暴露）EX=2000万元。求该投资性房地产的房地产价格风险最低资本MC。","blanks":[{"label":"房地产价格风险因子RF","answer":0.18,"tolerance":0.001},{"label":"房地产价格风险最低资本MC（万元）","answer":360,"tolerance":0.5}],"steps":["第1步：确定因子。物权投资性房地产RF0=0.15；境内其他地区位置特征系数k1=0.2（直辖市、省会、计划单列市k1=0）。","第2步：计算RF = RF0×(1+k1) = 0.15×(1+0.2) = 0.15×1.2 = 0.18（<1）。","第3步：计算MC = EX×RF = 2000×0.18 = 360（万元）。"],"formula_card":"MC = EX×RF0×(1+k1)；物权投资性房地产RF0=0.15，境内其他地区k1=0.2","analysis":"本题两步：先由资产位置确定k1=0.2合成RF=0.18，再乘认可价值得MC=360万元。若为直辖市等地区则k1=0、RF=0.15、MC=300万元。验算：0.15×1.2=0.18，2000×0.18=360，无误。","trap":"易错点：①混淆位置系数，直辖市/省会/计划单列市k1=0，仅'境内其他地区'才0.2；②漏乘(1+k1)直接用0.15；③RF未超1不封顶。","tag":""},{"id":"c-08-03","difficulty":3,"stem":"某保险公司持有两类境外固定收益类资产：发达市场部分最低资本MC1=500万元（k1=0，已按综合因子法计算），新兴市场部分最低资本MC2=300万元（k1=0.25，已计算）。已知境外固定收益类资产发达市场与新兴市场之间的相关系数ρ=0.1365。要求：（1）用相关系数矩阵法计算境外固定收益类资产汇总后的最低资本；（2）判断若仅按单一最大敞口（500万元）计提，与汇总结果相比是低估还是高估风险。","blanks":[{"label":"境外固收汇总最低资本（万元）","answer":617.21,"tolerance":0.5},{"label":"简单加总（万元，用于对比）","answer":800,"tolerance":0.5}],"steps":["第1步：写出两资产汇总公式。MC = √(MC1² + MC2² + 2×ρ×MC1×MC2)。","第2步：代入数值。MC1²=250000，MC2²=90000，2×ρ×MC1×MC2=2×0.1365×500×300=40950。","第3步：求和开方。250000+90000+40950=380950；√380950≈617.21（万元）。","第4步：判断。简单加总=500+300=800万元；617.21<800，仅按最大敞口500万元计提则低于汇总617.21万元，属低估风险。"],"formula_card":"两资产汇总：MC=√(MC1²+MC2²+2×ρ×MC1×MC2)；境外固收ρ=0.1365","analysis":"因相关系数ρ=0.1365<1，跨市场存在风险分散效应，汇总结果617.21万元介于单一最大敞口500万元与简单加总800万元之间：仅计提500万元会低估风险，简单加总800万元会高估风险。验算：250000+90000+40950=380950，√380950≈617.21，无误。","trap":"易错点：①误用境外权益相关系数0.375（本题是境外固收，应用0.1365）；②忘记是'平方和加2ρ交叉项'再开方，而非直接相加；③混淆'单一最大敞口'与'汇总'的低估/高估方向。","tag":""}]},{"id":"rule-09","group":"监管规则","name":"第9号 信用风险最低资本","qa":[{"id":"qa-09-01","difficulty":1,"q":"请简述保险公司信用风险的定义，并说明其包含的三类子风险及各自的风险来源。","answer_points":[{"point":"信用风险总体定义","detail":"信用风险是指由于利差的不利变动、交易对手不能履行或不能按时履行合同义务、或交易对手信用状况不利变动，导致保险公司遭受非预期损失的风险，是偿二代二期量化风险最低资本的重要组成部分。"},{"point":"利差风险","detail":"指资产的收益率超过无风险利率的部分（即利差）发生不利变动，导致非预期损失的风险，主要源于持有固定收益类资产时的利率与信用利差波动。"},{"point":"交易对手违约风险","detail":"指交易对手不能履行或不能按时履行其合同义务，导致非预期损失的风险，典型如再保险分入人、存款银行、保单质押贷款借款人违约。"},{"point":"集中度风险","detail":"指对同一交易对手或同类资产的风险敞口过于集中，导致非预期损失的风险，按第8号规则第七章计量，是信用风险三类子风险之一。"},{"point":"适用与归属","detail":"本规则适用于境内保险公司及外国保险公司分公司、相互保险组织；基础资产按本规则计量，非基础资产按第7号规则穿透计量。"}],"framework":"定义—三类子风险（利差/违约/集中度）各自来源—归属量化风险最低资本。","memo":"信用风险三类＝利差风险＋交易对手违约风险＋集中度风险，莫与市场风险混淆。","tag":""},{"id":"qa-09-02","difficulty":1,"q":"说明信用风险最低资本基本公式 MC信用＝EX×RF 中各符号含义，以及风险因子 RF 的计算方法。","answer_points":[{"point":"基本公式","detail":"MC信用＝EX×RF，EX为风险暴露（如资产账面价值或担保金额），RF为风险因子，二者相乘得到该类资产信用风险最低资本。"},{"point":"RF0与K","detail":"RF＝RF0×(1+K)，其中RF0为基础因子，K为特征系数，等于各特征系数ki之和，用于刻画资产特定风险特征。"},{"point":"RF上限限制","detail":"当计算得到的RF≥1时取值为1，监管不允许风险因子放大超过1倍，防止最低资本被过度调减或调增失控。"},{"point":"K的取值范围","detail":"K∈[-0.25,0.25]，即各类特征系数之和被限制在±0.25区间，银保监会另有规定的除外。"},{"point":"计量口径","detail":"计量某类资产信用风险时应对各项资产（负债）分别计量，不得按类别合并计量，确保各笔敞口准确反映风险。"}],"framework":"公式结构—RF0/K含义—RF上限—K区间—分别计量要求。","memo":"RF＝RF0×(1+K)，RF≥1取1；K∈[-0.25,0.25]。","tag":""},{"id":"qa-09-03","difficulty":2,"q":"当保险公司使用信用风险缓释工具或信用保护工具时，应如何合并计量最低资本？说明调整后评级的确定原则。","answer_points":[{"point":"合并计算要求","detail":"标的资产及缓释（保护）工具的最低资本应合并计算，不能将二者割裂，缓释工具的风险暴露为其账面价值。"},{"point":"调整后评级确定","detail":"应以缓释工具创设机构主体信用评级与标的资产信用评级孰高原则确定调整后评级，从而确定调整后的基础因子。"},{"point":"拆分计量","detail":"合并计算采用 MC信用＝EXA×RF调整后＋EXB×RF调整前，将资产拆分为受缓释覆盖部分（A）和未覆盖部分（B）分别计量。"},{"point":"仍须计量","detail":"使用缓释工具后并非一律免于计量，只是依调整后评级降低相应部分的风险因子，仍需就未覆盖敞口计提最低资本。"},{"point":"监管目的","detail":"该处理承认缓释工具降低信用风险的作用，同时通过评级孰高防止过度高估缓释效果，体现审慎原则。"}],"framework":"合并计算—评级孰高—A/B拆分—并非免计量—审慎逻辑。","memo":"评级“孰高”确定调整后RF；缓释工具风险暴露＝账面价值；非免计量。","tag":""},{"id":"qa-09-04","difficulty":2,"q":"说明境内标准化债权类资产利差风险基础因子 RF0 的计算规则（以政策性银行金融债、政府支持机构债券为例），并指出浮息债与赎回安排下的久期处理。","answer_points":[{"point":"政策性银行金融债（D≤5）","detail":"0＜D≤5时 RF0＝D×(-0.0012×D＋0.012)，久期越短因子越小，体现短期利差风险较低。"},{"point":"政策性银行金融债（D＞5）","detail":"D＞5时 RF0＝D×0.001＋0.025，久期越长因子线性递增，反映长期利差风险上升。"},{"point":"政府支持机构债券","detail":"0＜D≤5时 RF0＝D×(-0.001×D＋0.012)，D＞5时 RF0＝D×0.001＋0.03，与政府支持机构债风险略高于政策性金融债一致。"},{"point":"浮息债久期","detail":"对浮息债，利差风险中的D取利率久期而非期限久期，因为浮息债现金流随利率重定，利率敏感度不同于期限。"},{"point":"赎回安排","detail":"存续期有赎回安排的按下一赎回日计算D，无赎回安排的按永续期限计算D，确保久期反映真实利率敏感期。"}],"framework":"两档分段公式—政金债vs政府支持机构债差异—浮息债利率久期—赎回/永续处理。","memo":"政府支持机构债D>5系数0.03高于政金债0.025；浮息债用利率久期。","tag":""},{"id":"qa-09-05","difficulty":2,"q":"列举保险公司主要交易对手违约风险基础因子 RF0 的取值（至少六项），并说明账龄与再保险分入人充足率对 RF0 的影响。","answer_points":[{"point":"现金与拆出资金","detail":"现金RF0＝0，拆出资金RF0＝0.03，体现现金无违约风险、拆出资金风险很低。"},{"point":"第三方支付/保单质押贷款","detail":"存放在第三方支付机构账户资金RF0＝0.05，保单质押贷款RF0＝0.05，有质押担保故因子较低。"},{"point":"定期存款","detail":"国有大型商业银行及政策性银行定期存款RF0＝0.005，非保本结构性存款RF0＝0.5，财务公司存款RF0＝0.1，风险随银行类型与产品保本性变化。"},{"point":"境内再保险分入人","detail":"按综合偿付能力充足率分档：200%及以上0.008、[150%,200%)0.013、[100%,150%)0.047、[50%,100%)0.261、50%以下或无数据0.745，充足率越低因子越高。"},{"point":"境外再保分入人","detail":"达标且有担保部分0.077、无担保部分0.499，不满足监管或无数据0.867，无法获取评级按CCC+以下对应RF0。"},{"point":"账龄影响","detail":"分入业务再保险资产账龄≤6月RF0＝0、(6,12]月0.7、12月以上1；应收保费其他业务账龄≤6月0、6-12月0.5、12月以上1，账龄越长违约风险越大。"}],"framework":"现金/拆出/支付/保单贷—存款分档—境内再保分档—境外再保—账龄分档。","memo":"国有大行定存0.005；非保本结构性存款0.5；再保分入人充足率5档。","tag":""},{"id":"qa-09-06","difficulty":3,"q":"综合分析信用风险最低资本的汇总机制：说明利差风险与交易对手违约风险如何汇总，集中度风险在哪个规则计量，并解释相关系数ρ＝0.25的监管含义。","answer_points":[{"point":"汇总公式","detail":"MC信用＝√(MC利差²＋2×ρ×MC利差×MC交易对手违约＋MC交易对手违约²)，是两类风险最低资本的相关系数法汇总。"},{"point":"相关系数ρ＝0.25","detail":"两类风险并非完全相关，取ρ＝0.25体现适度分散效应，低于完全相关的1、高于独立时的0，审慎且合理。"},{"point":"集中度风险归属","detail":"集中度风险定义为对同一交易对手或同类资产敞口过于集中导致的风险，不在此处直接加总，而是按第8号规则第七章计量。"},{"point":"分类计量前提","detail":"汇总前需对各类资产（负债）分别计量不得合并，利差风险仅对标准化债权类资产计量，交易对手违约风险对存款、再保、应收等逐项计量。"},{"point":"监管逻辑","detail":"将信用风险拆为利差与违约两维度分别计量再汇总，既细致刻画风险来源，又通过相关系数避免简单加总高估资本要求。"}],"framework":"汇总公式—ρ＝0.25含义—集中度归第8号—分类计量—监管逻辑。","memo":"汇总ρ＝0.25；集中度风险按第8号第七章，不在第9号加总。","tag":""},{"id":"qa-09-07","difficulty":3,"q":"对比分析第9号规则中关于信用评级使用、政府债券处理、分别计量、境外再保评级缺失等监管要求，说明其共同的审慎逻辑。","answer_points":[{"point":"外部评级使用","detail":"境内按境内评级机构、境外按国际公认机构，多家评级从低适用，编报用最近一期合格评级并定期跟踪，确保评级客观反映风险。"},{"point":"政府债券与央行票据","detail":"政府债券和央行票据不计量信用风险最低资本（银保监会另有规定除外），因其违约概率极低视作无信用风险。"},{"point":"分别计量","detail":"计量某类资产应对各项资产（负债）分别计量，不得按类别合并，防止低风险敞口被高风险平均掩盖。"},{"point":"境外再保评级缺失","detail":"无法获取境外再保险分入人最近一年内信用评级的，按CCC+以下评级对应RF0计算，以保守方式兜底。"},{"point":"监管兜底权","detail":"银保监会认为外部评级不能客观反映风险的，有权要求调整评级或指定因子；无法获取商业银行资本充足率数据的按所属类型最高一档因子。"},{"point":"共同审慎逻辑","detail":"上述要求一致体现“宁可高估风险、不可低估”的审慎原则，通过从低评级、禁止合并、缺失即从严保障最低资本充足。"}],"framework":"评级从低—政府债免计量—分别计量—缺失从严—监管兜底—审慎逻辑。","memo":"多家评级从低适用；境外再保无评级→CCC+以下；缺失即从严。","tag":""},{"id":"qa-09-08","difficulty":3,"q":"综合说明应收账款类（应收保费、分入业务再保险资产）交易对手违约风险基础因子的账龄分档规则，并对比政府补贴类业务的特殊规定。","answer_points":[{"point":"分入业务再保险资产账龄","detail":"账龄≤6个月RF0＝0，(6,12]个月RF0＝0.7，12个月以上RF0＝1，短账龄视为低风险。"},{"point":"应收保费（其他业务）账龄","detail":"其他业务账龄≤6个月RF0＝0，(6,12]个月RF0＝0.5，12个月以上RF0＝1。"},{"point":"政府补贴类业务特殊档","detail":"农业保险、大病保险等政府补贴业务账龄≤9月RF0＝0、(9,12]月0.2、(12,18]月0.7、18月以上1，宽限期更长因财政结算慢。"},{"point":"零因子项目","detail":"预付赔款、待抵扣预交税费RF0＝0，不视为信用风险敞口。"},{"point":"监管逻辑","detail":"账龄越长回收不确定性越大故因子递增；对政府补贴业务给予更宽容账龄，反映其实际回款风险低、财政兜底的实务特征。"}],"framework":"再保资产账龄三档—应收保费其他业务三档—政府补贴四档—零因子—逻辑。","memo":"政府补贴业务账龄≤9月即0、宽限至18月；其他业务仅≤6月为0。","tag":""}],"calc":[{"id":"c-09-01","difficulty":1,"stem":"某保险公司持有政策性银行发行的金融债券，资产修正久期D＝6年（D＞5）。试计算该资产利差风险基础因子RF0。","blanks":[{"label":"利差风险基础因子RF0","answer":0.031,"tolerance":0.001}],"steps":["第1步：判断区间，D＝6＞5，适用长期档公式 RF0＝D×0.001＋0.025。","第2步：代入 RF0＝6×0.001＋0.025＝0.006＋0.025＝0.031。","第3步：结果 RF0＝0.031，后续用于 MC利差＝EX×RF0。"],"formula_card":"D＞5时：RF0＝D×0.001＋0.025（政策性银行金融债）","analysis":"因D＝6大于5，采用长期档公式，计算得RF0＝0.031。该因子用于后续MC利差＝EX×RF0，结果合理：久期越长利差风险因子越大。","trap":"注意区分D≤5与D＞5两档公式；政策性银行债与政府支持机构债的长期档常数项不同（0.025 vs 0.03）。","tag":""},{"id":"c-09-02","difficulty":2,"stem":"保险公司持有一笔保单质押贷款，风险暴露EX＝20,000万元，基础因子RF0＝0.05，适用某特征系数K＝0.1。试计算风险因子RF及该笔贷款交易对手违约风险最低资本MC信用。","blanks":[{"label":"风险因子RF","answer":0.055,"tolerance":0.001},{"label":"交易对手违约风险最低资本MC信用（万元）","answer":1100,"tolerance":0.5}],"steps":["第1步：计算RF＝RF0×(1+K)＝0.05×(1+0.1)＝0.055。","第2步：计算MC信用＝EX×RF＝20000×0.055＝1100万元。","第3步：结果 RF＝0.055，MC信用＝1100万元。"],"formula_card":"RF＝RF0×(1+K)，MC信用＝EX×RF（RF≥1时取值为1）","analysis":"RF＝0.055未超过1，无需封顶；MC信用＝20000×0.055＝1100万元。K为正则因子上调、资本增加，体现额外风险特征的审慎加成。","trap":"K∈[-0.25,0.25]，本题K＝0.1在范围内；若RF≥1须取值为1而非继续放大。","tag":""},{"id":"c-09-03","difficulty":3,"stem":"某保险公司报告期末：①持有政策性银行金融债，修正久期D＝8年，风险暴露EX利差＝50,000万元；②存放国有大型商业银行定期存款，风险暴露EX存款＝30,000万元，RF0＝0.005、K＝0。分别计算利差风险最低资本、交易对手违约风险最低资本，并按ρ＝0.25汇总信用风险最低资本MC信用。","blanks":[{"label":"利差风险最低资本MC利差（万元）","answer":1650,"tolerance":0.5},{"label":"交易对手违约风险最低资本MC交易对手（万元）","answer":150,"tolerance":0.5},{"label":"信用风险最低资本MC信用（万元）","answer":1693.74,"tolerance":0.5}],"steps":["第1步：MC利差＝EX利差×RF0(D>5)＝50000×(8×0.001＋0.025)＝50000×0.033＝1650万元。","第2步：MC交易对手＝EX存款×RF0×(1+K)＝30000×0.005×1＝150万元。","第3步：MC信用＝√(1650²＋2×0.25×1650×150＋150²)＝√(2722500＋123750＋22500)＝√2868750≈1693.74万元。"],"formula_card":"MC信用＝√(MC利差²＋2ρ·MC利差·MC交易对手＋MC交易对手²)，ρ＝0.25","analysis":"MC利差＝1650万元，MC交易对手＝150万元，汇总得MC信用≈1693.74万元，低于两子项简单相加（1800万元），体现ρ＝0.25的分散效应。计算经两遍验算一致。","trap":"汇总必须用相关系数法开平方，不能简单相加；D＝8＞5用长期档公式（8×0.001＋0.025＝0.033），勿误用D≤5档。","tag":""}]},{"id":"rule-10","group":"监管规则","name":"第10号 压力测试","qa":[{"id":"qa-10-01","difficulty":1,"q":"简述保险公司偿付能力压力测试的定义，并说明压力测试分为哪三类方法，各自评估什么。","answer_points":[{"point":"压力测试定义","detail":"压力测试是保险公司在基本情景和各种压力情景下，对未来一段时间内偿付能力充足率进行预测和评价，用以识别和预警不达标的主要风险因素。"},{"point":"情景法测试","detail":"评估多种风险因素同时联动变化情景下，对公司偿付能力充足率的影响，捕捉风险共振效应。"},{"point":"敏感性测试","detail":"评估某一特定风险因素的变动对公司偿付能力充足率的影响，定位单一风险敏感度。"},{"point":"反向压力测试","detail":"针对特定风险因素，反向评估偿付能力充足率不达标时该风险因素的不利变动幅度，用于底线排查。"},{"point":"季度与年度归属","detail":"季度压力测试为敏感性测试，年度压力测试包括全部三类，测试方法体系完整覆盖常态与极端情形。"}],"framework":"定义—三类（情景法/敏感性/反向）各自评估对象—季度属敏感性、年度含三类。","memo":"三类＝情景法＋敏感性＋反向；季度测试＝敏感性测试。","tag":""},{"id":"qa-10-02","difficulty":1,"q":"说明季度压力测试与年度压力测试在测试类型、预测期间上的主要区别。","answer_points":[{"point":"季度测试类型","detail":"季度压力测试为动态单因素敏感性测试，评估下一季度末实际资本、核心资本、最低资本、溢额及充足率等指标变化。"},{"point":"年度测试类型","detail":"年度压力测试包括情景法测试、敏感性测试和反向压力测试三类，分析更全面。"},{"point":"基本情景预测期间","detail":"基本情景下预测报告年度后未来两个会计年度末的偿付能力指标，给出中期展望。"},{"point":"压力情景测试期间","detail":"压力情景（情景法）下测试未来一个会计年度末的指标，聚焦短期冲击。"},{"point":"差异逻辑","detail":"季度重短期单因素、年度重多情景多期间，二者频率与深度互补，共同支撑偿付能力预警。"}],"framework":"季度＝动态单因素敏感性—年度＝三类—基本情景2年/压力情景1年。","memo":"季度＝下一季度末；基本情景预测2个会计年度末，压力情景测1个会计年度末。","tag":""},{"id":"qa-10-03","difficulty":2,"q":"基本情景预测中对资本补充事项和股利分配计划的处理有何规定？说明其监管意图。","answer_points":[{"point":"资本补充事项","detail":"预测应反映银保监会已批准（认可）的增资和资本补充工具发行，不应考虑测试期间内未获批准（认可）的资本补充行为。"},{"point":"股利分配计划","detail":"基本情景下的预测应反映公司的股利分配计划，即使该计划尚未得到批准，因为分红会减少实际资本。"},{"point":"新业务与费用假设","detail":"新业务假设应与经批准的业务规划一致，费用假设与批准的财务预算一致，投资假设与战略资产配置规划一致。"},{"point":"监管意图","detail":"既防止公司把未批资本补充“画饼”抬高预测，又要求如实扣减已定分红，确保基本情景预测审慎、可落地。"}],"framework":"已批资本补充计入—未批不计—分红计划照扣—假设一致性—审慎意图。","memo":"已批准资本补充计入，未批准不计入；分红计划即使未批也要扣减。","tag":""},{"id":"qa-10-04","difficulty":2,"q":"说明反向压力测试的适用条件、测试假设及核心计算目标。","answer_points":[{"point":"适用条件","detail":"基本情景下报告年度后未来一个会计年度末综合偿付能力充足率处于100%~150%之间的保险公司，应开展反向压力测试。"},{"point":"测试假设","detail":"假设下一个会计年度末综合偿付能力充足率降低至100%的水平（即监管红线），反推风险因素变动。"},{"point":"计算目标","detail":"计算导致充足率降至100%的最主要风险因素的不利变动幅度，定位公司最脆弱的风险点。"},{"point":"触发背景","detail":"该区间公司贴近不达标边缘，需提前识别哪一风险因素稍恶化即击穿红线，便于前置管理。"}],"framework":"触发区间100%~150%—假设降至100%—反推最主要风险因素变动幅度。","memo":"反向测试触发：综合充足率100%~150%；假设降至100%反推风险变动。","tag":""},{"id":"qa-10-05","difficulty":2,"q":"说明年度压力测试报告的报送、批准与独立第三方审核要求。","answer_points":[{"point":"报送时间","detail":"保险公司应在每年5月31日前向银保监会报送年度压力测试报告。"},{"point":"董事会批准与责任","detail":"报告应经董事会批准，董事会对压力测试的合规性和合理性承担最终责任。"},{"point":"第三方审核","detail":"报告须经独立第三方机构（会计师事务所、精算咨询顾问公司等）审核；除会计师事务所外其他机构从事审核应报银保监会备案。"},{"point":"模型评估校验","detail":"保险公司应每年评估和校验压力测试模型、预测方法和关键假设，保证方法持续有效。"}],"framework":"5月31日前报送—董事会批准担责—第三方审核（其他机构备案）—年度评估校验。","memo":"5月31日前报送；董事会最终责任；非会计师事务所审核须备案。","tag":""},{"id":"qa-10-06","difficulty":3,"q":"综合说明压力测试对象的覆盖范围、必测与自测风险因素的确定方式，以及特征因子在预测期的简化处理原则。","answer_points":[{"point":"测试对象范围","detail":"压力测试对象涵盖公司全部业务，包括报告期末有效业务和测试期间内的新业务，保险与非保险业务均须覆盖。"},{"point":"必测风险因素","detail":"必测风险因素和必测压力情景由银保监会统一确定发布并适时调整，体现行业一致底线。"},{"point":"自测风险因素","detail":"自选（自测）风险因素由保险公司基于自身风险状况选取；设置自测压力情景应选择至少两个重大风险因素。"},{"point":"特征因子简化","detail":"采用与评估日相同原则计量最低资本时，报告期特征因子大于0的假设预测期维持不变，小于等于0的假设预测期为0。"},{"point":"监管逻辑","detail":"统一必测保证可比、自测体现个性，特征因子简化避免对不确定优惠的过度外推，兼顾可操作与审慎。"}],"framework":"全业务覆盖—必测由银保监会/自测由公司—自测≥2因素—特征因子>0维持、≤0归零。","memo":"自测情景须≥2个重大风险因素；特征因子>0维持、≤0预测期为0。","tag":""},{"id":"qa-10-07","difficulty":3,"q":"对比说明年度压力测试报告的两类独立第三方审核机构（会计师事务所与其他机构）在签名资格与审核意见范围上的差异。","answer_points":[{"point":"会计师事务所签名","detail":"会计师事务所出具的审核报告由两名注册会计师签名并盖章，依审计准则执行。"},{"point":"其他机构签名资格","detail":"其他独立第三方机构（如精算咨询顾问）的审核报告，由两名在中国从事保险精算及相关工作3年以上、熟悉监管法规并具有精算师资格的精算师签名并盖章，且机构须报银保监会备案。"},{"point":"审核范围","detail":"审核范围包括实际资本/最低资本/充足率预测方法的合规合理、业务覆盖全面性、必测与自测情景的合规充分、披露信息真实完整等九项。"},{"point":"审核意见事项","detail":"审核意见针对预测假设是否为报告提供合理基础、报告是否依据假设并按监管规则编制列报；公司充足率是否达标不属于审核意见事项。"},{"point":"监管逻辑","detail":"以专业胜任与独立性保障压力测试可信，区分会计与精算视角，但均聚焦过程合规而非替公司担保结果达标。"}],"framework":"会计师事务所＝两注会—其他机构＝两精算师(3年+资格+备案)—审核九项范围—意见不含达标判定。","memo":"其他机构：两名在华3年以上精算师资格；审核意见不含“是否达标”。","tag":""},{"id":"qa-10-08","difficulty":3,"q":"综合说明人身保险公司测试对象分类、风险载体因子法适用条件及修正久期区间划分等量化实施要求。","answer_points":[{"point":"销售渠道分类","detail":"人身保险公司测试对象销售渠道至少划分为个险、银邮、团体、网销及其他共5类，保证渠道维度覆盖。"},{"point":"产品类型分类","detail":"非高利率产品至少进一步划分为长期传统、长期分红、万能等共10种类型，并区分1999年（含）前高利率产品，依第3号规则业务类别。"},{"point":"风险载体因子法条件","detail":"某二级或三级风险占风险分散效应前寿险业务保险风险最低资本的比例不大于15%时，可采用风险载体因子法简化计算该类风险最低资本。"},{"point":"修正久期区间","detail":"修正久期区间划分至少包括1及以下、1-3、3-5、5-7、7-10、10-15、15以上共七档，支持利率风险敏感性分组。"},{"point":"监管逻辑","detail":"通过细致分类与简化门槛，在确保测试颗粒度的同时降低中小风险子项的计量成本，提升年度测试可操作性。"}],"framework":"渠道5类—产品10类—风险载体因子法≤15%—久期7档—可操作逻辑。","memo":"风险载体因子法门槛＝占比≤15%；久期至少7档；销售渠道至少5类。","tag":""}],"calc":[{"id":"c-10-01","difficulty":1,"stem":"某人身保险公司评估时点风险分散效应前寿险业务保险风险最低资本为100亿元，其中某二级子类风险最低资本为13.5亿元。计算该子类风险占比，并判断能否采用风险载体因子法简化计算。","blanks":[{"label":"该二级风险占比（%）","answer":13.5,"tolerance":0.5}],"steps":["第1步：计算占比＝13.5÷100×100%＝13.5%。","第2步：判断13.5%≤15%，可以采用风险载体因子法。","第3步：结果占比13.5%，满足简化条件。"],"formula_card":"占比＝某二级/三级风险最低资本÷风险分散效应前寿险业务保险风险最低资本；≤15%可用风险载体因子法","analysis":"占比13.5%小于15%门槛，符合附件2风险载体因子法适用条件，可简化计量该类风险最低资本。计算无误。","trap":"分母是“风险分散效应前”寿险业务保险风险最低资本，不是分散后；门槛是15%不是10%或20%。","tag":""},{"id":"c-10-02","difficulty":2,"stem":"某公司基本情景下报告年度后未来一个会计年度末综合偿付能力充足率预测为128%，核心偿付能力充足率为55%。判断是否需要开展反向压力测试，并计算若假设综合充足率降至监管红线，需下降多少个百分点。","blanks":[{"label":"是否需开展反向压力测试（1＝是，0＝否）","answer":1,"tolerance":0},{"label":"综合偿付能力充足率需下降幅度（百分点）","answer":28,"tolerance":0.5}],"steps":["第1步：判断触发：综合充足率128%处于100%~150%区间→应开展反向压力测试（标记1）。","第2步：计算降幅：128%－100%＝28个百分点。","第3步：结果需下降28个百分点至红线100%。"],"formula_card":"触发：综合充足率∈(100%,150%]；反向测试假设降至100%","analysis":"128%落入触发区间，须开展反向压力测试，反推最主要风险因素需使综合充足率下降28个百分点至100%。核心充足率55%＞50%不单独触发管理措施条款。计算正确。","trap":"触发看的是综合充足率100%~150%，不是核心；降至的假设水平是100%而非50%。","tag":""},{"id":"c-10-03","difficulty":3,"stem":"某保险公司报告年度末综合偿付能力充足率＝145%、核心＝60%。基本情景预测下一会计年度末综合充足率维持145%、核心维持60%。①判断是否触发反向压力测试；②若反向测试假设综合充足率降至100%，计算需下降幅度；③判断在年度测试中是否需详细说明管理措施并提供预测值。","blanks":[{"label":"是否触发反向压力测试（1＝是，0＝否）","answer":1,"tolerance":0},{"label":"综合偿付能力充足率需下降幅度（百分点）","answer":45,"tolerance":0.5},{"label":"是否需说明管理措施并提供预测值（1＝是，0＝否）","answer":0,"tolerance":0}],"steps":["第1步：判断触发：基本情景下一会计年度末综合充足率145%∈(100%,150%]→触发反向压力测试（1）。","第2步：计算降幅：145%－100%＝45个百分点。","第3步：达标判断：年度测试中任一期末综合<100%或核心<50%才需说明措施；本题综合145%＞100%、核心60%＞50%→无需（0）。"],"formula_card":"反向测试触发：综合充足率100%~150%；措施触发：综合<100%或核心<50%","analysis":"综合145%触发反向测试，需降45个百分点至100%红线；但核心60%、综合145%均高于措施触发阈值，年度测试中暂不需说明管理措施。三步判断与计算均基于第10号规则阈值，结论正确。","trap":"反向测试触发（100%~150%）与“说明管理措施”触发（综合<100%或核心<50%）是两套不同阈值，勿混淆；145%只满足前者。","tag":""}]},{"id":"rule-11","group":"监管规则","name":"第11号 保险公司偿付能力监管规则第11号：风险综合评级（分类监管）","qa":[{"id":"qa-11-01","difficulty":1,"q":"简述保险公司偿付能力风险的整体构成，并说明固有风险进一步可划分为哪两类。","answer_points":[{"point":"偿付能力风险由固有风险和控制风险共同构成","detail":"固有风险是指在现有正常行业物质技术条件和生产组织方式下，保险公司经营活动中必然存在的客观风险；控制风险是因内部管理和控制不完善或无效，导致固有风险未被及时识别和控制的风险。两者叠加构成公司整体偿付能力风险。"},{"point":"固有风险进一步划分为可资本化风险与难以资本化风险","detail":"可资本化风险是可资本化为最低资本的固有风险，包括保险风险、市场风险、信用风险；难以资本化风险是难以资本化的固有风险，包括操作风险、战略风险、声誉风险和流动性风险。"},{"point":"两类固有风险分别采用不同监管手段计量与评估","detail":"可资本化的固有风险和控制风险通过最低资本进行计量；难以资本化的固有风险则纳入风险综合评级予以评估，这是分类监管与最低资本计量的分野基础。"},{"point":"风险综合评级核心是综合评价固有风险与控制风险","detail":"监管以风险为导向，综合分析、评价公司的固有风险和控制风险，据其偿付能力风险大小评定监管类别并采取相应政策或措施。"}],"framework":"先答'两层结构'：偿付能力风险=固有风险+控制风险；再答固有风险=可资本化风险+难以资本化风险；最后点明两类风险在监管处理上的差异（最低资本计量 vs 风险综合评级评估）。","memo":"易错：控制风险不是'第三种风险'，而是与固有风险并列；难以资本化风险并不等于'不可管理'，只是难以资本化为最低资本。","tag":""},{"id":"qa-11-02","difficulty":1,"q":"简述风险综合评级（分类监管）评价所采用的方法，以及可资本化风险评分与难以资本化风险评分的权重安排。","answer_points":[{"point":"分类监管评价采用加权平均法","detail":"监管综合评价保险公司偿付能力风险时，将可资本化风险评分与难以资本化风险评分按权重加权汇总，由偿付能力监管信息系统按预设统一规则自动计算。"},{"point":"可资本化风险评分权重为50%","detail":"可资本化风险（保险、市场、信用风险）已通过最低资本计量，其评分在综合评价中占一半权重，反映资本充足维度的风险状况。"},{"point":"难以资本化风险评分权重为50%","detail":"操作、战略、声誉、流动性四类难以资本化风险评分同样占一半权重，反映难以用资本覆盖的非量化风险状况。两者各占半壁，体现'资本+管理'并重。"},{"point":"综合评价分数决定最终评级类别","detail":"系统自动计算各项分类监管指标得到综合评价分数和评级结果；监管部门认为自动得分未准确反映风险状况的，可以调整评级结果。"}],"framework":"先说方法（加权平均法），再说两个权重（各50%），最后说明结果的用途（综合分数定类别、监管可相机调整）。","memo":"易错：权重不是60/40或40/60，而是可资本化风险与难以资本化风险各占50%。","tag":""},{"id":"qa-11-03","difficulty":2,"q":"对比说明风险综合评级中A、B、C、D四类公司的界定标准，并指出A类与B类内部的细分。","answer_points":[{"point":"A类公司：充足率达标且四类难以资本化风险小","detail":"核心与综合偿付能力充足率均达标，同时操作、战略、声誉、流动性四类风险都很小，是风险最小的公司。"},{"point":"B类公司：充足率达标且四类风险较小","detail":"与A类同属达标，但四类难以资本化风险仅'较小'而非'小'，风险状况略高于A类。"},{"point":"C类公司：充足率不达标，或达标但部分风险较大","detail":"出现核心或综合偿付能力充足率不达标；或虽达标，但操作、战略、声誉、流动性中某一类或几类风险较大，需加强监管。"},{"point":"D类公司：充足率不达标，或达标但风险严重","detail":"充足率不达标，或虽达标但某一类或几类风险'严重'，属于风险最高的监管类别。"},{"point":"A、B类内部进一步细分","detail":"A类细分为AAA类、AA类、A类（风险由小到大）；B类细分为BBB类、BB类、B类，以更精细反映风险梯度。"}],"framework":"按A→B→C→D顺序，每类抓住两个判定维度：偿付能力充足率是否达标 + 四类难以资本化风险程度（小/较小/较大/严重）。最后补充A、B类内部细分。","memo":"易错：C、D两类都可能'充足率达标'但风险较大/严重；A、B两类均要求充足率达标，区别在风险程度。","tag":""},{"id":"qa-11-04","difficulty":2,"q":"说明操作风险的定义、包含内容，以及其在分类监管评价中的细分维度。","answer_points":[{"point":"操作风险的定义","detail":"操作风险是由于不完善的内部操作流程、人员、系统或外部事件而导致直接或间接损失的风险，强调流程、人、系统、外部事件四大诱因。"},{"point":"包含法律及监管合规风险","detail":"操作风险涵盖法律及监管合规风险，即在业务经营中因违反法律法规和监管规定而产生的风险。"},{"point":"不包括战略风险和声誉风险","detail":"虽同属难以资本化风险，但战略风险和声誉风险被明确排除在操作风险之外，三者并列而非包含关系，这是易错考点。"},{"point":"分类监管中操作风险划分为六类","detail":"操作风险细分为保险业务线、资金运用业务线、公司治理、信息系统、案件管理及其他操作风险共六类，作为评价的操作风险维度。"},{"point":"监管从多方面评估操作风险","detail":"监管评估操作风险的外部环境（行业总体水平与趋势）、各业务线内控流程与历史数据、人员因素、信息系统问题等，综合判断风险水平。"}],"framework":"定义→包含（法律合规风险）→排除（战略、声誉风险）→细分（六类）→评估维度。","memo":"易错：操作风险'含法律合规、不含战略与声誉'，三者并列；六类细分中包含'案件管理'。","tag":""},{"id":"qa-11-05","difficulty":2,"q":"说明风险综合评级的运行机制，包括评价频率、信息报送、计算方式与监管调整。","answer_points":[{"point":"评价频率为每季度一次","detail":"银保监会和银保监局在每季度结束后，对保险公司法人机构进行一次分类监管评价，确定其风险综合评级。"},{"point":"规定期限内报送指标信息和数据","detail":"每季度结束后的规定期限内，保险公司和银保监局应向偿付能力监管信息系统报送分类监管指标有关信息和数据，作为计算基础。"},{"point":"系统按统一规则自动计算","detail":"偿付能力监管信息系统依据预设的统一计算规则自动计算各项分类监管指标，得出综合评价分数和评级结果，减少人为干预。"},{"point":"监管部门可调整评级结果","detail":"银保监会或属地监管局认为系统自动得分未准确反映公司风险状况的，可以调整评级结果，体现监管的能动性。"},{"point":"结果通报与披露","detail":"监管部门向保险公司通报风险综合评级结果并对外披露相关信息，形成市场约束。"}],"framework":"按流程链条作答：频率（季）→报送→系统自动计算→监管调整→通报披露。","memo":"易错：评价频率是'每季度一次'而非每年；监管保留'调整评级结果'的相机权力，并非完全机械依赖系统。","tag":""},{"id":"qa-11-06","difficulty":3,"q":"从监管逻辑角度分析：为何将偿付能力风险分为可资本化与难以资本化两类，并分别采用最低资本计量与风险综合评级两种手段？","answer_points":[{"point":"风险可量化程度不同决定了监管手段差异","detail":"保险、市场、信用风险可通过模型资本化为最低资本，用资本要求直接覆盖；操作、战略、声誉、流动性风险难以量化或难以用资本覆盖，须用定性评价方式评估。"},{"point":"最低资本计量可资本化风险","detail":"可资本化固有风险及其控制风险通过最低资本计量，形成资本充足约束，是定量监管的核心。"},{"point":"风险综合评级评估难以资本化风险","detail":"难以资本化风险纳入风险综合评级，按操作、战略、声誉、流动性四类进行评价，与可资本化评分各占50%加权，是定性监管核心。"},{"point":"两类手段互补形成'资本+管理'并重框架","detail":"定量最低资本与定性评级并行，既约束资本充足，又约束风险管理能力，避免单纯资本充足但管理薄弱的公司被低估风险。"},{"point":"评价结果驱动差异化监管措施","detail":"综合评级结果将公司分为A、B、C、D四类，并递进施加监管措施，实现风险导向的精准监管。"}],"framework":"从'风险可量化性'切入，分述最低资本与风险综合评级两种手段，再综合说明互补关系与监管闭环，最后落到差异化措施。","memo":"易错：两类手段不是替代而是互补；可资本化用最低资本、难以资本化用评级，两者权重各50%，不可偏废。","tag":""},{"id":"qa-11-07","difficulty":3,"q":"综合说明风险综合评级如何体现'以风险为导向'，并分析其与差异化监管措施的衔接关系。","answer_points":[{"point":"评价对象覆盖全部偿付能力风险","detail":"评级综合评价固有风险（可资本化+难以资本化）与控制风险，不局限于资本指标，全面刻画风险状况。"},{"point":"评价内容直接针对四类难以资本化风险","detail":"对操作、战略、声誉、流动性风险逐项评价，操作风险本身再细分为六类，体现对各类风险特点的针对性评估。"},{"point":"方法上资本与管理并重（各50%）","detail":"可资本化与难以资本化风险评分各占50%，防止重资本轻管理或反之，真实反映风险全貌。"},{"point":"评级结果映射差异化监管政策","detail":"A类实施常规监管；B类采取风险提示、谈话、整改、专项检查、要求提交计划等；C、D类在B类基础上递进加强，D类可被接管。"},{"point":"监管保留相机调整权","detail":"系统自动计算后仍允许监管据日常信息调整评级，使监管措施能够匹配公司实际风险，实现精准分类监管。"}],"framework":"先总述'以风险为导向'的体现（全覆盖、针对性、并重），再衔接差异化监管措施（A/B/C/D递进），最后强调监管调整机制。","memo":"易错：B类措施不含'接管'，接管仅对D类；评级结果是监管措施的依据而非目的本身。","tag":""}],"calc":[{"id":"c-11-01","difficulty":1,"stem":"某保险公司可资本化风险评分为80分，难以资本化风险评分为60分。分类监管评价采用加权平均法，可资本化风险评分与难以资本化风险评分各占50%权重。计算该公司的分类监管综合评价分数。","blanks":[{"label":"分类监管综合评价分数（分）","answer":70,"tolerance":0.5}],"steps":["第1步：列加权平均公式——综合评价分数=可资本化风险评分×50%+难以资本化风险评分×50%。","第2步：代入数据——80×50%+60×50%=40+30。","第3步：求和得到综合评价分数=70分。"],"formula_card":"综合评价分数 = 可资本化风险评分×50% + 难以资本化风险评分×50%","analysis":"可资本化风险评分80分贡献40分，难以资本化风险评分60分贡献30分，加权合计70分。该分数将作为风险综合评级的输入，结合充足率与风险程度最终确定A/B/C/D监管类别。","trap":"两类风险评分权重均为50%，不是60/40；直接相加（80+60=140）会严重高估，必须按权重加权。","tag":""},{"id":"c-11-02","difficulty":2,"stem":"某保险公司本期可资本化风险评分78分、难以资本化风险评分62分，分类监管评价两类评分各占50%。第一步计算本期综合评价分数；第二步假设下期监管将可资本化风险评分下调10分（难以资本化风险评分不变），重新计算综合评价分数，并求分数变化量。","blanks":[{"label":"本期综合评价分数（分）","answer":70,"tolerance":0.5},{"label":"下期综合评价分数（分）","answer":65,"tolerance":0.5}],"steps":["第1步：本期综合分数=78×50%+62×50%=39+31=70分。","第2步：下期可资本化评分变为78−10=68分，下期综合分数=68×50%+62×50%=34+31=65分。","第3步：分数变化量=65−70=−5分，即下降5分。"],"formula_card":"综合评价分数 = 可资本化风险评分×50% + 难以资本化风险评分×50%（单类变动对综合的影响=变动额×50%）","analysis":"可资本化风险评分每变动10分，因权重为50%，综合评价分数仅变动5分，体现两类风险各占半壁。本期70分、下期65分，下降5分，反映可资本化风险恶化对整体评级的半幅传导。","trap":"易误将可资本化评分的10分变动直接当作综合分数变动（应为×50%=5分）；难以资本化风险评分在本题保持不变。","tag":""},{"id":"c-11-03","difficulty":3,"stem":"某再保险公司可资本化风险评分72分。监管将难以资本化风险按操作、战略、声誉、流动性四个子类评价，当期得分分别为88分、84分、80分、76分，并以四类得分的算术平均作为难以资本化风险评分。分类监管评价两类评分各占50%。第一步计算难以资本化风险评分；第二步计算综合评价分数；第三步假设监管认为系统自动得分未准确反映风险，将综合评价分数下调5分作为最终评级分数，求最终评级分数，并据'充足率达标且四类难以资本化风险小'判断其监管类别倾向。","blanks":[{"label":"难以资本化风险评分（分）","answer":82,"tolerance":0.5},{"label":"综合评价分数（分）","answer":77,"tolerance":0.5},{"label":"最终评级分数（分）","answer":72,"tolerance":0.5}],"steps":["第1步：难以资本化风险评分=(88+84+80+76)/4=328/4=82分。","第2步：综合评价分数=72×50%+82×50%=36+41=77分。","第3步：监管调整后最终评级分数=77−5=72分。"],"formula_card":"难以资本化风险评分=四子类算术平均；综合评价分数=可资本化×50%+难以资本化×50%；最终评级分数=综合评价分数±监管调整","analysis":"四子类平均得82分，与可资本化72分按50/50加权得77分，监管基于日常信息下调5分后最终评级分数为72分。若该公司综合偿付能力充足率达标且四类难以资本化风险均小，则倾向评为A类；监管调整机制体现相机抉择，最终类别以监管认定为准。","trap":"四子类是'平均'而非'相加'（相加会得328分谬误）；监管调整可能减少或增加系统分；类别判定需同时满足'充足率达标'与'风险小'两条件。","tag":""}]},{"id":"rule-12","group":"监管规则","name":"第12号 保险公司偿付能力监管规则第12号：偿付能力风险管理要求与评估","qa":[{"id":"qa-12-01","difficulty":1,"q":"简述第12号规则的制定目的，并说明其适用范围的边界（直接适用、参照执行、不适用）。","answer_points":[{"point":"制定目的包含三个方面","detail":"明确保险公司偿付能力风险管理的监管要求、规范监管机构对保险公司风险管理能力的评估、确定控制风险最低资本的计量标准（注意是'控制风险'最低资本，而非流动性风险最低资本）。"},{"point":"直接适用机构","detail":"境内经营商业保险业务的保险公司和外国保险公司分公司适用；相互保险组织、经营保险业务的保险集团公司也适用本规则。"},{"point":"参照执行机构","detail":"自保公司参照本规则执行，每年开展一次自评估，但不计算控制风险最低资本（银保监会另有规定的除外）。"},{"point":"明确不适用情形","detail":"不经营保险业务的保险集团公司不属于本规则适用范围，其分类监管规则由银保监会另行制定，需注意适用边界。"}],"framework":"目的'三要点'（监管要求、评估规范、控制风险最低资本计量）；适用范围'直接适用+参照执行+不适用'三层边界。","memo":"易错：目的是'控制风险'最低资本而非'流动性风险'最低资本；自保公司参照执行但不计算控制风险最低资本；不经营保险业务的保险集团不适用。","tag":""},{"id":"qa-12-02","difficulty":1,"q":"简述Ⅰ类保险公司的划分标准，并说明其判定原则与Ⅱ类公司的关系。","answer_points":[{"point":"满足三个标准中任意两个即为Ⅰ类公司","detail":"Ⅰ类公司并非全部满足，而是成立年限、规模、机构数量三类标准中满足任意两个即可，给予一定弹性。"},{"point":"标准一：成立超过5年","detail":"公司设立并持续经营超过5年，反映经营稳定性与历史风险数据积累。"},{"point":"标准二：规模标准（财险/再保与人身险不同）","detail":"财险、再保最近会计年度签单保费超50亿元或总资产超200亿元；人身险签单保费超200亿元或总资产超300亿元。"},{"point":"标准三：省级分支机构数量超过15家","detail":"机构网络覆盖广、地域分散度高的公司归为Ⅰ类，因其风险传染与管控复杂度更高。"},{"point":"Ⅱ类公司为不满足Ⅰ类标准的公司","detail":"Ⅱ类公司在考核权重、委员会设立等方面要求相对宽松，但考核权重不得为零。"}],"framework":"先点明'满足任意两个'的弹性原则，再分述三个标准（成立>5年、规模、省级机构>15家），最后说明Ⅱ类为其余公司。","memo":"易错：Ⅰ类是'任意两个'而非'全部满足'；财险/再保与人身险的规模阈值不同（50/200亿 vs 200/300亿）。","tag":""},{"id":"qa-12-03","difficulty":2,"q":"说明保险公司在偿付能力风险管理中的治理职责划分（董事会、高级管理层、风险管理委员会、首席风险官、内部审计）。","answer_points":[{"point":"董事会承担最终责任","detail":"董事会对偿付能力风险管理体系的完整性和有效性承担最终责任，审批总体目标、风险偏好、容忍度和政策。"},{"point":"高级管理层负责组织实施","detail":"高级管理层负责偿付能力风险管理体系的组织实施，并至少每年向风险管理委员会汇报一次风险水平及管理状况。"},{"point":"Ⅰ类公司须设风险管理委员会","detail":"Ⅰ类公司应在董事会下设立风险管理委员会，主任由具有风险管理经验的董事担任；Ⅱ类公司可不设立，由审计委员会履职。"},{"point":"首席风险官是关键岗位","detail":"首席风险官需具有三年以上风险管理经验或五年以上相关领域管理经验，并取得高管任职资格，不得兼任销售、投资等利益冲突岗位。"},{"point":"内部审计独立监督","detail":"内部审计部门每年至少检查、评估一次管理体系运行情况并向董事会报告，形成独立制衡。"}],"framework":"按治理层级作答：董事会（最终责任）→高级管理层（组织实施+汇报）→风险管理委员会（Ⅰ类必设）→首席风险官→内部审计（独立监督）。","memo":"易错：董事会负'最终责任'而非高管；Ⅱ类可不设风险管理委员会，由审计委员会履职；高级管理层汇报频率至少每年一次。","tag":""},{"id":"qa-12-04","difficulty":2,"q":"说明首席风险官的任职条件，以及Ⅰ类公司风险管理部门的人员配备要求（含Ⅱ类公司的替代安排）。","answer_points":[{"point":"首席风险官经验条件","detail":"具有三年以上风险管理工作经验，或五年以上法律合规、投资、精算、财务、会计等相关领域管理经验，并取得高管任职资格。"},{"point":"首席风险官独立性要求","detail":"不得同时负责销售、投资等与风险管理有利益冲突的工作，保证风险监督的客观性。"},{"point":"Ⅰ类风险管理部门配备总量","detail":"Ⅰ类公司应设立独立风险管理部门，至少配备8名专业人员。"},{"point":"Ⅰ类人员经验要求","detail":"其中至少5人具有3年以上相关工作经验，确保团队具备足够专业纵深。"},{"point":"Ⅱ类公司的替代安排","detail":"Ⅱ类公司未设立独立风险管理部门的，牵头部门至少应有两名具有3年以上相关工作经验的专业人员。"}],"framework":"分'任职条件'与'人员配备'两块：首席风险官经验（3年/5年）+独立性；Ⅰ类部门8名且5人具3年经验；Ⅱ类替代为2名。","memo":"易错：首席风险官是'3年风险管理'或'5年相关领域'二选一；不得兼任销售、投资等利益冲突岗位；Ⅰ类是8名中至少5人。","tag":""},{"id":"qa-12-05","difficulty":2,"q":"说明偿付能力风险管理评估的结果分类、'大部分符合'的判定区间，以及最终得分的评分方法。","answer_points":[{"point":"评估结果分五类","detail":"制度健全性、遵循有效性评估分为完全符合、大部分符合、部分符合、不符合、不适用五类。"},{"point":"大部分符合的判定区间","detail":"制度健全性'大部分符合'为符合程度80%～100%；遵循有效性'大部分符合'为80%以上但未达100%。"},{"point":"健全性与有效性各占50%权重","detail":"评估中制度健全性和遵循有效性各占50%，兼顾'有没有制度'与'制度是否有效执行'。"},{"point":"最终得分加权公式","detail":"最终得分S=S1×50%+S2×50%，S1为现场评估绝对分，S2为相对分。"},{"point":"相对分计算方式","detail":"相对分S2=S1×K，K=m/M，标准分m=80，M为当期行业评估绝对分排名前15%公司的平均分，用于横向校准。"}],"framework":"结果'五分类'→'大部分符合'区间（健全性80%~100%、有效性80%以上未达100%）→两维度各50%→最终得分公式S=S1×50%+S2×50%→相对分S2=S1×K，m=80。","memo":"易错：健全性与有效性各50%而非60/40；标准分m固定为80；M是行业前15%平均分，用于横向校准。","tag":""},{"id":"qa-12-06","difficulty":3,"q":"结合第12号规则，分析控制风险最低资本的确定逻辑及其与偿付能力风险管理评估的关系。","answer_points":[{"point":"控制风险最低资本公式","detail":"MC控制风险=Q×MC可资本化风险，即在可资本化风险最低资本基础上乘以控制风险系数Q，体现管理好坏对资本要求的影响。"},{"point":"系数Q由风险评估结果确定","detail":"Q来自偿付能力风险管理评估结果（最终得分S映射），风险管理能力越强，Q越低，所需控制风险资本越少。"},{"point":"评估频率与结果运用","detail":"银保监会每三年现场评估一次，当年未评估的公司以最近一次结果计算，使资本要求与最新风险管理能力挂钩。"},{"point":"评估方法是权重加权","detail":"最终得分S=S1×50%+S2×50%（绝对分+相对分），相对分经行业前15%校准，保证评分可比。"},{"point":"监管逻辑：激励强化风险管理","detail":"通过资本要求反向激励保险公司完善风险管理体系，实现'管得好则资本占用少'的导向，衔接第11号评级形成闭环。"}],"framework":"从公式MC控制风险=Q×MC可资本化切入，说明Q来自评估得分S，再述评估频率、方法，最后点明'管得好→资本少'的激励逻辑。","memo":"易错：Q是乘数（0~1）不是加减项；现场评估每三年一次、当年未评估用最近一次结果；S含相对分校准。","tag":""},{"id":"qa-12-07","difficulty":3,"q":"综合对比第11号与第12号规则在风险分类、评估手段与监管衔接上的关系。","answer_points":[{"point":"风险构成框架一致","detail":"两规则均认定偿付能力风险=固有风险+控制风险，固有风险=可资本化风险+难以资本化风险，术语完全对齐。"},{"point":"第12号评估控制风险，第11号运用结果","detail":"第12号通过风险管理评估确定控制风险最低资本（MC控制风险=Q×MC可资本化风险）；第11号将控制风险纳入风险综合评级综合评价。"},{"point":"评估手段一为能力评估、一为风险评级","detail":"第12号以制度健全性、遵循有效性各50%评估风险管理能力；第11号以可资本化、难以资本化各50%评价整体风险。"},{"point":"监管类别与措施递进衔接","detail":"第11号据评级分A/B/C/D四类并施加差异化措施，第12号的自评估与现场评估为评级提供控制风险依据，二者共同构成分类监管基础。"},{"point":"适用与频率呼应","detail":"第12号要求每年自评估、每三年现场评估；第11号每季度评级，频率与粒度不同但目标一致——风险导向监管。"}],"framework":"按'风险框架一致→评估对象衔接（控制风险）→评估手段→监管类别衔接→频率呼应'五层对比两规则。","memo":"易错：第12号'评估'控制风险并提供最低资本依据，第11号'运用'结果做评级；二者术语与风险构成完全对齐，考核时易混清。","tag":""}],"calc":[{"id":"c-12-01","difficulty":1,"stem":"根据第12号规则，Ⅰ类保险公司风险管理部门及分管该部门的高级管理人员考核指标中，风险管理制度健全性、遵循有效性相关指标的权重不应低于50%。若某公司风险管理部门分管高管年度考核总分为100分，计算其中风险管理制度健全性与遵循有效性相关指标至少应占多少分。","blanks":[{"label":"风险相关指标最低考核分值（分）","answer":50,"tolerance":0.5}],"steps":["第1步：确定风险管理部门及分管高管考核权重下限为50%。","第2步：计算最低分值=考核总分×权重下限=100×50%。","第3步：结果=50分。"],"formula_card":"风险相关指标最低分值 = 考核总分 × 50%","analysis":"Ⅰ类公司对风险管理部门的考核权重要求最高（不低于50%），高于业务部门的20%、职能部门的30%、其他部门的15%，体现风险管理在Ⅰ类公司的核心地位。100分中至少50分须与风险管理制度健全性、遵循有效性挂钩。","trap":"易误用业务部门20%或职能部门30%的权重；本题明确是'风险管理部门及分管高管'的50%下限。","tag":""},{"id":"c-12-02","difficulty":2,"stem":"偿付能力风险管理评估中，最终得分S=S1×50%+S2×50%，其中S1为现场评估绝对分，S2为相对分，且S2=S1×K，K=m/M（标准分m=80，M为当期行业评估绝对分排名前15%公司的平均分）。某保险公司现场评估绝对分S1=75分，当期行业前15%公司平均绝对分M=90分。第一步计算相对分S2；第二步计算最终得分S。","blanks":[{"label":"相对分S2（分）","answer":66.67,"tolerance":0.5},{"label":"最终得分S（分）","answer":70.83,"tolerance":0.5}],"steps":["第1步：K=m/M=80/90≈0.8889；S2=S1×K=75×80/90=600/9≈66.67分。","第2步：S=S1×50%+S2×50%=75×0.5+66.67×0.5=37.5+33.33=70.83分。","第3步：复核——S=0.5×75+0.5×(75×80/90)=37.5+33.33=70.83分，一致。"],"formula_card":"S2 = S1 × (m/M)，m=80；S = S1×50% + S2×50%","analysis":"因行业前15%平均分M=90高于标准分m=80，校准系数K=0.8889<1，使该公司相对分66.67低于其绝对分75；最终得分70.83为绝对分与相对分的等权平均，用于映射控制风险系数Q。","trap":"易把K算反为M/m=90/80=1.125（应采用m/M=80/90）；S2可能小于S1，这正体现相对分横向校准的作用。","tag":""},{"id":"c-12-03","difficulty":3,"stem":"某财产保险公司成立6年，最近会计年度签单保费55亿元、总资产210亿元、省级分支机构12家。经风险管理评估得到控制风险系数Q=0.5，其可资本化风险最低资本MC可资本化=200亿元。第一步依据Ⅰ类公司划分标准判断该公司满足几项标准并是否归为Ⅰ类；第二步按MC控制风险=Q×MC可资本化计算控制风险最低资本；第三步计算控制风险最低资本占可资本化风险最低资本的比例。","blanks":[{"label":"满足的Ⅰ类划分标准项数（项）","answer":3,"tolerance":0.5},{"label":"控制风险最低资本MC控制风险（亿元）","answer":100,"tolerance":0.1},{"label":"控制风险最低资本占比（%）","answer":50,"tolerance":0.5}],"steps":["第1步：成立6年>5年(满足)；签单保费55亿>50亿(满足)；总资产210亿>200亿(满足)；省级机构12家<15家(不满足)。满足3项≥2项，故为Ⅰ类公司。","第2步：MC控制风险=Q×MC可资本化=0.5×200=100亿元。","第3步：占比=100/200×100%=50%（即系数Q）。"],"formula_card":"Ⅰ类：满足(成立>5年 / 财险再保签单>50亿或总资产>200亿(人身险200/300亿) / 省级机构>15家)任意两项；MC控制风险=Q×MC可资本化","analysis":"该公司满足三项标准（成立年限、签单保费、总资产），依'任意两项'原则明确为Ⅰ类，须满足更严格的风险管理要求（如独立风险管理部门≥8人）。控制风险最低资本100亿元，体现其控制风险较低（Q=0.5）；若管理进一步改善使Q下降，资本占用相应减少，形成正向激励。","trap":"Ⅰ类是'满足任意两项'而非全部；省级机构12家未达标不影响Ⅰ类认定；Q是0~1的乘数，控制风险最低资本=Q×可资本化最低资本，不是相加。","tag":""}]},{"id":"rule-13","group":"监管规则","name":"第13号 流动性风险","qa":[{"id":"qa-13-01","difficulty":1,"q":"请简述《保险公司偿付能力监管规则第13号》的制定目的，并说明本规则所称“流动性风险”的定义。","answer_points":[{"point":"制定目的为规范流动性风险管理的“最低”监管要求","detail":"规则第一条明确是“最低”而非最高或指导性要求，意味着保险公司必须满足这一底线，在此基础上可自行更严格。"},{"point":"建立流动性监管指标与压力测试制度","detail":"通过流动性覆盖率（LCR）等监管指标和现金流压力测试，量化并前瞻性地识别公司流动性状况。"},{"point":"防范流动性风险，维护保单持有人利益","detail":"流动性风险会直接威胁公司及时赔付与履约能力，是偿付能力监管体系的重要组成部分。"},{"point":"流动性风险定义包含“两个无法及时”","detail":"一是无法及时获得充足资金；二是无法及时以合理成本获得充足资金，二者满足其一即构成该风险。"},{"point":"风险后果是无力支付到期债务或履行其他支付义务","detail":"具体表现为退保挤兑、赔付集中、融资断裂等导致现金枯竭、无法履约的情形。"},{"point":"适用主体涵盖境内保险公司、外国分公司及相互保险组织","detail":"但保险集团的流动性风险监管规则另行规定，不由本规则直接适用。"}],"framework":"目的（最低要求→建立指标与压力测试→防范风险）＋定义（双“无法及时”＋合理成本＋履约后果）","memo":"记“最低＋合理成本”；LCR是核心指标而非目的本身。","tag":""},{"id":"qa-13-02","difficulty":1,"q":"保险公司流动性风险管理体系应包括哪些基本要素？请简要说明。","answer_points":[{"point":"治理结构","detail":"包括董事会最终责任、高级管理层职责，并应指定一名高级管理人员负责流动性风险管理工作。"},{"point":"策略、政策和程序","detail":"涵盖限额管理、流动性风险管理的日常管理等，将风险偏好落到可执行的操作层面。"},{"point":"识别、计量、监测和控制","detail":"包括现金流管理、业务/投资/融资/再保险管理、压力测试及应急计划等具体机制。"},{"point":"三要素不含公众信息披露安排","detail":"信息披露属于第18号偿付能力报告规则的要求，不纳入本规则管理体系的组成要素。"},{"point":"董事会至少每年审议一次关键事项","detail":"审批并至少每年审议流动性风险偏好和容忍度、管理策略、重要政策和流程。"},{"point":"外国分公司由高级管理层履行董事会职责","detail":"未设董事会的外国保险公司分公司，由高级管理层履行董事会职责并承担相应责任。"}],"framework":"治理＋策略政策＋识别计量监测控制 三块要素","memo":"三要素不含“信息披露”，信息披露归第18号。","tag":""},{"id":"qa-13-03","difficulty":2,"q":"请比较第13号规则中LCR1、LCR2、LCR3三项流动性覆盖率指标的计算口径差异，并说明各自的达标标准。","answer_points":[{"point":"LCR1为“基本情景公司整体”流动性覆盖率","detail":"分子＝基本情景下公司现金流入＋现金及现金等价物评估时点账面价值，分母＝基本情景下公司现金流出。"},{"point":"LCR2为“压力情景含资产变现”流动性覆盖率","detail":"分子在LCR1口径基础上额外加“流动性资产储备变现金额”，用于衡量压力下变现储备后的覆盖能力。"},{"point":"LCR3为“压力情景不考虑资产变现”流动性覆盖率","detail":"分子＝压力情景下公司现金流入＋现金及现金等价物账面价值，不含储备变现金额，反映最保守压力。"},{"point":"达标标准：LCR1≥100%、LCR2≥100%、LCR3≥50%","detail":"三项指标均以100%或50%为监管底线，LCR3门槛明显低于前两项。"},{"point":"需分别计算未来3个月和12个月两个期限","detail":"即应计算未来3个月和未来12个月的流动性覆盖率，形成短、中期双重监测。"},{"point":"LCR3的50%反映“不考虑变现”的保守压力","detail":"因LCR3分子剔除了储备变现，监管仅要求不低于50%，体现对极端但不可变现情景的宽容底线。"}],"framework":"三公式差异在“情景（基本/压力）”与“是否含储备变现”；达标线100/100/50","memo":"LCR3只50%；LCR2比LCR3多一笔“储备变现金额”。","tag":""},{"id":"qa-13-04","difficulty":2,"q":"什么是“流动性资产储备”？其应具备哪三个特征？请列举至少三类不纳入储备的资产。","answer_points":[{"point":"定义：可快速以合理成本变现提供流动性的资产","detail":"指具备易交易、易变现及无变现障碍等特征，通过出售或抵（质）押方式能快速变现为公司提供流动性的资产。"},{"point":"关键排除：不包括现金及现金等价物","detail":"现金及现金等价物已在LCR分子单独列示，流动性资产储备是与之并列、额外可变现的资产集合。"},{"point":"三特征之一：易于交易","detail":"资产应具备活跃市场，能够便利地进行买卖或融资交易。"},{"point":"三特征之二：易于变现","detail":"能够在较短时间内转化为现金且价值损失可控，不依赖特殊条件。"},{"point":"三特征之三：无变现障碍","detail":"即未作为任何交易的质押、抵押或信用增级工具，不会被锁定而无法动用。"},{"point":"不纳入储备：非标准化债权资产、另类投资资产","detail":"此类资产缺乏活跃市场或存在变现限制，不符合储备的三特征。"},{"point":"不纳入储备：AAA级以下债券、持有至到期类债券、长期股权投资等","detail":"低评级、持有至到期及权益类长期资产均因变现障碍或期限错配被排除在储备之外。"}],"framework":"定义＋三特征（易交易/易变现/无变现障碍）＋排除项（非标/AAA下/长股投等）","memo":"储备“不含现金及现金等价物”且有三特征；非标、低评级、长股投均排除。","tag":""},{"id":"qa-13-05","difficulty":2,"q":"请说明经营活动净现金流回溯不利偏差率（RDR）的计算公式、达标要求及其监管含义。","answer_points":[{"point":"公式：RDR＝（实际值−预测值）÷ABS（预测值）×100%","detail":"用实际值与预测值的差额除以预测值的绝对值，衡量现金流预测的方向性偏差。"},{"point":"达标要求：最近两个季度不得连续低于−30%","detail":"只要连续两个季度RDR均低于−30%即触发监管关注，单个季度低于不必然违规。"},{"point":"负值表示实际比预测“更差”","detail":"负偏差意味着实际现金流入更少或流出更多，预测过于乐观，公司现金流管理存在失准。"},{"point":"监管含义是现金流预测严重失准的预警信号","detail":"连续两季低于−30%提示公司预算与真实经营脱节，可能隐藏流动性隐患。"},{"point":"RDR与LCR、净现金流共同构成三项监管指标","detail":"三者分别从覆盖能力、预测回溯、历史累计三个维度监控流动性风险。"},{"point":"净现金流不得连续小于零","detail":"净现金流反映过去两个会计年度及当年累计的整体净现金流，计算口径与现金流量表一致。"}],"framework":"公式＋阈值（−30%连续两季）＋含义（预测失准信号）","memo":"RDR看“连续两季<−30%”，净现金流看“连续<0”。","tag":""},{"id":"qa-13-06","difficulty":3,"q":"对比流动性风险现金流测试中“基本情景”与“压力情景”的设定要求差异，并说明压力情景下预测筹资活动现金流的特殊规定。","answer_points":[{"point":"基本情景是最优估计假设","detail":"应考虑现有业务和未来新业务，新业务假设须与业务规划一致，由公司内部自行确定。"},{"point":"压力情景包含自测与必测两类","detail":"自测情景由公司自行确定，必测情景由银保监会根据行业情况统一确定并发布。"},{"point":"压力情景不考虑管理层应急行为","detail":"测试时不考虑临时银行贷款等管理层为改善流动性采取的紧急措施，以反映真实承压能力。"},{"point":"筹资仅考虑已履行决策程序、有明确安排的筹资","detail":"必须是符合章程、决策程序已完成、安排明确的筹资，排除临时起意的融资。"},{"point":"压力情景可考虑正回购、拆入资金等短期筹资","detail":"但各期末短期筹资余额以报告日已有余额为限，不得凭空放大融资能力。"},{"point":"不应考虑股东增资、发行资本补充债等资本工具流入","detail":"此类资本性现金流入在压力情景下不予计入，防止高估流动性。"},{"point":"投资性不动产、长股投、固定资产等不假设变现","detail":"除非已有明确交收合约，也不应假设原计划持有至到期的金融资产提前变现。"}],"framework":"基本（最优估计/自定）vs 压力（自测＋必测/不含管理层行为）；筹资以报告日余额为限、不含增资","memo":"压力情景下“不认增资、不认临时贷款、短期筹资以报告日余额为顶”。","tag":""},{"id":"qa-13-07","difficulty":3,"q":"请综合分析保险公司流动性风险治理结构中董事会、高级管理层及指定高管各自的职责，并说明外国保险公司分公司的特殊安排。","answer_points":[{"point":"董事会承担最终责任","detail":"董事会是流动性风险管理的最终责任人，对整体风险状况负总责。"},{"point":"董事会应审批并至少每年审议关键事项","detail":"包括流动性风险偏好和容忍度、管理策略、重要政策和流程，并持续关注风险水平及重大变化。"},{"point":"高级管理层负责有效管理与控制","detail":"在董事会授权下组织落实流动性风险管理，制定并实施应急计划。"},{"point":"指定一名高级管理人员专责管理","detail":"公司应指定一名（而非一个部门或董事）高级管理人员负责流动性风险管理工作。"},{"point":"重大流动性风险须3日内报告","detail":"自发现之日起3日内向银保监会报告，说明流动性水平、风险状况及已采取和拟采取的措施。"},{"point":"外国分公司由高级管理层履行董事会职责","detail":"未设董事会的外国保险公司分公司，由高级管理层履行董事会职责并承担相应责任。"},{"point":"指标披露依第18号规则执行","detail":"应在偿付能力季度报告中披露流动性监管指标、监测指标和现金流测试等信息。"}],"framework":"董事会（最终责任/年审）→高管层（执行）→指定高管（专责）；外分司高管理事会职责","memo":"是“指定一名高管”而非部门；外分司由高管理事会职责；重大风险3日内报。","tag":""},{"id":"qa-13-08","difficulty":3,"q":"请比较财产险、人身险、再保险三类保险公司的流动性风险监测指标，并说明“监管指标”与“监测指标”的区别。","answer_points":[{"point":"三类公司共同的监管指标为三项","detail":"即流动性覆盖率（LCR1/LCR2/LCR3）、经营活动净现金流回溯不利偏差率（RDR）、净现金流。"},{"point":"财产险监测指标含百元保费经营活动净现金流","detail":"反映每百元保费对应的经营活动净现金流水平，用于观察财险业务现金生成效率。"},{"point":"人身险监测指标含综合退保率、分红/万能账户业务净现金流","detail":"重点关注退保集中与账户现金流波动，是人身险流动性风险的核心观察点。"},{"point":"再保险监测指标含应收分保账款率、特定业务现金流支出占比等","detail":"再保险公司还关注经营活动净现金流，应收分保账款率反映分保资金回收风险。"},{"point":"监管指标具强制达标要求","detail":"如LCR1/LCR2≥100%、LCR3≥50%、RDR不得连续低于−30%，未达标将引致监管措施。"},{"point":"监测指标用于观察与预警而非强制达标","detail":"监测指标分负债端（退保、分保等）和资产端（现金占比、融资杠杆、低评级资产占比），重在提示趋势。"},{"point":"特定业务指集中或大额赔付业务","detail":"包括融资性信用保证保险，以及再保后预估或实际赔付超上年非车险整体赔付5%的非车险业务。"}],"framework":"监管指标（强制达标）vs 监测指标（观察预警）；财/人/再各自监测项","memo":"综合退保率是人身险的；百元保费净现金流是财险的；应收分保账款率是再保险的。","tag":""}],"calc":[{"id":"c-13-01","difficulty":1,"stem":"某保险公司报告期末基本情景下：公司现金流入为850万元，现金及现金等价物评估时点账面价值为250万元，公司现金流出为1100万元。请计算其基本情景公司整体流动性覆盖率LCR1，并判断是否满足达标要求。","blanks":[{"label":"LCR1（%）","answer":100.0,"tolerance":0.5}],"steps":["第1步：公式 LCR1＝（基本情景现金流入＋现金及现金等价物账面价值）÷基本情景现金流出×100%","第2步：代入数值 LCR1＝（850＋250）÷1100×100%","第3步：计算 LCR1＝1100÷1100×100%＝100.0%，满足LCR1不低于100%的达标要求"],"formula_card":"LCR1＝（基本情景公司现金流入＋现金及现金等价物账面价值）÷基本情景公司现金流出×100%","analysis":"分子850＋250＝1100万元，分母1100万元，LCR1＝100.0%。根据附件2达标标准，LCR1应不低于100%，本题结果恰好达标。该指标衡量基本情景下公司整体未来一年（3个月及12个月）的流动性覆盖水平。","trap":"LCR1分子不含流动性资产储备变现金额，那是LCR2的口径；勿把储备折算金额误加进来。","tag":""},{"id":"c-13-02","difficulty":2,"stem":"某保险公司压力情景下：公司现金流入为600万元，现金及现金等价物账面价值为200万元，公司现金流出为1200万元。其流动性资产储备账面价值为500万元，构成如下：可提前支取定期存款200万元（折算系数90%）、交易类及可供出售类国债200万元（折算系数100%）、上市股票100万元（折算系数50%）。请计算流动性资产储备变现金额，并据此计算压力情景公司整体流动性覆盖率LCR2。","blanks":[{"label":"流动性资产储备变现金额（万元）","answer":430.0,"tolerance":0.5},{"label":"LCR2（%）","answer":102.5,"tolerance":0.5}],"steps":["第1步：计算储备变现金额＝Σ（各项储备账面价值×折算系数）＝200×90%＋200×100%＋100×50%","第2步：代入 变现金额＝180＋200＋50＝430万元","第3步：LCR2＝（压力情景现金流入＋现金及现金等价物＋储备变现金额）÷压力情景现金流出×100%＝（600＋200＋430）÷1200×100%＝102.5%"],"formula_card":"流动性资产储备变现金额＝Σ（储备账面价值×折算系数）；LCR2＝（压力情景现金流入＋现金及现金等价物＋储备变现金额）÷压力情景现金流出×100%","analysis":"储备变现金额：定存200×0.9＝180，国债200×1.0＝200，股票100×0.5＝50，合计430万元。LCR2分子＝600＋200＋430＝1230万元，分母1200万元，LCR2＝102.5%。达标注明LCR2应不低于100%，本题达标。不同资产折算系数差异显著（国债100%、定存90%、股票50%），是本题主要计算点。","trap":"不同资产折算系数不同，须逐项相乘后求和；LCR2分子含储备变现金额，而LCR3不含，二者分母同为压力情景现金流出。","tag":""},{"id":"c-13-03","difficulty":3,"stem":"某保险公司报告期末数据如下。基本情景：现金流入960万元，现金及现金等价物240万元，现金流出1200万元。压力情景：现金流入720万元，现金及现金等价物240万元，现金流出1100万元，另有流动性资产储备400万元（全部为AAA级金融企业债，折算系数85%）。请分别计算LCR1、LCR2、LCR3，并判断三项指标是否全部达标。","blanks":[{"label":"LCR1（%）","answer":100.0,"tolerance":0.5},{"label":"LCR2（%）","answer":118.18,"tolerance":0.5},{"label":"LCR3（%）","answer":87.27,"tolerance":0.5}],"steps":["第1步：LCR1＝（基本情景现金流入＋现金及现金等价物）÷基本情景现金流出×100%＝（960＋240）÷1200×100%","第2步：LCR2＝（压力情景现金流入＋现金及现金等价物＋储备×系数）÷压力情景现金流出×100%＝（720＋240＋400×85%）÷1100×100%","第3步：LCR3＝（压力情景现金流入＋现金及现金等价物）÷压力情景现金流出×100%＝（720＋240）÷1100×100%","第4步：达标判断：LCR1≥100%、LCR2≥100%、LCR3≥50%"],"formula_card":"LCR1＝（基本情景流入＋现金）÷基本情景流出；LCR2＝（压力情景流入＋现金＋储备×系数）÷压力情景流出；LCR3＝（压力情景流入＋现金）÷压力情景流出；达标线 LCR1/LCR2≥100%、LCR3≥50%","analysis":"LCR1：分子960＋240＝1200，1200÷1200＝100.0%，达标（≥100%）。LCR2：储备变现400×0.85＝340，分子720＋240＋340＝1300，1300÷1100＝118.18%，达标（≥100%）。LCR3：分子720＋240＝960，960÷1100＝87.27%，达标（≥50%）。三项全部满足监管底线。可见即便在压力且不考虑全部变现的LCR3口径下，公司仍保持较高覆盖水平。","trap":"LCR2与LCR3分母同为压力情景现金流出，区别仅在分子是否含储备变现金额；LCR3达标线为50%而非100%，勿与LCR1/LCR2混淆。","tag":""}]},{"id":"rule-14","group":"监管规则","name":"第14号 资本规划","qa":[{"id":"qa-14-01","difficulty":1,"q":"请简述第14号规则中“资本规划”的定义，并说明制定本规则的主要目的。","answer_points":[{"point":"目的之一：强化保险公司资本刚性约束","detail":"通过硬性规划要求，防止资本被随意消耗，保障公司具备持续偿付能力。"},{"point":"目的之二：提升保险公司资本管理水平","detail":"推动公司建立系统化、前瞻性的资本管理机制，而非临时补救。"},{"point":"目的之三：明确资本规划监管标准","detail":"统一资本规划的编制、报送与实施要求，为监管评估提供依据。"},{"point":"定义：基于偿付能力充足率目标的资本计划安排","detail":"资本规划是保险公司基于偿付能力充足率目标，对资本规模、资本结构、资本来源和运用等进行的计划和安排。"},{"point":"适用主体与解释权属","detail":"适用于境内经营商业保险的保险公司、外国保险公司分公司及相互保险组织；由银保监会负责解释和修订。"},{"point":"发布与施行","detail":"本规则于2021年12月30日第一次发布，施行日期另行规定。"}],"framework":"目的（刚性约束＋管理水平＋监管标准）＋定义（基于充足率目标＋规模/结构/来源/运用）","memo":"核心是“偿付能力充足率目标”导向的资本计划。","tag":""},{"id":"qa-14-02","difficulty":1,"q":"保险公司资本规划应当遵循哪四项原则？请简要说明。","answer_points":[{"point":"充足性原则","detail":"资本规划应确保资本水平满足偿付能力等监管与经营需要，留有充足缓冲。"},{"point":"审慎性原则","detail":"规划假设与资本补充安排应保守稳健，充分考虑不利因素而非盲目乐观。"},{"point":"前瞻性原则","detail":"应着眼未来，滚动预判业务发展、风险变化对资本的影响，提前布局。"},{"point":"可行性原则：目标与措施须契合实际","detail":"规划目标、资本补充措施等应与公司实际情况和市场环境相符，具有可操作性。"},{"point":"不存在“收益性”原则","detail":"收益性并非资本规划的原则，易与可行性、审慎性混淆，答题时需排除。"},{"point":"四项原则贯穿规划全流程","detail":"从编制、实施到考核，均应在四项原则框架下开展。"}],"framework":"充足＋审慎＋前瞻＋可行（无收益性）","memo":"四原则中没有“收益性”。","tag":""},{"id":"qa-14-03","difficulty":2,"q":"资本规划至少应包括哪些内容？其中资本管理目标至少应覆盖哪些偿付能力指标？","answer_points":[{"point":"内容一：资本管理目标","detail":"明确规划期内资本水平与结构的预期，是资本规划的起点和锚定基准。"},{"point":"内容二：资本规划制定依据","detail":"包括宏观环境、监管要求、公司战略等作为规划编制的支撑理由。"},{"point":"内容三：资本需求评估","detail":"在基本情景和不利情景下评估未来资本需求，是测算缺口的前提。"},{"point":"内容四：资本补充方案","detail":"制定内源性与外源性相结合的资本补充路径，内源性优先。"},{"point":"内容五：上一年度资本规划执行情况分析","detail":"回顾上期规划落地情况，为本期调整提供经验依据。"},{"point":"内容六：应急预案","detail":"设定偿付能力充足率预警值及极端不利情景下的资本补充安排。"},{"point":"管理目标至少覆盖综合与核心两类充足率","detail":"资本管理目标至少包括综合偿付能力充足率、核心偿付能力充足率未来三年的目标。"}],"framework":"六内容（目标/依据/需求/补充/执行/应急）＋两指标（综合/核心）","memo":"六内容为下限；管理目标必含“综合＋核心”两类充足率。","tag":""},{"id":"qa-14-04","difficulty":2,"q":"请区分内源性资本补充措施与外源性资本补充措施，各举至少三例，并说明资本补充的优先顺序。","answer_points":[{"point":"内源之一：提升盈利能力","detail":"通过稳健经营增厚留存收益，是最可持续的核心资本来源。"},{"point":"内源之二：制定合理的利润分配政策","detail":"平衡股东回报与公司资本积累，避免过度分红侵蚀资本。"},{"point":"内源之三：优化产品与资产结构、提升风险管理能力","detail":"从业务端降低资本消耗、提高资本使用效率，间接补充资本。"},{"point":"外源之一：增资扩股","detail":"引入新资本或全部由股东注资，直接补充核心资本。"},{"point":"外源之二：发行资本补充工具","detail":"如发行资本补充债等，主要补充附属资本。"},{"point":"外源之三：保单责任证券化、再保险等","detail":"通过风险转移或证券化释放资本，属监管认可的其他资本工具。"},{"point":"优先顺序：内源优先、核心资本优先","detail":"应优先考虑内源性措施；补充资本时优先补充核心资本、合理补充附属资本，持续优化资本结构。"}],"framework":"内源（盈利/分配/产品资产结构）vs 外源（增资/资本债/证券化/再保）；内源优先、核心优先","memo":"内源优先于外源；核心资本优先于附属资本。","tag":""},{"id":"qa-14-05","difficulty":2,"q":"资本规划中基本情景与不利情景的设定要求有何不同？不利情景至少应考虑哪些因素？","answer_points":[{"point":"基本情景须与第10号规则保持一致","detail":"基本情景的相关参数和假设应当与《偿付能力监管规则第10号：压力测试》保持一致。"},{"point":"不利情景由保险公司结合实际合理设定","detail":"不利情景不由监管统一发布，公司应结合自身业务与风险状况自行设定。"},{"point":"不利情景应避免极端情景的简单叠加","detail":"应根据风险分散、交叉传染等相互作用合理设定，而非将各项最坏情形机械相加。"},{"point":"因素一：业务发展的不利变化","detail":"如保费下滑、赔付恶化等业务端下行压力。"},{"point":"因素二：资产配置的调整","detail":"资产端结构调整带来的收益与流动性变化。"},{"point":"因素三：投资收益率的不利波动","detail":"市场下行导致投资收益不及预期。"},{"point":"因素四与五：费用假设不利变化、折现率曲线不利变化","detail":"费用上升侵蚀利润，准备金折现率下行抬高负债评估，均推高资本需求。"}],"framework":"基本（对标第10号）vs 不利（公司自定、忌极端叠加）；五因素（业务/资产/收益/费用/折现率）","memo":"基本情景“对齐第10号”；不利情景五因素，且不可简单叠加极端。","tag":""},{"id":"qa-14-06","difficulty":3,"q":"请综合分析资本规划的审议批准与报送时限要求：谁有权审议批准？常规何时报送？调整规划时程序如何？","answer_points":[{"point":"审议批准：董事会批准并经股东（大）会审议","detail":"资本规划应当经董事会批准，并经股东（大）会审议，体现治理层的最高决策。"},{"point":"常规报送：每年5月31日前","detail":"保险公司应当于每年5月31日前向银保监会报送资本规划。"},{"point":"调整触发条件：重大变化导致重大偏离","detail":"因监管要求、经营环境、公司战略等重大变化，导致资本需求、补充和使用情况与规划重大偏离时，应及时调整。"},{"point":"调整内部程序：提交董事会审议","detail":"实施过程中出现重大变化的，应当提交董事会审议。"},{"point":"调整后报送：董事会批准10个工作日内","detail":"依第二十七条调整的，经董事会审议批准后10个工作日内向银保监会报送调整后的规划。"},{"point":"评估与回溯机制","detail":"公司应建立评估与回溯分析机制，定期回顾执行结果；监管评估依据第12号及本规则。"}],"framework":"批准（董事会＋股东会）→常规报送（5/31）→调整（董事会审＋10工作日报）","memo":"常规5月31日；调整“董事会批准＋10个工作日”报送。","tag":""},{"id":"qa-14-07","difficulty":3,"q":"对比资本管理目标设定应考虑的三方面因素与不利情景设定的五项因素，并分析其背后的监管逻辑。","answer_points":[{"point":"管理目标三因素：外部环境","detail":"包括外部经济环境、法律政策环境，决定规划可施展的外部空间。"},{"point":"管理目标三因素：公司发展战略","detail":"包括业务发展规划、风险管理状况、风险偏好，是目标设定的内部锚点。"},{"point":"管理目标三因素：资本补充可行性与可持续性","detail":"确保目标不仅有意愿，更有能力与渠道持续实现。"},{"point":"不利情景五因素：业务、资产、收益、费用、折现率","detail":"分别对应业务发展不利变化、资产配置调整、投资收益率不利波动、费用假设不利变化、折现率曲线不利变化。"},{"point":"管理目标因素偏“规划可行性”","detail":"回答“目标能不能做、可不可持续”，使规划积极但落地。"},{"point":"不利情景因素偏“风险压力”","detail":"回答“最坏会糟到什么程度”，倒逼资本充足覆盖下行风险。"},{"point":"监管逻辑：目标定下限、情景测抗压，二者互补","detail":"目标确保积极达标，情景确保极端承压仍可控，体现“既积极又审慎”的资本刚性约束。"}],"framework":"目标三因素（环境/战略/可行）vs 情景五因素（业务/资产/收益/费用/折现率）；逻辑＝积极又审慎","memo":"目标看“能不能做”，情景看“最坏多糟”；五因素中四项为“不利变化”压力。","tag":""},{"id":"qa-14-08","difficulty":3,"q":"对未按规则报送、编制不符或实施重大偏离未调整的保险公司，银保监会可采取哪些监管措施？其中哪些是本规则特有手段？","answer_points":[{"point":"措施一：监管谈话","detail":"通过谈话督促公司认识问题、落实整改，属常规监管手段。"},{"point":"措施二：责令限期整改","detail":"要求公司在限定期限内纠正报送、编制或实施中的问题。"},{"point":"措施三：扣减SARMRA评估得分并限制最高得分","detail":"依据第12号规则，在偿付能力风险管理评估中扣减得分并限制最高分，影响风险综合评级。"},{"point":"措施四：限制或停止资本补充工具发行","detail":"直接约束公司外部融资能力，是强约束手段。"},{"point":"资本工具发行审批以资本规划为依据","detail":"不一致时银保监会审慎考虑其发行申请，形成事前约束。"},{"point":"特有手段：扣SARMRA分与限停资本工具发行","detail":"相较于一般谈话、整改，扣减并限制评估得分、限制或停止资本补充工具发行是本规则较有特色的处罚手段。"},{"point":"监管评估同时依据第12号规则","detail":"银保监会对资本规划的编制、报送和实施评估，结合第12号（偿付能力风险管理要求与评估）进行。"}],"framework":"四措施（谈话/整改/扣SARMRA分限最高/限停资本工具）；后两项为特色","memo":"特色处罚＝扣SARMRA分（限最高）＋限停资本工具发行。","tag":""}],"calc":[{"id":"c-14-01","difficulty":1,"stem":"某保险公司因经营环境重大变化需调整资本规划。董事会于2024年3月1日（星期五）审议批准调整方案。规则要求经董事会审议批准后10个工作日内向银保监会报送调整后的资本规划；假设期间无节假日，仅周六、周日为非工作日，批准当日不计入。请问最迟应在3月几日之前报送？","blanks":[{"label":"最迟报送日（3月几日）","answer":15,"tolerance":0.5}],"steps":["第1步：从批准日的次一工作日起算10个工作日（3月1日周五为批准日，不计入）","第2步：逐日计数——3月4日周一(1)、5日周二(2)、6日周三(3)、7日周四(4)、8日周五(5)、11日周一(6)、12日周二(7)、13日周三(8)、14日周四(9)、15日周五(10)","第3步：第10个工作日为3月15日，即最迟报送日"],"formula_card":"调整后报送时限＝董事会批准日＋10个工作日（剔除周末，无节假日）","analysis":"批准日为2024年3月1日（周五），按“批准后10个工作日”且批准当日不计入，从3月4日（周一）起数10个工作日，依次为4、5、6、7、8、11、12、13、14、15日，第10个工作日为3月15日。故最迟3月15日前报送。","trap":"批准当日不计入10个工作日；只剔除周六周日，不臆测法定节假日；勿把3月1日当作第1个工作日。","tag":""},{"id":"c-14-02","difficulty":2,"stem":"保险公司每年滚动编制未来三年的资本规划，资本规划至少包括六项内容。某公司编制2024年资本规划时已列明四项：资本管理目标、资本规划制定依据、资本需求评估、资本补充方案。该公司自2021年起每年滚动编制。请回答：①还至少需补充几项内容？②2021年至2024年共滚动编制几次？","blanks":[{"label":"还至少需补充内容项数（项）","answer":2,"tolerance":0.5},{"label":"滚动编制次数（次）","answer":4,"tolerance":0.5}],"steps":["第1步：内容项数＝法定下限6项－已列4项＝2项","第2步：滚动编制每年一次，2021、2022、2023、2024各编制一次","第3步：编制次数＝末年－首年＋1＝2024－2021＋1＝4次"],"formula_card":"内容项数＝6－已列项数；编制次数＝末年－首年＋1","analysis":"资本规划至少六项内容，已列四项，尚缺“上一年度资本规划执行情况分析”和“应急预案”两项，故至少补2项。滚动编制为每年一次，2021至2024年共4个年度，编制4次（每次覆盖未来三年，但“每年滚动编制”指每年出一份规划）。","trap":"“未来三年”指每份规划覆盖的期间长度，并非每年只编一次；六项内容是法定下限，缺项即不合规。","tag":""},{"id":"c-14-03","difficulty":3,"stem":"某保险公司2024年度资本规划按规则须于每年5月31日前报送。因经营环境重大变化需调整：董事会于2024年5月14日（星期二）审议批准调整方案，规定批准后10个工作日内报送，期间无节假日、仅周末为非工作日，批准当日不计入。请回答：①规则规定的常规报送截止日是5月几日？②调整后最迟报送日是5月几日？③若调整后最迟报送日不晚于常规截止日，是否符合及时报送要求？","blanks":[{"label":"常规报送截止日（5月几日）","answer":31,"tolerance":0.5},{"label":"调整后最迟报送日（5月几日）","answer":28,"tolerance":0.5}],"steps":["第1步：常规报送截止日为每年5月31日，即5月31日","第2步：从5月15日（批准日次日、周三）起算10个工作日——15(1)、16(2)、17(3)、20(4)、21(5)、22(6)、23(7)、24(8)、27(9)、28(10)","第3步：第10个工作日为5月28日；比较28≤31，满足及时报送要求"],"formula_card":"常规报送＝每年5月31日前；调整后＝董事会批准日＋10个工作日（剔除周末）","analysis":"常规报送截止日为5月31日。调整方案5月14日（周二）批准，从5月15日（周三）起数10个工作日：15、16、17、20、21、22、23、24、27、28日（周末18、19、25、26跳过），最迟5月28日。因28日早于31日常规截止日，调整后报送仍符合及时报送要求；若超出31日则构成延迟报送违规。","trap":"批准当日（5月14日）不计入工作日；日期比较用“日”数值（28与31），勿把月份也混入；Weekend须跳过。","tag":""}]},{"id":"rule-15","group":"监管规则","name":"第15号 偿付能力信息公开披露","qa":[{"id":"qa-15-01","difficulty":1,"q":"简述保险公司偿付能力信息公开披露的立法目的与适用范围。","answer_points":[{"point":"立法目的","detail":"为规范保险公司偿付能力信息公开披露行为，建立健全偿付能力市场约束机制。市场约束与监管约束、企业内控共同构成偿付能力监管的三支柱，信息披露让市场力量参与监督。"},{"point":"适用主体","detail":"依法在境内设立的经营商业保险业务的保险公司和外国保险公司分公司均须适用。相互保险组织也适用本规则，体现规则对不同组织形式的覆盖。"},{"point":"除外主体","detail":"政策性保险公司不适用本规则。这是因政策性业务具有特殊属性，监管另行安排，考生须与第15号适用主体区分清楚。"},{"point":"披露行为界定","detail":"信息披露指保险公司向社会公众或利益相关方等信息使用者公开其偿付能力相关信息的行为。强调'公开'与'信息使用者'两要素，区别于内部报告。"},{"point":"最低要求定位","detail":"本规则是偿付能力信息公开披露的最低要求，银保监会鼓励公司按更高标准披露。因此公司在符合要求基础上可自愿增加披露内容。"}],"framework":"先说目的（市场约束机制），再说适用主体与除外主体，最后强调最低要求定位。","memo":"易错：政策性保险公司不适用；相互保险组织适用。两者不要混淆。","tag":""},{"id":"qa-15-02","difficulty":1,"q":"列举并说明保险公司公开披露偿付能力信息应遵循的五项原则。","answer_points":[{"point":"充分性原则","detail":"充分披露有助于使用者了解公司偿付能力风险状况的所有重大相关信息。意味着不能选择性披露，重大风险信息须完整呈现。"},{"point":"及时性原则","detail":"定期、及时披露偿付能力相关信息。对应季度报告摘要的时限要求，避免信息滞后影响使用者决策。"},{"point":"真实性原则","detail":"披露内容真实、准确、完整，没有虚假、误导性陈述或重大遗漏。这是信息披露质量底线，与会计信息真实性要求一致。"},{"point":"可理解性原则","detail":"披露内容清晰，便于信息使用者理解和使用。要求用清晰语言与结构，避免过于技术化导致使用者无法解读。"},{"point":"公平性原则","detail":"确保信息披露的集中性、可访问性和获取便利，使各信息使用者平等获悉。强调集中统一渠道（协会专栏）与平等获取，区别于选择性沟通。"}],"framework":"五原则逐条说明：充分性、及时性、真实性、可理解性、公平性；注意区别于会计信息质量要求（无谨慎性）。","memo":"易错：五原则中没有'谨慎性原则'，谨慎性是会计信息质量要求而非披露原则。","tag":""},{"id":"qa-15-03","difficulty":2,"q":"说明偿付能力季度报告摘要的组成，以及自保公司、按第18号规则披露部分的特殊安排。","answer_points":[{"point":"十一分项组成","detail":"摘要由公司信息、董事会和管理层声明、基本情况、主要指标、风险管理能力、风险综合评级、重大事项、管理层分析与讨论、外部机构意见、实际资本、最低资本十一部分组成，是摘要的标准架构。"},{"point":"前九项衔接第18号","detail":"第（一）至（九）项按《保险公司偿付能力监管规则第18号：偿付能力报告》披露。体现与第18号报告编制规则的衔接，避免重复规定。"},{"point":"实际资本部分披露","detail":"披露核心一级、核心二级、附属一级、附属二级资本金额及核心一级资本调整表、认可资产、认可负债的本季度（末）数和上季度（末）数，须同时披露两期数据以便对比。"},{"point":"最低资本部分披露","detail":"披露最低资本及保险、市场、信用各子类最低资本、可资本化风险最低资本、控制风险最低资本、附加资本（不适用为零值），附加资本不适用须以零值披露，不得省略。"},{"point":"自保公司特殊安排","detail":"自保公司仅披露第（一）至（四）项、第（六）项、第（十）项、第（十一）项，即不含重大事项、风险管理能力等内容，反映自保公司业务特殊性。"}],"framework":"先列十一分项，再说前九项衔接第18号，再分实际资本、最低资本披露要求，最后说明自保公司缩减范围。","memo":"易错：自保公司不披露'重大事项'（第七项）与'风险管理能力'（第五项）；附加资本不适用以零值披露。","tag":""},{"id":"qa-15-04","difficulty":2,"q":"说明定期披露的时间要求及网站保留期限。","answer_points":[{"point":"非上市公司时限","detail":"非上市保险公司应在每季度结束后30日内披露季度报告摘要。统一为季度后30日，区别于上市安排的灵活处理。"},{"point":"上市公司时限","detail":"上市及其子公司第1、3季度结束后30日内披露；第2、4季度摘要与半年度、年度财务报告同时披露，即第2、4季度不单独限时，随财报披露。"},{"point":"补充信息时限","detail":"经审计的第4季度信息存在重大变动等情况，自审计报告出具之日起10日内发布补充信息。重大变动触发补正义务，时限自审计报告出具日起算。"},{"point":"延迟披露上限","detail":"不能按时披露的，延迟时间不得超过15日，且须在披露期限之前在官网首页公布原因及预计披露时间，保障使用者预期。"},{"point":"网站保留期限","detail":"季度报告摘要在公司网站保留至少10年。满足监管追溯与使用者长期查询需要，体现披露信息的长期可获取性。"}],"framework":"按非上市/上市/补充/延迟/保留五类时限分别说明，注意各自触发条件与天数。","memo":"易错：第2、4季度摘要随财报披露（不另限30日）；延迟上限15日不是30日；保留10年。","tag":""},{"id":"qa-15-05","difficulty":2,"q":"说明日常披露中投保、投标、股东沟通等场景的具体披露要求。","answer_points":[{"point":"投保场景","detail":"在投保提示书、红利通知书、保单状态报告显著位置披露最近季度综合偿付能力充足率、风险综合评级，说明是否达标，或以二维码、网址链接形式披露，保障消费者知情权。"},{"point":"投标场景","detail":"参加投标应列示最近四个季度的核心、综合偿付能力充足率及最近一期风险综合评级，以连续四季数据反映公司偿付能力稳定性。"},{"point":"股东沟通","detail":"非上市向所有股东、上市向持股5%以上股东发送季度报告摘要；公布利润分配方案时同时公布对充足率的影响，体现股东知情权与潜在影响披露。"},{"point":"交易说明","detail":"增资、股权变更、债券发行等向股东及潜在投资方、债权人书面说明最近四季充足率及交易潜在影响，便于交易对手评估偿付能力。"},{"point":"路演应询","detail":"业绩发布、证券发行等路演活动应设置偿付能力信息应询环节，将偿付能力纳入市场沟通强制环节。"}],"framework":"分投保/投标/股东/交易/路演五场景，各抓'最近季度/四季'与'应询环节'等关键词。","memo":"易错：投标与交易说明均用'最近四个季度'；上市仅向持股5%以上股东发送摘要。","tag":""},{"id":"qa-15-06","difficulty":3,"q":"对比分析定期披露与日常披露在监管逻辑上的区别，并说明董事会最终责任与内控要求。","answer_points":[{"point":"定期披露特征","detail":"按固定周期（季度）和统一格式（十一分项摘要）在指定渠道披露，是标准化、可横向比较的强制披露，服务于市场总体监督。"},{"point":"日常披露特征","detail":"嵌入具体业务场景（投保、投标、股东、交易、路演），针对特定对象与时点，是场景化、针对性的披露，服务于具体交易与个体决策。"},{"point":"二者互补逻辑","detail":"定期披露提供持续可比的基准信息，日常披露在具体情境下落实知情权，共同构成市场约束的'普遍+特定'双层机制。"},{"point":"董事会最终责任","detail":"董事会对偿付能力信息公开披露负最终责任。即使由管理层操作，最终责任在董事会，凸显公司治理顶层责任。"},{"point":"内控要求","detail":"应建立覆盖信息生成、采集、审核和披露各环节的内控制度，明确责任部门和责任人，并将披露信息仅限于本公司，不得与其他公司对比。"}],"framework":"先对比定期/日常披露的时效、格式、对象差异，再落到董事会最终责任与全流程内控。","memo":"易错：披露信息不得与其他保险公司对比；董事会负'最终'责任而非'主要'责任。","tag":""},{"id":"qa-15-07","difficulty":3,"q":"分析监管复核、暂缓披露与违规处理机制，说明最低要求与豁免安排。","answer_points":[{"point":"监管复核","detail":"银保监会认为信息可能存在问题的，应要求公司复核。赋予监管主动核查权，作为披露质量的事中把关。"},{"point":"暂缓披露","detail":"未按时完成复核或结果未获认可的，应暂缓披露并在官网发布声明，说明正根据监管要求复核，防止不实信息流入市场。"},{"point":"违规处理","detail":"对未按规则披露的公司，银保监会依法责令改正；情节严重的依法处罚，形成从责令改正到处罚的递进责任。"},{"point":"最低要求定位","detail":"本规则是披露最低要求，鼓励更高标准。公司可在合规基础上自愿增信披露，提升市场形象。"},{"point":"豁免安排","detail":"银保监会可根据审慎监管和金融稳定需要，豁免公司披露义务或调整内容、频率、形式，体现监管灵活性与个案处理空间。"}],"framework":"按复核→暂缓→违规处罚的递进，再补最低要求与豁免两端，呈现监管闭环。","memo":"易错：豁免是银保监会基于审慎监管/金融稳定需要，非公司自行申请；暂缓须官网声明。","tag":""},{"id":"qa-15-08","difficulty":3,"q":"综合说明哪些情形需发布补充信息，并区分充足率变动与实际资本/最低资本变动比例的阈值。","answer_points":[{"point":"审计意见异常","detail":"审计机构出具除无保留意见外的审计报告，应发布补充信息。审计意见本身即重大信号，须向市场提示。"},{"point":"充足率不达标","detail":"审计后核心或综合偿付能力充足率不达标的，应发布补充信息。直接关系监管红线，须及时揭示。"},{"point":"充足率变动阈值","detail":"审计后核心或综合偿付能力充足率变动超过3个百分点，应发布补充信息。以'百分点'计量，阈值为3。"},{"point":"资本变动比例阈值","detail":"审计后实际资本或最低资本变动比例（审计后-审计前）÷审计前超过1%，应发布补充信息。以'百分比'计量，阈值为1。"},{"point":"其他与时限","detail":"上述及监管认为需披露的其他情况，自审计报告出具之日起10日内发布，注意变动比例公式分母为审计前金额。"}],"framework":"按触发情形分类，重点区分'3个百分点'（充足率）与'1%'（资本变动比例）两个阈值及计量单位。","memo":"易错：充足率变动用'百分点'、资本变动用'百分比/比例'；变动比例分母=审计前金额；时限10日。","tag":""}],"calc":[{"id":"c-15-01","difficulty":1,"stem":"某非上市保险公司审计前实际资本为200亿元，经审计后实际资本为204亿元。计算审计后实际资本的变动比例，并判断是否需要发布补充信息。","blanks":[{"label":"实际资本变动比例（%）","answer":2.0,"tolerance":0.5},{"label":"是否需发布补充信息（1是/0否）","answer":1,"tolerance":0}],"steps":["第1步：变动比例 = (审计后金额 - 审计前金额) ÷ 审计前金额 = (204 - 200) ÷ 200。","第2步：代入 = 4 ÷ 200 = 0.02 = 2.0%。","第3步：2.0% > 1% 阈值，需发布补充信息，标记1。"],"formula_card":"变动比例 = (审计后金额 - 审计前金额) ÷ 审计前金额","analysis":"变动比例 = (204 - 200) / 200 = 2.0%，超过1%阈值，应自审计报告出具之日起10日内发布补充信息。结论：变动比例2.0%，需发布（1）。","trap":"实际资本/最低资本变动比例的阈值是1%，不要与充足率变动的3个百分点混淆；分母为审计前金额。","tag":""},{"id":"c-15-02","difficulty":2,"stem":"某保险公司审计前综合偿付能力充足率为152%，审计后综合偿付能力充足率为147%。计算审计后综合偿付能力充足率的变动百分点，并判断是否需要发布补充信息。","blanks":[{"label":"综合偿付能力充足率变动（百分点）","answer":5,"tolerance":0.5},{"label":"是否需发布补充信息（1是/0否）","answer":1,"tolerance":0}],"steps":["第1步：充足率变动 = 审计后综合充足率 - 审计前综合充足率。","第2步：代入 = 147% - 152% = -5个百分点，取绝对变动5个百分点。","第3步：5个百分点 > 3个百分点阈值，需发布补充信息（1）。"],"formula_card":"充足率变动（百分点） = 审计后充足率 - 审计前充足率","analysis":"变动 = 147% - 152% = -5个百分点，绝对变动5个百分点，超过3个百分点阈值，应发布补充信息。结论：变动5个百分点，需发布（1）。","trap":"充足率变动以'百分点'计量，阈值为3个百分点；与资本变动比例的1%不同，单位勿混。","tag":""},{"id":"c-15-03","difficulty":3,"stem":"某保险公司审计前实际资本800亿元、最低资本400亿元；审计后实际资本760亿元、最低资本400亿元。分别计算审计前后综合偿付能力充足率，并综合判断是否需要发布补充信息（任一触发即发布）。","blanks":[{"label":"审计前综合偿付能力充足率（%）","answer":200,"tolerance":0.5},{"label":"审计后综合偿付能力充足率（%）","answer":190,"tolerance":0.5},{"label":"是否需发布补充信息（1是/0否）","answer":1,"tolerance":0}],"steps":["第1步：审计前综合充足率 = 实际资本 ÷ 最低资本 = 800 ÷ 400 = 200%。","第2步：审计后综合充足率 = 760 ÷ 400 = 190%。","第3步：综合充足率变动 = 200% - 190% = 10个百分点 > 3个百分点；实际资本变动比例 = (760 - 800) / 800 = -5% > 1%。任一触发，需发布（1）。"],"formula_card":"综合偿付能力充足率 = 实际资本 ÷ 最低资本；变动比例 = (后 - 前) ÷ 前","analysis":"审计前200%、审计后190%，充足率变动10个百分点超3阈值；实际资本变动比例-5%超1%阈值。任一条件满足即需发布补充信息。结论：200%、190%、需发布（1）。","trap":"综合充足率用百分点、资本变动用百分比，单位不同；实际资本变动比例分母=审计前800亿元；任一触发即发布。","tag":""}]},{"id":"rule-16","group":"监管规则","name":"第16号 偿付能力信息交流","qa":[{"id":"qa-16-01","difficulty":1,"q":"简述本规则的立法目的与偿付能力信息交流机制的特征。","answer_points":[{"point":"立法目的","detail":"建立健全偿付能力市场约束机制，加强偿付能力信息交流，发挥相关方监督作用，有效防范风险。与第15号互补，从'披露'延伸到'交流'。"},{"point":"机制特征","detail":"银保监会与相关方建立持续、双向、互动的偿付能力信息交流机制。区别于第15号单向公开披露，强调双向互动。"},{"point":"规范对象","detail":"本规则规范银保监会与相关方之间持续、双向、互动的信息交流机制，主体包括监管机关与各相关方，明确监管机关是交流发起与组织方。"},{"point":"发布时间","detail":"本规则2015年2月13日第一次发布、2021年12月30日修订发布，与第15号同日修订，体现二期工程同步更新。"}],"framework":"目的—机制特征—规范主体—修订时间，四步展开。","memo":"易错：第16号是'双向互动'交流，区别于第15号'单向公开披露'。","tag":""},{"id":"qa-16-02","difficulty":1,"q":"列举本规则所称'相关方'的八类主体，并简要说明其角色。","answer_points":[{"point":"保险消费者","detail":"作为信息使用者与监督方，监管可通过座谈、问卷、访谈向其介绍情况，是市场约束的需求侧。"},{"point":"保险公司股东","detail":"监管通过培训、情况通报等建立交流，重大风险时向股东通报，股东是公司治理与资本供给方。"},{"point":"审计机构","detail":"作为外部鉴证方纳入相关方，参与偿付能力信息质量保障。"},{"point":"信用评级机构","detail":"与监管建立定期交流机制，并可就重大事项向监管报告，发挥评级信号作用。"},{"point":"行业分析师","detail":"同评级机构纳入定期交流，发挥市场解读作用，引导投资者预期。"},{"point":"研究机构","detail":"同前述专业机构，定期交流并具报告权，提供专业研究支撑。"},{"point":"政府部门","detail":"与财政部、人民银行、证监会等建立交流共享与协作机制，属跨监管部门协同。"},{"point":"新闻媒体","detail":"至少每半年通过发布会等通报情况，属公众沟通渠道，保障社会知情权。"}],"framework":"八类主体逐类点出，注意与第15号'信息使用者'概念不同，第16号明确列举八类。","memo":"易错：相关方含'新闻媒体'但不含'保险公司董事'；政府部门含财政部、人民银行、证监会等。","tag":""},{"id":"qa-16-03","difficulty":2,"q":"说明偿付能力监管工作信息与季度通报在频率、内容、发布渠道上的区别。","answer_points":[{"point":"季度通报","detail":"银保监会每季度对外通报保险业偿付能力充足率和风险综合评级总体情况，频度高、内容为行业总体指标。"},{"point":"半年度发布","detail":"银保监会每半年发布一次偿付能力监管工作信息，内容为制度建设、监管措施、下一步重点等监管工作情况，频度低、内容广。"},{"point":"内容区别","detail":"季度通报是行业总体指标（充足率、评级）；半年度发布是监管工作信息（总体状况加监管工作情况），范围更广、更具工作性。"},{"point":"渠道区别","detail":"监管工作信息在官网定期发布，也可经官方公众号、新闻发布会、新闻通气会发布；协会专栏是第15号披露渠道，非本规则发布渠道。"}],"framework":"按频率、内容、渠道三维对比季度通报与半年度发布，并排除协会专栏。","memo":"易错：季度通报=行业总体情况（高频）；半年度发布=监管工作信息（低频）；协会专栏属第15号。","tag":""},{"id":"qa-16-04","difficulty":2,"q":"说明银保监会与保险消费者、保险公司股东交流的机制与方式。","answer_points":[{"point":"与消费者方式","detail":"通过座谈会、问卷调查、访谈等方式介绍监管工作情况、听取意见建议，体现自下而上听取市场声音。"},{"point":"与股东常规方式","detail":"通过培训、情况通报等方式建立交流机制，不定期向股东通报监管工作情况，提升股东偿付能力认知。"},{"point":"与股东重大风险方式","detail":"对存在重大偿付能力风险或风险管理重大缺陷的公司，向保险公司股东通报有关情况，将风险直接传导至资本方。"},{"point":"股东沟通意义","detail":"促使股东关注并支持公司改善偿付能力，发挥资本所有者监督作用，与日常披露中的股东沟通相呼应。"}],"framework":"消费者（座谈/问卷/访谈）与股东（培训/通报，重大风险专项通报）两类分别说明。","memo":"易错：向股东通报限'重大风险或重大缺陷'公司；消费者方式含问卷但不含强制披露。","tag":""},{"id":"qa-16-05","difficulty":2,"q":"说明银保监会与信用评级机构、行业分析师、研究机构建立的定期交流机制及其报告权事项。","answer_points":[{"point":"定期交流机制","detail":"银保监会与信用评级机构、行业分析师、研究机构建立定期交流机制，区别于与消费者的不定期方式。"},{"point":"交流方式","detail":"通过座谈会、新闻发布会、访谈等方式就偿付能力信息交流，与新闻媒体方式部分重叠但属定期安排。"},{"point":"报告权","detail":"上述机构发现法定事项时，有权向银保监会报告，是市场专业机构向监管反馈的通道。"},{"point":"报告事项","detail":"包括宏观经济重大变化可能影响偿付能力、公司存在重大偿付能力风险、风险管理重大缺陷、其他危及偿付能力事项，覆盖外部与内部风险信号。"}],"framework":"定期机制+交流方式+四项报告权事项，突出专业机构双向作用。","memo":"易错：评级机构等是'定期'交流；报告事项四类须完整（宏观、重大风险、重大缺陷、其他）。","tag":""},{"id":"qa-16-06","difficulty":3,"q":"对比第15号（信息披露）与第16号（信息交流）的异同，分析市场约束机制的双重路径。","answer_points":[{"point":"第15号定位","detail":"规范保险公司向社会公众或利益相关方公开披露，是单向、强制、标准化的信息披露，主体是被监管公司。"},{"point":"第16号定位","detail":"规范银保监会与相关方持续双向互动的信息交流，是双向、监管主导的交流机制，主体是监管机关。"},{"point":"相同点","detail":"二者目的均为建立健全偿付能力市场约束机制、防范风险，同属二期工程同日修订，目标完全一致。"},{"point":"差异点","detail":"主体不同（公司 vs 监管）、方向不同（单向披露 vs 双向交流）、内容不同（公司个体信息 vs 行业总体与监管工作信息）。"},{"point":"双重路径","detail":"公司披露提供市场可比基准，监管交流补充行业视角与专业反馈，二者构成市场约束的'公司披露+监管交流'双层路径。"}],"framework":"先分述两规则主体与方向，再归纳异同，最后提炼市场约束双重路径。","memo":"易错：第15号主体是被监管公司，第16号主体是银保监会；二者均服务于市场约束机制。","tag":""},{"id":"qa-16-07","difficulty":3,"q":"说明偿付能力监管工作信息的发布时间节点与临时发布依据，分析监管的灵活性。","answer_points":[{"point":"上半年信息时限","detail":"原则上每年9月30日前发布上半年偿付能力监管工作信息，即滞后约一个季度发布，便于汇总半年度情况。"},{"point":"上一年度信息时限","detail":"原则上每年3月31日前发布上一年度监管工作信息，形成跨年发布节奏，与会计年度衔接。"},{"point":"发布频率","detail":"每半年一次，一年共两次（上半年加上一年度），与季度通报（4次）频度不同。"},{"point":"临时发布","detail":"银保监会根据监管工作需要，可临时发布偿付能力监管工作信息，体现监管的机动性与应急性。"}],"framework":"两个时间节点（9.30/3.31）+频率（半年）+临时发布依据（监管需要）。","memo":"易错：上半年信息9月30日前（非6月30日）；上一年度信息在次年3月31日前；临时发布依据'监管工作需要'。","tag":""},{"id":"qa-16-08","difficulty":3,"q":"说明银保监局参照执行的条款范围及与新闻媒体交流的频率要求，分析规则的可执行性。","answer_points":[{"point":"银保监局参照条款","detail":"银保监局可参照本规则第九条至第十四条规定建立辖区交流机制，即消费者、股东、评级机构、政府部门、新闻媒体等交流条款。"},{"point":"参照灵活性","detail":"可结合辖区实际建立与股东、中介机构、消费者等市场相关方的机制，赋予派出机构因地制宜空间。"},{"point":"与新闻媒体频率","detail":"银保监会与新闻媒体至少每半年通过新闻发布会、新闻通气会、媒体采访通报情况，保底频度为半年一次。"},{"point":"可执行性意义","detail":"自上而下（会）与属地（局）双层机制加明确频度，使信息交流既有统一框架又可落地执行。"}],"framework":"银保监局参照范围（第九条至第十四条）+新闻媒体保底频率（半年）+可执行性分析。","memo":"易错：银保监局参照的是第九条至第十四条，非全文；与新闻媒体'至少每半年'一次。","tag":""}],"calc":[{"id":"c-16-01","difficulty":1,"stem":"银保监会每季度对外通报保险业偿付能力充足率和风险综合评级总体情况。计算一年内银保监会对外通报上述总体情况的次数。","blanks":[{"label":"年度通报次数（次）","answer":4,"tolerance":0}],"steps":["第1步：通报频率为每季度一次。","第2步：一年共4个季度，次数 = 4 × 1 = 4次。","第3步：结论为4次/年。"],"formula_card":"年度次数 = 季度数(4) × 每季次数(1)","analysis":"每季度通报1次，全年4个季度，共4次。区别于半年度监管工作信息发布（2次/年）。结论：4次。","trap":"注意季度通报（4次/年）与半年度监管工作信息发布（2次/年）频率不同，勿混。","tag":""},{"id":"c-16-02","difficulty":2,"stem":"银保监会每半年发布一次偿付能力监管工作信息，其中上半年信息最迟于每年9月30日前发布，上一年度信息最迟于次年3月31日前发布。计算一年内监管工作信息发布的次数，以及上半年信息与上一年度信息发布截止月份。","blanks":[{"label":"年度发布次数（次）","answer":2,"tolerance":0},{"label":"上半年信息截止月份","answer":9,"tolerance":0},{"label":"上一年度信息截止月份","answer":3,"tolerance":0}],"steps":["第1步：每半年发布一次，一年2次。","第2步：上半年信息截止日为9月30日，对应月份9。","第3步：上一年度信息截止日为3月31日，对应年份次月的月份3。"],"formula_card":"年度发布次数 = 12月 ÷ 6月 = 2次；截止月份：上半年=9，上一年度=3","analysis":"半年发布一次即2次/年；上半年信息9月30日前、上一年度信息3月31日前。结论：2次、9月、3月。","trap":"上半年信息截止在9月（非6月）；上一年度信息在次年3月（跨年）发布。","tag":""},{"id":"c-16-03","difficulty":3,"stem":"某年度银保监会计划开展有明确频率要求的信息交流活动：季度通报偿付能力充足率总体情况；每半年发布一次监管工作信息；与新闻媒体至少每半年通报一次。计算该年度上述明确频率活动的次数下限（与评级机构等的定期交流无明确次数下限，不计入；临时发布不计入）。","blanks":[{"label":"季度通报次数（次）","answer":4,"tolerance":0},{"label":"监管工作信息发布次数（次）","answer":2,"tolerance":0},{"label":"新闻媒体通报次数下限（次）","answer":2,"tolerance":0},{"label":"明确频率活动合计下限（次）","answer":8,"tolerance":0}],"steps":["第1步：季度通报每季1次，全年4次。","第2步：监管工作信息半年1次，全年2次。","第3步：新闻媒体至少半年1次，全年下限2次；合计 = 4 + 2 + 2 = 8次。"],"formula_card":"合计下限 = 4(季度) + 2(半年发布) + 2(媒体) = 8次","analysis":"季度通报4次、监管工作信息2次、新闻媒体至少2次，合计下限8次。与评级机构等的定期交流无明确次数下限，不计入。结论：4、2、2、8。","trap":"与信用评级机构、行业分析师、研究机构的'定期交流'无明确次数下限，不计入合计；临时发布也不计入。","tag":""}]},{"id":"rule-17","group":"监管规则","name":"第17号 保险公司信用评级","qa":[{"id":"qa-17-01","difficulty":1,"q":"简述《保险公司偿付能力监管规则第17号：保险公司信用评级》的制定目的与适用范围。","answer_points":[{"point":"规范评级行为","detail":"本规则旨在规范信用评级机构对保险公司的信用评级行为，使评级活动有章可循，避免无序竞争与利益冲突侵蚀评级公信力。"},{"point":"发挥市场约束","detail":"通过信用评级向市场传递保险公司信用风险信号，发挥市场对偿付能力的外侧约束作用，弥补监管资源的有限性。"},{"point":"适用主体","detail":"适用于依法在境内设立的经营商业保险业务的保险公司和外国保险公司分公司，保险集团、相互保险组织同样适用本规则。"},{"point":"监管主体","detail":"本规则由银保监会负责解释和修订，保证评级监管口径的统一性与权威性。"},{"point":"修订沿革","detail":"规则于2015年2月13日第一次发布，于2021年12月30日随偿二代二期修订发布，与二期工程整体同步推进。"}],"framework":"目的→适用→监管主体→沿革，四段式作答。","memo":"适用对象不局限于中资险企，外资分公司、保险集团、相互保险组织都算在内。","tag":""},{"id":"qa-17-02","difficulty":1,"q":"保险公司信用评级包含哪两大类型？请分别说明其含义。","answer_points":[{"point":"主体评级","detail":"对保险公司整体信用状况的评级，反映公司整体偿付能力与信用风险水平，是评级的基础层级。"},{"point":"债项评级","detail":"对保险公司发行的债务工具、资本工具等具体债项的评级，重点关注该债项自身的信用风险特征。"},{"point":"两者关系","detail":"主体评级刻画公司整体，债项评级在主体信用之上叠加债项特有因素，二者评级逻辑不同但相互关联。"},{"point":"评级原则","detail":"评级机构从事保险公司评级业务应遵循独立、客观、公正原则，确保评级结果可信可比。"}],"framework":"主体评级+债项评级+二者关系+原则。","memo":"主体评“公司”，债项评“具体工具”，概念不要颠倒。","tag":""},{"id":"qa-17-03","difficulty":2,"q":"境内信用评级机构从事保险公司信用评级业务，应当具备哪些主要资质条件？","answer_points":[{"point":"法人资格","detail":"应具有境内法人资格，这是境内评级机构开展评级业务的基本主体资格要求。"},{"point":"资本门槛","detail":"最近年度末实收资本和净资产均不低于2000万元，体现机构的风险承担能力与经营实力。"},{"point":"专业人员","detail":"应具备3年以上信用评级业务经验的专业人员不少于20人，其中从事保险公司信用评级的不少于3人。"},{"point":"诚信记录","detail":"应具有良好的诚信记录，最近3年没有重大违法违规行为，保证机构声誉与独立性。"},{"point":"业务制度","detail":"应具有健全的业务制度，涵盖评级标准、程序、方法、实地调查、跟踪、披露、评审委员会、独立性、保密及档案管理等。"},{"point":"配合监管","detail":"须向银保监会递交《配合监管承诺函》，承诺及时全面报送材料并自觉接受监督检查。"}],"framework":"资格—资本—人员—诚信—制度—承诺，六要素作答。","memo":"实收资本“和”净资产“均”不低于2000万元，是“且”不是“或”。","tag":""},{"id":"qa-17-04","difficulty":2,"q":"保险公司选聘境内信用评级机构应采用何种方式？投标邀请有哪些基本要求？","answer_points":[{"point":"招标方式","detail":"选聘境内评级机构应当采用公开招标或邀请招标方式，规则明确禁止直接委托等随意选聘。"},{"point":"投标家数","detail":"发出投标邀请的信用评级机构不得少于3家，以保证选聘过程的竞争性与公平性。"},{"point":"中资要求","detail":"受邀机构中至少应有1家中资信用评级机构，保障境内评级话语权与监管可触达性。"},{"point":"报告义务","detail":"与评级机构签订聘用合同之日起10个工作日内，应当向银保监会书面报告选聘结果。"},{"point":"材料提供","detail":"保险公司应按双方约定，向评级机构提供真实的财务报告、偿付能力报告、业务发展规划、风险管理报告等必要材料。"}],"framework":"招标—家数—中资—报告—材料，逐条作答。","memo":"“10个工作日”不是10个自然日；“3家”中包含“至少1家中资”。","tag":""},{"id":"qa-17-05","difficulty":2,"q":"对比分析境内与境外信用评级机构在准入条件上的主要差异。","answer_points":[{"point":"适用场景","detail":"保险公司在境内融资、开展保险业务等需要评级的，应当聘境内机构；境外融资或开展国际业务等情况下，可以聘境外机构。"},{"point":"资本与人员门槛","detail":"境内机构须满足2000万元资本、3年以上经验专业人员不少于20人（其中保险评级不少于3人）等硬门槛；境外机构不适用这些要求。"},{"point":"监管备案","detail":"境外机构只需符合所在地监管部门的监管要求，且其评级程序已向银保监会备案即可开展业务。"},{"point":"共同义务","detail":"无论境内外机构，均须向银保监会递交《配合监管承诺函》，承诺积极配合监管。"},{"point":"逻辑本质","detail":"对境内机构设准入门槛保质量，对境外机构重程序备案降壁垒，体现分类监管与开放并重的思路。"}],"framework":"场景—门槛—备案—共同义务—逻辑，对比作答。","memo":"境外机构“不需”资本人员条件，但“需”承诺函+程序备案。","tag":""},{"id":"qa-17-06","difficulty":3,"q":"债项评级与主体评级在考量因素上有何区别？结合监管逻辑加以分析。","answer_points":[{"point":"主体考量基础","detail":"主体评级关注保险公司整体信用状况，涵盖经营、财务、偿付能力等公司总体层面的风险因素。"},{"point":"债项额外因素","detail":"债项评级除公司总体状况外，还应综合考量该债项的发行协议、期限、清偿顺序、转股权利、增信措施等特点。"},{"point":"清偿顺序意义","detail":"清偿顺序靠后的债项受偿优先级更低、风险更高，评级应真实反映其相对主体更弱的次级属性。"},{"point":"增信作用","detail":"担保、抵押等增信措施可提升债项评级，使债项评级可能高于主体评级，二者并非简单包含关系。"},{"point":"监管逻辑","detail":"投资者实际持有的是具体债项，需要了解该工具的真实风险结构，故要求债项评级精细化，以保护债权人利益。"}],"framework":"主体基础→债项叠加五因素→逐因素分析→监管目的。","memo":"债项评级可能因增信“高于”主体评级，不要想当然认为债项≤主体。","tag":""},{"id":"qa-17-07","difficulty":3,"q":"信用评级机构出现哪些违规行为时，银保监会有权责令保险公司更换评级机构乃至不认可其评估报告？分析监管处置逻辑。","answer_points":[{"point":"虚假材料","detail":"向银保监会、保险公司提供虚假材料的，银保监会有权责令保险公司更换该评级机构。"},{"point":"利益冲突","detail":"与被评价保险公司之间存在除评级业务以外的重大利益关系、不能确保自身独立性的，应当更换。"},{"point":"泄露信息","detail":"未经保险公司同意，将评级过程中掌握的信息向社会公布或泄露给他人的，应当更换。"},{"point":"合谋篡改","detail":"与保险公司合谋篡改评级资料或歪曲评级结果的，应当责令更换。"},{"point":"不正当竞争","detail":"以压价竞争、诋毁同行、以级定价、以价定级等不正当竞争手段招揽业务的，应当责令更换。"},{"point":"严重处置","detail":"情节严重时，银保监会不认可其评估报告，直接影响该机构在监管体系内的采信效力。"},{"point":"监管逻辑","detail":"通过“责令更换+不认可报告”的双层威慑，倒逼评级机构保持独立客观，维护评级市场秩序。"}],"framework":"五类违规→责令更换→情节严重不认可→监管逻辑。","memo":"“责令更换”与“不认可报告”是两档处置，情节严重才到第二档。","tag":""},{"id":"qa-17-08","difficulty":3,"q":"结合规则主线，说明保险公司信用评级从机构准入到持续监管的全程要求。","answer_points":[{"point":"准入界定","detail":"先界定谁能评级：境内机构须满足资本、人员、诚信等条件，境外机构须符合所在地要求并备案。"},{"point":"选聘规范","detail":"采用公开或邀请招标，邀请不少于3家且含至少1家中资机构，签合同后10个工作日内向监管报告。"},{"point":"评级程序","detail":"评级机构须履行科学完整程序，对不同公司采用一致标准与工作程序，并在有效期内持续跟踪、及时更新结果。"},{"point":"信息披露","detail":"保险公司应按第18号规则要求，在偿付能力季度报告中披露信用评级的有关信息，实现市场透明。"},{"point":"配合监管","detail":"评级机构须递交承诺函、书面报送信用等级划分标准及其含义的说明，监管可应其申请提供信息与意见。"},{"point":"违规报告","detail":"评级机构发现保险公司存在重大违法违规行为时，应当向银保监会报告，形成双向监督闭环。"},{"point":"主线逻辑","detail":"规则主线为“谁能评→怎么选→怎么评→怎么管”，实现评级活动全流程闭环监管。"}],"framework":"准入→选聘→评级→披露→配合→报告→主线。","memo":"第18号规则承接评级信息披露义务，两规则存在明确衔接。","tag":""}],"calc":[{"id":"c-17-01","difficulty":1,"stem":"某保险公司拟在境内融资并选聘信用评级机构。根据规则要求，该公司发出投标邀请的信用评级机构总数最少应为多少家？其中至少应包含多少家中资信用评级机构？","blanks":[{"label":"发出投标邀请的信用评级机构最少家数（家）","answer":3,"tolerance":0.5},{"label":"其中至少包含的中资信用评级机构家数（家）","answer":1,"tolerance":0.5}],"steps":["第1步：依据第十条，保险公司发出投标邀请的信用评级机构不得少于3家。","第2步：受邀机构中至少应有1家中资信用评级机构。","第3步：综合得出最少3家、其中至少1家中资的结论。"],"formula_card":"发出投标邀请的信用评级机构≥3家，且其中至少1家中资信用评级机构。","analysis":"直接适用第十条的硬性数量要求，投标邀请总数下限为3家，中资机构下限为1家（中资包含在这3家之内，而非额外增加）。","trap":"注意“至少3家”且“至少1家中资”，中资机构是包含在3家内而非在3家之外另行增加。","tag":""},{"id":"c-17-02","difficulty":2,"stem":"某境内信用评级机构专业人员名册显示：具有3年以上信用评级业务经验的人员共22人，其中同时标注从事保险公司信用评级业务的有4人。请核验该机构在专业人员条件上是否达标（达标线：3年以上经验人员不少于20人，其中从事保险公司评级不少于3人）。","blanks":[{"label":"具备3年以上经验的专业人员数（人）","answer":22,"tolerance":0.5},{"label":"其中从事保险公司信用评级的专业人员数（人）","answer":4,"tolerance":0.5}],"steps":["第1步：提取名册中“3年以上经验”人员数22人，与门槛20人比较，22≥20，达标。","第2步：提取其中“从事保险公司评级”人员数4人，与门槛3人比较，4≥3，达标。","第3步：两项均满足，判定该机构专业人员条件整体达标。"],"formula_card":"3年以上评级经验专业人员≥20人，其中从事保险公司信用评级≥3人。","analysis":"该机构3年以上经验人员22人（超门槛2人），其中保险评级人员4人（超门槛1人），两项均满足第八条第（三）项要求，专业人员条件达标。","trap":"两个门槛是“且”的关系，须同时满足；勿把“从事保险评级的3人”误当成在20人之外的额外要求。","tag":""},{"id":"c-17-03","difficulty":3,"stem":"某境内评级机构拟承接保险公司评级业务，已知：①最近年度末实收资本1800万元、净资产2600万元（门槛：实收资本和净资产均不低于2000万元）；②3年以上经验专业人员21人，其中从事保险公司评级4人（门槛：前者≥20人、后者≥3人）；③最近3年仅有1次一般违规、无重大违法。请计算资本缺口/盈余及人员超出情况，并判断该机构能否承接业务。","blanks":[{"label":"实收资本相对门槛的缺口（万元，负值表示不足）","answer":-200,"tolerance":0.1},{"label":"净资产相对门槛的盈余（万元，正值表示超出）","answer":600,"tolerance":0.1},{"label":"从事保险公司评级人员超出最低要求的人数（人）","answer":1,"tolerance":0.5}],"steps":["第1步：资本条件核验——实收资本1800万元＜2000万元门槛，缺口=1800-2000=-200万元，不达标；净资产2600万元≥2000万元，盈余=2600-2000=600万元。","第2步：人员条件核验——3年以上经验21人≥20人、保险评级4人≥3人，保险评级超出最低要求=4-3=1人，达标。","第3步：综合判断——资本条件中“实收资本和净资产均不低于2000万元”为“且”关系，因实收资本不足，该机构整体不符合承接资质，诚信记录虽满足仍不能弥补资本缺口。"],"formula_card":"实收资本≥2000万元 且 净资产≥2000万元；3年以上经验人员≥20人 且 保险评级人员≥3人。","analysis":"实收资本缺口-200万元、净资产盈余600万元、保险评级人员超出1人。结论：专业人员条件达标，但实收资本未达2000万元门槛，资本条件不满足“均不低于”的要求，故该机构不能承接保险公司评级业务。","trap":"资本门槛是“均不低于”（且关系），任一项不足即整体不达标；诚信“最近3年无重大违法”满足也不能替代资本硬门槛。","tag":""}]},{"id":"rule-18","group":"监管规则","name":"第18号 偿付能力报告","qa":[{"id":"qa-18-01","difficulty":1,"q":"保险公司向银保监会报送的偿付能力报告包括哪几类？各自有何定位？","answer_points":[{"point":"季度报告","detail":"是最完整的报告，含公司信息、董事会和管理层声明、主要指标、风险管理能力、实际资本、最低资本、压力测试等共十二（十三节）部分，是偿二代报告体系核心。"},{"point":"季度快报","detail":"仅包括基本信息和主要指标两部分，突出时效性，用于监管快速掌握偿付能力轮廓。"},{"point":"临时报告","detail":"针对偿付能力不足、重大不利影响事项、审计重大变动、重大流动性风险等突发或异常事项专门报送。"},{"point":"责任主体","detail":"保险公司董事会和管理层对所报送报告的真实性、准确性、完整性和合规性负责。"}],"framework":"三类报告+责任主体，逐类说明。","memo":"快报“只有两部分”；临时报告是“因事件触发”而非定期。","tag":""},{"id":"qa-18-02","difficulty":1,"q":"偿付能力季度报告应遵循的“一体观”原则是什么含义？","answer_points":[{"point":"基本含义","detail":"将报告季度视为年度会计期间的一部分，而非孤立独立的会计时段。"},{"point":"判断依据","detail":"以对整个年度经营状况和财务状况的判断，来决定季度末的会计估计、成本分配、递延和应计等项目。"},{"point":"监管目的","detail":"防止公司利用季度间的调节扭曲全年真实业绩，保证财务信息在年度维度上的连贯与可比。"},{"point":"例外规定","detail":"银保监会特别规定的除外，体现原则性与灵活性相结合。"}],"framework":"含义—依据—目的—例外，四段式。","memo":"一体观是“以年看季”，不是各季度独立核算。","tag":""},{"id":"qa-18-03","difficulty":2,"q":"季度报告应由哪些人员签字？第1、3季度在审议程序上有何特殊规定？","answer_points":[{"point":"七类签字人员","detail":"董事长、总经理（或具有相同职权的公司高级管理人员）、财务负责人、精算负责人、投资负责人、首席风险官、合规负责人。"},{"point":"加盖印章","detail":"上述人员签字并加盖公司印章，共同对报告质量承担责任。"},{"point":"1、3季度特殊审议","detail":"第1季度和第3季度的偿付能力报告可以不经过董事会审议，但须经董事长批准并作相应声明。"},{"point":"外资分公司例外","detail":"本规则第11至13条有关董事会和董事长的要求，不适用于外国保险公司分公司。"},{"point":"审计要求","detail":"第四季度季度报告应当经会计师事务所审计，其余三个季度可根据自身需要或监管要求委托审计。"}],"framework":"七签字—盖章—1/3季免董事会—外资例外—审计。","memo":"监事会主席“不在”签字人范围；1、3季免董事会但需董事长批准。","tag":""},{"id":"qa-18-04","difficulty":2,"q":"请说明偿付能力报告各类报送时限的要求。","answer_points":[{"point":"季度快报","detail":"应当在每季度结束后12日内报送，时限最短以突出时效。"},{"point":"季度报告","detail":"应当在每季度结束后25日内报送。"},{"point":"年度审计报送","detail":"每年4月30日前报送上一年度第四季度季度报告的审计报告和经审计报告。"},{"point":"临时报告（不足/不利影响）","detail":"偿付能力不足、重大不利影响事项，自发现或发生之日起5个工作日内报告。"},{"point":"临时报告（审计重大变动）","detail":"审计后相关重大变动，自审计报告出具之日起10日内报告。"},{"point":"临时报告（流动性风险）","detail":"重大流动性风险自发现之日起3日内报告，是各类时限中最短的。"}],"framework":"定期两类+年度+三类临时，按时限长短罗列。","memo":"流动性风险3日最短；不足/不利影响5个工作日；审计变动10日。","tag":""},{"id":"qa-18-05","difficulty":2,"q":"偿付能力报告中“重大再保险合同”“重大投资损失”“重大融资事项”的认定标准分别是什么？","answer_points":[{"point":"重大再保险合同","detail":"分入（分出）保额超过保险公司本季度末有效保额5%，或分入（分出）保费超过报告期保费收入5%的单项再保险合同（保额与保费门槛为“或”关系）。"},{"point":"重大投资损失","detail":"单项股权投资、不动产投资、基础设施投资、信托资产投资、资产证券化产品投资等的投资损失金额，超过报告期末净资产总额5%的投资损失。"},{"point":"重大融资事项","detail":"报告期内增资扩股、发行债务性资本工具等单笔融资金额，超过公司报告期末净资产10%的融资活动。"},{"point":"其他重大事项","detail":"还包括重大赔付（财险再保后赔付前五位）、重大诉讼（标的前三位）、重大投资行为等认定标准。"},{"point":"阈值逻辑","detail":"统一以“占净资产/保费/保额的比例”量化门槛，便于横向比较并在触发时及时监管介入。"}],"framework":"再保险5%/保费5%—投资损失5%—融资10%—其他—逻辑。","memo":"再保险合同“保额5%或保费5%”是“或”；投资损失5%与融资10%勿混。","tag":""},{"id":"qa-18-06","difficulty":3,"q":"保险公司风险管理自评估有哪些具体要求？请综合分析。","answer_points":[{"point":"评估频率","detail":"保险公司应当对照第12号规则各项要求，每年至少开展一次风险管理自评估。"},{"point":"九个部分","detail":"自评估应区分九个部分：风险管理基础与环境、风险管理目标与工具、保险风险管理、市场风险管理、信用风险管理、操作风险管理、战略风险管理、声誉风险管理、流动性风险管理。"},{"point":"五档符合程度","detail":"评估结果符合程度分为完全符合、大部分符合、部分符合、不符合、不适用五档，逐项列报。"},{"point":"季度自评估","detail":"保险公司应当每季度对操作风险、战略风险、声誉风险和流动性风险开展自评估，频率高于全面自评估。"},{"point":"监管意义","detail":"自评估是公司风险管理的自我体检，监管据此识别薄弱环节并实施分类监管，形成持续改进的闭环。"}],"framework":"频率—九部分—五档—四类季度—监管意义。","memo":"全面自评估“每年”一次，四类风险“每季度”一次；符合程度是“五档”非四档。","tag":""},{"id":"qa-18-07","difficulty":3,"q":"人身保险公司与财产保险公司在偿付能力报告经营指标列报上有何差异？分析其监管逻辑。","answer_points":[{"point":"财险效益类指标","detail":"财产保险公司应列报综合成本率、综合费用率、综合赔付率、手续费及佣金占比、业务管理费占比等效益类指标。"},{"point":"人身险新业务指标","detail":"人身保险公司应列报新业务利润率（=本期新业务首日利得÷新业务各期保费收入之和×100%）、剩余边际、新业务价值等。"},{"point":"人身险品质类指标","detail":"人身保险公司应列报13个月续保率、综合退保率、个人营销渠道件均保费、人均保费、营销员脱落率等品质类指标。"},{"point":"共通指标","detail":"偿付能力充足率、流动性风险监管指标等为核心共通指标，两类公司均需列报。"},{"point":"监管逻辑","detail":"按业务性质差异化设置指标，使列报真正反映各险种的风险驱动因素，避免一刀切，提升监管针对性。"}],"framework":"财险指标—人身新业务—人身品质—共通—监管逻辑。","memo":"综合成本率是“财险”效益指标；13个月续保率、综合退保率是“人身险”品质指标。","tag":""},{"id":"qa-18-08","difficulty":3,"q":"临时报告中“重大不利影响事项”与“审计后重大变动”各包含哪些情形？结合报告时限分析监管逻辑。","answer_points":[{"point":"不足/重大不利影响情形","detail":"偿付能力不足，重大投资损失，重大赔付、大规模退保或重大诉讼，主要股东/子公司/合营企业财务危机或被接管，重大资产遭冻结或受重大行政处罚等，均须报告。"},{"point":"不足/不利时限","detail":"上述事项自发现或发生之日起5个工作日内向银保监会报告。"},{"point":"审计重大变动情形","detail":"审计机构出具非无保留意见，审计后充足率不达标，核心或综合偿付能力充足率变动超过3个百分点，实际资本或最低资本变动比例超过1%。"},{"point":"审计变动时限","detail":"审计后重大变动自审计报告出具之日起10日内报告。"},{"point":"监管逻辑","detail":"风险越紧急时限越短（流动性3日<不足/不利5工作日<审计变动10日），确保监管及时介入、防范风险外溢。"}],"framework":"三类情形—各自时限—差异—监管逻辑。","memo":"审计变动看“充足率变动超3个百分点”和“资本变动超1%”两道门槛。","tag":""}],"calc":[{"id":"c-18-01","difficulty":1,"stem":"某保险公司报告期期初净资产为100000万元，期末净资产为120000万元，报告期实现净利润11000万元。请计算该公司报告期的净资产收益率（保留两位小数）。","blanks":[{"label":"净资产收益率（%）","answer":10.0,"tolerance":0.5}],"steps":["第1步：计算平均净资产=（期初净资产＋期末净资产）÷2=（100000＋120000）÷2=110000万元。","第2步：套用公式：净资产收益率=净利润÷平均净资产×100%=11000÷110000×100%。","第3步：得出结果=0.10×100%=10.00%。"],"formula_card":"净资产收益率＝净利润÷[（期初净资产＋期末净资产）÷2]×100%","analysis":"平均净资产为110000万元，净利润11000万元占其10.00%，净资产收益率计算结果为10.00%，反映公司运用净资产创利的能力。","trap":"分母是“期初与期末的平均净资产”而非期末净资产；结果以百分比表示，注意乘以100%。","tag":""},{"id":"c-18-02","difficulty":2,"stem":"某人身保险公司上年可比季度末长期寿险有效保单为10000件，本季度末其中仍然有效的保单为8500件。请计算失效保单件数及13个月续保率（保留两位小数）。","blanks":[{"label":"失效保单件数（件）","answer":1500,"tolerance":0.5},{"label":"13个月续保率（%）","answer":85.0,"tolerance":0.5}],"steps":["第1步：计算失效保单件数=上年可比季末有效保单10000件－本季末仍有效8500件=1500件。","第2步：套用公式：13个月续保率=仍有效保单数÷上年可比季末有效保单数×100%=8500÷10000×100%。","第3步：得出续保率=0.85×100%=85.00%。"],"formula_card":"13个月续保率＝（上年可比季度末长期寿险有效保单在本季度末仍有效的保单数量÷上年可比季度末长期寿险有效保单数量）×100%","analysis":"失效保单1500件，13个月续保率为85.00%，该指标反映长期寿险保单的留存水平，是人身险品质类核心指标。","trap":"分子是“仍有效”保单数而非失效数；分母为“上年可比季末”基数，注意口径对应。","tag":""},{"id":"c-18-03","difficulty":3,"stem":"某保险公司报告期末净资产为200000万元。已知：①单项股权投资发生投资损失12000万元；②单笔发行债务性资本工具融资25000万元；③审计后核心偿付能力充足率上季末为110%，本季末为106%。请计算重大投资损失与重大融资的认定门槛，并判断核心偿付能力充足率的变动幅度是否触发审计重大变动报告（重大投资损失门槛为净资产5%，重大融资门槛为净资产10%，审计重大变动中充足率变动超3个百分点即触发）。","blanks":[{"label":"重大投资损失认定门槛（万元，净资产5%）","answer":10000,"tolerance":0.5},{"label":"重大融资认定门槛（万元，净资产10%）","answer":20000,"tolerance":0.5},{"label":"核心偿付能力充足率变动（个百分点，本季减上季）","answer":-4,"tolerance":0.5}],"steps":["第1步：重大投资损失门槛=报告期末净资产×5%=200000×5%=10000万元；实际损失12000万元＞10000万元，触发重大投资损失。","第2步：重大融资门槛=报告期末净资产×10%=200000×10%=20000万元；实际融资25000万元＞20000万元，触发重大融资事项。","第3步：核心偿付能力充足率变动=本季末106%－上季末110%=-4个百分点，绝对值4＞3个百分点，触发审计后重大变动报告（须自审计报告出具之日起10日内报告）。"],"formula_card":"重大投资损失＞净资产×5%；重大融资＞净资产×10%；核心/综合充足率变动绝对值＞3个百分点触发审计重大变动。","analysis":"重大投资损失门槛10000万元（实际超出2000万元）、重大融资门槛20000万元（实际超出5000万元）、核心偿付能力充足率下降4个百分点（超3个百分点门槛）。三项均触发相应报告义务，其中审计重大变动需在10日内报告。","trap":"净资产5%与10%易混；充足率变动看“绝对值”是否超3个百分点；投资损失与融资是“超过”门槛即触发，不计等于。","tag":""}]},{"id":"rule-19","group":"监管规则","name":"第19号 保险集团","qa":[{"id":"qa-19-01","difficulty":1,"q":"请简述保险集团的基本类别，并说明各类别的核心划分依据。","answer_points":[{"point":"保险控股型集团","detail":"由一家保险集团（控股）公司或保险公司，与受其直接或间接控制、共同控制的若干保险公司及其他非保险机构共同形成的企业集合，控制人体现为显性保险母公司。"},{"point":"非保险控股型集团","detail":"由非保险机构作为母公司，与受其控制或共同控制的若干保险公司及其他非保险机构共同形成的企业集合，集团母公司本身不经营保险主业。"},{"point":"混合型集团","detail":"由同一实际控制人或一致行动人控制（或共同控制）的多家保险公司组成，但不具有显性的控制人，结构更松散、股权更隐晦。"},{"point":"划分意义","detail":"三类划分决定了实际资本评估方法、特征系数k2取值与监管报告主体，是后续资本计量与风险管理要求适用的前提。"}],"framework":"按'母公司属性＋是否显性控制人'二分法作答：保险母公司→控股型；非保险母公司→非保险控股型；无显性控制人但有共同实际控制人→混合型。","memo":"易错：混合所有制不等于混合型；混合型的关键特征是'无显性控制人'。","tag":""},{"id":"qa-19-02","difficulty":1,"q":"保险集团偿付能力监管分为哪几个层次？各层次的监管重点是什么？","answer_points":[{"point":"单一法人公司监管","detail":"针对集团内每家保险成员公司本身，按一般保险公司偿付能力监管规则计量其最低资本、实际资本与风险综合评级。"},{"point":"集团监管","detail":"在成员公司之上统筹计量集团层面特有风险（风险传染、集中度等）并评估集团整体偿付能力，防范集团化经营叠加风险。"},{"point":"系统重要性保险集团监管","detail":"对具有系统重要性的保险集团实施更严格的附加监管，关注其风险外溢和对金融体系的潜在冲击。"},{"point":"主监管机构","detail":"银保监会作为保险集团的主监管机构，承担集团范围监管协调职能，统筹三个层次的监管衔接。"}],"framework":"三层次由'个体→集团→系统'递进作答，并点出银保监会的主监管与协调角色。","memo":"易错：跨国联合监管不是三层次之一（选择题常设此干扰项）。","tag":""},{"id":"qa-19-03","difficulty":2,"q":"说明保险集团最低资本的构成，并简述集团层面可资本化特有风险最低资本的组成与计量方法。","answer_points":[{"point":"最低资本三部分","detail":"保险集团最低资本由可资本化风险最低资本、控制风险最低资本、附加资本三部分组成，不含单独的流动性风险最低资本。"},{"point":"可资本化风险最低资本组成","detail":"可资本化风险最低资本＝母公司最低资本＋子公司最低资本＋合营企业最低资本×权益比例＋集团层面可资本化特有风险对应最低资本－风险分散效应的资本要求减少。"},{"point":"集团层面特有风险组成","detail":"集团层面可资本化特有风险最低资本＝风险传染最低资本＋集中度风险最低资本，反映集团化经营产生的叠加风险。"},{"point":"综合因子法计量","detail":"采用综合因子法，MC＝EX×RF，其中RF＝RF0×(1+K)，K∈[-0.25,0.25]，EX为风险暴露、RF0为基础因子。"},{"point":"合营企业剔除","detail":"合营企业最低资本中，非本集团成员公司持股部分应剔除，即仅按本集团权益比例计入集团最低资本。"}],"framework":"先答最低资本三构成，再展开可资本化风险公式，最后落到集团层面特有风险＝风险传染＋集中度及综合因子法。","memo":"易错：最低资本不含'流动性风险最低资本'；合营企业须按权益比例并剔除外部持股。","tag":""},{"id":"qa-19-04","difficulty":2,"q":"对比保险控股型集团、非保险控股型集团、混合型集团在实际资本评估方法上的差异，并说明各自特征系数k2的取值。","answer_points":[{"point":"保险控股型集团用合并报表法","detail":"保险控股型集团采用合并报表法评估实际资本，将集团合并范围内的资本统一计量，k2取值为0。"},{"point":"非保险控股型集团用减项合并法","detail":"非保险控股型集团与混合型集团采用减项合并法，即集团实际资本＝成员公司实际资本之和－成员公司之间重复计算的资本，k2取值为0.1。"},{"point":"混合型集团用减项合并法","detail":"混合型集团同样采用减项合并法，因其无显性控制人，无法简单合并报表，须剔除成员间重复资本，k2取值为0.2。"},{"point":"减项合并法原理","detail":"减项合并法核心是消除成员公司之间资产转让、交叉持股等导致的资本重复计算，防止集团人为放大实际资本。"},{"point":"k2的监管含义","detail":"k2随集团类型递增（0→0.1→0.2），体现监管对隐性控制、结构不透明程度越高者赋予越大风险因子的审慎态度。"}],"framework":"按集团类型并列：控股型→合并报表法/k2=0；非保险控股型→减项合并法/k2=0.1；混合型→减项合并法/k2=0.2，并解释k2递增逻辑。","memo":"易错：k2最高是混合型0.2，而非非保险控股型；且只有非保险控股型与混合型用减项合并法。","tag":""},{"id":"qa-19-05","difficulty":2,"q":"说明保险集团集中度风险的三种类型，以及各自风险暴露与基础因子的规定。","answer_points":[{"point":"交易对手集中度","detail":"针对单一交易对手的暴露。全国性股份制商业银行限额为集团总资产5%、RF0=0.03；其他交易对手限额3%、RF0=0.05。"},{"point":"行业集中度","detail":"风险暴露为投资于单一行业资产超过集团总资产10%的部分，基础因子RF0=0.05；境内按申银万国一级行业、境外按GICS一级行业，境内外独立计算不得合并。"},{"point":"客户集中度","detail":"风险暴露为来自单一客户收入超过集团收入30%的部分，基础因子RF0=0.1。"},{"point":"聚合公式","detail":"集中度风险最低资本采用平方和开根号聚合：MC集中度＝√(MC交易对手²＋MC行业²＋MC客户²)，而非简单相加。"},{"point":"监管目的","detail":"防范成员公司单个或组合风险在集团层面聚合后造成非预期损失，是集团特有风险的重要组成部分。"}],"framework":"三类并列（交易对手/行业/客户），各答'限额口径＋RF0'，最后给出聚合公式与监管目的。","memo":"易错：交易对手限额与RF0反向配对（股份行5%/0.03，其他3%/0.05）；聚合是平方和开根号而非相加。","tag":""},{"id":"qa-19-06","difficulty":3,"q":"分析保险集团偿付能力达标的三项监管要求，并说明风险综合评级的分类及细分规则。","answer_points":[{"point":"三项达标门槛","detail":"保险集团须同时满足：核心偿付能力充足率不低于50%、综合偿付能力充足率不低于100%、风险综合评级在B类及以上，三项缺一不可。"},{"point":"评级四类框架","detail":"银保监会按风险大小将保险集团分为A、B、C、D四类监管类别，A、B类再细分，体现风险由小到大的梯度。"},{"point":"A类细分","detail":"A类集团进一步细分为AAA类、AA类、A类，反映偿付能力充足且风险管理能力优秀的程度差异。"},{"point":"B类细分","detail":"B类集团细分为BBB类、BB类、B类，虽达标但风险水平相对A类更高，仍为合格区间。"},{"point":"C类与D类定位","detail":"C类指偿付能力充足率虽达标但某类风险较大，D类指充足率不达标或虽达标但风险严重，均须纳入重点监管。"},{"point":"合规逻辑","detail":"三项门槛中'评级在B类及以上'把定量资本充足与定性风险评级捆绑，避免资本达标但风险失控的集团过关。"}],"framework":"先列三项定量/定性门槛，再展开A/B/C/D四类及其A、B细分，最后点出评级门槛的捆绑监管逻辑。","memo":"易错：综合充足率≥100%、核心≥50%是集团与单一公司一致，但集团额外要求评级B类及以上；A在上、D在下。","tag":""},{"id":"qa-19-07","difficulty":3,"q":"对比保险集团与单一保险公司在控制风险评估上的差异，涵盖监管评估频率、权重安排、控制风险因子Q分段及评估不高于70分的情形。","answer_points":[{"point":"评估频率","detail":"银保监会每三年对保险集团偿付能力风险管理进行一次监管评估以确定控制风险；单一公司评估频率相对更高、更常规。"},{"point":"权重结构","detail":"评估中制度健全性与遵循有效性各占50%权重；集团本级与保险成员公司权重分别为40%和60%，采用百分制。"},{"point":"控制风险因子Q分段","detail":"Q随评估得分S分段：S≤70时Q＝-0.01S+0.75；70≤S≤90时Q＝-0.005S+0.4；90≤S≤100时Q＝-0.01S+0.85，得分越高资本要求越低。"},{"point":"不高于70分情形","detail":"存在股权结构不清晰、风险治理部分得分率低于60%、出现重大风险事件等八类情形之一的，评估结果不高于70分，对应Q取最高段。"},{"point":"差异本质","detail":"集团控制风险评估更强调集团本级统筹与跨成员协调，并把结构性缺陷（如股权不清）直接触发低分惩罚，严于单一公司。"}],"framework":"按'频率→权重→Q分段→70分红线→本质'五线对比，突出集团层面统筹与惩罚性低分机制。","memo":"易错：Q三段公式的折点（70、90）与系数不同；权重本级40%/成员60%、健全性与遵循各50%。","tag":""},{"id":"qa-19-08","difficulty":3,"q":"综合说明保险集团风险传染的监管逻辑：风险传染如何界定、内部担保风险暴露与基础因子如何确定、特征系数如何运用，其防范目的为何？","answer_points":[{"point":"风险传染定义","detail":"风险传染指成员公司风险通过内部关联交易或其他方式传染至集团其他成员，使其遭受非预期损失，是集团化经营特有风险之一。"},{"point":"内部担保风险暴露","detail":"内部担保风险暴露为集团成员公司之间重大担保余额超过集团净资产（合并报表）20%的部分；重大担保指担保金额占上一年度期末净资产1%以上且超过500万元。"},{"point":"基础因子RF0","detail":"内部担保风险基础因子RF0＝0.1，采用综合因子法MC＝EX×RF计量，RF＝RF0×(1+K)，K∈[-0.25,0.25]。"},{"point":"特征系数运用","detail":"集团层面风险因子可叠加特征系数：含控制或共同控制的银行业务k1＝0.1（不含为0），按集团类型k2为0/0.1/0.2，体现结构不透明溢价。"},{"point":"防范目的","detail":"通过量化成员间担保与关联传染的资本占用，抑制集团内部利益输送、违规认购资本工具与风险隐蔽传导，维护集团整体稳健。"},{"point":"配套约束","detail":"规则同时禁止成员公司之间交叉持股、违规认购资本工具及将金融核心业务外包，与风险传染计量形成制度闭环。"}],"framework":"从'定义→暴露门槛→RF0与综合因子法→k1/k2特征系数→监管目的→配套禁令'六层展开，体现计量与行为监管闭环。","memo":"易错：暴露阈值是净资产20%的'超出部分'；重大担保还需满足1%净资产且超500万元双重条件。","tag":""}],"calc":[{"id":"c-19-01","difficulty":1,"stem":"某保险集团合并财务报表净资产为2000亿元。经核查，集团成员公司之间相互提供重大担保，担保余额合计500亿元（该担保已满足'占上一年度期末净资产1%以上且超过500万元'的重大担保认定条件）。请计算该集团内部担保风险对应的最低资本。","blanks":[{"label":"内部担保风险最低资本（亿元）","answer":10,"tolerance":0.1}],"steps":["第1步：确定风险暴露EX＝重大担保余额－集团净资产×20%＝500－2000×20%＝500－400＝100亿元。","第2步：取基础因子RF0＝0.1，按综合因子法MC＝EX×RF0计算。","第3步：MC内部担保＝100×0.1＝10亿元。"],"formula_card":"内部担保风险最低资本 MC＝EX×RF0；EX＝成员公司间重大担保余额－集团净资产（合并）×20%；RF0＝0.1","analysis":"风险暴露为超过集团净资产20%的那部分担保余额，即100亿元。乘以基础因子0.1后得到最低资本10亿元。该结果是集团层面可资本化特有风险（风险传染）的组成部分，将并入集团可资本化风险最低资本。","trap":"易错点一：直接用500亿元全额乘以0.1得到50亿元，忽略了'超出净资产20%部分'的门槛；易错点二：将'重大担保'的500万元认定门槛与20%暴露门槛混淆。","tag":""},{"id":"c-19-02","difficulty":2,"stem":"某保险集团（合并报表）总资产5000亿元、总收入1000亿元。已知：①对全国性股份制商业银行的交易对手风险暴露为400亿元；②投资于单一行业的资产账面价值为900亿元；③来自单一客户的收入为550亿元。请计算该集团集中度风险最低资本（暂不考虑特征系数，基础因子按规则直接取值）。","blanks":[{"label":"集中度风险最低资本（亿元，保留两位小数）","answer":32.33,"tolerance":0.5}],"steps":["第1步：分别计算三类集中度风险最低资本。交易对手限额＝5000×5%＝250亿元，EX＝400－250＝150亿元，RF0＝0.03，MC交易对手＝150×0.03＝4.5亿元。","第2步：行业限额＝5000×10%＝500亿元，EX＝900－500＝400亿元，RF0＝0.05，MC行业＝400×0.05＝20亿元；客户限额＝1000×30%＝300亿元，EX＝550－300＝250亿元，RF0＝0.1，MC客户＝250×0.1＝25亿元。","第3步：聚合MC集中度＝√(MC交易对手²＋MC行业²＋MC客户²)＝√(4.5²＋20²＋25²)＝√(20.25＋400＋625)＝√1045.25≈32.33亿元。"],"formula_card":"MC集中度＝√(MC交易对手²＋MC行业²＋MC客户²)；交易对手（股份行）限额5%/RF0=0.03，行业限额10%/RF0=0.05，客户限额30%/RF0=0.1","analysis":"三类集中度分别按'超出限额的暴露×基础因子'计量后，以平方和开根号方式聚合，得到约32.33亿元。该数值是非简单相加的结果，体现各类集中度风险的部分分散效应。","trap":"易错点一：交易对手集中度限额误用3%（仅适用于非股份行），导致EX与MC算错；易错点二：把聚合公式误作三项相加（4.5+20+25＝49.5），正确应为平方和开根号。","tag":""},{"id":"c-19-03","difficulty":3,"stem":"某混合型保险集团（特征系数k2＝0.2）合并财务报表净资产5000亿元、总资产10000亿元、总收入2000亿元。已知：①成员公司之间重大担保余额1800亿元；②对全国性股份制商业银行交易对手暴露900亿元；③投资于单一行业资产1800亿元；④来自单一客户收入1100亿元。综合因子法下RF＝RF0×(1＋k2)。请计算风险传染最低资本、集中度风险最低资本及集团层面可资本化特有风险最低资本。","blanks":[{"label":"风险传染最低资本（亿元）","answer":96,"tolerance":0.5},{"label":"集中度风险最低资本（亿元，保留两位小数）","answer":78.18,"tolerance":0.5},{"label":"集团层面可资本化特有风险最低资本（亿元，保留两位小数）","answer":174.18,"tolerance":0.5}],"steps":["第1步：风险传染（内部担保）。EX＝1800－5000×20%＝1800－1000＝800亿元；RF＝0.1×(1＋0.2)＝0.12；MC传染＝800×0.12＝96亿元。","第2步：集中度三项。交易对手EX＝900－10000×5%＝400亿元，RF＝0.03×1.2＝0.036，MC＝14.4亿元；行业EX＝1800－10000×10%＝800亿元，RF＝0.05×1.2＝0.06，MC＝48亿元；客户EX＝1100－2000×30%＝500亿元，RF＝0.1×1.2＝0.12，MC＝60亿元。","第3步：MC集中度＝√(14.4²＋48²＋60²)＝√(207.36＋2304＋3600)＝√6111.36≈78.18亿元。","第4步：集团层面特有风险MC＝MC传染＋MC集中度＝96＋78.18＝174.18亿元。"],"formula_card":"MC集团特有＝MC风险传染＋MC集中度；RF＝RF0×(1+k2)；传染EX＝担保余额－净资产×20%(RF0=0.1)；集中度＝√(交易对手²+行业²+客户²)","analysis":"混合型集团k2＝0.2使所有集团层面特有风险基础因子上浮20%。风险传染96亿元叠加集中度78.18亿元，合计174.18亿元，须并入集团可资本化风险最低资本。该数值越高，集团资本要求越大，反映隐性控制结构带来的风险溢价。","trap":"易错点一：忘记对混合型集团叠加k2＝0.2，导致RF仍用RF0（如传染算成80亿元）；易错点二：集中度聚合误作相加（14.4+48+60＝122.4）；易错点三：混淆各交易对手限额（股份行5%、其他3%）。","tag":""}]},{"id":"rule-20","group":"监管规则","name":"第20号 劳合社保险（中国）有限公司","qa":[{"id":"qa-20-01","difficulty":1,"q":"请简述劳合社（中国）偿付能力监管应当遵循的'穿透原则'，并说明其监管含义。","answer_points":[{"point":"穿透原则定义","detail":"劳合社（中国）应按照穿透原则，分别评估和计量承保部与公司层面可资本化的偿付能力风险，再在此基础上对整体偿付能力进行评估与计量。"},{"point":"两个层面分离","detail":"规则将劳合社（中国）拆解为'承保部'与'公司层面'两个独立计量单元，各自计算最低资本与实际资本，而非简单合并。"},{"point":"整体合成","detail":"在分层面计量基础上，按承保部平均值60%、公司层面40%的权重合成整体偿付能力充足率，反映辛迪加业务与运营职能的不同权重。"},{"point":"监管目的","detail":"穿透原则旨在识别承保部再保险业务的真实风险敞口，避免以集团整体掩盖单项业务的资本不足。"}],"framework":"按'定义→两层面分离→加权合成→监管目的'四步作答，核心是'分别计量、加权合成'。","memo":"易错：整体充足率权重是承保部60%、公司层面40%，而非相反。","tag":""},{"id":"qa-20-02","difficulty":1,"q":"说明劳合社（中国）'承保部'与'公司层面'的定义及二者职能划分。","answer_points":[{"point":"承保部定义","detail":"承保部是劳合社（中国）为在中国开展保险业务的劳合社辛迪加及其管理代理公司设立的对应承保业务部门，承载具体承保与再保险风险。"},{"point":"公司层面定义","detail":"公司层面指主要承担整体运营管理、风险控制等职能的机构，即除承保部外劳合社（中国）的其他职能部门、组织和人员。"},{"point":"职能划分逻辑","detail":"承保部对应前端辛迪加承保与再保险业务风险，公司层面对应中后台运营与管控，二者风险性质与资本计量方式不同。"},{"point":"多辛迪加处理","detail":"同一承保部对应多个劳合社辛迪加时，应以每一辛迪加开展的业务为主体，按承保部规定分别评估计量。"}],"framework":"先分别给出承保部与公司层面的定义，再说明'前端承保/中后台运营'的职能分界与多辛迪加处理。","memo":"易错：公司层面不是'母公司'，而是劳合社（中国）内部除承保部以外的职能部门。","tag":""},{"id":"qa-20-03","difficulty":2,"q":"列举承保部的认可资产与认可负债（含非认可负债），并说明留存资产的性质与用途。","answer_points":[{"point":"承保部认可资产","detail":"包括留存资产、应收分保准备金、分入再保险业务的应收分保账款、应收保费，以及银保监会规定的其他认可资产。"},{"point":"承保部认可负债","detail":"包括保险合同负债、分入再保险业务的应付分保账款、应付赔付款，以及银保监会规定的其他认可负债。"},{"point":"非认可负债","detail":"承保部分出再保险业务的应付分保账款为非认可负债，不计入认可负债，体现穿透后仅保留自留风险的负债口径。"},{"point":"留存资产定义","detail":"留存资产是劳合社辛迪加作为劳合社（中国）的再保险人或转分保接受人，留存在劳合社（中国）专门用于支付保险赔款和相关理赔费用的资产。"},{"point":"留存资产范围","detail":"包括留存的应收承保部的分保保费、其他划拨的资产及其投资收益，属承保部认可资产，保障赔付资金专项可用。"}],"framework":"分'认可资产/认可负债/非认可负债/留存资产定义/留存资产范围'五点，重点是分出口应付分保账款的非认可处理。","memo":"易错：分入再保险应付分保账款是认可负债，而分出再保险应付分保账款是非认可负债，方向相反。","tag":""},{"id":"qa-20-04","difficulty":2,"q":"说明承保部保险风险最低资本的构成、公司层面保险风险最低资本的计算方法，并指出哪些层面不计算控制风险最低资本。","answer_points":[{"point":"承保部保险风险构成","detail":"承保部保险风险最低资本＝非寿险再保险业务保险风险最低资本＋非寿险业务保险风险最低资本，两类业务分别计量后相加。"},{"point":"承保部最低资本范围","detail":"承保部最低资本包括保险风险、市场风险、信用风险最低资本三部分，但不计算控制风险最低资本。"},{"point":"公司层面保险风险计算","detail":"公司层面保险风险最低资本＝各承保部保险风险最低资本之和×15%，即以承保部保险风险合计为基数计提15%。"},{"point":"公司层面控制风险","detail":"公司层面同样不计算控制风险最低资本，与承保部保持一致，控制风险不在劳合社（中国）最低资本中体现。"},{"point":"信用风险基础","detail":"承保部的信用风险最低资本应以再保险分出前业务为基础评估和计量，确保风险敞口不被再保安排低估。"}],"framework":"按'承保部保险风险构成→承保部最低资本三因子（不含控制）→公司层面×15%→两层面均不含控制风险→信用分出前基础'展开。","memo":"易错：两层面都不计控制风险；公司层面保险风险基数必须是'各承保部保险风险之和'的15%，而非公司自身业务。","tag":""},{"id":"qa-20-05","difficulty":2,"q":"说明劳合社（中国）整体偿付能力充足率的合成方法，以及各层面与整体的达标标准。","answer_points":[{"point":"核心充足率合成","detail":"整体核心偿付能力充足率＝承保部核心偿付能力充足率平均值×60%＋公司层面核心偿付能力充足率×40%。"},{"point":"综合充足率合成","detail":"整体综合偿付能力充足率＝承保部综合偿付能力充足率平均值×60%＋公司层面综合偿付能力充足率×40%，权重与核心一致。"},{"point":"平均值口径","detail":"承保部偿付能力充足率平均值＝各承保部核心（或实际）资本之和÷各承保部最低资本之和，为资本加权平均值。"},{"point":"各层面达标标准","detail":"各承保部、公司层面均应分别满足核心偿付能力充足率不低于50%、综合偿付能力充足率不低于100%。"},{"point":"整体达标标准","detail":"公司整体同样须满足核心不低于50%、综合不低于100%；整体不达标的，银保监会依《保险公司偿付能力管理规定》采取监管措施。"}],"framework":"先给核心与综合两条合成公式（均60%/40%），再说明平均值口径，最后强调各层面与整体均须分别达标。","memo":"易错：达标是'各承保部、公司层面、整体'三层分别要求，而非仅看整体；权重始终是承保部60%、公司层面40%。","tag":""},{"id":"qa-20-06","difficulty":3,"q":"对比承保部非寿险再保险业务与非寿险业务在保险风险最低资本计量上的特别规定差异。","answer_points":[{"point":"适用规则不同","detail":"非寿险再保险业务按第6号规则（再保险公司）计量，非寿险业务按第4号规则计量，两者基准规则不同。"},{"point":"保费风险暴露口径","detail":"两类业务的保费风险最低资本风险暴露均为过去12个月再保险分出前的保费，但再保险业务须以分出前为基础单独界定。"},{"point":"巨灾风险划分差异","detail":"非寿险再保险业务巨灾风险最低资本须区分比例再保险与非比例再保险分别计算；非寿险业务则不划分业务类型，按MC巨灾＝MC保费及准备金×25%合并计算。"},{"point":"特征系数适用差异","detail":"非寿险再保险业务的比例再保险业务不适用综合成本率特征系数；非寿险业务的保费风险不适用综合成本率、非比例分保净分出比例等特征系数，准备金风险亦不适用未决赔款准备金回溯偏差率等特征系数。"},{"point":"风险性质差异本质","detail":"差异源于再保险业务以分入风险为主、结构特殊，故监管对其特征系数与巨灾划分作特别简化或调整，以更贴合辛迪加业务实质。"}],"framework":"从'基准规则→保费暴露→巨灾划分→特征系数→本质'五维对比两类业务，突出再保险业务的特殊简化处理。","memo":"易错：巨灾风险25%系数仅适用于非寿险业务合并计算；再保险业务巨灾须分比例/非比例两类。","tag":""},{"id":"qa-20-07","difficulty":3,"q":"综合说明劳合社（中国）偿付能力监管的逻辑主线，并分析为何各层面均须分别达标。","answer_points":[{"point":"逻辑主线","detail":"主线为：承保部与公司层面分别计量资本→分别计算各层面偿付能力充足率→按60%/40%加权合成整体偿付能力，形成'分—算—合'三层结构。"},{"point":"分层面计量的必要性","detail":"承保部承载辛迪加再保险风险、公司层面承载运营风险，二者风险属性与资本基础不同，须分开计量才能真实反映风险。"},{"point":"分别计算充足率","detail":"各层面用自身实际/核心资本除以自身最低资本得出充足率，避免以一个层面的充裕掩盖另一层面的不足。"},{"point":"各层面分别达标意义","detail":"规则要求各承保部、公司层面及整体均须核心≥50%、综合≥100%，防止某一承保部资本严重不足却被整体平均稀释过关。"},{"point":"穿透监管闭环","detail":"本规则未规定的适用其他保险公司监管规则，自评估、现金流测试与压力情景要求进一步压实各层面风险，形成穿透闭环。"}],"framework":"先概括'分—算—合'主线，再从分计量必要性、分别达标防稀释、穿透闭环三方面分析为何层层设门槛。","memo":"易错：整体达标不等于各层面达标；平均值可能掩盖个别承保部不达标，故要求分别达标。","tag":""},{"id":"qa-20-08","difficulty":3,"q":"说明劳合社（中国）在监督管理方面的特殊要求，并分析其与一般保险公司的异同。","answer_points":[{"point":"风险管理自评估","detail":"应参照第12号规则每年对偿付能力风险管理能力自评估，并在每年第一季度偿付能力季度报告中说明上一年度自评估情况。"},{"point":"流动性与现金流测试","detail":"应加强整体及各承保部流动性风险管理，按第13号规则开展现金流测试，计算基本情景与压力情景下的流动性覆盖率。"},{"point":"压力情景特殊性","detail":"现金流测试适用再保险公司的压力情景，体现其再保险业务属性，区别于一般直接保险公司的压力假设。"},{"point":"整体不达标监管依据","detail":"整体偿付能力充足率不达标的，银保监会根据《保险公司偿付能力管理规定》采取监管措施，与一般公司依据相同。"},{"point":"与一般公司异同","detail":"相同点：自评估、现金流测试、不达标监管依据与一般保险公司一致；不同点：采用穿透双层面计量、适用再保险压力情景、本规则未作规定时转用其他保险公司规则。"}],"framework":"分'自评估→流动性测试→再保险压力情景→不达标依据→异同总结'五点，落脚于'框架同、计量异'。","memo":"易错：自评估在'第一季度'季度报告披露；压力情景适用再保险公司口径而非财险/寿险口径。","tag":""}],"calc":[{"id":"c-20-01","difficulty":1,"stem":"某劳合社（中国）有两家承保部：甲承保部保险风险最低资本为200亿元，乙承保部保险风险最低资本为300亿元。请计算该公司层面保险风险最低资本。","blanks":[{"label":"公司层面保险风险最低资本（亿元）","answer":75,"tolerance":0.1}],"steps":["第1步：计算各承保部保险风险最低资本之和＝200＋300＝500亿元。","第2步：按公司层面保险风险最低资本＝各承保部保险风险最低资本之和×15%计算。","第3步：公司层面保险风险最低资本＝500×15%＝75亿元。"],"formula_card":"公司层面保险风险最低资本＝各承保部保险风险最低资本之和×15%","analysis":"公司层面保险风险以承保部保险风险合计为基数计提15%，结果为75亿元。该数值并入公司层面最低资本，再参与整体偿付能力充足率的40%权重合成。","trap":"易错点：误将15%当作60%或误用公司层面自身业务为基数；注意基数是'各承保部保险风险之和'而非各承保部最低资本之和。","tag":""},{"id":"c-20-02","difficulty":2,"stem":"某劳合社（中国）有两家承保部，其资本数据如下：甲承保部核心资本120亿元、最低资本200亿元；乙承保部核心资本180亿元、最低资本300亿元。公司层面核心资本50亿元、最低资本80亿元。请计算该公司整体核心偿付能力充足率。","blanks":[{"label":"整体核心偿付能力充足率（%，保留两位小数）","answer":61,"tolerance":0.5}],"steps":["第1步：计算承保部核心偿付能力充足率平均值＝各承保部核心资本之和÷各承保部最低资本之和＝(120＋180)÷(200＋300)＝300÷500＝60%。","第2步：计算公司层面核心偿付能力充足率＝50÷80＝62.5%。","第3步：整体核心充足率＝承保部平均值×60%＋公司层面×40%＝60%×0.6＋62.5%×0.4＝36%＋25%＝61%。"],"formula_card":"整体核心充足率＝承保部核心充足率平均值×60%＋公司层面核心充足率×40%；平均值＝Σ承保部核心资本÷Σ承保部最低资本","analysis":"承保部核心充足率平均值为60%，公司层面为62.5%，按60%/40%加权得整体61%。该值高于50%的达标线，整体核心充足率达标。","trap":"易错点一：平均值误用简单平均((60%+某值)/2)而非资本加权平均；易错点二：权重误用40%/60%倒置。","tag":""},{"id":"c-20-03","difficulty":3,"stem":"某劳合社（中国）有两家承保部，数据如下（单位：亿元）：甲承保部保险风险最低资本100、市场风险80、信用风险40（以再保险分出前为基础），核心资本130、实际资本240；乙承保部保险风险最低资本150、市场风险100、信用风险50，核心资本170、实际资本320。公司层面最低资本60、核心资本35、实际资本70（其中保险风险最低资本按承保部保险风险之和的15%计）。请计算：①公司层面保险风险最低资本；②承保部综合偿付能力充足率平均值；③整体综合偿付能力充足率，并判断整体是否达标。","blanks":[{"label":"公司层面保险风险最低资本（亿元）","answer":37.5,"tolerance":0.1},{"label":"承保部综合偿付能力充足率平均值（%，保留两位小数）","answer":107.69,"tolerance":0.5},{"label":"整体综合偿付能力充足率（%，保留两位小数）","answer":111.28,"tolerance":0.5}],"steps":["第1步：承保部保险风险最低资本合计＝100＋150＝250亿元；公司层面保险风险最低资本＝250×15%＝37.5亿元（与给定公司层面最低资本60中保险部分一致）。","第2步：承保部最低资本：甲＝100＋80＋40＝220，乙＝150＋100＋50＝300（均不计控制风险）。承保部综合充足率平均值＝(甲实际资本＋乙实际资本)÷(甲最低资本＋乙最低资本)＝(240＋320)÷(220＋300)＝560÷520≈107.69%。","第3步：公司层面综合充足率＝70÷60≈116.67%。","第4步：整体综合充足率＝承保部平均值×60%＋公司层面×40%＝107.69%×0.6＋116.67%×0.4≈64.61%＋46.67%＝111.28%。","第5步：判断达标。各承保部（甲240/220≈109.09%、乙320/300≈106.67%）与公司层面（116.67%）均≥100%，整体111.28%≥100%、且核心充足率亦达标，整体达标。"],"formula_card":"公司层面保险风险＝Σ承保部保险风险×15%；综合平均值＝Σ承保部实际资本÷Σ承保部最低资本；整体综合＝平均值×60%＋公司层面×40%；达标：核心≥50%、综合≥100%","analysis":"公司层面保险风险37.5亿元，承保部综合充足率均值约107.69%，整体综合约111.28%。各承保部、公司层面及整体综合充足率均超过100%，且核心充足率均不低于50%，满足各层面分别达标要求，整体达标。","trap":"易错点一：承保部最低资本漏计市场或信用风险，或误加控制风险（规则规定不计）；易错点二：综合平均值误用简单平均而非资本加权；易错点三：整体达标判断仅看整体而忽略'各层面分别达标'要求。","tag":""}]}],"challenge":{"qa":[{"id":"qa-chsol-01","difficulty":3,"title":"某寿险公司资本分级与偿付能力充足率体系诊断","stem":"华信人寿保险股份有限公司是一家成立十二年的全国性人身险公司，2026年第二季度末母公司报表显示：认可资产540亿元，认可负债450亿元。公司资本结构为：核心一级资本60亿元（含计入核心一级的保单未来盈余），核心二级资本8亿元，附属一级资本6亿元，附属二级资本10亿元。经计量，公司最低资本为50亿元。该公司核心偿付能力充足率与综合偿付能力充足率均达标，但监管注意到其保单未来盈余占核心资本比例偏高，且发行的次级定期债务剩余期限结构复杂，你作为精算咨询顾问需对该公司资本体系出具诊断意见。","parts":[{"q":"小问1：请说明实际资本的定义与计算，并解释核心资本与附属资本在吸收损失性质上的区别。","answer_points":[{"point":"实际资本的定义与计算","detail":"实际资本是指保险公司在持续经营或破产清算状态下可以吸收损失的财务资源，等于认可资产减去认可负债后的余额。本案中实际资本＝540－450＝90亿元。评估应以母公司财务报表而不以合并财务报表为基础，且资产与负债的评估原则应当一致。"},{"point":"核心资本的性质","detail":"核心资本是指在持续经营状态下和破产清算状态下均可以吸收损失的资本，吸收损失能力最强，分为核心一级资本和核心二级资本。本案核心资本＝60＋8＝68亿元。"},{"point":"附属资本的性质","detail":"附属资本是指仅在破产清算状态下可以吸收损失的资本，吸收损失能力弱于核心资本，分为附属一级资本和附属二级资本。本案附属资本＝6＋10＝16亿元。"},{"point":"两者区别的监管含义","detail":"核心偿付能力充足率以核心资本为分子，是监管更为关注的指标；附属资本占比过高说明资本质量偏弱，须受附属资本不得超过核心资本100%的限额约束。本案附属资本16亿元，为核心资本68亿元的23.5%，未超限。"}]},{"q":"小问2：请说明保单未来盈余按剩余期限分级的规则及各级资本限额要求。","answer_points":[{"point":"分级的基本逻辑","detail":"保单未来盈余按现行有效寿险保单剩余期限分组折现后计入不同层级资本，剩余期限越长资本质量越高：剩余期限30年（含）以上的，按核心一级资本对应的资本报酬率折现到评估时点的现值作为核心一级资本工具，剩余部分作为附属一级资本工具。"},{"point":"中间期限档位","detail":"剩余期限10年（含）至30年的，折现现值作为核心二级资本工具，剩余部分作为附属一级资本工具；剩余期限5年（含）至10年的，折现现值作为附属一级资本工具，剩余部分作为附属二级资本工具。"},{"point":"短期限档位","detail":"保单剩余期限在5年以内的，保单未来盈余全部作为附属二级资本工具；分组保单未来盈余小于零的，折现前按零取值，相应冲减剩余期限30年（含）以上组的未来盈余，不足冲减的冲减核心一级资本。"},{"point":"资本限额要求","detail":"计入核心资本的保单未来盈余不得超过核心资本的35%；附属资本不得超过核心资本的100%；核心二级资本不得超过核心资本的30%；附属二级资本不得超过核心资本的25%。各级资本工具余额超过限额的，应确认为资本性负债，以超过限额的金额作为该负债的认可价值。本案应重点核查未来盈余占核心资本比例是否接近35%的红线。"}]},{"q":"小问3：公司发行的部分次级定期债务剩余期限较短，请说明次级定期债务和资本补充债券认可价值的确定规则。","answer_points":[{"point":"无赎回条款的认可档位","detail":"无赎回条款的次级定期债务和资本补充债券：剩余期限2年以上（含）认可价值为0；1年以上（含）2年以内为账面价值的50%；1年以内为账面价值的80%。"},{"point":"有赎回条款的认可档位","detail":"有赎回条款的：剩余期限4年以上（含）为0；3年以上（含）4年以内为账面价值的20%；2年以上（含）3年以内为40%；1年以上（含）2年以内为60%；1年以内为80%。"},{"point":"剩余期限按赎回日计算的触发条件","detail":"赎回日之前和赎回日之后的票面利率差额超过100个基点，或者有证据表明保险公司会提前赎回的，剩余期限按赎回日计算；否则按到期日计算。"},{"point":"诊断提示","detail":"剩余期限越短认可价值越高，意味着临近赎回期的次级债对实际资本贡献上升，但公司也面临再融资压力；诊断时需逐笔核对赎回条款与利率跳升幅度，防止高估资本。"}]},{"q":"小问4：请计算该公司核心偿付能力充足率与综合偿付能力充足率，并判断其偿付能力是否达标、可能落入的风险综合评级类别。","answer_points":[{"point":"两个充足率的计算","detail":"核心偿付能力充足率＝核心资本÷最低资本＝68÷50＝136%；综合偿付能力充足率＝实际资本÷最低资本＝90÷50＝180%。"},{"point":"达标判断","detail":"监管达标标准为核心偿付能力充足率不低于50%且综合偿付能力充足率不低于100%，本案两项均达标，公司偿付能力达标。"},{"point":"评级类别的判断框架","detail":"风险综合评级分为A、B、C、D四类：充足率达标且操作、战略、声誉、流动性四类难以资本化风险小的为B类，风险小的为A类；充足率不达标，或达标但某一类或几类难以资本化风险较大的为C类；风险严重的为D类。"},{"point":"本案结论","detail":"本案充足率达标，若无重大难以资本化风险，可评为A类或B类；若流动性或操作风险等某类风险较大，则即使充足率达标也可能被评为C类，说明充足率达标不等于高评级。"}]},{"q":"小问5：针对该公司资本结构，请提出优化建议并说明监管对各级资本工具期限特性的要求。","answer_points":[{"point":"降低对未来盈余的依赖","detail":"未来盈余本质是负债评估差异，受折现率等假设影响大，应控制在核心资本35%限额内并预留缓冲，通过增资、发行合格资本工具补充外部资本。"},{"point":"各级资本工具的期限要求","detail":"核心二级资本工具应没有到期日或期限不低于10年，发行5年后方可赎回且不得含利率跳升机制；附属一级资本期限不低于5年；附属二级资本期限可以低于5年。"},{"point":"次级债与资本补充债的搭配","detail":"通过合理安排有赎回、无赎回条款债务的发行节奏，使各认可档位（0、20%、40%、60%、80%）平滑分布，避免认可价值集中衰减导致充足率骤降。"},{"point":"提升核心一级资本","detail":"核心一级资本以财务报表净资产为基础调整得到，是最优质的资本；可通过利润留存、增资扩股提升其占比，增强持续经营下的损失吸收能力。"}]}],"framework":"整案沿“实际资本定义→资本四级分级与限额→资本工具认可规则→充足率计算与达标判断→评级类别与优化建议”的主线展开：先以认可资产减认可负债得到实际资本底数，再区分核心与附属资本核对限额红线，结合次级债认可档位和未来盈余分级判断资本质量，最后用核心/综合双充足率对照50%与100%门槛得出达标结论并映射到A/B/C/D评级框架，形成完整的资本体系诊断链条。","memo":"案例易错点：①附属资本限额是“不得超过核心资本的100%”，而非不得超过实际资本；②核心偿付能力充足率分子是核心资本（核心一级＋核心二级），不含附属资本；③无赎回条款次级债剩余期限2年以上（含）认可价值为0，与有赎回条款的4年以上（含）为0容易混淆；④计入核心资本的保单未来盈余限额是核心资本的35%，不要与核心二级30%、附属二级25%的限额混淆；⑤充足率达标不代表评级一定为A类，C、D类公司中包含“达标但某类风险较大或严重”的情形。"},{"id":"qa-chsol-02","difficulty":3,"title":"某财险公司权益与不动产投资的市场风险最低资本计量诊断","stem":"泰岳财产保险股份有限公司近年加大投资端布局，2026年二季度末持有：沪深主板非沪深300成份股上市股票8亿元、创业板上市股票3亿元、沪深300指数成份股4亿元、债券基金5亿元、股票基金4亿元、货币市场基金2亿元，以物权方式持有的投资性房地产12亿元（全部位于省会城市），美元存款折合人民币6亿元、同币种美元负债3亿元。监管现场检查发现该公司将全部上市股票按0.35的基础因子合并计量权益价格风险最低资本，且未单独计量汇率风险，你作为风险管理顾问需指出计量差错并给出正确方法。","parts":[{"q":"小问1：指出该公司权益价格风险计量中的错误，并说明正确的计量要求。","answer_points":[{"point":"必须逐项分别计量","detail":"计量某类资产的市场风险最低资本时，应对该类别的各项资产分别计量，不得按类别合并计量。将全部上市股票按统一因子合并计量违反了第七条要求。"},{"point":"上市股票基础因子的区分","detail":"沪深主板股基础因子为0.35，创业板股和科创板股基础因子为0.45；本案8亿元主板股用0.35、3亿元创业板股应用0.45。"},{"point":"沪深300成份股特征系数","detail":"沪深300指数成份股设置特征系数k2＝−0.05，其他股票为0，故4亿元沪深300成份股的RF＝0.35×(1−0.05)＝0.3325。"},{"point":"特征系数的取值区间","detail":"特征系数K为各特征系数之和，K∈[−0.25, 0.25]；风险因子RF＝RF0×(1＋K)，RF≥1时取值为1。"}]},{"q":"小问2：请说明证券投资基金的权益价格风险基础因子取值，以及综合因子法的基本公式。","answer_points":[{"point":"综合因子法基本公式","detail":"除人身保险公司利率风险最低资本采用情景法外，市场风险最低资本采用综合因子法：MC市场＝EX×RF，EX为风险暴露（等于认可价值，EX≤0时取0），RF＝RF0×(1＋K)。"},{"point":"各基金类型的基础因子","detail":"债券基金0.06、股票基金0.28、混合基金及商品金融衍生品基金0.23、货币市场基金0.01；本案5亿元债券基金、4亿元股票基金、2亿元货币基金应分别适用。"},{"point":"可转债的归类","detail":"债券资产的利率风险计量不含可转债（可交换债），可转债计入权益价格风险，基础因子为0.23，实务中容易错配到利率风险。"},{"point":"计量顺序建议","detail":"应先按资产明细逐项确定EX与RF0、K，逐项计算最低资本后再按市场风险相关系数矩阵汇总，而不是先汇总暴露再套一个因子。"}]},{"q":"小问3：请说明投资性房地产的房地产价格风险计量方法及集中度风险的触发条件。","answer_points":[{"point":"基础因子与位置特征系数","detail":"以物权形式持有的投资性房地产基础因子RF0＝0.15；位置特征系数k1：位于直辖市、省会城市、计划单列市的为0，境内其他地区为0.2。本案房地产全部位于省会城市，k1＝0，RF＝0.15。"},{"point":"项目公司持有方式的处理","detail":"通过项目公司股权方式持有投资性房地产的，按规定计量房地产价格风险；以物权或项目公司方式持有的投资性房地产在认可资产评估中还应以成本模式计量金额作为认可价值。"},{"point":"房地产集中度风险触发条件","detail":"直接持有的投资性房地产账面价值占总资产的比例超过25%时，应计量房地产集中度风险，特征系数k集中度3＝0.5；本案应测算占比是否触及25%红线。"},{"point":"逐项计量要求","detail":"不同地段的房地产应逐项计量，不得合并；若未来新增三四线城市物业，k1＝0.2将推高整体房地产价格风险最低资本。"}]},{"q":"小问4：指出该公司汇率风险计量遗漏，并说明正确的计量方法。","answer_points":[{"point":"风险暴露的确定","detail":"汇率风险暴露为同币种资产认可价值减去同币种负债认可价值的净额绝对值，不能只看资产端或忽略负债端的对冲作用。"},{"point":"本案暴露计算","detail":"美元资产6亿元减美元负债3亿元，净额绝对值为3亿元，这是汇率风险的计量暴露，该公司完全未计量属于重大差错。"},{"point":"基础因子的币种区分","detail":"美元和汇率跟美元挂钩的货币基础因子RF0＝0.05，欧元、英镑为0.08，其他货币为0.15；美元与挂钩货币之间可视为同币种计算。"},{"point":"汇总方式","detail":"汇率风险应区分币种分别计算最低资本后汇总；若公司做了符合套期有效性要求且期限不低于1个月的衍生品对冲，可将衍生品空头与被套期组合合并计算。"}]},{"q":"小问5：请说明市场风险六类风险最低资本汇总的方法以及该诊断对公司的管理建议。","answer_points":[{"point":"相关系数矩阵汇总","detail":"市场风险最低资本通过相关系数矩阵法汇总：MC市场＝MC向量×M相关系数×MC向量T，MC向量由利率、权益价格、房地产价格、境外固收、境外权益及房地产、汇率六项组成，反映风险分散效应。"},{"point":"各类风险先分后总","detail":"六类风险各自先按综合因子法（人身险利率风险用情景法）逐项计量，再进入矩阵聚合；利率风险在财险公司按修正久期分段的基础因子计量，债券计量范围不含可转债。"},{"point":"管理建议一：优化股票结构","detail":"增加沪深300成份股可享受k2＝−0.05的特征系数折减，降低创业板、科创板高因子资产的占比，在同等收益目标下节约最低资本。"},{"point":"管理建议二：控制集中度与敞口","detail":"监控投资性房地产占总资产25%的集中度红线，管理同币种资产负债匹配以压缩汇率净敞口，从源头降低市场风险最低资本占用。"}]}],"framework":"整案以“发现计量差错→逐类给出正确计量→汇总与管理建议”为骨架：先依据“逐项分别计量、不得合并”的总原则否定公司做法，再分别按权益价格风险（主板0.35／创业板科创板0.45／沪深300 k2＝−0.05）、基金因子、房地产因子与位置系数、汇率净额暴露与币种因子给出正确算法，最后落到相关系数矩阵汇总与集中度、敞口管理建议，覆盖综合因子法MC＝EX×RF的完整应用。","memo":"案例易错点：①市场风险除人身险公司利率风险用情景法外一律用综合因子法，不要把财险公司利率风险也说成情景法；②创业板、科创板股票因子0.45高于主板的0.35，沪深300成份股k2为负0.05是折减项；③汇率风险暴露是同币种资产负债净额的绝对值，不是外币资产总额；④投资性房地产省会城市k1＝0、其他地区k1＝0.2，房地产集中度触发线是占总资产25%；⑤货币市场基金因子0.01属于权益价格风险因子而非不计提。"},{"id":"qa-chsol-03","difficulty":3,"title":"某人身险公司流动性风险管理体系与监管指标整改","stem":"永泰人寿保险股份有限公司因短期内集中退保上升、投资端非标资产占比较高，监管在风险综合评级评价中关注其流动性风险。公司董事会尚未建立流动性风险偏好陈述书，财务部仅按年度编制现金流预测；2026年二季度末数据显示，未来3个月压力情景下现金流出40亿元、现金流入12亿元，现金及现金等价物6亿元，持有交易类国债10亿元、可提前支取的定期存款8亿元、AAA级非金融企业债券5亿元、上市股票4亿元。你作为合规顾问，需就管理体系与监管指标达标情况出具整改意见。","parts":[{"q":"小问1：请说明流动性风险的定义、三大监管指标及各自的达标标准。","answer_points":[{"point":"流动性风险定义","detail":"流动性风险是指保险公司无法及时获得充足资金或无法及时以合理成本获得充足资金，以支付到期债务或履行其他支付义务的风险；第13号规则规范的是流动性风险管理的最低监管要求。"},{"point":"三大监管指标","detail":"监管指标包括流动性覆盖率（LCR）、经营活动净现金流回溯不利偏差率（RDR）和净现金流三项；综合退保率、百元保费经营活动净现金流等属于监测指标而非监管指标。"},{"point":"达标标准","detail":"LCR1（基本情景公司整体流动性覆盖率）不低于100%，LCR2（压力情景公司整体流动性覆盖率）不低于100%，LCR3（压力情景不考虑资产变现）不低于50%；且应分别计算未来3个月和未来12个月的流动性覆盖率。"},{"point":"另两项指标要求","detail":"RDR＝（经营活动净现金流实际值－预测值）÷ABS（预测值）×100%，最近两个季度不得连续低于−30%；净现金流反映过去两个会计年度及当年累计的公司整体净现金流状况，不得连续小于零。"}]},{"q":"小问2：请写出LCR的计算公式，并说明流动性资产储备的特征、折算方式与排除项。","answer_points":[{"point":"三个LCR公式","detail":"LCR1＝（基本情景下公司现金流入＋现金及现金等价物评估时点账面价值）÷基本情景下公司现金流出×100%；LCR2在分子中另加流动性资产储备变现金额，分母改为压力情景下现金流出；LCR3与LCR2公式相同但不加储备变现金额。"},{"point":"流动性资产储备三特征","detail":"流动性资产储备应具备易于交易、易于变现、无变现障碍的特征，即未作为任何交易的质押、抵押或信用增级工具，可通过出售或抵（质）押以合理成本快速变现，且不包括现金及现金等价物本身。"},{"point":"折算方式","detail":"储备变现金额＝储备评估时点账面价值×折算系数：货币市场基金、交易类及可供出售类国债为100%；可提前支取的定期存款或协议存款为90%；AAA级非金融企业（公司）债为80%；上市股票为50%；境内债券型基金（开放式）85%、股票型基金（开放式）60%、混合型基金（开放式）65%、可转债65%。"},{"point":"排除项","detail":"非标准化债权资产、另类投资资产、AAA级以下债券、持有至到期类债券资产、长期股权投资、处于封闭期的开放式基金、持有份额超过80%的组合类保险资产管理产品（开放式）以及在预测期内到期且已计入未来现金流入的资产等，不属于流动性资产储备；本案非标占比较高意味着储备结构薄弱。"}]},{"q":"小问3：结合公司现金流预测现状，说明现金流压力测试的频率、区间与情景要求。","answer_points":[{"point":"频率与区间","detail":"现金流测试至少每个季度进行一次，测试区间为报告期末起未来12个月，以季度为单位划分为测试时点后第一个季度至第四个季度；仅按年度编制现金流预测不满足要求。"},{"point":"基本情景与压力情景","detail":"测试情景包括基本情景和压力情景：基本情景是考虑现有业务和未来新业务的最优估计假设情景，新业务假设应与业务规划一致；压力情景包括自测情景和必测情景，必测情景由银保监会统一确定发布。"},{"point":"压力情景的限制性假设","detail":"压力情景下不考虑管理层行为（如临时银行贷款等紧急措施），不应考虑股东增资、发行资本补充债等资本工具产生的现金流入，也不应假设出售资产、变现投资性不动产等；可考虑正回购、拆入资金等短期筹资，但未来各期末余额以报告日已有余额为限。"},{"point":"整改方向","detail":"公司应建立季度现金流测试机制、明确自测情景设置方法，并将测试结果纳入流动性应急计划的触发指标体系。"}]},{"q":"小问4：请说明流动性风险治理结构要求，指出该公司董事会层面的缺陷。","answer_points":[{"point":"董事会最终责任","detail":"董事会承担流动性风险管理的最终责任，应审批并至少每年审议一次流动性风险偏好和容忍度、流动性风险管理策略、重要的政策和流程；公司尚未建立风险偏好陈述书，直接违反该要求。"},{"point":"高管层与责任人对","detail":"高级管理层负责组织实施流动性风险管理，制定和执行流动性风险管理制度、应急计划；公司应指定一名高级管理人员负责流动性风险管理工作。"},{"point":"体系三要素","detail":"流动性风险管理体系的基本要素包括治理结构、策略政策程序、识别计量监测控制三项，不含公众信息披露安排；本案三方面均需完善。"},{"point":"重大事件识别","detail":"公司应识别和关注可能引发流动性风险的重大事件，如非正常的集中退保、重大理赔事件、失去关键销售渠道、重要交易对手外部信用评级下调至BB+及以下等；本案集中退保上升正属此类，应纳入监测。"}]},{"q":"小问5：若公司压力情景下LCR不达标或出现重大流动性风险，请说明报告义务与监管可能采取的措施。","answer_points":[{"point":"重大流动性风险的报告时限","detail":"保险公司出现重大流动性风险时，应当自发现之日起3日内向银保监会报告，说明当前流动性水平、流动性风险状况以及已采取和拟采取的应急措施等。"},{"point":"季度报告披露义务","detail":"公司应按第18号规则要求，在偿付能力季度报告中披露流动性风险监管指标、监测指标和现金流测试等有关信息，接受市场与监管监督。"},{"point":"监管措施","detail":"对指标异常、存在重大流动性风险隐患或未建立执行流动性风险管理体系的保险公司，银保监会可要求提交改善流动性水平的计划、要求完善流动性管理机制和制度、进行监管谈话及采取其他必要措施。"},{"point":"应急措施建议","detail":"公司应提高储备资产中高折算系数资产的占比（国债、货基等100%折算资产），压缩非标与长持至到期资产，建立以LCR为触发指标的分层应急融资安排。"}]}],"framework":"整案按“指标定义与达标线→LCR公式与储备折算→现金流压力测试机制→治理结构责任→报告与监管措施”推进：先锁定LCR1≥100%、LCR2≥100%、LCR3≥50%三个硬性标准与3个月、12个月双期限要求，再通过储备三特征与折算系数表分析公司储备质量，结合季度测试频率与压力情景假设限制指出预测机制的缺陷，最后落到董事会最终责任、3日报告时限与监管谈话等递进措施，形成从计量到治理到披露的流动性整改闭环。","memo":"案例易错点：①LCR3是“不考虑资产变现”的压力情景指标，达标线50%而非100%；②上市股票折算系数50%，可转债与混合型基金均为65%，勿与股票型基金60%混淆；③压力情景下不得考虑股东增资和出售资产的现金流入，短期筹资余额以报告日已有余额为限；④综合退保率是监测指标，不属于三大监管指标；⑤重大流动性风险报告时限为发现之日起3日，与偿付能力不足的5个工作日不同。"},{"id":"qa-chsol-04","difficulty":3,"title":"某财险公司年度压力测试与反向压力测试实务","stem":"安平财产保险股份有限公司2026年一季度末综合偿付能力充足率132%，核心偿付能力充足率71%，处于行业中游。董事会要求风险管理部门牵头编制2026年度压力测试报告，测试显示：基本情景下未来第一、第二个会计年度末综合偿付能力充足率分别为128%和109%，核心偿付能力充足率分别为66%和53%；压力情景下未来一个会计年度末综合偿付能力充足率降至87%。管理层对是否需要开展反向压力测试、报告治理流程及预测假设存在疑问，你作为外部精算顾问需逐项解答。","parts":[{"q":"小问1：请说明偿付能力压力测试的定义、三类测试方法及其含义。","answer_points":[{"point":"压力测试定义","detail":"偿付能力压力测试是保险公司在基本情景和各种压力情景下对其未来一段时间内偿付能力充足率的预测和评价，目的是识别和预警导致偿付能力充足率不达标的主要风险因素，及时采取管理和监管措施。"},{"point":"情景法测试","detail":"情景法测试评估多种风险因素同时联动变化情景下对公司偿付能力充足率的影响，反映风险之间的联动效应。"},{"point":"敏感性测试","detail":"敏感性测试评估某一特定风险因素的变动对公司偿付能力充足率的影响；季度压力测试即属于动态单因素敏感性测试。"},{"point":"反向压力测试","detail":"反向压力测试针对特定风险因素，反向评估偿付能力充足率不达标时该风险因素的不利变动幅度，回答“多大幅度的不利变动会使公司不达标”的问题。"}]},{"q":"小问2：请说明季度压力测试与年度压力测试在类型、测试期间上的区别。","answer_points":[{"point":"季度压力测试","detail":"季度压力测试为动态单因素敏感性测试，评估下一季度末实际资本、核心资本、最低资本、偿付能力溢额、偿付能力充足率等指标的变化，结果应在季度偿付能力报告中列报。"},{"point":"年度压力测试的类型","detail":"年度压力测试包括情景法测试、敏感性测试和反向压力测试三类，测试范围与深度均高于季度测试。"},{"point":"基本情景预测期间","detail":"基本情景下应预测报告年度后未来两个会计年度末的偿付能力指标，本案两个年度末的128%和109%即属于此类预测。"},{"point":"压力情景测试期间","detail":"压力情景下应测试未来一个会计年度末的偿付能力指标；公司自测压力情景至少设置一种，且应选择至少两个重大风险因素。"}]},{"q":"小问3：判断该公司是否应开展反向压力测试，并说明反向压力测试的具体要求。","answer_points":[{"point":"适用条件判断","detail":"反向压力测试的适用条件是基本情景下报告年度后未来一个会计年度末综合偿付能力充足率处于100%～150%之间；本案第一年末为128%，落入该区间，应开展反向压力测试。"},{"point":"测试假设水平","detail":"反向压力测试假设下一个会计年度末综合偿付能力充足率降低至100%的水平，倒算最主要风险因素的变化水平，如赔付率恶化幅度、投资收益率下降幅度等。"},{"point":"管理含义","detail":"反向测试结果揭示公司距离不达标的“安全边际”：第二年末109%已逼近100%，说明缓冲很薄，应针对最主要脆弱点制定资本补充或风险对冲预案。"},{"point":"与基本情景预警的衔接","detail":"基本情景下任一期末综合偿付能力充足率低于100%或核心偿付能力充足率低于50%的，应详细说明管理措施及实施计划并提供实施后的预测值；本案两期均未触发，但109%和53%已接近阈值，应在报告中提前披露应对安排。"}]},{"q":"小问4：请说明基本情景预测对增资、资本补充与股利分配的处理要求。","answer_points":[{"point":"资本补充的处理","detail":"基本情景预测应反映银保监会已批准（认可）的增资和资本补充工具发行事项，不应考虑测试期间内未获批准（认可）的资本补充行为，防止虚增预测期资本。"},{"point":"股利分配的处理","detail":"基本情景下的预测应反映公司的股利分配计划，即使股利分配计划尚未得到批准，体现审慎原则：先流出、后补充。"},{"point":"假设一致性要求","detail":"新业务假设应与经董事会或管理层批准的公司业务规划一致，费用假设与业务规划和财务预算一致，投资假设与战略资产配置规划一致，再保险假设符合公司再保险管理策略。"},{"point":"模型评估校验","detail":"公司应每年评估和校验压力测试模型、预测方法和关键假设，特征因子简化处理时报告期特征因子大于0的预测期维持不变、小于等于0的预测期取0。"}]},{"q":"小问5：请说明年度压力测试报告的报送时限、治理要求与审核安排。","answer_points":[{"point":"报送时限","detail":"年度压力测试报告应于每年5月31日前报送银保监会；季度压力测试结果及相关信息应在季度偿付能力报告中列报。"},{"point":"董事会最终责任","detail":"年度压力测试报告应经董事会批准，董事会对压力测试的合规性和合理性承担最终责任，不能仅由风险管理部门或管理层签发。"},{"point":"独立第三方审核","detail":"年度压力测试报告须经独立第三方机构（会计师事务所、精算咨询顾问公司等）审核；除会计师事务所外，其他机构从事审核业务应报银保监会备案。"},{"point":"审核与签章要求","detail":"会计师事务所出具的审核报告由两名注册会计师签名并盖章；其他独立第三方机构的报告由两名在中国从事保险精算及相关工作3年以上、具有精算师资格的精算师签名并盖章；审核意见针对预测假设的合理性和报告编制列报的合规性，而非对充足率是否达标发表意见。"}]}],"framework":"整案以“三类测试方法辨析→季度与年度测试的期间差异→反向压力测试条件与倒算逻辑→基本情景假设的审慎处理→报告治理与第三方审核”为主线：先区分情景法（多因素联动）、敏感性（单因素）与反向测试（倒算不达标幅度）三种方法，再用“基本情景两个会计年度末、压力情景一个会计年度末、季度测试看下一季度末”三个时间轴定位本案数据，判断128%落入100%～150%区间须做反向测试，最后强调5月31日报送、董事会批准、第三方审核三项治理要求。","memo":"案例易错点：①反向压力测试的触发区间是基本情景下未来一个会计年度末综合充足率在100%～150%之间，不是压力情景数据；②压力情景测试期间为一个会计年度末，基本情景预测为两个会计年度末，两者不能互换；③基本情景要反映已批准的增资但反映未获批的股利分配计划，方向容易记反；④自测压力情景须至少包含两个重大风险因素；⑤第三方审核意见不包含“充足率是否达标”的保证。"},{"id":"qa-chsol-05","difficulty":3,"title":"某寿险公司风险综合评级申辩与差异化监管措施应对","stem":"锦绣人寿保险股份有限公司最近四个季度核心偿付能力充足率与综合偿付能力充足率均持续达标，但监管评价发现：公司操作风险中信息系统多次故障、合规内控存在缺陷，战略风险方面新业务规划与自身能力明显不匹配，且流动性风险监测指标接近临界值。公司认为自己充足率达标应评为A类，拟向监管部门提交申辩材料。你作为风险管理咨询顾问，需帮助公司正确理解分类监管的评价逻辑与监管措施体系，并就降级风险提出应对方案。","parts":[{"q":"小问1：请说明偿付能力风险的构成，以及可资本化风险与难以资本化风险各自包含的风险类型。","answer_points":[{"point":"两大风险构成","detail":"保险公司偿付能力风险由固有风险和控制风险组成：固有风险是在现有行业物质技术条件和生产组织方式下经营中必然存在的、客观的偿付能力相关风险；控制风险是因内部管理和控制不完善或无效，导致固有风险未被及时识别和控制的风险。"},{"point":"可资本化风险","detail":"可资本化风险是可以资本化为最低资本的固有风险，包括保险风险、市场风险和信用风险三类，通过最低资本计量予以防范。"},{"point":"难以资本化风险","detail":"难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险四类，难以直接折算为资本要求，纳入风险综合评级定性评估。"},{"point":"本案映射","detail":"本案信息系统故障、合规缺陷属操作风险，新业务规划不匹配属战略风险，监测指标临界属流动性风险隐患，均在难以资本化风险范畴，充足率达标无法抵消其影响。"}]},{"q":"小问2：请说明分类监管的评价方法、评级类别划分及各类别的判定标准。","answer_points":[{"point":"加权平均法","detail":"分类监管评价采用加权平均法：可资本化风险评分与难以资本化风险评分各占50%权重，综合得到评价分数；每季度评价一次，依托偿付能力监管信息系统自动计算，监管部门认为系统得分未准确反映风险状况的可调整评级结果。"},{"point":"四类八档","detail":"按偿付能力风险大小将公司分为A、B、C、D四个监管类别，A类细分为AAA、AA、A（风险由小到大），B类细分为BBB、BB、B。"},{"point":"A类与B类标准","detail":"A类公司：偿付能力充足率达标，且操作、战略、声誉和流动性风险小；B类公司：充足率达标，且四类难以资本化风险较小。"},{"point":"C类与D类标准","detail":"C类公司：偿付能力充足率不达标，或达标但某一类或几类难以资本化风险较大；D类公司：充足率不达标，或达标但某一类或几类风险严重。本案操作与战略风险若被认定“较大”，即使充足率达标也可能评为C类。"}]},{"q":"小问3：针对公司“充足率达标就应评A类”的主张，说明其认识误区。","answer_points":[{"point":"误区一：混淆偿付能力达标与风险评级","detail":"充足率达标只是评级的必要条件之一，A、B类还要求难以资本化风险小或较小；C、D类明确包含“达标但风险较大或严重”的情形，充足率与评级是两条并行而非替代的评价线。"},{"point":"误区二：忽视控制风险","detail":"内部控制缺陷会放大控制风险，控制风险不仅影响风险综合评级，还通过第12号规则的评估结果计量为控制风险最低资本（MC控制风险＝Q×MC可资本化风险），拉低偿付能力充足率本身。"},{"point":"误区三：低估流动性风险联动","detail":"流动性风险通过第13号规则的监管指标、监测指标和现金流压力测试结果评估，接近临界值本身就是降级信号，且与声誉、战略风险相互传染。"},{"point":"正确理解","detail":"申辩材料应聚焦于证明四类难以资本化风险的可控性（整改证据、指标改善趋势），而非仅主张充足率达标；评级每季度动态调整，改善需要持续性数据支撑。"}]},{"q":"小问4：请说明监管机构对A、B、C、D四类公司差异化监管政策与递进的监管措施安排。","answer_points":[{"point":"差异化监管政策","detail":"银保监会在市场准入、产品管理、资金运用、现场检查等方面对四类公司实施差异化监管政策，风险越高的公司受到的限制越多。"},{"point":"B类公司的监管措施","detail":"对B类公司可采取风险提示、监管谈话、要求限期整改、专项现场检查、要求提交和实施预防偿付能力充足率不达标或完善风险管理的计划等措施。"},{"point":"C类公司的递进措施","detail":"对C类公司采取比对B类更严格的监管措施，通常包括责令增加资本金、限制业务范围、限制向股东分红、限制商业性广告、限制高管薪酬等，督促公司限期改善。"},{"point":"D类公司的措施","detail":"对D类公司除可采取对C类公司的监管措施外，还可根据情况采取接管以及银保监会认为必要的其他监管措施，属于最严厉层级。"}]},{"q":"小问5：请为公司制定避免降级的整改方案要点。","answer_points":[{"point":"操作风险整改","detail":"针对信息系统故障加大IT投入、建立故障复盘与问责机制，补齐合规内控短板，操作风险应区分保险业务线、资金运用业务线、公司治理、信息系统、案件管理等类别分别治理。"},{"point":"战略风险校准","detail":"重新评估新业务规划与公司资本、渠道、人才能力的匹配度，将业务规划提交董事会审批前经首席风险官审批，避免激进扩张。"},{"point":"流动性风险前置管理","detail":"落实季度现金流压力测试，建立流动性限额与预警指标体系，制定并演练流动性应急计划，使监测指标远离临界值。"},{"point":"治理与报告配合","detail":"按第12号规则每年开展风险管理自评估，高级管理层至少每年向风险管理委员会汇报一次风险水平；在偿付能力季度报告中如实列报风险状况与整改进展，以持续改善的数据支撑下一季度评级回升。"}]}],"framework":"整案以“风险构成→评价方法与类别标准→误区辨析→监管措施阶梯→整改方案”递进：先拆解固有风险（可资本化三类＋难以资本化四类）与控制风险的双层结构，再用50%＋50%加权平均法和A/B/C/D判定标准反驳“达标即A类”的观点，强调C、D类包含“达标但风险较大或严重”的条款，最后按B类五项基础措施、C类加码措施、D类可接管的递进阶梯，给出信息系统、战略校准、流动性前置三线整改建议。","memo":"案例易错点：①可资本化风险只有保险、市场、信用三类，操作、战略、声誉、流动性四类是难以资本化风险，不要把保险风险归入后者；②评级是每季度评价一次，而非每年一次；③C、D类公司都可能“充足率达标”，达标不是高评级的充分条件；④控制风险最低资本公式为MC控制风险＝Q×MC可资本化风险，与第11号规则的50%＋50%评分权重是两套机制，不能混用；⑤D类公司可被接管，接管仅适用于D类，不要写到B、C类的措施清单里。"}],"calc":[{"id":"c-chsol-01","difficulty":3,"title":"实际资本、充足率与达标判断全链条计算","stem":"华信人寿2026年二季度末（母公司报表口径）：认可资产540亿元，认可负债450亿元。资本结构如下：核心一级资本60亿元，核心二级资本8亿元，附属一级资本6亿元，附属二级资本10亿元；经核查各级资本工具余额均未超过相应限额。公司计量得到最低资本为50亿元。监管达标标准：核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%。","parts":[{"q":"小问1：计算公司实际资本，并判断附属资本是否超过核心资本的100%限额。","blanks":[{"label":"实际资本（亿元）","answer":90,"tolerance":0.1},{"label":"附属资本占核心资本比例（%）","answer":23.5,"tolerance":0.5}],"steps":["实际资本＝认可资产－认可负债＝540－450＝90（亿元）","核心资本＝核心一级60＋核心二级8＝68（亿元）；附属资本＝附属一级6＋附属二级10＝16（亿元）","附属资本占核心资本比例＝16÷68×100%≈23.5%，低于100%限额，未超限"],"formula_card":"实际资本＝认可资产－认可负债；附属资本限额＝核心资本×100%"},{"q":"小问2：计算核心二级资本占核心资本的比例、附属二级资本占核心资本的比例，验证是否超过限额。","blanks":[{"label":"核心二级占核心资本比例（%）","answer":11.8,"tolerance":0.5},{"label":"附属二级占核心资本比例（%）","answer":14.7,"tolerance":0.5}],"steps":["核心二级占比＝8÷68×100%≈11.76%，低于30%限额，合规","附属二级占比＝10÷68×100%≈14.71%，低于25%限额，合规","两档限额分别为核心资本的30%和25%，本案均有充足空间"],"formula_card":"核心二级资本≤核心资本×30%；附属二级资本≤核心资本×25%"},{"q":"小问3：计算核心偿付能力充足率与综合偿付能力充足率。","blanks":[{"label":"核心偿付能力充足率（%）","answer":136,"tolerance":0.5},{"label":"综合偿付能力充足率（%）","answer":180,"tolerance":0.5}],"steps":["核心偿付能力充足率＝核心资本÷最低资本＝68÷50×100%＝136%","综合偿付能力充足率＝实际资本÷最低资本＝90÷50×100%＝180%","两指标分子不同：核心资本（68）与实际资本（90），分母均为最低资本（50）"],"formula_card":"核心充足率＝核心资本÷最低资本×100%；综合充足率＝实际资本÷最低资本×100%"},{"q":"小问4：判断公司偿付能力是否达标，并说明充足率达标时可能落入的风险综合评级类别。","blanks":[{"label":"偿付能力是否达标（达标填1，不达标填0）","answer":1,"tolerance":0}],"steps":["核心充足率136%≥50%，综合充足率180%≥100%，两项均达标","充足率达标且四类难以资本化风险小或较小的，评为A类或B类","若某类难以资本化风险较大或严重，即使达标也可能评为C类或D类"],"formula_card":"达标：核心充足率≥50%且综合充足率≥100%；评级A/B/C/D按风险大小划分"},{"q":"小问5：假设下季度末最低资本上升至60亿元、实际资本与核心资本不变，计算新的两个充足率。","blanks":[{"label":"新核心偿付能力充足率（%）","answer":113.33,"tolerance":0.5},{"label":"新综合偿付能力充足率（%）","answer":150,"tolerance":0.5}],"steps":["新核心充足率＝68÷60×100%≈113.33%","新综合充足率＝90÷60×100%＝150%","结论：分母上升仍达标，但充足率空间收窄，提示最低资本增长对充足率的稀释效应"],"formula_card":"充足率＝资本÷最低资本×100%，最低资本上升则充足率同比例下降"}],"analysis":"全案贯穿实际资本评估与充足率计算主线：以认可资产减认可负债得实际资本90亿元，核心资本68亿元、附属资本16亿元，逐项核对100%、30%、25%三档限额均合规；充足率层面核心136%、综合180%均远超50%和100%达标线；最低资本升至60亿元后两指标分别降至约113.33%和150%，展示充足率的分母敏感性。评级判断需注意充足率达标只是必要条件，最终类别取决于难以资本化风险的大小。","trap":"全案易错点：①核心偿付能力充足率的分子是核心资本68亿元而非实际资本90亿元；②附属资本限额的比较基准是核心资本而非实际资本；③第三小问易将实际资本90÷50误作核心充足率；④最后一问最低资本变化后实际资本与核心资本保持不变，分子切勿随分母联动调整。"},{"id":"c-chsol-02","difficulty":3,"title":"财险公司最低资本多风险聚合与充足率计算","stem":"泰岳财产保险股份有限公司2026年二季度末经分别计量得到：非寿险保险风险最低资本40亿元，市场风险最低资本30亿元，信用风险最低资本25亿元。按第2号规则，财产保险公司可资本化风险最低资本由非寿险保险风险、市场风险、信用风险三项经相关系数矩阵聚合，相关系数为：非寿险保险与市场0.1，非寿险保险与信用0.15，市场与信用0.27。经风险管理能力评估，控制风险最低资本＝Q×MC可资本化风险，Q＝0.1。附加资本为0。公司实际资本为91.2亿元。","parts":[{"q":"小问1：计算三项风险聚合前的最低资本简单加总，以及按相关系数矩阵聚合后的可资本化风险最低资本。","blanks":[{"label":"简单加总（亿元）","answer":95,"tolerance":0.1},{"label":"可资本化风险最低资本（亿元）","answer":63.8,"tolerance":0.1}],"steps":["简单加总＝40＋30＋25＝95（亿元）","平方项：40²＋30²＋25²＝1600＋900＋625＝3125","交叉项：2×0.1×40×30＝240；2×0.15×40×25＝300；2×0.27×30×25＝405；合计945","聚合结果＝√(3125＋945)＝√4070≈63.80（亿元）"],"formula_card":"MC可资本化＝√(ΣMCi²＋2Σρij×MCi×MCj)，ρ：保险-市场0.1、保险-信用0.15、市场-信用0.27"},{"q":"小问2：计算风险分散效应金额。","blanks":[{"label":"分散效应（亿元）","answer":31.2,"tolerance":0.1}],"steps":["分散效应＝简单加总－聚合结果＝95－63.80＝31.20（亿元）","分散效应源于风险间的相关性小于1，相关系数越低分散效应越大"],"formula_card":"分散效应＝ΣMCi－√(ΣMCi²＋2Σρij×MCi×MCj)"},{"q":"小问3：计算控制风险最低资本与公司最低资本。","blanks":[{"label":"控制风险最低资本（亿元）","answer":6.38,"tolerance":0.05},{"label":"最低资本（亿元）","answer":70.18,"tolerance":0.05}],"steps":["控制风险最低资本＝Q×MC可资本化风险＝0.1×63.80＝6.38（亿元）","最低资本＝可资本化风险最低资本＋控制风险最低资本＋附加资本＝63.80＋6.38＋0＝70.18（亿元）"],"formula_card":"MC控制风险＝Q×MC可资本化风险；最低资本＝可资本化＋控制风险＋附加资本"},{"q":"小问4：计算综合偿付能力充足率。","blanks":[{"label":"综合偿付能力充足率（%）","answer":129.95,"tolerance":0.5}],"steps":["综合偿付能力充足率＝实际资本÷最低资本＝91.2÷70.18×100%≈129.95%","129.95%≥100%，综合充足率达标"],"formula_card":"综合偿付能力充足率＝实际资本÷最低资本×100%"},{"q":"小问5：假设实际资本降至70亿元、最低资本不变，计算新的综合偿付能力充足率并判断是否达标、评级上属于什么情形。","blanks":[{"label":"新综合偿付能力充足率（%）","answer":99.74,"tolerance":0.5},{"label":"是否达标（达标填1，不达标填0）","answer":0,"tolerance":0}],"steps":["新综合充足率＝70÷70.18×100%≈99.74%，低于100%，不达标","综合充足率不达标的，风险综合评级应评为C类或D类","此时即使难以资本化风险控制良好，充足率不达标仍直接导致低评级"],"formula_card":"综合充足率＜100%即不达标，对应评级C类或D类"}],"analysis":"全案展示最低资本的完整生成路径：三项风险最低资本40、30、25亿元先经相关系数矩阵（0.1、0.15、0.27）聚合成63.80亿元，较简单加总95亿元产生31.20亿元分散效应；再叠加Q＝0.1的控制风险最低资本6.38亿元和零附加资本，得到最低资本70.18亿元；实际资本91.2亿元对应综合充足率约129.95%。最后通过实际资本降至70亿元的反事实情景，演示99.74%＜100%触发不达标并落入C/D类评级的判断。","trap":"全案易错点：①交叉项必须乘2，漏乘导致聚合结果明显偏低；②三项相关系数数值不同（0.1、0.15、0.27），不能套用单一相关系数；③控制风险最低资本以可资本化风险最低资本为基数（不含控制风险自身），且与可资本化部分直接相加而非再聚合；④分散效应是简单加总减聚合结果，方向不能颠倒。"},{"id":"c-chsol-03","difficulty":3,"title":"压力测试情景下充足率变动与监管应对判断","stem":"安平财产保险股份有限公司编制2026年度压力测试报告。基本情景预测：未来第一个会计年度末实际资本48亿元、最低资本40亿元，其中核心资本26亿元；压力情景测试：未来一个会计年度末实际资本36亿元、最低资本45亿元，其中核心资本18亿元。公司当前综合偿付能力充足率132%。监管要求：基本情景下任一期末综合偿付能力充足率低于100%或核心偿付能力充足率低于50%的，应详细说明管理措施并提供实施后的预测值；基本情景下未来一个会计年度末综合偿付能力充足率处于100%～150%之间的应开展反向压力测试。","parts":[{"q":"小问1：计算基本情景下未来第一个会计年度末的核心偿付能力充足率与综合偿付能力充足率。","blanks":[{"label":"基本情景核心充足率（%）","answer":65,"tolerance":0.5},{"label":"基本情景综合充足率（%）","answer":120,"tolerance":0.5}],"steps":["核心充足率＝核心资本÷最低资本＝26÷40×100%＝65%","综合充足率＝实际资本÷最低资本＝48÷40×100%＝120%","两项均高于50%和100%的达标线"],"formula_card":"充足率＝相应资本÷最低资本×100%"},{"q":"小问2：计算压力情景下未来一个会计年度末的核心偿付能力充足率与综合偿付能力充足率，以及综合充足率相对基本情景的下降幅度。","blanks":[{"label":"压力情景核心充足率（%）","answer":40,"tolerance":0.5},{"label":"压力情景综合充足率（%）","answer":80,"tolerance":0.5},{"label":"综合充足率下降幅度（个百分点）","answer":40,"tolerance":0.5}],"steps":["压力情景核心充足率＝18÷45×100%＝40%，低于50%","压力情景综合充足率＝36÷45×100%＝80%，低于100%","综合充足率下降幅度＝120%－80%＝40个百分点"],"formula_card":"下降幅度（个百分点）＝基本情景充足率－压力情景充足率"},{"q":"小问3：判断公司是否应开展反向压力测试，并说明反向压力测试的假设水平。","blanks":[{"label":"是否应开展反向压力测试（应开展填1，不需要填0）","answer":1,"tolerance":0},{"label":"反向测试假设充足率降至（%）","answer":100,"tolerance":0.5}],"steps":["适用条件：基本情景下未来一个会计年度末综合偿付能力充足率处于100%～150%之间","本案基本情景第一年末为120%，落入区间，应开展反向压力测试","反向压力测试假设下一会计年度末综合偿付能力充足率降低至100%，倒算最主要风险因素的变化水平"],"formula_card":"反向压力测试触发条件：100%≤基本情景第一年末综合充足率≤150%"},{"q":"小问4：判断基本情景下是否触发“详细说明管理措施并提供实施后预测值”的要求。","blanks":[{"label":"是否触发（触发填1，未触发填0）","answer":0,"tolerance":0}],"steps":["触发条件：基本情景下任一期末综合充足率低于100%或核心充足率低于50%","本案基本情景两期充足率均未低于阈值（120%≥100%，65%≥50%），未触发","注意：压力情景下的80%和40%属于压力结果，不直接触发该基本情景条款，但应作为预警信息在报告中分析"],"formula_card":"触发条件：基本情景任一期末综合充足率＜100%或核心充足率＜50%"},{"q":"小问5：若压力情景结果被监管认可为重大风险预警，简述年度压力测试报告的报送时限与治理要求，并计算报告须在每年何日前报送（以“5月31日”填空：填1表示5月31日前）。","blanks":[{"label":"年度报告报送时点为5月31日前（是填1，否填0）","answer":1,"tolerance":0},{"label":"报告须批准的主体层级为董事会（是填1，否填0）","answer":1,"tolerance":0}],"steps":["年度压力测试报告应于每年5月31日前报送银保监会","报告应经董事会批准，董事会对压力测试的合规性和合理性承担最终责任","报告还须经独立第三方机构审核，并在季度偿付能力报告中列报季度压力测试结果"],"formula_card":"年度压力测试报告：每年5月31日前报送＋董事会批准＋第三方审核"}],"analysis":"全案以压力测试为轴心串联充足率计算与监管判断：基本情景第一年末核心65%、综合120%均达标且120%落入100%～150%区间，因此必须开展反向压力测试并假设充足率降至100%倒算主要风险因素变动幅度；压力情景下综合80%、核心40%双双跌破达标线，降幅达40个百分点，虽然压力结果不触发基本情景的管理措施条款，但构成重大预警；报告治理上须落实5月31日前报送、董事会批准与第三方审核三项要求。","trap":"全案易错点：①反向压力测试的判断依据是基本情景（120%）而非压力情景（80%）的充足率；②压力情景充足率跌破100%不等于触发“基本情景管理措施”条款，两者的适用情景不同；③下降幅度按个百分点计算（120−80＝40），不能算百分比变化率；④核心充足率分母同样是最低资本，不要用实际资本做分子。"},{"id":"c-chsol-04","difficulty":3,"title":"流动性覆盖率三指标计算与达标判断","stem":"永泰人寿2026年二季度末开展流动性风险监管指标测算（母公司报表口径）。未来3个月压力情景下：公司现金流出40亿元，公司现金流入12亿元；现金及现金等价物评估时点账面价值6亿元。流动性资产储备构成如下：交易类国债10亿元（折算系数100%）、可提前支取的定期存款8亿元（折算系数90%）、AAA级非金融企业（公司）债券5亿元（折算系数80%）、上市股票4亿元（折算系数50%）、境内股票型开放式基金5亿元（折算系数60%）。未来12个月压力情景下：现金流出80亿元，现金流入30亿元。达标标准：LCR1、LCR2不低于100%，LCR3不低于50%。","parts":[{"q":"小问1：计算流动性资产储备变现金额。","blanks":[{"label":"储备变现金额（亿元）","answer":26.2,"tolerance":0.05}],"steps":["变现金额＝Σ（账面价值×折算系数）＝10×100%＋8×90%＋5×80%＋4×50%＋5×60%","＝10＋7.2＋4＋2＋3＝26.2（亿元）","注意储备不包括现金及现金等价物本身，6亿元现金只在公式中单独计入分子"],"formula_card":"储备变现金额＝流动性资产储备评估时点账面价值×折算系数（逐项计算后加总）"},{"q":"小问2：计算未来3个月的LCR3并判断是否达标。","blanks":[{"label":"未来3个月LCR3（%）","answer":45,"tolerance":0.5},{"label":"LCR3是否达标（达标填1，不达标填0）","answer":0,"tolerance":0}],"steps":["LCR3＝（压力情景现金流入＋现金及现金等价物账面价值）÷压力情景现金流出×100%","＝(12＋6)÷40×100%＝45%","LCR3达标线为50%，45%＜50%，不达标——即使不考虑资产变现障碍，纯靠流入与现金已不足覆盖一半的流出"],"formula_card":"LCR3＝(压力情景现金流入＋现金及现金等价物)÷压力情景现金流出×100%，达标线50%"},{"q":"小问3：计算未来3个月的LCR2并判断是否达标。","blanks":[{"label":"未来3个月LCR2（%）","answer":110.5,"tolerance":0.5},{"label":"LCR2是否达标（达标填1，不达标填0）","answer":1,"tolerance":0}],"steps":["LCR2＝（压力情景现金流入＋现金及现金等价物＋储备变现金额）÷压力情景现金流出×100%","＝(12＋6＋26.2)÷40×100%＝44.2÷40×100%＝110.5%","110.5%≥100%，未来3个月LCR2达标，说明公司短期内依赖储备资产变现可维持流动性"],"formula_card":"LCR2＝(压力情景现金流入＋现金＋储备变现金额)÷压力情景现金流出×100%，达标线100%"},{"q":"小问4：计算未来12个月的LCR2并判断是否达标。","blanks":[{"label":"未来12个月LCR2（%）","answer":77.75,"tolerance":0.5},{"label":"LCR2是否达标（达标填1，不达标填0）","answer":0,"tolerance":0}],"steps":["假设12个月口径下储备变现金额与现金不变：LCR2＝(30＋6＋26.2)÷80×100%＝62.2÷80×100%＝77.75%","77.75%＜100%，未来12个月LCR2不达标","结论：公司流动性风险呈“短稳长险”特征，应按3个月和12个月两个期限分别计算并披露"],"formula_card":"LCR2（12个月）＝(12个月现金流入＋现金＋储备变现金额)÷12个月现金流出×100%"},{"q":"小问5：结合测算结果，判断公司是否应关注重大流动性风险报告义务，并给出至少两项改善流动性状况的应对措施方向。","blanks":[{"label":"重大流动性风险报告时限为发现之日起3日内（是填1，否填0）","answer":1,"tolerance":0}],"steps":["LCR3为45%、12个月LCR2为77.75%，两项监管指标不达标，存在重大流动性风险隐患，若认定为重大流动性风险应自发现之日起3日内向银保监会报告","应对一：调整资产结构，提高100%折算的高流动性资产（国债、货币市场基金）占比，压缩非标与长期限资产","应对二：负债端管理退保与满期给付节奏，稳定现金流入；必要时按既定决策程序落实有明确安排的筹资","监管方面：公司可能被要求提交改善流动性水平的计划、完善流动性管理机制或接受监管谈话"],"formula_card":"重大流动性风险：发现之日起3日内报告；监管措施含改善计划、完善机制、监管谈话"}],"analysis":"全案完整演练三大LCR口径：储备逐项折算得变现金额26.2亿元；3个月LCR3＝45%（＜50%不达标）、LCR2＝110.5%（≥100%达标），12个月LCR2＝77.75%（＜100%不达标），呈现“不考虑变现不行、考虑变现短期够用、拉长到一年仍不足”的典型结构；由此引出3日报告义务与资产结构调整、负债端管理等应对方向。计算关键在于折算系数逐项匹配与分子三项（流入＋现金＋储备变现）的完整组合。","trap":"全案易错点：①LCR3不计算储备变现金额，若把26.2亿元加进LCR3分子会得到80.5%的错误结果；②上市股票折算系数50%、股票型开放式基金60%、可提前支取定期存款90%，易互相混淆；③12个月口径下不要沿用3个月的流入流出数据，分母80亿元、分子流入30亿元需重新代入；④达标判断LCR2看100%、LCR3看50%，两线不同。"},{"id":"c-chsol-05","difficulty":3,"title":"偿付能力报告时限与重大事项门槛判断","stem":"恒昌财产保险股份有限公司2026年第三季度经营数据：报告期末净资产100亿元，报告期保费收入20亿元，本季度末有效保额500亿元。报告期内发生如下事项：（1）发行资本补充债券12亿元；（2）单项股权投资损失4亿元；（3）与某再保险人签订的分出保费为1.4亿元的分保合同；（4）本季度发生一起赔付金额居前五位的重大赔付事项。年度审计后（2027年初出具审计报告）：综合偿付能力充足率由报告数148%调整为143%，实际资本由80亿元调整为79.2亿元（原最低资本60亿元不变）。此外公司在报告期内出现重大流动性风险。","parts":[{"q":"小问1：计算第三季度季度快报与季度报告的报送时限截止日（以季度结束后天数计），并判断第三季度报告是否必须经董事会审议。","blanks":[{"label":"季度快报报送时限（季度结束后日内）","answer":12,"tolerance":0.5},{"label":"季度报告报送时限（季度结束后日内）","answer":25,"tolerance":0.5},{"label":"第三季度报告是否可不经董事会审议（可填1，必须填0）","answer":1,"tolerance":0}],"steps":["季度快报应在每季度结束后12日内报送，季度报告应在每季度结束后25日内报送","第1季度和第3季度的偿付能力报告可以不经过董事会审议，但须经董事长批准并在报告中作相应声明","第四季度报告须经会计师事务所审计，第二季度报告应列报上一年度第四季度报告的审计意见"],"formula_card":"季度快报：季度结束后12日内；季度报告：季度结束后25日内；Q1、Q3可免董事会审议"},{"q":"小问2：判断发行12亿元资本补充债券是否构成重大融资事项（计算占净资产比例）。","blanks":[{"label":"融资额占净资产比例（%）","answer":12,"tolerance":0.5},{"label":"是否构成重大融资事项（是填1，否填0）","answer":1,"tolerance":0}],"steps":["重大融资事项标准：单笔融资金额超过公司报告期末净资产10%","比例＝12÷100×100%＝12%，超过10%，构成重大融资事项","应在当季季度报告的重大事项部分列报，能够估计影响金额的应说明对核心与综合偿付能力充足率的影响"],"formula_card":"重大融资事项：单笔融资＞报告期末净资产×10%"},{"q":"小问3：判断单项股权投资损失4亿元是否构成重大投资损失，并判断1.4亿元分出保费的分保合同是否构成重大再保险合同。","blanks":[{"label":"投资损失占净资产比例（%）","answer":4,"tolerance":0.5},{"label":"是否构成重大投资损失（是填1，否填0）","answer":0,"tolerance":0},{"label":"分出保费占报告期保费收入比例（%）","answer":7,"tolerance":0.5},{"label":"是否构成重大再保险合同（是填1，否填0）","answer":1,"tolerance":0}],"steps":["重大投资损失标准：单项投资损失金额超过报告期末净资产总额5%；4÷100＝4%，未超过5%，不构成重大投资损失","重大再保险合同标准：分出保额超过本季度末有效保额的5%或分出保费超过报告期保费收入的5%","分出保费比例＝1.4÷20×100%＝7%，超过5%，构成重大再保险合同，应列报"],"formula_card":"重大投资损失：单项损失＞净资产×5%；重大再保险合同：分出保费＞报告期保费收入×5%"},{"q":"小问4：计算审计调整后综合偿付能力充足率的变动幅度，判断是否属于审计后重大变动、应在何时限内报告。","blanks":[{"label":"调整后综合偿付能力充足率（%）","answer":132,"tolerance":0.5},{"label":"充足率变动（个百分点）","answer":16,"tolerance":0.5},{"label":"是否属于审计后重大变动（是填1，否填0）","answer":1,"tolerance":0},{"label":"报告时限（自审计报告出具之日起日内）","answer":10,"tolerance":0.5}],"steps":["调整后综合充足率＝调整后实际资本÷最低资本＝79.2÷60×100%＝132%","变动＝148%－132%＝16个百分点，超过3个百分点的标准，属于审计后重大变动","同时实际资本变动＝(80－79.2)÷80＝1%，达到1%的变动标准（超过1%即触发，本案等于1%按充足率变动已足以判定）","应在审计报告出具之日起10日内向银保监会报告"],"formula_card":"审计重大变动标准：核心或综合充足率变动超3个百分点，或实际资本/最低资本变动比例超1%；报告时限10日内"},{"q":"小问5：判断重大流动性风险的报告时限，以及偿付能力不足时临时报告的时限。","blanks":[{"label":"重大流动性风险报告时限（发现之日起日内）","answer":3,"tolerance":0.5},{"label":"偿付能力不足报告时限（发现之日起工作日内）","answer":5,"tolerance":0.5}],"steps":["出现重大流动性风险时，应自发现之日起3日内向银保监会报告，说明当前流动性水平、风险状况及已采取和拟采取的应急措施","任何时点出现偿付能力不足的，应在发现之日起5个工作日内报告","重大不利影响事项（重大投资损失、重大赔付、大规模退保、重大诉讼等）的报告时限同为5个工作日；三者时限易混淆，须分清“3日”与“5个工作日”及“10日”的适用情形"],"formula_card":"重大流动性风险3日内；偿付能力不足及重大不利影响事项5个工作日内；审计重大变动10日内"}],"analysis":"全案以第18号规则为轴心，把时限类规则（季度快报12日、季度报告25日、重大流动性风险3日、偿付能力不足5个工作日、审计重大变动10日）与门槛类规则（重大融资10%、重大投资损失5%、重大再保险合同5%、审计充足率变动3个百分点、资本变动1%）统一放在同一案情中辨析：12亿元融资占净资产12%构成重大融资事项，4亿元投资损失占4%未达5%，1.4亿元分出保费占7%构成重大再保险合同，审计后充足率由148%降至132%、变动16个百分点远超3个百分点，须在审计报告出具之日起10日内报告。","trap":"全案易错点：①重大投资损失门槛5%本案4%未触发，不要见到损失就判定为重大；②重大再保险合同的保费口径是报告期保费收入（7%触发），不要用保额口径误算；③审计重大变动的报告时限是“审计报告出具之日起10日内”，与流动性风险的“发现之日起3日内”、偿付能力不足的“5个工作日”分属不同起算点与单位；④调整后充足率132%用调整后实际资本79.2÷最低资本60计算，不要沿用原实际资本80亿元。"}]}},"fm":{"name":"财务管理","short":"财务管理","icon":"🧮","units":[{"id":"cpa_ch01","group":"财务成本管理","name":"第1章 财务管理概述","qa":[{"id":"qa-cpach01-01","difficulty":1,"q":"简述公司制企业相对于个人独资企业和合伙企业的主要优点，并说明其自身存在的局限性。","answer_points":[{"point":"优点一：无限续存","detail":"公司作为独立法人，股东退出、死亡或转让股权均不影响公司存续，经营具有长期稳定性，这是个人独资与合伙企业不具备的。"},{"point":"优点二：股权可以转让","detail":"所有者权益可细分为股份并自由转让，便于融资和所有权流动，而个人独资与合伙企业权益转让受限。"},{"point":"优点三：有限责任","detail":"股东仅以其出资额为限对公司债务承担责任，公司债务是法人债务而非所有者个人债务，降低了股东投资风险。"},{"point":"局限一：双重课税","detail":"公司赚取利润先缴企业所得税，股东分红再缴个人所得税，存在重复征税，抬升了资本成本。"},{"point":"局限二：组建成本高","detail":"公司须依公司法登记、提交一系列法律文件、定期报备并公告，设立与合规成本高昂。"},{"point":"局限三：存在代理问题","detail":"所有权与经营权分离，经营者可能背离股东利益，产生监督与激励的代理成本。"}],"framework":"先列三点优点（无限续存、股权转让、有限责任），再列三点局限（双重课税、组建成本、代理问题）。","memo":"易错：股权'可以转让'是公司制优点而非局限；有限责任是'以出资额为限'。","tag":""},{"id":"qa-cpach01-02","difficulty":2,"q":"比较利润最大化、每股收益最大化与股东财富最大化三种财务管理目标，并分析前两种目标的局限性。","answer_points":[{"point":"利润最大化局限一：不考虑取得时间","detail":"今年赚100万与十年后赚100万对股东价值不同，该目标未用货币时间价值折现，偏向短期行为。"},{"point":"利润最大化局限二：不考虑投入资本","detail":"未将利润与投入资本挂钩，投入500万赚100万与投入5000万赚100万不可同等评价。"},{"point":"利润最大化局限三：不考虑风险","detail":"高收益常伴高风险，该目标可能诱导经营者追逐高风险项目而损害资本安全。"},{"point":"每股收益最大化仍未考虑时间与风险","detail":"虽以每股收益引入投入资本因素，但仍忽视每股收益取得的时间和对应风险，本质局限未消除。"},{"point":"每股收益最大化下不同公司不可比","detail":"各公司每股投入资本差别大，每股盈余口径不一致，跨公司比较缺乏意义。"},{"point":"股东财富最大化以市场增加值最大化为核心","detail":"目标为股东权益的市场增加值（市场价值减投资资本）最大化，同时考虑时间、风险与投入，教材倡导此目标。"},{"point":"资本市场有效时三目标同义","detail":"在有效市场中，股东财富最大化与股价最大化、公司价值最大化等价，是实务可观测的代理变量。"}],"framework":"按'利润最大化三局限→每股收益最大化两局限→股东财富最大化内涵与同义'逐层递进。","memo":"易错：每股收益最大化只解决了'投入资本'问题，时间与风险仍缺失；利益相关者要求是目标间分歧，不是利润最大化本身的缺陷。","tag":""},{"id":"qa-cpach01-03","difficulty":2,"q":"经营者可能以哪些方式背离股东利益？股东又通过哪些制度性措施来协调双方利益？","answer_points":[{"point":"表现一：道德风险（不十分卖力）","detail":"经营者为增加闲暇、规避风险而工作不努力，属于'该做不做'的消极背离，不直接侵吞资产。"},{"point":"表现二：逆向选择（谋取私利）","detail":"装修豪华办公室、购置高档汽车、借工作之便乱花公司钱、蓄意压低股价买入股票等，主动为自身谋利。"},{"point":"协调措施一：监督","detail":"完善公司治理结构、聘请注册会计师审计、建立信息披露与制衡机制，约束经营者机会主义行为。"},{"point":"协调措施二：激励","detail":"通过奖金、股票期权等报酬安排，使经营者收益与股东财富挂钩，利益趋向一致。"},{"point":"补充：股东亦可能损害债权人","detail":"股东可投资高风险项目或发行新债使旧债贬值来转移财富，故债权人需在借款合同中加入保护性条款。"}],"framework":"先列'两大背离表现（道德风险、逆向选择）'，再列'两措施（监督、激励）'，最后可延展至债权人保护。","memo":"易错：'偷懒'属道德风险而非逆向选择；'装修豪华办公室'属逆向选择而非道德风险。","tag":""},{"id":"qa-cpach01-04","difficulty":3,"q":"在有效资本市场假设下，管理者能否通过会计政策选择或金融投机提升股票价值？请结合有效市场假说的三种程度说明其依据与实务含义。","answer_points":[{"point":"会计政策选择不能提升价值","detail":"有效市场中价格同步、完全反映全部可用信息，会计政策选择不改变公司真实现金流量，故不能创造股东价值。"},{"point":"金融投机不能持续获利","detail":"若市场有效，投资人无法持续获得超额收益，公司进行金融投机亦不能系统性提升股价。"},{"point":"实务含义：管理者应关注本公司股价","detail":"股价是市场对公司行为（投资、筹资、经营）的评价信号，可用于检验决策是否被市场认可。"},{"point":"弱式有效：仅反映历史信息","detail":"股价已包含历史价格与交易量信息，技术分析失效；以随机游走模型与过滤检验验证。"},{"point":"半强式有效：反映历史与公开信息","detail":"所有公开财报、公告信息均已定价，基本面分析失效；以事件研究法与投资基金表现研究验证。"},{"point":"强式有效：反映全部信息含内部信息","detail":"连内幕信息也无法获得超额收益，是最强程度的效率，现实中较少完全满足。"},{"point":"市场有效的三个条件","detail":"理性投资者、独立的理性偏差、套利三者至少满足其一，市场即有效，此为有效假说的逻辑前提。"}],"framework":"总起'不能提升价值'→分述会计政策与投机→按弱式/半强式/强式三层展开→收尾市场有效条件。","memo":"易错：有效市场'不能提升价值'不等于'不用管股价'，恰恰应关注股价这一评价信号；弱式仅排除技术分析。","tag":""},{"id":"qa-cpach01-05","difficulty":3,"q":"对比个人独资企业、合伙企业与公司制企业在法律责任、设立成本与存续性上的差异，并说明财务管理内容与资产负债表各项目的对应关系。","answer_points":[{"point":"个人独资企业：无限责任、设立简单","detail":"一个自然人投资，财产归个人所有，投资人以个人财产对企业债务承担无限责任，设立成本低、无独立法人地位。"},{"point":"合伙企业：普通合伙无限连带、有限合伙有限","detail":"两以上主体订立合伙协议共担风险；普通合伙人对债务承担无限连带责任，有限合伙人以出资为限担责，设立成本适中。"},{"point":"公司制企业：有限责任但双重课税","detail":"依公司法登记的独立法人，股东以出资为限担责，但需缴企业所得税与个人所得税，组建成本高。"},{"point":"长期投资对应非流动资产","detail":"财务管理中的长期投资（如固定资产、长期股权）落在资产负债表左下方非流动资产，是资源配置核心。"},{"point":"长期筹资对应非流动负债与股东权益","detail":"长期筹资（长期借款、债券、权益融资）对应右下方非流动负债与股东权益，决定资本结构。"},{"point":"营运资本管理对应流动项目","detail":"营运资本管理对应上方流动资产与流动负债；营运资本本身＝流动资产－流动负债，衡量短期偿债缓冲。"}],"framework":"先横向对比三种组织形式的'责任/成本/存续'，再纵向将'长期投资、长期筹资、营运资本'映射到资产负债表三大区块。","memo":"易错：营运资本＝流动资产－流动负债（差额而非比率）；合伙企业要区分普通与有限合伙的责任差异。","tag":""}],"calc":[{"id":"c-cpach01-01","difficulty":1,"stem":"甲公司股东投入资本为3000万元，当前股东权益市场价值为5000万元。要求计算该公司股东权益的市场增加值。","blanks":[{"label":"股东权益的市场增加值（万元）","answer":2000,"tolerance":0.1}],"steps":["第1步（公式）：股东权益的市场增加值 = 股东权益市场价值 - 股东投资资本。","第2步（代入）：市场增加值 = 5000 - 3000 = 2000（万元）。"],"formula_card":"股东权益的市场增加值 = 股东权益市场价值 - 股东投资资本","analysis":"依定义直接计算，5000万元市场价值中超出股东原始投入3000万元的部分2000万元，即为公司为本股东新创造的价值。结果为正，说明公司毁灭价值之反向情形未发生。","trap":"勿将'股东权益市场价值'误当作'市场增加值'；本题求的是超出投资资本的增量而非 total 市值。","tag":""},{"id":"c-cpach01-02","difficulty":2,"stem":"乙公司股东投资资本为5000万元，当前股东权益市场价值为8000万元，债务价值为2000万元。要求先计算股东权益的市场增加值，再计算公司价值。","blanks":[{"label":"股东权益的市场增加值（万元）","answer":3000,"tolerance":0.1},{"label":"公司价值（万元）","answer":10000,"tolerance":0.1}],"steps":["第1步（市场增加值）：股东权益的市场增加值 = 8000 - 5000 = 3000（万元）。","第2步（公司价值）：公司价值 = 股东权益市场价值 + 债务价值 = 8000 + 2000 = 10000（万元）。"],"formula_card":"股东权益市场增加值 = 股东权益市场价值 - 股东投资资本；公司价值 = 股东权益市场价值 + 债务价值","analysis":"先由市值减投资资本得市场增加值3000万元，再将股权市值与债务价值相加得公司价值10000万元。债务价值不变时，公司价值最大化与股东财富最大化同义。","trap":"公司价值公式中的'股东权益'用市场价值而非账面价值；债务价值'不变'是两者同义的前提，若债务价值变动则不再等价。","tag":""},{"id":"c-cpach01-03","difficulty":3,"stem":"丙公司股东投资资本始终为4000万元，债务价值在年初、年末均为3000万元（保持不变）。年初股东权益市场价值为6000万元，年末升至9000万元。要求计算年末股东权益市场增加值、年初股东权益市场增加值，并测算本年度公司为股东新创造的价值（用市场增加值法与用公司价值法各验证一次）。","blanks":[{"label":"年末股东权益的市场增加值（万元）","answer":5000,"tolerance":0.1},{"label":"年初股东权益的市场增加值（万元）","answer":2000,"tolerance":0.1},{"label":"本年度为股东新创造的价值（万元）","answer":3000,"tolerance":0.1}],"steps":["第1步（年末市场增加值）：年末市场增加值 = 9000 - 4000 = 5000（万元）。","第2步（年初市场增加值）：年初市场增加值 = 6000 - 4000 = 2000（万元）。","第3步（新增股东价值·市场增加值法）：本年度新增 = 5000 - 2000 = 3000（万元）。","第4步（验证·公司价值法）：年末公司价值 = 9000 + 3000 = 12000，年初公司价值 = 6000 + 3000 = 9000，增加额 = 12000 - 9000 = 3000（万元），与第3步一致。"],"formula_card":"股东权益市场增加值 = 股东权益市场价值 - 股东投资资本；公司价值 = 股东权益市场价值 + 债务价值；新增股东价值 = 年末市场增加值 - 年初市场增加值","analysis":"在投资资本与债务价值均不变的前提下，本年股东权益市值增加3000万元，对应市场增加值由2000增至5000，净增3000万元；用公司价值法验证（12000-9000）同样得3000万元，说明债务价值不变时公司价值增量与股东财富增量完全等价。","trap":"比较'创造的价值'必须用两期市场增加值之差，而非直接用年末市值；若债务价值在两期间变动，公司价值增量将不等于股东财富增量。","tag":""}]},{"id":"cpa_ch02","group":"财务成本管理","name":"第2章 财务报表分析和财务预测","qa":[{"id":"qa-cpach02-01","difficulty":1,"q":"简述评价企业短期偿债能力的四个主要财务比率，并说明其反映的偿债能力侧重点有何不同。","answer_points":[{"point":"流动比率 = 流动资产 ÷ 流动负债","detail":"最常用，反映流动资产对流动负债的总体覆盖倍数；但包含变现较慢的存货与预付款项，稳健性有限。"},{"point":"速动比率 = 速动资产 ÷ 流动负债","detail":"速动资产＝货币资金＋交易性金融资产＋各项应收款项，剔除存货等，更严格地衡量即时变现偿债能力。"},{"point":"现金比率 = 货币资金 ÷ 流动负债","detail":"最保守，仅以现金及现金等价物覆盖流动负债，反映最坏情形下的即时支付能力。"},{"point":"现金流量比率 = 经营活动现金流量净额 ÷ 流动负债","detail":"以'真金白银'的经营现金流衡量偿债保障，弥补了以资产负债表时点数计算的上述比率的静态局限。"},{"point":"四指标保守程度递增","detail":"从流动比率到现金比率，资产变现能力要求逐步提高，对偿债能力的判断也日趋严格；现金流量比率则从动态现金生成角度补充验证。"}],"framework":"按'流动→速动→现金→现金流量'四个比率逐一定义并比较保守程度。","memo":"易错：速动资产不含存货、预付款项、一年内到期非流动资产；现金比率仅含货币资金而非全部速动资产。","tag":""},{"id":"qa-cpach02-02","difficulty":2,"q":"计算存货周转率时，周转额在不同分析目的下应如何选择？为什么？并说明存货周转天数是否越低越好。","answer_points":[{"point":"短期偿债与总资产周转分析用营业收入","detail":"为保持与资产规模口径一致、便于跨资产周转比较，短期偿债能力分析和总资产周转率计算常以营业收入作周转额。"},{"point":"评价存货管理业绩用营业成本","detail":"存货按成本计价，用营业成本作周转额使分子（成本流出）与分母（存货成本）口径一致，更能反映管理效率。"},{"point":"选择依据是口径一致原则","detail":"周转额应与资产计价基础匹配：资产按成本计则用成本，按市价/收入关联计则用收入，否则比率失去解释力。"},{"point":"存货周转天数并非越低越好","detail":"过低可能意味存货不足、断货或生产安排过紧，需结合行业经营需要与安全库存综合判断。"},{"point":"周转天数 = 365 ÷ 周转次数","detail":"无论采用何种周转额，周转天数均由365除以对应周转次数求得，用于直观表达变现所需天数。"}],"framework":"先分'营业收入 vs 营业成本'两种用途，再讲'口径一致'原理，最后澄清'天数非越低越好'。","memo":"易错：同一公司用收入算与用成本算的存货周转率数值不同，比较时必须统一口径；周转天数低≠业绩好。","tag":""},{"id":"qa-cpach02-03","difficulty":2,"q":"杜邦分析体系的核心公式是什么？权益乘数在口径选择上应注意什么？","answer_points":[{"point":"核心公式：权益净利率 = 营业净利率 × 总资产周转次数 × 权益乘数","detail":"将股东回报率拆为盈利性、资产运营效率与财务杠杆三层驱动，是杜邦体系的经典分解。"},{"point":"中间层：权益净利率 = 总资产净利率 × 权益乘数","detail":"总资产净利率 = 净利润 ÷ 总资产，再乘以权益乘数即得到股东报酬率，体现杠杆放大效应。"},{"point":"权益乘数 = 总资产 ÷ 股东权益","detail":"衡量财务杠杆，权益乘数越大说明负债占比越高、股东每元投入撬动更多资产。"},{"point":"需区分平均数与期末数口径","detail":"教材中权益乘数可能用股东权益平均余额或期末余额，不同口径结果不同，跨公司比较须统一。"},{"point":"分析意义：定位驱动因素","detail":"权益净利率变动可归因于净利率、周转次数或权益乘数变化，便于针对性改进经营或资本结构。"}],"framework":"先给三因素核心公式，再给两因素中间式，接着定义权益乘数并强调'平均数/期末数'口径。","memo":"易错：权益乘数分母用'股东权益'而非'总负债'；比较杜邦结果前务必确认权益乘数口径一致。","tag":""},{"id":"qa-cpach02-04","difficulty":3,"q":"在改进杜邦分析体系（管理用财务报表）中，权益净利率 = 净经营资产净利率 +（净经营资产净利率 - 税后利息率）× 净财务杠杆。请说明式中'经营差异率'与'杠杆贡献率'的含义，并分析提高杠杆贡献率的途径及其伴随的风险。","answer_points":[{"point":"净经营资产净利率 = 税后经营净利润 ÷ 净经营资产","detail":"反映经营活动本身（不含融资结构）的盈利能力，是管理用体系的基础盈利指标。"},{"point":"税后利息率 = 税后利息费用 ÷ 净负债","detail":"反映债务的真实税后成本，分子须用抵税后的税后利息费用，分母用净负债。"},{"point":"经营差异率 = 净经营资产净利率 - 税后利息率","detail":"衡量经营活动回报率超出债务成本的部分，是杠杆能否为股东'加值'的前提条件。"},{"point":"杠杆贡献率 = 经营差异率 × 净财务杠杆","detail":"净财务杠杆＝净负债 ÷ 股东权益，杠杆贡献率表示因借入资金而额外增加（或减少）的股东权益报酬。"},{"point":"提高途径：提高净财务杠杆","detail":"在经营差异率为正时，增加净负债比重（提高净财务杠杆）可放大杠杆贡献率，提升权益净利率。"},{"point":"风险：经营差异率为负时加杠杆反而损害股东","detail":"若净经营资产净利率低于税后利息率，经营差异率为负，此时提高杠杆会放大损失，且高负债还加剧财务风险与破产可能。"}],"framework":"拆解改进杜邦四要素→定义经营差异率与杠杆贡献率→'正差异率才宜加杠杆'的权衡与风险。","memo":"易错：经营差异率必须为正加杠杆才有利；税后利息率分子用'税后'利息而非息税前利息。","tag":""},{"id":"qa-cpach02-05","difficulty":3,"q":"对比内含增长率与可持续增长率的基本假设差异，并说明外部融资额计算公式中各项对融资需求的影响方向。","answer_points":[{"point":"内含增长率假设不外部融资","detail":"仅靠内部留存积累支撑销售增长，外部融资额为零，反映企业不依赖外部资金时能实现的最高增速。"},{"point":"可持续增长率假设经营效率与财务政策不变且不增发新股","detail":"营业净利率、总资产周转率、权益乘数、利润留存率均维持基期水平，资本结构不能随意调整，是'稳态'增速。"},{"point":"外部融资额 = 经营资产增加 - 经营负债增加 - 可动用金融资产 - 留存收益增加","detail":"该式以销售百分比法为基础，四部分共同决定需从外部筹措的资金规模。"},{"point":"经营资产增加、经营负债增加方向相反","detail":"经营资产随销售增加需追加资金（增大外部融资需求），经营负债随销售自发增加（抵减外部融资需求）。"},{"point":"可动用金融资产与留存收益增加均抵减需求","detail":"可动用金融资产越多、利润留存率越高（留存收益增加越多），内部资金来源越充裕，外部融资需求越小。"}],"framework":"先对比两增长率假设→再列外部融资额四项式→逐项分析正负影响方向。","memo":"易错：内含增长率'零外部融资'不等于'零融资'，而是靠留存；经营负债是自发融资，会'减'而非'加'需求。","tag":""}],"calc":[{"id":"c-cpach02-01","difficulty":1,"stem":"某企业本年净利润为136万元，营业收入为3000万元。要求计算其营业净利率。","blanks":[{"label":"营业净利率（%）","answer":4.53,"tolerance":0.01}],"steps":["第1步（公式）：营业净利率 = 净利润 ÷ 营业收入 × 100%。","第2步（代入）：营业净利率 = 136 ÷ 3000 × 100% = 4.5333…% ≈ 4.53%。"],"formula_card":"营业净利率 = 净利润 ÷ 营业收入 × 100%","analysis":"净利润136万元占营业收入3000万元的比重约为4.53%，反映每百元收入实现的净利润水平，是杜邦分析的第一驱动因素。","trap":"结果以百分比表示，计算时勿遗漏×100%；保留两位小数为4.53%而非4.5%。","tag":""},{"id":"c-cpach02-02","difficulty":2,"stem":"某企业总资产为5000万元，总负债为3000万元，股东权益为2000万元。要求先计算资产负债率，再计算权益乘数。","blanks":[{"label":"资产负债率（%）","answer":60,"tolerance":0.01},{"label":"权益乘数","answer":2.5,"tolerance":0.01}],"steps":["第1步（资产负债率）：资产负债率 = 总负债 ÷ 总资产 × 100% = 3000 ÷ 5000 × 100% = 60.00%。","第2步（权益乘数）：权益乘数 = 总资产 ÷ 股东权益 = 5000 ÷ 2000 = 2.50。"],"formula_card":"资产负债率 = 总负债 ÷ 总资产 × 100%；权益乘数 = 总资产 ÷ 股东权益","analysis":"企业资产中60%由负债形成，权益乘数为2.50，说明股东每1元投入撬动了2.5元资产，负债水平中等偏高，财务杠杆明显。","trap":"资产负债率分母为'总资产'不是'股东权益'；权益乘数用期末股东权益口径时为2.50，若改平均数口径数值会变化。","tag":""},{"id":"c-cpach02-03","difficulty":3,"stem":"某公司本年数据：净利润300万元、营业收入5000万元、总资产2500万元、股东权益1000万元、利润留存率40%，且不增发新股。要求沿'比率→杜邦→可持续增长率'链条计算：营业净利率、总资产周转次数、权益乘数、权益净利率（杜邦），以及按期初股东权益法口径的可持续增长率。","blanks":[{"label":"营业净利率（%）","answer":6,"tolerance":0.01},{"label":"权益净利率·杜邦（%）","answer":30,"tolerance":0.01},{"label":"可持续增长率（%）","answer":12,"tolerance":0.01}],"steps":["第1步（营业净利率）：净利润 ÷ 营业收入 = 300 ÷ 5000 = 6.00%。","第2步（总资产周转次数）：营业收入 ÷ 总资产 = 5000 ÷ 2500 = 2.00（次）。","第3步（权益乘数·期末口径）：总资产 ÷ 股东权益 = 2500 ÷ 1000 = 2.50。","第4步（权益净利率·杜邦）：营业净利率 × 总资产周转次数 × 权益乘数 = 6% × 2.00 × 2.50 = 30.00%。","第5步（可持续增长率·期初股东权益法）：营业净利率 × 总资产周转次数 × 权益乘数 × 利润留存率 = 6% × 2.00 × 2.50 × 40% = 12.00%。"],"formula_card":"权益净利率 = 营业净利率 × 总资产周转次数 × 权益乘数；可持续增长率(期初股东权益法) = 营业净利率 × 总资产周转次数 × 权益乘数 × 利润留存率","analysis":"企业盈利能力6%、资产周转2次、杠杆2.5倍共同驱动权益净利率达30%；在经营效率与财务政策不变且不增发新股下，可持续增长率为12%，即销售最高可年增12%而无需外部股权融资。中间值总资产周转次数2.00、权益乘数2.50已用于第4、5步，此处未单列填空。","trap":"可持续增长率若用'期末股东权益法'需除(1-权益净利率×留存率)，结果不同；本题采用源文件所列'期初股东权益法'乘积口径，直接得12%。权益乘数须明确用期末数。","tag":""}]},{"id":"cpa_ch04","group":"财务成本管理","name":"第4章 资本成本","qa":[{"id":"qa-cpach04-01","difficulty":1,"q":"简述资本成本的本质及其在财务管理中的主要用途。","answer_points":[{"point":"本质是投资资本的机会成本","detail":"资本成本是公司将资本投入本项目而放弃的其他最佳投资机会所能获得的收益，而非实际已付利息。"},{"point":"也是公司使用资金的代价","detail":"从筹资方看，资本成本是募集和使用资金所付出的报酬，通常用相对数（年化百分比）表示。"},{"point":"是投资项目取舍率与最低可接受报酬率","detail":"项目预期报酬率低于资本成本则应放弃，资本成本构成了投资决策的临界基准。"},{"point":"用途一：筹资决策","detail":"比较不同融资方式成本，选择加权成本最低的资本结构方案。"},{"point":"用途二：投资决策","detail":"作为折现率评估项目净现值，或作为内含报酬率的比较基准。"},{"point":"用途三：营运资本管理、价值评估与业绩评价","detail":"营运资本机会成本计量、企业价值评估的折现率、以及经济增加值(EVA)中的资本成本扣减均依赖它。"}],"framework":"先讲'本质（机会成本+使用代价）'，再列'取舍率'定位，最后展开五项用途。","memo":"易错：资本成本是'机会成本'而非账面利息；必须面向未来，不能用历史成本代替。","tag":""},{"id":"qa-cpach04-02","difficulty":2,"q":"估计债务资本成本有哪四种方法？分别说明各自的适用条件。","answer_points":[{"point":"方法一：到期收益率法","detail":"使债券未来现金流量现值等于当前市价的折现率，适用于公司有上市长期债券、市价可观察的情形，反映当前市场要求的税前债务成本。"},{"point":"方法二：可比公司法","detail":"找信用级别、期限相近的上市公司债券作参照，适用于本公司无上市债券但有合适可比公司的情形。"},{"point":"方法三：风险调整法","detail":"税前债务成本＝同期政府债券到期收益率＋信用风险补偿率，适用于无上市债券且无可比公司的情形，需估算信用风险补偿率。"},{"point":"方法四：财务比率法","detail":"通过公司关键财务比率推断信用级别，再据级别估算风险溢价，适用于缺乏市价与可比对象、但财务数据充分的情形。"},{"point":"选择逻辑由易到难","detail":"优先用市场数据（到期收益率、可比公司），缺市场数据才用模型推算（风险调整、财务比率），估计精度依次递减。"}],"framework":"按'到期收益率→可比公司→风险调整→财务比率'顺序列方法，并各附适用条件。","memo":"易错：风险调整法用'政府债收益率＋信用补偿率'而非直接公司债收益率；四法适用条件层层递进。","tag":""},{"id":"qa-cpach04-03","difficulty":2,"q":"估计普通股资本成本的主要方法有哪些？比较资本资产定价模型(CAPM)与股利增长模型在所需参数上的差异。","answer_points":[{"point":"方法一：CAPM","detail":"rs = rRF + β×(rm - rRF)，用无风险利率、β系数与市场风险溢价估计，适合数据市场充分定价的股票。"},{"point":"方法二：股利增长模型","detail":"rs = D1/P0 + g，用下期股利、当前股价与股利增长率估计，适合股利政策稳定、持续增长的公司。"},{"point":"方法三：债券收益率风险调整模型","detail":"rs = 税后债务成本 + 风险溢价（通常3%~5%），用公司自身债券成本加股权风险溢价简便估算。"},{"point":"参数差异：CAPM不依赖股利","detail":"CAPM只需市场数据（无风险利率、β、市场风险溢价），无需公司分红信息，适用不分红或分红不稳定的公司。"},{"point":"参数差异：股利增长模型需g","detail":"股利增长模型须估计长期股利增长率g（可用历史、可持续增长率或分析师预测），对g高度敏感。"}],"framework":"先列三种方法，再分'CAPM参数'与'股利增长模型参数'对比差异。","memo":"易错：CAPM无需股利增长率g；股利增长模型中D1=D0×(1+g)，用'下期'股利而非本期。","tag":""},{"id":"qa-cpach04-04","difficulty":3,"q":"计算加权平均资本成本(WACC)时，为何债务成本必须用税后成本而优先股成本通常直接用税前值？并分析企业所得税税率变化对WACC的影响方向。","answer_points":[{"point":"债务利息可抵税，故用税后成本","detail":"利息支出在税前扣除，产生税盾，债权人要求的税前报酬中有一部分由税收承担，股东实际负担为税前×(1-税率)。"},{"point":"优先股股息不可抵税，故直接用面值成本","detail":"优先股股息用税后利润分配，无抵税效应，其资本成本（Dp÷[Pp×(1-F)]）即为税后口径，无需再调整。"},{"point":"分类取决于金融工具属性","detail":"若优先股/永续债被认定为金融负债且利息可抵税，则其成本亦需税后化；权益工具属性下则不调，需先判定会计分类。"},{"point":"税率提高降低税后债务成本","detail":"税率上升使(1-税率)下降，税后债务成本 rd×(1-T)降低，在债务权重不变时拉低WACC。"},{"point":"税率变化的净效应受权重结构影响","detail":"税率提高对WACC是负向（降）影响，但若同时推高债务比重或股权成本，需结合资本结构综合判断最终方向。"}],"framework":"先讲'债务税后VS优先股税前'的抵税逻辑，再延伸到'税率↑→税后债务↓→WACC↓'及权重交互。","memo":"易错：优先股成本'不抵税'是通常情形，若被分类为可抵税金融负债则需调整；WACC中债务必用税后成本。","tag":""},{"id":"qa-cpach04-05","difficulty":3,"q":"比较到期收益率法与风险调整法估计税前债务资本成本的原理差异，说明信用风险补偿率的确定步骤，并分析当公司同时有上市债券与可参考政府债收益率时两法结果是否一致。","answer_points":[{"point":"到期收益率法：市场要求的折现率","detail":"解 P0 = Σ利息/(1+rd)^t + 本金/(1+rd)^n 中的rd，直接由本公司债券市价与现金流反推，是最贴近市场的观测值。"},{"point":"风险调整法：无风险利率加信用溢价","detail":"税前债务成本 = 与本公司债到期日相近的政府债到期收益率 + 公司信用风险补偿率，属模型推算而非直接观测。"},{"point":"信用风险补偿率确定步骤","detail":"①选信用级别与本公司相同的上市公司债券；②算其到期收益率；③算同期长期政府债到期收益率；④取两者差额的平均值为补偿率。"},{"point":"两法一致性的前提","detail":"若市场有效且公司信用级别稳定，风险调整法所用的'政府债收益率＋补偿率'应趋近本公司债到期收益率，结果基本一致。"},{"point":"两法差异的来源","detail":"风险调整法依赖可比公司级别与利差平均，存在级别错配、流动性差异与估计误差，故一般为近似；有上市债时优先用到期收益率法。"}],"framework":"先分述两法原理→列补偿率四步→再论'市场有效下趋同、但风险调整法仅为近似'。","memo":"易错：风险调整法政府债须与本公司债'到期日相近'；补偿率取'同级别公司债与政府债收益率差的平均'，非单只。","tag":""}],"calc":[{"id":"c-cpach04-01","difficulty":1,"stem":"某公司税前债务资本成本为8%，企业所得税税率为25%。要求计算其税后债务资本成本。","blanks":[{"label":"税后债务资本成本（%）","answer":6,"tolerance":0.01}],"steps":["第1步（公式）：税后债务资本成本 = 税前债务资本成本 × (1 - 所得税税率)。","第2步（代入）：税后债务资本成本 = 8% × (1 - 25%) = 8% × 75% = 6.00%。"],"formula_card":"税后债务资本成本 = 税前债务资本成本 × (1 - 所得税税率)","analysis":"利息的税盾使股东实际负担降为税前成本的75%，税后债务成本为6%，该值将用于WACC中债务部分的权重成本。","trap":"WACC中债务必须用税后成本；勿直接用8%或误算为8%×25%=2%。","tag":""},{"id":"c-cpach04-02","difficulty":2,"stem":"已知无风险利率为6%，某股票β系数为1.2，市场平均收益率为11%，该公司税后债务资本成本为6%、普通股风险溢价为4%。要求分别用CAPM和债券收益率风险调整模型计算该普通股资本成本。","blanks":[{"label":"普通股资本成本·CAPM（%）","answer":12,"tolerance":0.01},{"label":"普通股资本成本·风险调整模型（%）","answer":10,"tolerance":0.01}],"steps":["第1步（CAPM）：rs = rRF + β×(rm - rRF) = 6% + 1.2×(11% - 6%) = 6% + 6% = 12.00%。","第2步（债券收益率风险调整模型）：rs = 税后债务成本 + 风险溢价 = 6% + 4% = 10.00%。"],"formula_card":"CAPM：rs = rRF + β×(rm - rRF)；债券收益率风险调整模型：rs = 税后债务成本 + 风险溢价","analysis":"两法结果不同：CAPM得12%（含市场β风险溢价），风险调整模型得10%（仅加固定3%~5%股权溢价）。实务常以CAPM为主、风险调整模型为交叉验证。","trap":"CAPM中市场风险溢价用(rm-rRF)=5%而非rm=11%；风险调整模型加的是'税后'债务成本而非税前。","tag":""},{"id":"c-cpach04-03","difficulty":3,"stem":"某公司目标资本结构为长期债务40%、优先股10%、普通股50%；税后债务成本为3.9%，优先股成本为8.16%，普通股成本为11.8%。要求沿'分项加权→WACC'链条计算：债务资本加权成本、优先股资本加权成本、普通股资本加权成本，以及公司加权平均资本成本(WACC)。","blanks":[{"label":"债务资本加权成本（%）","answer":1.56,"tolerance":0.01},{"label":"普通股资本加权成本（%）","answer":5.9,"tolerance":0.01},{"label":"加权平均资本成本WACC（%）","answer":8.276,"tolerance":0.01}],"steps":["第1步（债务加权）：40% × 3.9% = 1.56%。","第2步（优先股加权）：10% × 8.16% = 0.816%。","第3步（普通股加权）：50% × 11.8% = 5.90%。","第4步（WACC）：WACC = 1.56% + 0.816% + 5.90% = 8.276%。"],"formula_card":"WACC = Σ(个别资本成本 × 该资本在目标资本结构中的权重)；债务用税后成本","analysis":"按目标资本结构加权，债务贡献1.56%、优先股贡献0.816%、普通股贡献5.90%，合计WACC为8.276%，是公司价值评估与投资决策的基准折现率。各分项保留四位小数累加以保证精度。","trap":"债务成本务必用税后值3.9%（非税前）；权重用'目标资本结构'而非账面价值；优先股成本不抵税直接计入。","tag":""}]},{"id":"cpa_ch08","group":"财务成本管理","name":"第8章 资本结构","qa":[{"id":"qa-cpach08-01","difficulty":1,"q":"简述经营杠杆、财务杠杆与联合杠杆的含义，并说明三者之间的数量关系。","answer_points":[{"point":"经营杠杆源于固定经营成本的存在","detail":"由于固定经营成本不随销量变动，营业收入（或销量）的小幅变动会引起息税前利润（EBIT）更大比例的变动，这种放大效应即为经营杠杆，它衡量的是企业的经营风险。"},{"point":"财务杠杆源于固定融资成本的存在","detail":"当企业存在债务利息、优先股股利等固定融资成本时，EBIT的变动会引起每股收益（EPS）更大比例的变动，该放大效应衡量企业的财务风险。"},{"point":"联合杠杆是经营杠杆与财务杠杆的叠加","detail":"营业收入变动对每股收益的综合放大效应等于经营杠杆与财务杠杆共同作用的结果，反映企业整体风险。"},{"point":"数量关系：DTL = DOL × DFL","detail":"定义上 DOL=(ΔEBIT/EBIT)/(ΔS/S)，DFL=(ΔEPS/EPS)/(ΔEBIT/EBIT)，二者相乘得 DTL=(ΔEPS/EPS)/(ΔS/S)，即联合杠杆系数为两者乘积。"},{"point":"常用计算公式","detail":"DOL_Q=Q(P-V)/[Q(P-V)-F]，DFL=EBIT/[EBIT-I-PD/(1-T)]，DTL=(EBIT+F)/[EBIT-I-PD/(1-T)]，可通过销量、息税前利润与固定成本直接求得。"},{"point":"杠杆系数的边界条件","detail":"当固定经营成本为0时 DOL=1，当固定融资成本为0时 DFL=1；杠杆系数越大，意味收益波动被放大越多，风险也越高。"}],"framework":"先分别定义经营杠杆、财务杠杆、联合杠杆及其风险含义，再给出三者乘积关系与常用公式，最后说明边界条件。","memo":"DOL看经营风险（固定成本），DFL看财务风险（利息/优先股），DTL=二者乘积；系数为1表示无放大。","tag":""},{"id":"qa-cpach08-02","difficulty":2,"q":"对比资本成本比较法、每股收益无差别点法与企业价值比较法三种资本结构决策方法，各自有何特点与局限？","answer_points":[{"point":"资本成本比较法：选加权平均资本成本最低的方案","detail":"直接计算各方案 WACC 并比较，操作简便，但仅比较资本成本，没有考虑不同方案下财务风险（即风险差异）的不同。"},{"point":"每股收益无差别点法：求 EPS 相等的 EBIT 临界点","detail":"令两种筹资方案 EPS=[(EBIT-I)(1-T)-PD]/N 相等，解出 EBIT 临界值，便于比较特定盈利水平下债务与权益筹资的优劣；但未直接考虑风险因素。"},{"point":"企业价值比较法：同时考虑收益与风险","detail":"先按 S=[(EBIT-I)(1-T)-PD]/r_s 计算股权价值，再 V=S+B+P，以企业价值最大、WACC 最小为标准，理论上最为完善。"},{"point":"三者在风险处理上的差异","detail":"资本成本比较法与企业价值比较法以 WACC 体现风险，EPS 无差别点法侧重盈利比较，实务中要注意其未直接纳入风险权衡。"},{"point":"适用场景不同","detail":"资本成本比较法适合方案粗略筛选；EPS 无差别点法便于在已知预期 EBIT 时判断选债还是选股；企业价值比较法适合需要综合收益与风险的最优结构决策。"},{"point":"实务中常配合运用","detail":"可先用 EPS 无差别点判断盈利临界点，再用企业价值比较法在临界点附近评估风险，得出稳健结论。"}],"framework":"按方法逐条说明原理、优点、局限，再横向比较三者对风险的处理方式与适用场景。","memo":"资本成本比较法/EPS无差别点法忽略风险，企业价值比较法最完善但计算复杂。","tag":""},{"id":"qa-cpach08-03","difficulty":2,"q":"无税 MM 理论与有税 MM 理论关于资本结构与企业价值的核心结论有何不同？有税情形下负债为何能增加企业价值？","answer_points":[{"point":"无税 MM 命题Ⅰ：资本结构不影响企业价值","detail":"无税时 V_L=V_U=EBIT/r_WACC，有负债与无负债企业价值相等，资本结构与企业价值无关。"},{"point":"无税 MM 命题Ⅱ：负债提高权益资本成本但 WACC 不变","detail":"r_sL=r_sU+(r_sU-r_d)(D/E)，随着负债增加权益成本上升，但债务低成本抵消后 WACC 保持恒定。"},{"point":"有税 MM 命题Ⅰ：负债越多企业价值越大","detail":"考虑所得税后 V_L=V_U+D·T，债务利息产生抵税收益，使企业价值随负债增加而上升，全部负债时价值最大。"},{"point":"有税 MM 命题Ⅱ：权益成本上升幅度被（1-T）削弱","detail":"r_sL=r_sU+(r_sU-r_d)(1-T)(D/E)，因利息抵税，权益成本随负债上升的幅度小于无税情形。"},{"point":"机制：利息抵税增加企业价值","detail":"债务利息在税前抵扣，减少了应纳税所得额，形成税盾（PV 为 D·T），这部分抵税现值直接加入企业价值。"},{"point":"理论前提与局限","detail":"MM 理论假设完美市场且未考虑财务困境成本，因此在现实中负债并非越多越好，需由权衡理论进一步修正。"}],"framework":"分别列出无税与有税 MM 的命题Ⅰ和命题Ⅱ公式，解释负债影响价值的机制，最后指出假设局限。","memo":"无税：V与结构无关；有税：V_L=V_U+D·T，税盾使负债提升价值。","tag":""},{"id":"qa-cpach08-04","difficulty":3,"q":"企业应如何在权衡理论、代理理论与优序融资理论的共同框架下，结合内外部因素确定最优资本结构？","answer_points":[{"point":"权衡理论：平衡抵税收益与财务困境成本","detail":"V_L=V_U+PV(利息抵税)-PV(财务困境成本)，当利息抵税边际价值等于财务困境成本边际现值时，企业价值最大，对应最优负债额。"},{"point":"代理理论：在权衡基础上加入代理成本与收益","detail":"V_L=V_U+PV(利息抵税)-PV(财务困境成本)-PV(债务代理成本)+PV(债务代理收益)；债务可抑制经理过度投资（收益），但也会引发资产替代、投资不足等代理成本。"},{"point":"优序融资理论：融资有优先顺序","detail":"因信息不对称与逆向选择，企业优先内源融资，其次债务融资，最后股权融资，这解释了现实中的融资行为而非给出唯一最优比例。"},{"point":"三类理论互补而非互斥","detail":"权衡/代理理论给出'有多少债最优'的静态边界，优序融资理论解释'先融什么'的动态顺序，决策时应综合运用。"},{"point":"内部因素影响负债能力","detail":"收入稳定性高、成长性好、有形资产比重大、盈利能力强的企业可承受更高负债；反之应降低杠杆。"},{"point":"外部因素调节最优结构","detail":"税率高时税盾价值大、利率低时债务成本低、资本市场宽松时更易发债，均会推高适宜负债水平。"},{"point":"实务结论","detail":"最优资本结构没有唯一公式，需以理论框架为指引，结合行业特征、企业目标与外部环境动态调整并定期复核。"}],"framework":"先分别归纳三理论的贡献，再说明其互补关系，最后引入内部（收入、成长性、资产、盈利）与外部（税率、利率、市场）因素综合判定。","memo":"权衡定'最优负债量'，代理补成本收益，优序定'融资顺序'；再叠加内外部因素。","tag":""},{"id":"qa-cpach08-05","difficulty":3,"q":"在筹资方案决策中，如何综合运用杠杆系数、每股收益无差别点与企业价值比较法？各方法在风险考量上有何差异？","answer_points":[{"point":"用杠杆系数度量方案的风险水平","detail":"DOL、DFL、DTL 反映收入到 EPS 的放大程度，负债越高 DFL 越大、财务风险越高，可作为方案风险排序的基础。"},{"point":"用每股收益无差别点确定盈利临界点","detail":"解 EPS 无差别点 EBIT*，当预期 EBIT 高于临界值时债务筹资 EPS 更高，低于临界值时权益筹资更优，为定性判断提供依据。"},{"point":"用企业价值比较法做综合权衡","detail":"计算各方案股权价值 S 与总价值 V、WACC，以 V 最大且 WACC 最小选出理论上最佳结构，弥补前法忽略风险的不足。"},{"point":"风险考量差异一：EPS 无差别点法未直接计风险","detail":"该法只比较盈利水平下的 EPS，未把高风险方案带来的财务困境概率纳入，高杠杆方案在临界点附近可能高估吸引力。"},{"point":"风险考量差异二：资本成本比较法用 WACC 间接体现风险","detail":"WACC 含风险溢价，但仍是单一成本指标，不如企业价值比较法直接同时呈现收益与风险。"},{"point":"风险考量差异三：企业价值比较法最完整","detail":"通过权益资本成本 r_s 反映风险并折现，使高风险方案价值被合理压低，结论最稳健。"},{"point":"综合运用步骤","detail":"先以 EPS 无差别点判断盈利临界点，再用杠杆系数识别风险敞口，最后用企业价值比较法在临界点附近复核，得出兼顾收益与风险的决策。"}],"framework":"以'风险度量→盈利临界点→综合权衡'为主线，逐法说明作用，再集中对比三法在风险处理上的差异，给出综合运用步骤。","memo":"EPS无差别点定'选债还是选股'，杠杆看风险，企业价值比较法做最终风险/收益权衡。","tag":""}],"calc":[{"id":"c-cpach08-01","difficulty":1,"stem":"某公司生产单一产品，单价10元、单位变动成本6元，年固定经营成本20000元，计划年销量10000件；年债务利息10000元，无优先股，所得税率25%。要求计算经营杠杆系数 DOL、财务杠杆系数 DFL 与联合杠杆系数 DTL。","blanks":[{"label":"经营杠杆系数 DOL","answer":2.0,"tolerance":0.01},{"label":"财务杠杆系数 DFL","answer":2.0,"tolerance":0.01},{"label":"联合杠杆系数 DTL","answer":4.0,"tolerance":0.01}],"steps":["第1步：计算边际贡献与 EBIT：Q(P-V)=10000×(10-6)=40000元，EBIT=40000-20000=20000元。","第2步：经营杠杆 DOL=Q(P-V)/[Q(P-V)-F]=40000/20000=2.0。","第3步：财务杠杆 DFL=EBIT/[EBIT-I-PD/(1-T)]=20000/[20000-10000-0]=2.0。","第4步：联合杠杆 DTL=DOL×DFL=2.0×2.0=4.0。"],"formula_card":"DOL=Q(P-V)/[Q(P-V)-F]；DFL=EBIT/[EBIT-I-PD/(1-T)]；DTL=DOL×DFL","analysis":"边际贡献40000元、EBIT20000元，DOL=2.0说明销量变动1%引起EBIT变动2%；DFL=2.0说明EBIT变动1%引起EPS变动2%；DTL=4.0说明销量变动1%引起EPS变动4%。系数均为2表明经营与财务杠杆水平中等，整体风险由联合杠杆4倍放大。","trap":"DFL 分母中优先股股利需除以(1-T)折算为税前；优先股为0时该项直接省略，勿误写PD。","tag":""},{"id":"c-cpach08-02","difficulty":2,"stem":"某公司原有长期债务200万元（利率10%）、普通股40万股。拟追加筹资200万元，方案1为增发普通股20万股（每股10元，利率不变），方案2为发行债券（利率12%，股数不变）。所得税率25%。求两方案的每股收益无差别点 EBIT* 及该点下的每股收益 EPS*。","blanks":[{"label":"每股收益无差别点 EBIT*（万元）","answer":92.0,"tolerance":0.1},{"label":"无差别点下每股收益 EPS*（元/股）","answer":0.9,"tolerance":0.01}],"steps":["第1步：列两方案参数。方案1：I1=200×10%=20万元，N1=40+20=60万股；方案2：I2=20+200×12%=44万元，N2=40万股。","第2步：令 EPS 相等：[(EBIT-20)×(1-25%)]/60 = [(EBIT-44)×(1-25%)]/40，约去0.75得 (EBIT-20)/60=(EBIT-44)/40。","第3步：解方程：40(EBIT-20)=60(EBIT-44) → 40EBIT-800=60EBIT-2640 → 20EBIT=1840 → EBIT*=92万元。","第4步：代入求 EPS*=(92-20)×0.75/60=54/60=0.9元/股（方案2验证：(92-44)×0.75/40=0.9，一致）。"],"formula_card":"EPS=[(EBIT-I)(1-T)-PD]/N；令两方案 EPS 相等求解 EBIT*","analysis":"EBIT*为92万元：当预期EBIT>92万元时方案2（债务）EPS更高，应选债务筹资；当预期EBIT<92万元时方案1（股权）更优。该点下两方案EPS均为0.9元/股。","trap":"EPS无差别点只比较盈利、未考虑风险；临界点附近若选高杠杆方案，需评估盈利不及预期时的财务风险。","tag":""},{"id":"c-cpach08-03","difficulty":3,"stem":"某公司年EBIT为500万元，所得税率25%。现考虑两个资本结构方案：方案A发行债券1000万元（利率8%）、普通股100万股、权益资本成本12%；方案B发行债券1500万元（利率10%）、普通股100万股、权益资本成本14%。分别用企业价值比较法计算两方案的公司总价值V与加权平均资本成本WACC（金额单位：万元），并判断哪方案更优。","blanks":[{"label":"方案A公司总价值 V_A（万元）","answer":3625.0,"tolerance":0.1},{"label":"方案A加权平均资本成本 WACC_A（%）","answer":10.34,"tolerance":0.01},{"label":"方案B加权平均资本成本 WACC_B（%）","answer":11.11,"tolerance":0.01}],"steps":["第1步：方案A。利息I_A=1000×8%=80万元；税后利润=(500-80)×(1-25%)=315万元；股权价值S_A=315/12%=2625万元；总价值V_A=2625+1000=3625万元。","第2步：方案A的WACC_A=8%×(1-25%)×(1000/3625)+12%×(2625/3625)=6%×0.27586+12%×0.72414=10.34%。","第3步：方案B。利息I_B=1500×10%=150万元；税后利润=(500-150)×0.75=262.5万元；股权价值S_B=262.5/14%=1875万元；总价值V_B=1875+1500=3375万元。","第4步：方案B的WACC_B=10%×0.75×(1500/3375)+14%×(1875/3375)=7.5%×0.44444+14%×0.55556=11.11%。","第5步：比较：V_A(3625)>V_B(3375)、WACC_A(10.34%)<WACC_B(11.11%)，故方案A更优。"],"formula_card":"S=[(EBIT-I)(1-T)]/r_s；V=S+B；r_WACC=r_d(1-T)(B/V)+r_s(S/V)","analysis":"方案A总价值3625万元、WACC10.34%；方案B总价值3375万元、WACC11.11%。方案B虽负债更多但权益资本成本升至14%、利息抵税收益不足以弥补风险溢价，导致价值下降、WACC上升，因此方案A为更优资本结构。","trap":"WACC计算必须用税后债务成本r_d(1-T)，并分别以B/V、S/V为权重；权益资本成本r_s随负债上升而提高，不可沿用原值。","tag":""}]},{"id":"cpa_ch09","group":"财务成本管理","name":"第9章 长期筹资","qa":[{"id":"qa-cpach09-01","difficulty":1,"q":"简述普通股筹资的主要优点与缺点。","answer_points":[{"point":"优点：没有固定利息负担","detail":"股利由公司盈利与分配政策决定，盈利不佳时可少分或不分，不像债务必须按期付息，财务弹性好。"},{"point":"优点：没有固定到期日","detail":"普通股属永久资本，无需偿还本金，企业可长期使用，不会形成到期偿债压力。"},{"point":"优点：财务风险小","detail":"因无固定还本付息义务，普通股筹资不会像债务那样在经营低谷时引发违约或破产风险。"},{"point":"优点：能增加公司信誉","detail":"权益资本是债务资本的保障基础，权益比重高有利于提升信用评级、增强后续债务融资能力。"},{"point":"缺点：资本成本较高","detail":"投资者承担较高风险故要求报酬率高，且股利从税后利润支付无抵税作用，综合使普通股成本高于债务。"},{"point":"缺点：可能分散控制权","detail":"增发新股会引入新股东、稀释原股东表决权，可能影响原有控制结构。"},{"point":"缺点：信息披露成本高","detail":"公开发行须履行严格的信息披露与审计要求，增加合规与上市维护成本，并可能暴露商业信息。"}],"framework":"按'优点—缺点'两大块逐项展开，优点突出无固定负担/低风险/增信誉，缺点突出高成本/稀释控制权/披露成本。","memo":"普通股：成本低？错！是资本成本最高；优点是没固定负担、没到期日、风险小。","tag":""},{"id":"qa-cpach09-02","difficulty":2,"q":"对比配股、公开增发与非公开增发（定向增发）三种股权再融资方式在发行对象、定价与限制上的差异。","answer_points":[{"point":"配股：向原股东按比例低价配售","detail":"按持股比例以低于市价的价格向原股东配售，拟配售数量不超过配售前股本总额的50%，且须代销，认购未达70%则发行失败。"},{"point":"公开增发：向不特定对象发行","detail":"面向公众，主板要求最近3年盈利且加权平均ROE平均不低于6%，发行价不低于招股意向书前20个交易日或前1个交易日均价。"},{"point":"非公开增发：向特定对象发行","detail":"对象不超过35名，发行价不低于定价基准日前20个交易日均价的80%，可用股权、债权等非现金资产认购，股票限售6个月（战略投资者18个月）。"},{"point":"发行对象差异","detail":"配股仅限原股东、公开增发面向不特定公众、非公开增发面向少量特定投资者，覆盖范围依次收窄。"},{"point":"定价机制差异","detail":"配股为折价配售、公开增发挂钩市价均价、非公开增发为均价八折为底，三者折扣与约束各不相同。"},{"point":"适用情境差异","detail":"配股适合维护原股东优先认购权，公开增发适合大规模公开募资，非公开增发适合引入战略投资者或资产注入。"}],"framework":"以发行对象、定价、数量/资格限制为维度，对三种方式逐一对比，最后归纳适用情境。","memo":"配股≤50%且70%失败线；公开增发ROE≥6%；非公开增发对象≤35名、价≥八折、限售6/18月。","tag":""},{"id":"qa-cpach09-03","difficulty":2,"q":"说明可转换债券的主要条款及其各自保护的对象。","answer_points":[{"point":"转换价格与转换比率","detail":"转换价格通常比发行时股价高20%~30%，转换比率=债券面值/转换价格，决定每张债券可换股数，影响稀释程度。"},{"point":"转换期","detail":"约定持有人可行使转换权的期间，通常短于债券期限，界定转换的时间窗口。"},{"point":"赎回条款：保护发行人","detail":"发行人可在股价持续高于转价时提前赎回，促使持有人转股或避免市场利率下降后仍付高息，维护发行人利益。"},{"point":"回售条款：保护投资者","detail":"当股价持续低于转价时持有人可按约定价格回售给发行人，为投资者提供下行保护。"},{"point":"强制性转换条款","detail":"保证到期或条件满足时债券转换为股票，避免到期兑付现金，锁定股本化结果。"},{"point":"底线价值约束","detail":"可转债价值不低于 max(纯债券价值, 转换价值)，赎回与回售条款共同影响持有人决策与发行人的现金流安排。"}],"framework":"按条款列示定义，并逐条标注其保护主体（发行人/投资者），最后点明底线价值概念。","memo":"赎回保发行人、回售保投资者、强制转换锁股本；转价通常高股价20%~30%。","tag":""},{"id":"qa-cpach09-04","difficulty":3,"q":"综合比较优先股、永续债、附认股权证债券与可转换债券四类混合筹资工具在资本属性、税务、股权稀释与灵活性上的差异，并说明各自适用情境。","answer_points":[{"point":"优先股：固定股息、通常无表决权","detail":"股利一般不可税前抵扣（投资者可能免税），不稀释普通股控制权；不支付优先股股利不直接导致破产，适合希望补充权益又不让渡控制权的企业。"},{"point":"永续债：无到期日、兼具债股属性","detail":"利息可能税前抵扣也可能按股息处理，取决于是否满足债务属性条件；无到期日降低再融资压力，适合优化资本结构且不愿稀释股权的企业。"},{"point":"附认股权证债券：一次发行二次筹资","detail":"以潜在股权稀释换取较低票面利率，行权时发行新股会稀释EPS；灵活性不如可转债，主要适合高增长、高风险的小公司。"},{"point":"可转换债券：转换时不增加新资本","detail":"转换时以债换股、不新募现金，含赎回/回售/强制转换条款，灵活性较强；适合希望低成本筹资并预留转股空间的企业。"},{"point":"资本属性与税务对比","detail":"优先股偏权益、永续债视条件定属性、认股权证债+期权、可转债债+转股权；税务上优先股股利多税后、永续债利息可能税前。"},{"point":"股权稀释对比","detail":"优先股与永续债基本不稀释，认股权证行权稀释、可转债转换稀释，但可转债转换属存量转换而非新增募资。"},{"point":"适用情境总结","detail":"保控制权选优先股/永续债，降利率并引资选认股权证，低成本且留转股弹性选可转债；需结合资本结构与控制权目标综合选择。"}],"framework":"先逐类说明属性/税务/稀释/灵活性，再以对比维度（资本属性、税务、稀释、灵活性）横向归纳，最后给出适用情境。","memo":"优先股/永续债不稀释且偏权益；认股权证、可转债会稀释但换低利率；可转债转换不新增资本。","tag":""},{"id":"qa-cpach09-05","difficulty":3,"q":"租赁决策分析应如何运用租赁净现值？其折现率如何确定？并说明租赁存在的主要原因。","answer_points":[{"point":"租赁净现值原理","detail":"租赁净现值=租赁方案现金流量总现值-借款购买方案现金流量总现值；若净现值>0，租赁相对借款购买更划算，应选租赁。"},{"point":"折现率选择：税后担保借款利率","detail":"因租赁与借款购买现金流的风险特征类似有担保债务，故采用税后担保借款利率折现，而非WACC或无风险利率。"},{"point":"新租赁准则的会计处理","detail":"除短期租赁与低价值资产租赁外，承租人应确认使用权资产和租赁负债，统一在表内反映租赁义务。"},{"point":"原因一：节税","detail":"租赁付款的利息部分与折旧安排可产生税收利益，尤其在许可能加速扣除时更具吸引力。"},{"point":"原因二：降低交易成本","detail":"出租人专业化采购与资产管理可降低承租人获取与使用资产的交易与谈判成本。"},{"point":"原因三：减少不确定性","detail":"租赁将资产余值风险转移给出租人，承租人规避了残值波动与处置的不确定性。"},{"point":"实务注意","detail":"决策须保证两方案现金流口径一致（含税盾、维护费等），并正确取折现率，否则会误判租赁优劣。"}],"framework":"先讲租赁净现值公式与判断规则，再定折现率，接着阐述新准则处理，最后从节税/交易成本/不确定性三方面说明租赁动因。","memo":"租赁NPV>0选租赁；折现率用税后担保借款利率；存在原因=节税+降交易成本+减不确定性。","tag":""}],"calc":[{"id":"c-cpach09-01","difficulty":1,"stem":"某可转换债券面值1000元，转换价格50元，当前普通股股价60元。要求计算转换比率与转换价值。","blanks":[{"label":"转换比率（股/张）","answer":20.0,"tolerance":0.01},{"label":"转换价值（元）","answer":1200.0,"tolerance":0.1}],"steps":["第1步：转换比率=债券面值/转换价格=1000/50=20股。","第2步：转换价值=当前股价×转换比率=60×20=1200元。"],"formula_card":"转换比率=债券面值/转换价格；转换价值=股价×转换比率","analysis":"转换比率20股/张，按当前股价60元计算转换价值1200元，高于面值1000元，说明当前处于价内（转换有利），但持有人是否转股还受赎回条款与股价走势影响。","trap":"转换价值用'当前股价'而非转换价格；转换比率=面值/转价，勿颠倒为转价/面值。","tag":""},{"id":"c-cpach09-02","difficulty":2,"stem":"某上市公司配股前每股价格20元，拟按每10股配5股的比例配售，配股价格14元。要求计算配股除权参考价与每股配股权价值。","blanks":[{"label":"配股除权参考价（元）","answer":18.0,"tolerance":0.01},{"label":"每股配股权价值（元）","answer":2.0,"tolerance":0.01}],"steps":["第1步：股份变动比例=5/10=0.5；配股除权参考价=(配股前价+配股价×变动比例)/(1+变动比例)=(20+14×0.5)/1.5=27/1.5=18元。","第2步：购买1股新配股所需原股数=10/5=2股；每股配股权价值=(除权参考价-配股价)/所需原股数=(18-14)/2=2元。"],"formula_card":"除权参考价=(P0+P×k)/(1+k)；配股权价值=(除权价-P)/购买1股新股所需原股数","analysis":"除权参考价18元低于配股前价20元，反映配股摊薄效应；每股配股权价值2元，原股东若放弃配股其持股价值将受损，故理性股东应参与配股。","trap":"配股权价值分母是'买1股新股所需原股数'(10/5=2)，不是变动比例0.5；除权价公式分子勿漏配股价×k项。","tag":""},{"id":"c-cpach09-03","difficulty":3,"stem":"某可转换债券面值1000元、票面利率5%、期限5年、每年末付息，转换价格25元，当前股价30元，等风险普通债券市场利率8%。要求计算转换价值、纯债券价值与底线价值（金额单位：元）。","blanks":[{"label":"转换价值（元）","answer":1200.0,"tolerance":0.1},{"label":"纯债券价值（元）","answer":880.22,"tolerance":0.1},{"label":"底线价值（元）","answer":1200.0,"tolerance":0.1}],"steps":["第1步：转换比率=1000/25=40股；转换价值=30×40=1200元。","第2步：年利息=1000×5%=50元；纯债券价值=Σ50/(1.08)^t + 1000/(1.08)^5（t=1~5）。","第3步：折现计算：50/1.08=46.30，50/1.1664=42.87，50/1.259712=39.69，50/1.360489=36.75，50/1.469328=34.03，面值现值=1000/1.469328=680.58；合计=880.22元。","第4步：底线价值=max(纯债券价值, 转换价值)=max(880.22, 1200)=1200元。"],"formula_card":"纯债券价值=Σ年利息/(1+i)^t+面值/(1+i)^n；底线价值=max(纯债券价值, 转换价值)","analysis":"转换价值1200元高于纯债券价值880.22元，底线价值取较高的1200元，说明当前可转债价值由转换期权主导；若股价下跌使转换价值低于纯债价值，则底线由纯债价值托底。","trap":"纯债券价值用'等风险市场利率'而非票面利率折现；底线价值取两者较大者，不是相加。","tag":""}]},{"id":"cpa_ch10","group":"财务成本管理","name":"第10章 股利分配、股票分割与股票回购","qa":[{"id":"qa-cpach10-01","difficulty":1,"q":"简述股利无关论（MM 股利无关论）的假设条件与核心结论。","answer_points":[{"point":"假设一：投资政策已确定且被投资者理解","detail":"公司投资决策独立于股利政策并对外充分披露，投资者能正确评估公司价值，股利变动不改变投资机会集合。"},{"point":"假设二：不存在股票发行与交易费用","detail":"无筹资摩擦，公司可无成本地通过发行新股或留存收益满足资金需要，股利与筹资可自由替代。"},{"point":"假设三：不存在个人或公司所得税","detail":"现金股利与资本利得税负相同，投资者对股利与留存再投资的偏好无税收差异。"},{"point":"假设四：不存在信息不对称","detail":"经理与外部投资者掌握相同信息，股利政策不传递额外信号，不会引发市场误判。"},{"point":"假设五：无经理与外部投资者的代理成本","detail":"经理与股东利益一致，不会通过股利政策侵占或保护股东利益。"},{"point":"核心结论：股利政策不影响公司价值","detail":"在完美市场假设下，公司价值完全由投资决策决定，与股利支付率高低无关，即'股利无关'。"}],"framework":"先列出五项完美市场假设，再给出核心结论，强调结论依赖于假设、现实需由股利相关论修正。","memo":"MM无关论五假设：投资确定、无发行费、无所得税、无信息不对称、无代理成本→股利无关价值。","tag":""},{"id":"qa-cpach10-02","difficulty":2,"q":"比较剩余股利政策、固定股利政策、固定股利支付率政策与低正常股利加额外股利政策的特点及适用企业。","answer_points":[{"point":"剩余股利政策：先满足投资所需权益资本","detail":"按目标资本结构先用留存收益满足投资，剩余才分配股利；适合成长型企业，但股利波动大。"},{"point":"固定股利政策：每年支付固定现金股利","detail":"股利不随盈余波动，向市场传递稳定信号；但盈余低时仍须支付，可能引致资金短缺，适合盈利稳定企业。"},{"point":"固定股利支付率政策：股利随盈余比例变动","detail":"按固定支付率分配，体现多盈多分、少盈少分；但各年股利上下波动，可能传递经营不稳信号。"},{"point":"低正常股利加额外股利政策：稳定基础+灵活追加","detail":"固定较低基础股利，盈余多时加付额外股利；兼顾稳定性与灵活性，最适合盈余波动较大的成长期企业。"},{"point":"适用企业差异","detail":"剩余/低正常加额外适合成长期，固定股利适合成熟稳定企业，固定支付率较少单独采用。"},{"point":"风险与信号含义","detail":"固定类政策稳定但可能与盈余脱节，支付率类政策真实但波动；选择须权衡信号效应与资金压力。"}],"framework":"逐一说明四种政策的分配规则、优点、缺点与适用企业，最后归纳风险/信号权衡。","memo":"剩余（成长）、固定（稳定成熟）、固定支付率（波动）、低正常+额外（成长期波动）。","tag":""},{"id":"qa-cpach10-03","difficulty":2,"q":"股票分割与股票股利有何相同点与不同点？二者对每股收益、每股市价与股东财富分别产生什么影响？","answer_points":[{"point":"相同点：均增加流通股数","detail":"二者都使发行在外股数增加，每股收益与每股市价同比例下降，公司价值与股东权益总额不变，股东持股比例不变。"},{"point":"相同点：目的均在于降低股价","detail":"通过增加股数使每股市价下降到更受欢迎的区间，提升股票流动性，效果近似。"},{"point":"不同点：会计处理不同","detail":"股票分割仅降低股票面额、不改变权益各科目余额；股票股利则将留存收益转为股本/资本公积，改变权益内部结构。"},{"point":"不同点：法律属性不同","detail":"股票分割不属于股利分配、不减少留存收益；股票股利是利润分配的一种形式，受利润分配程序约束。"},{"point":"对EPS与市价的影响","detail":"二者都使EPS与每股市价同比例下降，股东持股市值（股数×股价）合计不变，股东财富不受影响。"},{"point":"反分割（股票合并）","detail":"股价过低时可采用反分割减少股数、提高市价，与股票分割方向相反，用于处理低价股问题。"}],"framework":"先列相同点（股数、EPS、市价、价值、持股比），再列不同点（会计、法律属性），最后总结影响与反分割。","memo":"二者都降EPS/市价、不公司价值；差异在股票分割改面额、股票股利转留存收益。","tag":""},{"id":"qa-cpach10-04","difficulty":3,"q":"股利相关论包含税差、客户效应、一鸟在手与代理理论四个分支，它们分别如何说明股利政策对公司价值的影响？企业据此制定政策时应注意什么？","answer_points":[{"point":"税差理论：偏好低股利支付率","detail":"资本利得税延至出售时缴纳、享有时间价值，而现金股利税即时缴纳，故投资者偏好低股利以提高税后财富，高股利反而降低价值。"},{"point":"客户效应理论：按边际税率分层","detail":"高税率投资者偏好低股利股票、低税率投资者偏好高股利股票；公司不应忽视股东需求，应保持与股东税率结构匹配的政策。"},{"point":"一鸟在手理论：偏好高股利支付率","detail":"认为现金股利比未来资本利得更确定可靠，投资者对股利要求更低贴现率，高股利提升当前公司价值。"},{"point":"代理理论：高股利降低代理成本","detail":"提高股利减少经理可自由支配的现金流，抑制过度投资与在职消费，降低股东—经理代理冲突，从而提升价值。"},{"point":"综合：理论指向并不一致","detail":"税差/客户效应偏低的、一鸟在手偏高的、代理偏高的，说明不存在唯一最优支付率，须结合企业与股东特征权衡。"},{"point":"制定政策注意一：股东结构","detail":"依据主要股东的边际税率与偏好（客户效应）选择支付率，避免错配导致估值折价。"},{"point":"制定政策注意二：投资机会与信号","detail":"高成长企业应保留更多收益（低股利），成熟企业可用高股利传递稳定信号并降低代理成本。"}],"framework":"逐一解释四分支的偏好方向与理由，指出其冲突，再给出制定政策时关于股东结构、投资机会与信号的综合考量。","memo":"税差/客户效应→低股利；一鸟在手/代理→高股利；实务按股东税率与投资机会权衡。","tag":""},{"id":"qa-cpach10-05","difficulty":3,"q":"股票回购的动机与主要方式有哪些？其与现金股利在财务影响上有何异同？并说明我国法定的回购情形与限制。","answer_points":[{"point":"动机：替代现金股利分配剩余现金","detail":"回购向股东返还现金，是现金股利的替代方式，且可避免持续高股利承诺带来的刚性。"},{"point":"动机：传递股价低估信号与调整资本结构","detail":"回购常被视为管理层认为股价被低估的信号，举债回购还能提高财务杠杆、发挥税盾作用。"},{"point":"动机：防御敌意收购","detail":"回购减少流通在外股份、提高持股比例集中度，可作为反收购手段保护公司控制。"},{"point":"方式：按地点/对象/筹资分类","detail":"按地点分场内公开收购与场外协议收购；按对象分随机、招标、协商回购；按筹资分举债、现金、混合回购。"},{"point":"与现金股利的等效性与税务差异","detail":"对剩余股东每股价值等效，但回购股东缴资本利得税、现金股利股东缴股利收益税，税负时点不同。"},{"point":"法定四种情形","detail":"减少注册资本、与持有本公司股份的其他公司合并、将股份奖励给职工、股东对合并分立决议持异议要求收购。"},{"point":"限制：不得长期持库存股","detail":"我国不允许西方实务中的库存股，回购股份须在规定期限注销或转让：减资情形10日内注销，合并/异议情形6个月内转让或注销，奖励职工情形的股份1年内转让给职工且不得超过已发行股份5%。"}],"framework":"先述动机与方式，再对比现金股利（等效+税务），最后列法定情形与库存股限制。","memo":"回购动机=替代股利/信号/调结构/反收购；法定四情形；我国禁库存股，职工回购≤5%且1年内转。","tag":""}],"calc":[{"id":"c-cpach10-01","difficulty":1,"stem":"某上市公司股权登记日收盘价20元，每股派发现金股利0.5元，同时每10股送红股3股（送股率0.3），资本公积每10股转增2股（转增率0.2）。要求计算除权（息）参考价。","blanks":[{"label":"除权（息）参考价（元）","answer":13.0,"tolerance":0.01}],"steps":["第1步：识别参数：登记日收盘价P0=20元，每股现金股利D=0.5元，送股率s=0.3，转增率z=0.2。","第2步：除权参考价=(P0-D)/(1+s+z)=(20-0.5)/(1+0.3+0.2)=19.5/1.5=13元。"],"formula_card":"除权参考价=(股权登记日收盘价-每股现金股利)/(1+送股率+转增率)","analysis":"同时实施现金分红、送股与转增后，除权参考价由20元降至13元，反映股本扩张与现金派发的综合摊薄；持股数量同比例增加，股东总财富在除权日前后理论不变。","trap":"分母包含所有股本扩张比率(送股率+转增率)，分子须减现金股利；仅送股勿遗漏转增率。","tag":""},{"id":"c-cpach10-02","difficulty":2,"stem":"某公司回购前共1000万股，每股市价20元（总价值20000万元）。公司拟以每股25元回购200万股（支付现金5000万元）。要求计算回购股数与回购后每股价值。","blanks":[{"label":"回购股数（万股）","answer":200.0,"tolerance":0.1},{"label":"回购后每股价值（元）","answer":18.75,"tolerance":0.01}],"steps":["第1步：回购股数=回购支付现金/每股回购价格=5000/25=200万股。","第2步：回购后总价值=回购前总价值-回购支付现金=20000-5000=15000万元。","第3步：回购后股数=1000-200=800万股；回购后每股价值=15000/800=18.75元。"],"formula_card":"回购股数=回购现金/回购价；回购后每股价值=(回购前总价值-回购现金)/(回购前股数-回购股数)","analysis":"回购200万股后剩余800万股，每股价值18.75元。由于回购价25元高于市价20元（支付溢价），回购后每股价值低于原市价，但剩余股东获得了现金、整体财富不变；若以市价回购则每股价值保持20元。","trap":"回购后每股价值=剩余价值/剩余股数，分子必须扣除已支付现金；溢价回购会压低每股价值。","tag":""},{"id":"c-cpach10-03","difficulty":3,"stem":"某公司目标资本结构为权益资本占60%、债务占40%。明年拟投资一项目需资金1000万元，当年净利润800万元，普通股股数400万股。采用剩余股利政策，要求计算投资所需权益资本、可分配股利总额与股利支付率。","blanks":[{"label":"投资所需权益资本（万元）","answer":600.0,"tolerance":0.1},{"label":"可分配股利总额（万元）","answer":200.0,"tolerance":0.1},{"label":"股利支付率（%）","answer":25.0,"tolerance":0.01}],"steps":["第1步：投资所需权益资本=项目资金×权益比例=1000×60%=600万元。","第2步：可分配股利总额=净利润-所需权益资本=800-600=200万元（剩余部分分配）。","第3步：每股收益EPS=净利润/股数=800/400=2元/股；每股股利DPS=200/400=0.5元/股。","第4步：股利支付率=DPS/EPS=0.5/2=25%（或200/800=25%）。","第5步：债务筹资额=1000×40%=400万元，与权益600万元合计满足投资。"],"formula_card":"权益资本需求=投资额×权益比；股利总额=净利润-权益需求；支付率=每股股利/每股收益","analysis":"按剩余股利政策，先留600万元满足投资权益部分，仅将剩余200万元分配，股利支付率25%。该政策使留存收益优先支撑增长，但股利额随投资机会波动；债务筹资400万元保持目标资本结构。","trap":"剩余股利政策先扣'权益资本需求'再分配，不是按固定比例分；支付率=每股股利/每股收益，分母用净利润算出的EPS而非分配后值。","tag":""}]},{"id":"cpa_ch11","group":"财务成本管理","name":"第11章 营运资本管理","qa":[{"id":"qa-cpach11-01","difficulty":1,"q":"简述营运资本的含义，并说明营运资本管理的两大方面及其核心目标。","answer_points":[{"point":"营运资本=流动资产-流动负债","detail":"它是投入日常经营活动的资本，差额反映企业短期偿债能力与日常经营运转能力，是流动性管理的核心指标。"},{"point":"管理一：流动资产投资管理","detail":"确定流动资产的最优投资规模，在持有成本与短缺成本之间权衡，使相关总成本最低。"},{"point":"管理二：流动负债融资管理","detail":"确定短期资金来源的结构，按期限匹配原则以长期资金支持长期资产，控制偿债风险。"},{"point":"核心是应对不确定性","detail":"营运资本管理需应对投资需求的不确定性，在风险与收益、流动性与盈利性之间取得平衡。"},{"point":"围绕六大模块展开","detail":"包括投资策略、融资策略、现金管理、应收账款管理、存货管理和短期债务管理。"}],"framework":"定义营运资本→管理两大方面→核心目标→六大模块","memo":"营运资本=流动资产-流动负债，不是长期资产相关概念","tag":""},{"id":"qa-cpach11-02","difficulty":2,"q":"对比适中型、保守型与激进型营运资本投资策略在流动资产持有量、成本与风险上的差异。","answer_points":[{"point":"适中型：短缺成本与持有成本大体相等","detail":"达到相关总成本最低的最优投资规模，流动资产持有量适中，是理论上的均衡策略。"},{"point":"保守型：保持较多流动资产、宽松信用","detail":"承担较大的持有成本，但短缺成本低、违约与断供风险小，盈利能力相对较低。"},{"point":"激进型：尽可能少的投资于流动资产","detail":"持有成本低、盈利能力高，但承担较大的短缺风险，一旦需求波动易出现流动性困难。"},{"point":"三者的本质权衡是风险与收益","detail":"流动资产比例越高越安全但收益越低，比例越低收益越高但风险越大，应结合经营环境选择。"},{"point":"体现流动性与盈利性的替代关系","detail":"投资策略实质是流动资产比例的决策，比例直接影响企业短期偿债能力与长期收益水平。"}],"framework":"定义三策略→各自成本/风险特征→风险收益权衡","memo":"保守=多流动=低风险低收益；激进反之；适中=成本相等","tag":""},{"id":"qa-cpach11-03","difficulty":2,"q":"说明信用政策的主要内容，并解释评估客户信用品质的5C系统。","answer_points":[{"point":"信用期间","detail":"允许客户从购货到付款的时间长度，延长可促进销售但增加资金占用、收账费用与坏账风险。"},{"point":"信用标准","detail":"客户获得商业信用应具备的最低条件，常用5C系统对客户信用品质进行评估与筛选。"},{"point":"现金折扣政策","detail":"为鼓励客户提早付款而提供的价格优惠，需权衡折扣成本与早收资金所带来的收益。"},{"point":"5C=品质、能力、资本、抵押、条件","detail":"品质(character)是首要因素，反映偿债意愿；能力看偿付能力；资本指财力；抵押为担保物；条件指外部环境。"},{"point":"信用政策决策比较边际收益与边际成本","detail":"改变信用政策需比较延长信用带来的边际收益与应计利息、收账费用、坏账损失及折扣成本的增加额。"}],"framework":"信用政策三内容→5C逐项解释→决策比较原则","memo":"5C中品质首要；信用政策=信用期间+信用标准+现金折扣","tag":""},{"id":"qa-cpach11-04","difficulty":3,"q":"综合说明确定最佳现金持有量的成本分析模式与随机模式的原理、公式及各自适用情形。","answer_points":[{"point":"成本分析模式基于机会成本与交易成本最低化","detail":"公式C*=√(2TF/K)，T为一定时期现金总需求量，F为每次交易成本，K为持有现金机会成本率，适用于现金流出稳定。"},{"point":"随机模式设置上下限动态控制","detail":"回归点R=∛(3bσ²/4i)+L，上限H=3R-2L，其中b为转换成本、i为日利率、σ为日现金余额波动标准差。"},{"point":"成本分析模式假设现金流出稳定","detail":"仅考虑机会成本与交易成本，管理成本固定不变，短缺成本在该模式下假定为零。"},{"point":"随机模式适用于现金需求难以预知","detail":"当现金需求量难以预测时，设下限L与上限H，余额触及上下限即买卖证券使现金回到回归点R。"},{"point":"两模式解决同一问题但前提不同","detail":"前者确定静态最优持有量，后者在波动区间内动态控制，实务中按现金可预测性选择方法。"},{"point":"回归点R是上下限的函数","detail":"上限H=3R-2L，现金达上限时买入证券、达下限时卖出证券，使余额维持在R附近。"}],"framework":"两模式公式→适用前提→控制机制→对比","memo":"成本分析C*=√(2TF/K)；随机R=∛(3bσ²/4i)+L","tag":""},{"id":"qa-cpach11-05","difficulty":3,"q":"综合说明存货经济订货量(EOQ)基本模型及其扩展：陆续供应、保险储备与再订货点。","answer_points":[{"point":"基本模型Q*=√(2KD/Kc)","detail":"K为每次订货变动成本，D为年需求量，Kc为单位储存变动成本，使年储存与订货总成本最低。"},{"point":"派生量：最佳订货次数与周期","detail":"N*=D/Q*为年订货次数，t*=1/N*为最佳订货周期，二者由Q*导出以安排采购频率。"},{"point":"经济订货量占用资金I*=(Q*/2)×U","detail":"以平均存货乘单价U得到资金占用额，便于企业安排周转资金。"},{"point":"保险储备防止交货期需求波动缺货","detail":"总成本TC(S,B)=Ku×S×N+B×Kc，权衡单位缺货成本Ku与储备持有成本Kc，选总成本最低的B。"},{"point":"再订货点R=L×d+B","detail":"平均交货时间L乘平均日需求d，再加保险储备B，使补货能在耗尽前及时到达。"},{"point":"陆续供应模型调整平均库存","detail":"边耗用边到货时，每日净入库为到货减耗用，需修正EOQ公式中的储存成本计算。"}],"framework":"基本模型→派生量→保险储备→再订货点→陆续供应","memo":"EOQ=√(2KD/Kc)；再订货点R=L×d+B","tag":""}],"calc":[{"id":"c-cpach11-01","difficulty":1,"stem":"某企业甲种材料年需要量D=1600件，每次订货变动成本K=25元，单位储存变动成本Kc=2元/件·年。要求计算该材料的经济订货量Q*。","blanks":[{"label":"经济订货量Q*（件）","answer":200,"tolerance":0.01}],"steps":["第1步：公式 经济订货量Q*=√(2KD/Kc)","第2步：代入 Q*=√(2×25×1600/2)=√40000","第3步：结果 Q*=200件"],"formula_card":"Q*=√(2KD/Kc)","analysis":"年需求1600件，每次订货变动成本25元，单位年储存变动成本2元，代入公式得经济订货量200件，此时年储存成本与年订货成本之和最低。","trap":"Kc是单位储存变动成本而非总金额；根号内系数2不可漏。","tag":""},{"id":"c-cpach11-02","difficulty":2,"stem":"某企业乙材料年需要量D=1800件，每次订货变动成本K=50元，单位储存变动成本Kc=2元/件·年，单价U=5元/件。要求计算经济订货量Q*，并计算经济订货量占用资金I*。","blanks":[{"label":"经济订货量Q*（件）","answer":300,"tolerance":0.01},{"label":"经济订货量占用资金I*（元）","answer":750,"tolerance":0.1}],"steps":["第1步：计算经济订货量 Q*=√(2×50×1800/2)=√90000=300件","第2步：计算平均存货 平均存货=Q*/2=300/2=150件","第3步：计算占用资金 I*=150×5=750元"],"formula_card":"Q*=√(2KD/Kc)；I*=(Q*/2)×U","analysis":"由基本模型得Q*=300件，平均存货150件，乘以单价5元得到占用资金750元，可据此安排存货周转资金。","trap":"占用资金用平均存货Q*/2而非Q*；单价U不要漏乘。","tag":""},{"id":"c-cpach11-03","difficulty":3,"stem":"某企业丙材料年需要量D=3600件（按360天计，平均日需求d=10件），每次订货变动成本K=4元，单位储存变动成本Kc=2元/件·年，平均交货时间L=5天，保险储备B=20件。要求计算：经济订货量Q*、最佳订货次数N*、再订货点R。","blanks":[{"label":"经济订货量Q*（件）","answer":120,"tolerance":0.01},{"label":"最佳订货次数N*（次）","answer":30,"tolerance":0.01},{"label":"再订货点R（件）","answer":70,"tolerance":0.01}],"steps":["第1步：计算经济订货量 Q*=√(2×4×3600/2)=√14400=120件","第2步：计算最佳订货次数 N*=D/Q*=3600/120=30次","第3步：计算再订货点 R=L×d+B=5×10+20=70件"],"formula_card":"Q*=√(2KD/Kc)；N*=D/Q*；R=L×d+B","analysis":"年需求3600件、每次订货成本4元、年储存成本2元得Q*=120件；年订货30次；交货期5天、日需求10件、保险储备20件，再订货点70件，当库存降至70件即应采购以免缺货。","trap":"再订货点须含保险储备B；N*用年需求除以Q*；日需求=年需求/360，三量须口径一致。","tag":""}]},{"id":"cpa_ch12","group":"财务成本管理","name":"第12章 产品成本计算","qa":[{"id":"qa-cpach12-01","difficulty":1,"q":"简述产品成本计算的三种基本方法及其各自适用的生产类型。","answer_points":[{"point":"品种法以产品品种为成本对象","detail":"适用于大量大批单步骤生产，或管理上不要求分步计算成本的多步骤生产。"},{"point":"分批法以产品批别为成本对象","detail":"适用于单件小批生产，成本计算期与产品的生产周期一致。"},{"point":"分步法以生产步骤为成本对象","detail":"适用于大量大批多步骤生产，进一步分为逐步结转与平行结转分步法。"},{"point":"方法选择取决于生产组织与工艺","detail":"企业的生产类型与管理要求是选择成本计算基本方法的根本依据。"}],"framework":"三方法→各自对象→各自适用生产类型","memo":"品种=大量大批单步；分批=单件小批；分步=多步骤","tag":""},{"id":"qa-cpach12-02","difficulty":2,"q":"说明完工产品与月末在产品之间分配生产费用的常用方法及其适用条件。","answer_points":[{"point":"不计算在产品成本法","detail":"月末在产品成本视为零，全部费用由完工产品负担，适用于在产品数量很少的情形。"},{"point":"在产品按固定成本计价法","detail":"各月在产品成本固定不变，适用于在产品数量稳定、定额成本稳定的情形。"},{"point":"约当产量法","detail":"将在产品按完工程度折算为约当产量，与完工产品共同分配费用，是最常用的方法。"},{"point":"定额比例法","detail":"按定额消耗量或定额成本比例在完工与在产品间分配，适用于定额较准确稳定的情形。"},{"point":"方法依在产品数量与定额稳定性选择","detail":"数量少或稳定可用简化法，变化较大则用约当产量法或定额比例法。"}],"framework":"列出方法→各自适用条件→选择依据","memo":"约当产量=在产品数量×完工程度","tag":""},{"id":"qa-cpach12-03","difficulty":2,"q":"对比逐步结转分步法与平行结转分步法在半成品成本计算、成本信息及成本还原上的差异。","answer_points":[{"point":"逐步结转逐步计算并结转半成品成本","detail":"按加工顺序逐步计算半成品成本，能提供各步骤半成品成本资料，支持在产品和资金管理。"},{"point":"平行结转只计算计入产成品的份额","detail":"各步骤只计算本步骤发生费用中应计入产成品的份额并平行汇总，不计算半成品成本。"},{"point":"成本还原要求不同","detail":"逐步综合结转需进行成本还原；平行结转及逐步分项结转不需要成本还原。"},{"point":"成本信息详细程度不同","detail":"逐步法全面反映各步骤耗费水平，平行法简化核算但缺少半成品成本资料。"},{"point":"适用管理需求不同","detail":"需要考核半成品成本时选逐步法，否则平行法更简便高效。"}],"framework":"定义两法→半成品计算→成本还原→信息详略与适用","memo":"逐步算半成品(需还原)；平行不算(不需还原)","tag":""},{"id":"qa-cpach12-04","difficulty":3,"q":"综合说明联产品联合成本的分配方法（分离点售价法、可变现净值法、实物数量法）及副产品的简化处理。","answer_points":[{"point":"分离点售价法","detail":"联合成本分配率=待分配联合成本/(A产品分离点总售价+B产品分离点总售价)，按售价比例分配，最常用。"},{"point":"可变现净值法","detail":"分配率=联合成本/(A可变现净值+B可变现净值)，适用于分离后还需进一步加工、售价未定情形。"},{"point":"实物数量法","detail":"单位数量(或重量)成本=联合成本/各联产品总数量(或总重量)，适用于联产品价值相近时。"},{"point":"副产品采用扣除法","detail":"先按固定单价等确定副产品成本从总成本中扣除，余额为主产品成本，处理较简化。"},{"point":"方法按产品特征选择","detail":"售价稳定用售价法，需继续加工用可变现净值法，价值接近用实物数量法。"},{"point":"仅分配分离点前联合成本","detail":"分配针对分离点前发生的联合成本，分离后各自加工成本由各产品自行归集。"}],"framework":"三法公式→副产品扣除→适用选择→分配范围","memo":"联产品三法：分离点售价/可变现净值/实物数量","tag":""},{"id":"qa-cpach12-05","difficulty":3,"q":"综合说明生产费用从要素归集到完工产品成本计算的整体流程（材料、人工、制造费用、辅助生产的分配与完工在产品分配）。","answer_points":[{"point":"材料费用按定额消耗比例分配","detail":"分配率=材料总耗(或成本)/各产品定额消耗之和，多种产品共耗时采用定额比例法。"},{"point":"人工费用按实用工时分配","detail":"计时工资制下，工资费用按各产品实用工时比例分配，公式=工资总额/实用工时之和。"},{"point":"制造费用按工时分配","detail":"月实际分配率=当月制造费用总额/各产品生产实用(或定额)工时之和。"},{"point":"辅助生产费用直接分配或交互分配","detail":"直接分配法单位成本=费用/(总量-对其他辅助部门量)，只对外部受益单位分配。"},{"point":"汇总后于完工与在产品间分配","detail":"月初在产品成本+本月发生费用=本月完工产品成本+月末在产品成本，用约当产量等分配。"},{"point":"全流程体现多次归集与分配","detail":"从要素费用到成本计算单需多环节归集分配，最终求得产品总成本和单位成本。"}],"framework":"要素分配→辅助生产→制造费用→完工在产品分配","memo":"材料用定额、人工用工时、制造用工时","tag":""}],"calc":[{"id":"c-cpach12-01","difficulty":1,"stem":"某企业生产A、B两种产品共同耗用某材料，A产品材料定额消耗量为100公斤，B产品为60公斤，该材料实际费用总额为1600元。要求计算材料费用分配率。","blanks":[{"label":"材料费用分配率（元/公斤）","answer":10,"tolerance":0.01}],"steps":["第1步：公式 分配率=材料实际费用总额/各产品定额消耗量之和","第2步：代入 分配率=1600/(100+60)=1600/160","第3步：结果 分配率=10元/公斤"],"formula_card":"分配率=材料费用/(定额消耗量之和)","analysis":"A、B定额消耗合计160公斤，材料费用1600元，分配率10元/公斤；A应负担1000元，B应负担600元。","trap":"分母用各产品定额消耗量之和，而非实际产量或实际消耗量。","tag":""},{"id":"c-cpach12-02","difficulty":2,"stem":"某产品月初在产品成本500元，本月发生生产费用5000元，本月完工产品100件，月末在产品20件，在产品平均完工程度50%。要求计算单位成本和本月完工产品成本。","blanks":[{"label":"单位成本（元）","answer":50,"tolerance":0.01},{"label":"完工产品成本（元）","answer":5000,"tolerance":0.1}],"steps":["第1步：计算月末在产品约当产量=20×50%=10件","第2步：计算单位成本=(500+5000)/(100+10)=5500/110=50元","第3步：计算完工产品成本=50×100=5000元"],"formula_card":"单位成本=(月初+本月)/(完工+约当)；完工=单位×完工","analysis":"在产品约当10件，可分配费用5500元在110个约当单位间分配得单位成本50元，完工100件负担5000元，月末在产品负担500元。","trap":"约当产量=在产品数量×完工程度；分母含约当产量而非仅在产品数量。","tag":""},{"id":"c-cpach12-03","difficulty":3,"stem":"某产品原材料在生产开始时一次投入。月初在产品：材料600元、加工费400元；本月发生：材料3000元、加工费4000元。本月完工100件，月末在产品20件，加工程度50%。要求计算：材料单位成本、加工单位成本、完工产品总成本。","blanks":[{"label":"材料单位成本（元）","answer":30,"tolerance":0.01},{"label":"加工单位成本（元）","answer":40,"tolerance":0.01},{"label":"完工产品总成本（元）","answer":7000,"tolerance":0.1}],"steps":["第1步：材料一次投入，材料单位成本=(600+3000)/(100+20)=3600/120=30元","第2步：加工约当产量=20×50%=10，加工单位成本=(400+4000)/(100+10)=4400/110=40元","第3步：完工产品总成本=30×100+40×100=3000+4000=7000元"],"formula_card":"材料单位=材料合计/(完工+在产实际数)；加工单位=加工合计/(完工+约当)；完工=单位×完工","analysis":"材料一次投入按实际数量（100+20）分配得30元，加工按约当产量（100+10）分配得40元，完工100件负担材料3000元、加工4000元，合计7000元。","trap":"材料一次投入不乘完工程度、直接按数量分配；加工费用必须先计算约当产量再分配。","tag":""}]},{"id":"cpa_ch13","group":"财务成本管理","name":"第13章 标准成本法","qa":[{"id":"qa-cpach13-01","difficulty":1,"q":"简述标准成本的种类（按制定依据划分）及其含义。","answer_points":[{"point":"理想标准成本","detail":"在最优生产条件下可达到的最低成本，现实极少能达成，主要作为理论参考。"},{"point":"正常标准成本","detail":"效率良好、考虑正常损耗与低效率后的现实标准成本，具有客观性、现实性与激励性。"},{"point":"现行标准成本","detail":"根据适用期间预计的价格、效率和产能利用程度制定，随当期条件变化而调整。"},{"point":"基本标准成本","detail":"只要生产基本条件无重大变化即不予变动，用于衡量各期成本变动趋势。"},{"point":"正常标准成本介于理想与历史平均之间","detail":"正常标准成本大于理想标准成本，但小于历史平均水平，是最具实用性的标准。"}],"framework":"理想/正常/现行/基本→各自含义与特征","memo":"正常=现实可行；基本=长期不变；现行=当期调整","tag":""},{"id":"qa-cpach13-02","difficulty":2,"q":"说明变动成本差异的两因素分解思路，并分别列出直接材料、直接人工、变动制造费用的差异公式。","answer_points":[{"point":"总差异=实际-标准=价格差异+数量差异","detail":"任一变动成本的总差异均可分解为价格(耗费)差异与数量(效率)差异两部分。"},{"point":"直接材料差异","detail":"价格差异=实际数量×(实际价格-标准价格)；数量差异=(实际数量-标准数量)×标准价格。"},{"point":"直接人工差异","detail":"工资率差异=实际工时×(实际工资率-标准工资率)；效率差异=(实际工时-标准工时)×标准工资率。"},{"point":"变动制造费用差异","detail":"耗费差异=实际工时×(实际分配率-标准分配率)；效率差异=(实际工时-标准工时)×标准分配率。"},{"point":"差异方向：正数为超支(U)、负数为节约(F)","detail":"计算结果为正表示不利差异，为负表示有利差异，需据以评价业绩。"}],"framework":"总差异拆分→各项目价格/数量公式→符号规则","memo":"价格差异用实际量；数量差异用标准价","tag":""},{"id":"qa-cpach13-03","difficulty":2,"q":"说明标准成本差异分析中各项差异通常应归属的责任部门。","answer_points":[{"point":"材料价格差异归采购部门","detail":"采购单价多由采购部门的谈判与决策决定，价格差异通常由采购部门负责。"},{"point":"材料数量差异归生产部门","detail":"材料用量浪费或节约取决于生产耗用水平，数量差异一般由生产部门负责。"},{"point":"人工工资率差异归人事或生产部门","detail":"工资率水平由人事政策或生产排班决定，多由人事或生产部门承担。"},{"point":"人工效率差异归生产部门","detail":"工时利用效率主要反映生产组织与操作水平，效率差异归生产部门负责。"},{"point":"固定制造费用耗费差异与业务量无关","detail":"固定制造费用以预算数考核，耗费差异不随产量变动而变，考核开支水平。"}],"framework":"各差异→对应责任部门","memo":"价归采购、量归生产；人效归生产","tag":""},{"id":"qa-cpach13-04","difficulty":3,"q":"综合说明固定制造费用差异的二因素分析法与三因素分析法，并阐明两者的关系。","answer_points":[{"point":"二因素：耗费差异=实际数-预算数","detail":"反映费用实际开支水平，与产量无关，二因素法与三因素法计算相同。"},{"point":"二因素：能力差异=预算数-标准成本","detail":"能力差异=(生产能力-实际产量标准工时)×标准分配率，反映生产能力利用不足的损失。"},{"point":"三因素：将能力差异再分解","detail":"闲置能力差异=(生产能力-实际工时)×标准分配率；效率差异=(实际工时-实际产量标准工时)×标准分配率。"},{"point":"三因素合计等于二因素","detail":"闲置能力差异+效率差异=二因素的能力(能量)差异，三因素只是对能力差异进一步细分。"},{"point":"标准分配率=预算总额/标准总工时","detail":"固定制造费用标准分配率=固定制造费用预算总额/直接人工标准总工时，是计算基础。"}],"framework":"二因素公式→三因素拆分→两者关系→分配率","memo":"三因素=耗费+闲置+效率；闲置+效率=能力差异","tag":""},{"id":"qa-cpach13-05","difficulty":3,"q":"综合说明标准成本的制定方法、差异分析的实施步骤，以及基本标准成本的修订条件。","answer_points":[{"point":"单位标准成本=标准消耗量×标准单价","detail":"直接材料、直接人工、变动与固定制造费用均按用量标准与价格(分配率)标准制定。"},{"point":"标准成本总额=实际产量×单位标准","detail":"以实际产量乘单位标准成本得到标准成本总额，作为与实际成本比较的基准。"},{"point":"实施六环节流程","detail":"制定标准→算标准成本→汇实际成本→算差异→析原因→向负责人提供控制报告。"},{"point":"基本标准成本仅基本条件重大变化才修订","detail":"如产品结构、重要原材料和劳动力价格、生产技术工艺发生重大变化时修订；售价或效率变化不修订。"},{"point":"差异用于业绩评价与控制","detail":"分析差异原因并落实责任部门，支持成本控制与经营决策。"}],"framework":"标准制定→实施流程→修订条件","memo":"基本标准成本仅生产基本条件大变才修订","tag":""}],"calc":[{"id":"c-cpach13-01","difficulty":1,"stem":"某企业本月实际采购材料1000公斤，实际价格12元/公斤，标准价格10元/公斤。要求计算直接材料价格差异，并判断有利或不利。","blanks":[{"label":"直接材料价格差异（元）","answer":2000,"tolerance":0.1}],"steps":["第1步：公式 价格差异=实际数量×(实际价格-标准价格)","第2步：代入 价格差异=1000×(12-10)=1000×2","第3步：结果 价格差异=2000元（超支U）"],"formula_card":"价格差异=实际量×(实际价-标准价)","analysis":"实际采购1000公斤，单价12元高于标准10元，价格差异2000元为不利差异(U)，通常归采购部门责任。","trap":"价格差异用实际数量乘价差；结果为正表示超支(不利)。","tag":""},{"id":"c-cpach13-02","difficulty":2,"stem":"某产品实际工时2000小时，实际工资率9元/小时，标准工资率8元/小时，实际产量标准工时1800小时。要求计算直接人工工资率差异与效率差异。","blanks":[{"label":"工资率差异（元）","answer":2000,"tolerance":0.1},{"label":"效率差异（元）","answer":1600,"tolerance":0.1}],"steps":["第1步：计算工资率差异=实际工时×(实际工资率-标准工资率)=2000×(9-8)=2000元","第2步：计算效率差异=(实际工时-标准工时)×标准工资率=(2000-1800)×8=200×8=1600元","第3步：合计总差异=2000+1600=3600元（超支）"],"formula_card":"工资率=实际工时×(实际率-标准率)；效率=(实际工时-标准工时)×标准率","analysis":"工资率差异2000元(U)归人事/生产部门，效率差异1600元(U)归生产部门，两者合计3600元为不利差异。","trap":"工资率差异用实际工时；效率差异用标准工资率而非实际工资率。","tag":""},{"id":"c-cpach13-03","difficulty":3,"stem":"某企业固定制造费用预算24000元，预算所依据的标准总工时(生产能力)6000小时；本月实际固定制造费用25000元，实际工时5800小时，实际产量标准工时5500小时。要求计算：固定制造费用标准分配率、耗费差异、闲置能力差异、效率差异。","blanks":[{"label":"标准分配率（元/小时）","answer":4,"tolerance":0.01},{"label":"耗费差异（元）","answer":1000,"tolerance":0.1},{"label":"闲置能力差异（元）","answer":800,"tolerance":0.1},{"label":"效率差异（元）","answer":1200,"tolerance":0.1}],"steps":["第1步：标准分配率=预算总额/标准总工时=24000/6000=4元/小时","第2步：耗费差异=实际数-预算数=25000-24000=1000元（U）","第3步：闲置能力差异=(生产能力-实际工时)×分配率=(6000-5800)×4=800元（U）；效率差异=(实际工时-实际产量标准工时)×分配率=(5800-5500)×4=1200元（U）"],"formula_card":"标准分配率=预算/标准总工时；耗费=实际-预算；闲置=(生产-实际工时)×率；效率=(实际工时-实际产量标准工时)×率","analysis":"三因素差异：耗费1000、闲置能力800、效率1200，合计3000元不利；其中闲置+效率=2000等于二因素能力差异，反映产能未充分利用且工时效率偏低。","trap":"三因素耗费差异同二因素；闲置能力差异+效率差异=二因素能力差异；计算均用标准分配率而非实际率。","tag":""}]},{"id":"cpa_ch14","group":"财务成本管理","name":"第14章 作业成本法","qa":[{"id":"qa-cpach14-01","difficulty":1,"q":"简述作业成本法下间接成本的分配路径，并说明它相比传统成本法能解决什么问题。","answer_points":[{"point":"作业成本法的分配路径是资源→作业→产品","detail":"先将资源耗费归集到各项作业，再把作业成本按动因分配到产品等成本对象，体现“作业消耗资源、产品消耗作业”的思路。"},{"point":"传统成本法分配路径是资源→部门→产品","detail":"以部门为中间环节、多以单一产量基础（如机器工时）将间接费用分摊到产品，路径较粗放。"},{"point":"作业成本法旨在减少成本扭曲","detail":"当产品多样性高、间接费用与产量因果关系不强时，单一产量分配会把制造费用不合理地摊到高产产品，作业成本法用多维动因纠正这种扭曲。"},{"point":"为定价、产品线决策和成本控制提供更准确信息","detail":"更准确的成本信息帮助企业识别真实盈利产品、合理定价，并定位高耗用作业以改进流程。"},{"point":"两者均对全部生产成本进行分配","detail":"作业成本法与传统完全成本法都不区分固定成本和变动成本，这与变动成本法不同，需避免混淆。"}],"framework":"先答两法分配路径对比，再说明作业成本法的目的与适用价值，最后点明与完全成本法的共同点。","memo":"易错点：作业成本法≠变动成本法，它仍对全部生产成本分配，不剔除固定制造费用。","tag":""},{"id":"qa-cpach14-02","difficulty":2,"q":"说明作业成本法下“资源动因”与“作业动因”的区别与联系，并各举两个实际例子。","answer_points":[{"point":"资源动因用于把资源成本分配到作业","detail":"它反映资源消耗与作业之间的因果关系，是第一阶段（资源→作业）的分配依据，解决“作业耗用了多少资源”。"},{"point":"作业动因用于把作业成本分配到成本对象","detail":"它反映产品等成本对象对作业的消耗，是第二阶段（作业→产品）的分配依据，解决“产品耗用了多少作业”。"},{"point":"两者是同一链条上的前后环节","detail":"资源动因在前、作业动因在后，共同构成两阶段成本计算；动因选择都需要判明真实的因果驱动关系。"},{"point":"资源动因例子：机器小时、搬运次数","detail":"机器加工作业可按耗用机器小时分配电力与折旧，搬运作业可按搬运次数分配搬运人工等资源。"},{"point":"资源动因例子：订单数量、安装小时","detail":"材料采购作业可按订单数量归集采购成本，生产准备作业可按安装小时分配准备耗费。"},{"point":"作业动因例子：检验次数、机器工时","detail":"质量检验作业以检验次数为动因分配到产品，机器加工作业以机器工时为动因分配到产品。"}],"framework":"先界定两个动因的定义与所处阶段，再说明联系，最后分别举例佐证。","memo":"易错点：资源动因对应“资源→作业”，作业动因对应“作业→产品”，勿颠倒两者阶段。","tag":""},{"id":"qa-cpach14-03","difficulty":2,"q":"作业成本法按作业层级分为哪几类？分别说明其成本分配基础和典型例子。","answer_points":[{"point":"单位级作业：随每件产品发生","detail":"分配基础是产量（如机器加工），典型例子是机器加工作业、直接加工，单位产品成本按产量分配。"},{"point":"批次级作业：每批产品发生一次","detail":"分配基础是批次数（如生产准备），典型例子是生产准备、抽样检验、材料送达，按批次分摊。"},{"point":"产品级作业：为某类产品服务","detail":"分配基础是产品品种或相关基础（如产品设计），典型例子是产品设计、工艺设计、产品广告。"},{"point":"生产维持级作业：服务于整个工厂","detail":"典型例子是工厂保安、维修、行政管理、保险，先分配到各产品品种，再分配到批次，最后到单位产品。"},{"point":"层级划分决定分配路径","detail":"不同层级采用不同动因，避免把批量性或维持性成本误按产量摊到单位产品，减少成本信息失真。"}],"framework":"按“单位级、批次级、产品级、生产维持级”四类逐一说明动因基础与例子，并点明层级意义。","memo":"易错点：生产维持级服务整个工厂，需先分到品种再分到批次和单位，而非直接按产量分配。","tag":""},{"id":"qa-cpach14-04","difficulty":3,"q":"综合分析作业成本法与变动成本法、传统完全成本法的异同。","answer_points":[{"point":"与传统完全成本法的共同点","detail":"两者都对全部生产成本（含固定制造费用）进行分配计入产品成本，都不区分固定与变动成本，均属完全成本计算体系。"},{"point":"与传统完全成本法的不同点","detail":"传统法以部门为中间环节、多用单一产量基础分配间接费用；作业成本法以作业为中间环节、用多维成本动因分配，成本更准确。"},{"point":"与变动成本法的根本区别","detail":"变动成本法产品成本只含直接材料、直接人工和变动制造费用，固定制造费用全部作期间费用计入当期损益；作业成本法仍分配全部生产成本。"},{"point":"对外财务报告口径不同","detail":"完全成本法和作业成本法都可满足对外报告对产品成本的要求；变动成本法主要用于内部决策，对外报告需调整。"},{"point":"成本信息用途不同","detail":"作业成本法侧重准确追溯与流程改进，变动成本法侧重本量利与短期决策，传统完全成本法侧重存货计价与对外报告。"},{"point":"结论：作业成本法改进的是分配精确度","detail":"它不改变“全部生产成本计入产品”的完全成本法属性，只是用更合理的动因替代单一产量分配，从而纠正成本扭曲。"}],"framework":"以“是否分配全部生产成本”为主线，先比作业法与传统完全成本法（同与异），再比作业法与变动成本法（根本异），最后归纳对外报告与用途差异。","memo":"易错点：作业成本法归属完全成本体系，不是变动成本法；它仍将固定制造费用分配进产品成本。","tag":""},{"id":"qa-cpach14-05","difficulty":3,"q":"说明作业成本法的优点、局限性及适用条件，并据此判断哪些企业更适合采用。","answer_points":[{"point":"优点：成本计算更准确、减少扭曲","detail":"多维动因使间接费用追溯到真正的成本驱动因素，尤其改善高产与低产产品的成本结构，支持合理定价。"},{"point":"优点：有助于成本控制与流程改进","detail":"通过作业认定可识别增值与非增值作业，为消减非增值作业、优化流程提供信息，支持战略管理。"},{"point":"局限性：开发和维护费用较高","detail":"需建立作业清单、成本库并持续维护动因数据，系统建设与运行成本高，这是其主要局限。"},{"point":"局限性：成本动因确定较困难","detail":"动因选择依赖专业判断，若动因选错反而产生新的扭曲；且并非只适用于大型企业，中小企业也可采用。"},{"point":"适用条件：制造费用比重大","detail":"间接费用占成本比重越高，单一产量分配的扭曲越严重，作业成本法改进效果越明显。"},{"point":"适用条件：产品多样性高、动因复杂","detail":"当产品种类多、生产工艺差异大、间接费用与产量因果关系不强时，采用作业成本法最能提升成本信息质量。"}],"framework":"分“优点—局限性—适用条件”三层展开，最后用适用条件反推“制造费用比重大、产品多样”的企业更合适。","memo":"易错点：作业成本法并非只适用于大型企业，也符合对外报告要求；其最大短板是开发与维护成本高。","tag":""}],"calc":[{"id":"c-cpach14-01","difficulty":1,"stem":"某企业质量检验作业成本库本月归集成本60000元，以检验次数（业务动因）为分配基础，全月共检验300次。其中甲产品耗用检验120次。要求：计算甲产品应分配的质量检验作业成本。","blanks":[{"label":"甲产品应分配的质量检验作业成本（元）","answer":24000,"tolerance":0.1}],"steps":["第1步：计算检验作业分配率=作业成本库总成本÷总检验次数=60000÷300=200（元/次）","第2步：甲产品应分配作业成本=分配率×甲耗用次数=200×120=24000（元）","第3步：结果：甲产品应分配质量检验作业成本24000元"],"formula_card":"业务动因：分配率=归集期作业总成本÷归集期总作业次数；某产品应分配作业成本=分配率×该产品耗用作业次数","analysis":"以业务动因为基础，分配率=60000÷300=200元/次；甲产品耗用120次，应分配200×120=24000元。数字干净自洽，业务动因假定每次检验耗费相同。","trap":"业务动因以“次数”为计量，不是以工时或产量；注意分子分母对应总次数而非某产品次数。","tag":""},{"id":"c-cpach14-02","difficulty":2,"stem":"某厂机器加工作业成本库归集成本240000元，以机器工时（持续动因）为分配基础，全月总机器工时4000小时。甲产品耗用1500小时，乙产品耗用2500小时。要求：计算机器加工作业分配率，以及甲产品应分配的机器加工作业成本。","blanks":[{"label":"机器加工作业分配率（元/小时）","answer":60,"tolerance":0.01},{"label":"甲产品应分配的机器加工作业成本（元）","answer":90000,"tolerance":0.1}],"steps":["第1步：计算持续动因分配率=作业总成本÷总机器工时=240000÷4000=60（元/小时）","第2步：甲产品应分配成本=分配率×甲耗用工时=60×1500=90000（元）；乙产品=60×2500=150000（元）","第3步：校验：90000+150000=240000，与归集总成本一致"],"formula_card":"持续动因：分配率=归集期作业总成本÷归集期总作业时间；某产品应分配作业成本=分配率×该产品耗用作业时间","analysis":"持续动因以时间为计量，分配率=240000÷4000=60元/小时；甲产品耗用1500小时，应分配60×1500=90000元，乙产品150000元，合计恰为240000元，验算无误。","trap":"持续动因按“时间”分配，与业务动因的“次数”不同；分配后两产品合计应等于成本库总额，可用此校验。","tag":""},{"id":"c-cpach14-03","difficulty":3,"stem":"某厂生产甲、乙两种产品，设三个作业成本库，甲产品本月产量1000件。资料如下：（1）机器加工作业（持续动因，机器工时）：归集成本200000元，总工时5000小时，甲耗用3000小时、乙2000小时；（2）质量检验作业（业务动因，检验次数）：归集成本60000元，总次数600次，甲400次、乙200次；（3）生产准备作业（业务动因，批次数）：归集成本40000元，总批次数80批，甲50批、乙30批。要求：计算甲产品应分配的机器加工作业成本、检验作业成本，以及甲产品单位作业成本。","blanks":[{"label":"甲产品应分配的机器加工作业成本（元）","answer":120000,"tolerance":0.1},{"label":"甲产品应分配的质量检验作业成本（元）","answer":40000,"tolerance":0.1},{"label":"甲产品单位作业成本（元/件）","answer":185,"tolerance":0.1}],"steps":["第1步：机器加工分配率=200000÷5000=40（元/小时）；甲分配=40×3000=120000（元）","第2步：检验分配率=60000÷600=100（元/次）；甲分配=100×400=40000（元）","第3步：生产准备分配率=40000÷80=500（元/批）；甲分配=500×50=25000（元）","第4步：甲总作业成本=120000+40000+25000=185000（元）；单位作业成本=185000÷1000=185（元/件）"],"formula_card":"多作业库：各库分别按自身动因求分配率（持续动因用时、业务动因用次/批），再汇总到产品；单位成本=产品总作业成本÷产量","analysis":"分库计算：机器加工40元/小时→甲120000元；检验100元/次→甲40000元；生产准备500元/批→甲25000元；合计185000元÷1000件=185元/件。乙产品对应为80000+20000+15000=115000元，三库合计200000+60000+40000=300000元，甲乙合计185000+115000=300000元，完全勾稽。","trap":"不同作业库动因不同（持续/业务），须分别求分配率；生产维持级应先分到品种再分到单位，本题仅含单位与批次级，注意按各自基础分配不串用。","tag":""}]},{"id":"cpa_ch15","group":"财务成本管理","name":"第15章 本量利分析","qa":[{"id":"qa-cpach15-01","difficulty":1,"q":"写出本量利分析的基本损益方程式，并说明方程中各变量的含义。","answer_points":[{"point":"基本方程式：息税前利润=单价×销量-单位变动成本×销量-固定成本","detail":"该式由“利润=销售收入-总成本”展开得到，是单产品本量利分析的核心模型。"},{"point":"单价与销量决定销售收入","detail":"单价×销量构成销售收入，是利润的正向来源，销量即业务量。"},{"point":"单位变动成本×销量构成变动总成本","detail":"变动成本随销量正比例变动，单位变动成本在相关范围内保持稳定。"},{"point":"固定成本是期间总额","detail":"固定成本在相关范围内不随业务量变动，从销售收入扣除变动成本后的边际贡献中补偿。"},{"point":"方程含5个相互联系的变量","detail":"单价、单位变动成本、销量、固定成本、利润五个变量相互制约，已知其中四个可求第五个，是预测与保本保利分析的基础。"}],"framework":"先写出公式，再按“收入项—变动成本项—固定成本—五变量关系”逐项解释。","memo":"易错点：基本式用的是息税前利润（EBIT），未扣利息与所得税；五个变量相互联动，注意固定成本用总额而非单位额。","tag":""},{"id":"qa-cpach15-02","difficulty":2,"q":"说明边际贡献、边际贡献率与变动成本率之间的关系，并解释其经济含义。","answer_points":[{"point":"边际贡献=销售收入-变动成本","detail":"单位边际贡献=单价-单位变动成本；边际贡献首先用于补偿固定成本，有剩余才形成利润。"},{"point":"边际贡献率=边际贡献÷销售收入","detail":"也等于单位边际贡献÷单价，反映每1元销售收入中能用于补偿固定成本和创造利润的比重。"},{"point":"变动成本率=单位变动成本÷单价","detail":"反映每1元销售收入中被产品自身耗费（变动成本）所占的比重。"},{"point":"变动成本率+边际贡献率=1","detail":"因为销售收入被分为变动成本和边际贡献两部分，二者此消彼长、互补为1。"},{"point":"经济含义：区分“耗费”与“贡献”","detail":"变动成本率衡量产品自身资源耗费，边际贡献率衡量对补偿固定成本与盈利的贡献，两者结合可用于产品盈利结构分析。"}],"framework":"先定义三个指标，再给出互补关系，最后解释经济含义。","memo":"易错点：边际贡献率+变动成本率=1（不是与固定成本率互补）；边际贡献要先补固定成本才会有利润。","tag":""},{"id":"qa-cpach15-03","difficulty":2,"q":"说明保本点与安全边际的含义，并阐述它们与利润之间的数量关系。","answer_points":[{"point":"保本点是收入与成本相等的经营状态","detail":"表现为保本量（销量）或保本额（销售额），此时息税前利润为零，是企业盈利与亏损的分界。"},{"point":"安全边际是实际（或预计）量（额）超过保本量（额）的差额","detail":"安全边际越大，企业经营越安全；安全边际率=1-盈亏临界点作业率。"},{"point":"利润与保本的关系：利润=安全边际×边际贡献率","detail":"息税前利润=安全边际额×边际贡献率，也等于安全边际量×单位边际贡献，即安全边际部分的边际贡献就是企业利润。"},{"point":"销售息税前利润率=安全边际率×边际贡献率","detail":"该式将盈利水平拆解为经营安全程度与单位销售贡献能力两个因素，便于指标分解。"},{"point":"盈亏临界点作业率与安全边际率互补","detail":"两者之和为1，分别从“危险边界”与“安全空间”两个角度刻画经营风险。"}],"framework":"先分别定义保本点与安全边际，再给出利润的两个关系式，最后说明作业率与安全边际率的互补。","memo":"易错点：利润来自安全边际而非全部销量；多品种下不同产品销量不可直接加总，须用综合保本额。","tag":""},{"id":"qa-cpach15-04","difficulty":3,"q":"综合比较变动成本法与完全成本法的区别，并说明两种方法下当期利润出现差异的原因。","answer_points":[{"point":"产品成本构成不同","detail":"变动成本法产品成本只含直接材料、直接人工和变动制造费用；完全成本法还包括固定制造费用，固定制造费用计入产品成本。"},{"point":"固定制造费用处理不同","detail":"变动成本法下固定制造费用全额作期间费用计入当期损益；完全成本法下固定制造费用随存货流转递延或转销。"},{"point":"当期利润可能不同","detail":"当存货水平变动时，两种方法下计入当期利润的固定制造费用不同，导致利润差异；产量等于销量时两者利润相等。"},{"point":"期末存货计价不同","detail":"完全成本法存货含固定制造费用，金额较高；变动成本法存货只含变动生产成本，金额较低。"},{"point":"利润差额公式：P1=P2+ΔP","detail":"ΔP=期末存货中固定制造费用-期初存货中固定制造费用；期末存货吸收固定制造费用多于期初，则完全成本法利润P1大于变动成本法利润P2。"},{"point":"根本原因是成本流转假设不同","detail":"差异全部来自固定制造费用的“计入产品”还是“费用化”，与销售、管理费用的变动/固定划分无直接关系。"}],"framework":"以“固定制造费用是否计入产品成本”为主线，依次比较产品成本构成、期间费用、利润、存货，最后用互转公式定量说明差异来源。","memo":"易错点：利润差额只由固定制造费用在存货中的吸收量决定，公式为期末减期初；不是本期发生的全部固定制造费用。","tag":""},{"id":"qa-cpach15-05","difficulty":3,"q":"说明利润敏感分析的原理、敏感系数的含义，并解释为什么销售单价的敏感系数通常最大。","answer_points":[{"point":"敏感分析研究参数变化对利润的影响程度","detail":"在基本损益方程式基础上，考察单价、单位变动成本、销量、固定成本等单独变动时利润的响应幅度，为风险管控提供依据。"},{"point":"敏感系数=目标值变动百分比÷参数值变动百分比","detail":"绝对值大于1为敏感因素，小于1为不敏感因素；系数符号表示利润与参数同方向或反方向变动。"},{"point":"单价敏感系数通常最大（绝对值约5）","detail":"单价同时影响收入与边际贡献，且单价基数往往大于单位变动成本，等额百分比变动对利润撬动最显著。"},{"point":"单位变动成本敏感系数次之（约-4）","detail":"单位变动成本只影响边际贡献、不影响收入基数，故敏感程度略低于单价，且符号为负（上升使利润下降）。"},{"point":"产销量与固定成本敏感系数最小（约1）","detail":"产销量敏感系数约等于1，固定成本敏感系数也较小；最大最小分析可进一步求各参数的极限忍受值。"},{"point":"实务用途：锁定关键敏感因素","detail":"通过敏感系数识别最易引致利润波动的因素（如单价），优先管控其风险，并用最大最小分析确定保本单价等极限。"}],"framework":"先讲原理与敏感系数公式，再按“单价>单位变动成本>产销量/固定成本”排序说明敏感程度，最后落到实务用途。","memo":"易错点：敏感系数是“百分比变动比”，不是绝对额变动比；单价敏感系数最大源于它同时作用于收入与边际贡献。","tag":""}],"calc":[{"id":"c-cpach15-01","difficulty":1,"stem":"某企业销售单价10元，单位变动成本6元，每月固定成本1000元。要求：计算该企业的保本销售量。","blanks":[{"label":"保本销售量（件）","answer":250,"tolerance":0.01}],"steps":["第1步：单位边际贡献=单价-单位变动成本=10-6=4（元/件）","第2步：保本量=固定成本÷单位边际贡献=1000÷4=250（件）","第3步：结果：保本销售量为250件"],"formula_card":"保本量=固定成本÷单位边际贡献=固定成本÷（单价-单位变动成本）","analysis":"单位边际贡献=10-6=4元/件；保本量=1000÷4=250件。销量低于250件则亏损，达到250件利润为零，与教材例题口径一致。","trap":"保本量用“单位边际贡献”作分母，不是用单价；固定成本用总额而非单位额。","tag":""},{"id":"c-cpach15-02","difficulty":2,"stem":"某企业产品单价20元，单位变动成本12元，每月固定成本4000元，计划实现息税前目标利润4000元。要求：计算实现目标利润的保利销售量与保利销售额。","blanks":[{"label":"保利销售量（件）","answer":1000,"tolerance":0.01},{"label":"保利销售额（元）","answer":20000,"tolerance":0.1}],"steps":["第1步：单位边际贡献=20-12=8（元/件）；边际贡献率=8÷20=40%","第2步：保利量=（固定成本+目标利润）÷单位边际贡献=（4000+4000）÷8=1000（件）","第3步：保利额=（固定成本+目标利润）÷边际贡献率=8000÷40%=20000（元），或1000×20=20000（元）"],"formula_card":"保利量=（固定成本+目标利润EBIT）÷单位边际贡献；保利额=（固定成本+目标利润EBIT）÷边际贡献率","analysis":"目标利润为息税前口径，单位边际贡献=8元，保利量=8000÷8=1000件；边际贡献率40%，保利额=8000÷0.4=20000元，亦可用1000件×20元验证一致。","trap":"若目标利润为税后利润需先÷（1-所得税税率）调整为息税前利润再代入；保利额用边际贡献率而非变动成本率。","tag":""},{"id":"c-cpach15-03","difficulty":3,"stem":"某企业产销甲、乙两种产品，固定成本总额17000元。甲产品单价10元、单位变动成本6元、销售量2000件；乙产品单价10元、单位变动成本7元、销售量3000件。要求：计算加权平均边际贡献率、保本销售总额，以及按销售比重计算的甲产品保本销售额。","blanks":[{"label":"加权平均边际贡献率（%）","answer":34,"tolerance":0.01},{"label":"保本销售总额（元）","answer":50000,"tolerance":0.1},{"label":"甲产品保本销售额（元）","answer":20000,"tolerance":0.1}],"steps":["第1步：甲边际贡献率=（10-6）÷10=40%，甲收入=10×2000=20000（元）；乙边际贡献率=（10-7）÷10=30%，乙收入=10×3000=30000（元）","第2步：总边际贡献=20000×40%+30000×30%=8000+9000=17000（元）；总收入=20000+30000=50000（元）","第3步：加权平均边际贡献率=总边际贡献÷总收入=17000÷50000=34%","第4步：保本销售总额=固定成本÷加权平均边际贡献率=17000÷34%=50000（元）","第5步：甲销售比重=20000÷50000=40%；甲保本销售额=50000×40%=20000（元）"],"formula_card":"加权平均边际贡献率=∑各产品边际贡献÷∑各产品销售收入；保本销售总额=固定成本÷加权平均边际贡献率；某产品保本销售额=保本销售总额×该产品销售比重","analysis":"甲、乙边际贡献率分别为40%、30%，总收入50000元、总边际贡献17000元，加权边际贡献率34%；保本总额=17000÷34%=50000元；甲占收入40%，保本销售额=50000×40%=20000元，乙为30000元，合计50000元勾稽无误。","trap":"多品种下销量不能直接加总，须用加权平均边际贡献率算综合保本额再按销售比重分摊；边际贡献率用“（单价-单位变动成本）÷单价”，勿用单位边际贡献绝对额加总。","tag":""}]},{"id":"cpa_ch17","group":"财务成本管理","name":"第17章 全面预算","qa":[{"id":"qa-cpach17-01","difficulty":1,"q":"简述全面预算体系的构成内容，并说明各类预算之间的逻辑关系。","answer_points":[{"point":"全面预算的定位","detail":"全面预算是企业未来一定时期经营和财务的具体计划，是决策的数字化、表格化、明细化表达，既是决策的具体化，又是控制经营和财务活动的依据。"},{"point":"资本预算（特种决策预算）","detail":"涉及长期投资、长期筹资等专项决策的预算，属于全局性、一次性的重大资源配置安排，不直接参与日常经营周转。"},{"point":"经营预算（营业预算）","detail":"与企业日常经营活动直接相关，包括销售、生产、直接材料、直接人工、制造费用、产品成本、销售及管理费用等预算，体现全员全过程特征。"},{"point":"财务预算","detail":"与现金收支、经营成果和财务状况有关，包括现金预算、利润表预算、资产负债表预算，是经营预算与资本预算结果的综合反映。"},{"point":"三类预算的逻辑关系","detail":"经营预算和资本预算是财务预算的编制基础，财务预算则综合汇总前两者的资金结果与财务状况，三者构成有机整体而非并列关系。"}],"framework":"总定位—三分项—关系","memo":"财务预算是全面预算的终点与综合，注意营业预算属于经营预算而非与其并列。","tag":""},{"id":"qa-cpach17-02","difficulty":2,"q":"说明弹性预算法的含义、具体编制方法及业务量范围的确定原则。","answer_points":[{"point":"含义","detail":"为克服固定预算只按单一业务量编制的缺点而设计，按一系列业务量水平编制，从而扩大预算的适用范围，便于后续评价和考核。"},{"point":"公式法","detail":"以 y=a+bx 表达成本总额与业务量关系，其中 a 为固定成本预算、b 为单位变动成本预算、x 为预计业务量、y 为该业务量下的成本预算总额。"},{"point":"列表法","detail":"按多个具体业务量水平逐一列示对应的预算数额，比公式法更直观，便于在相关范围内直接查用，但工作量略大。"},{"point":"业务量范围（上下限）","detail":"一般定在正常生产能力的 70%—110% 之间，也可取历史上最高业务量与最低业务量为上下限，确保实际业务量不超出相关范围。"},{"point":"相对固定预算的优点","detail":"可按多业务量水平评价、按成本性态分类列示便于考核、一次编制即可适用多种业务量，但仍会存在弹性预算差异不能完全避免。"}],"framework":"含义—两方法—范围—优点","memo":"弹性=多业务量，固定=单业务量；记住 a 固定、b 变动、x 业务量。","tag":""},{"id":"qa-cpach17-03","difficulty":2,"q":"说明滚动预算法的含义，以及按滚动时间单位划分的三种方式及其特点。","answer_points":[{"point":"含义","detail":"在上期预算完成情况基础上调整编制下期预算，并逐期向后滚动推移，使预算期间始终保持一定时期的跨度，也叫连续预算法或永续预算法。"},{"point":"逐月滚动","detail":"每月调整一次预算，精确度较高，但编制工作量最大，适用于对短期预算精度要求高的企业。"},{"point":"逐季滚动","detail":"每季调整一次预算，编制工作量较小，但精确度相对较差，适用于对精度要求不极高的情形。"},{"point":"混合滚动","detail":"近期按月、远期按季结合编制，兼顾精度与工作量，是实务中较常用的折中方式。"},{"point":"理论依据","detail":"其合理性在于对未来了解程度具有近期把握较大、远期把握较小的特征，因而近期细、远期粗。"}],"framework":"含义—三方式对比—理论依据","memo":"逐月精确但累，逐季省力但粗，混合取中。","tag":""},{"id":"qa-cpach17-04","difficulty":3,"q":"综合说明以销售预算为起点的营业预算编制逻辑，以及各预算之间的数据勾稽关系。","answer_points":[{"point":"销售预算是起点和关键","detail":"全面预算以销售预算为起点，其他预算（生产、现金、利润等）均以其为基础，因为销售量决定生产量、采购量与资金安排。"},{"point":"生产预算（只涉实物量）","detail":"预计生产量=预计销售量+预计期末存货−预计期初存货，期末存货通常按下期销售量一定百分比确定，该预算只算量不算金额。"},{"point":"直接材料预算","detail":"预计采购量=生产需用量+期末材料存货−期初材料存货；采购现金支出包括偿还上期应付账款和本期应付采购货款（如本季付 50%、下季付 50%）。"},{"point":"直接人工预算","detail":"以生产预算的预计产量为基础，人工总成本=预计产量×单位产品工时×每小时人工成本，工资全部现金支付可直接汇入现金预算。"},{"point":"制造费用预算","detail":"变动制造费用以生产预算为基础计算，固定制造费用与产量无关、按每季实际需要支付预计后汇总为全年数。"},{"point":"产品成本与销售管理费用预算","detail":"在料、工、费基础上汇总编制产品成本预算，并单独编制销售及管理费用预算，二者最终汇入现金预算与利润表预算。"}],"framework":"起点—生产—料—工—费—汇总","memo":"销售→生产→料工费层层推算；生产预算只算量不算钱。","tag":""},{"id":"qa-cpach17-05","difficulty":3,"q":"综合分析现金预算的构成与编制逻辑，并说明它如何衔接利润表预算和资产负债表预算。","answer_points":[{"point":"四部分构成","detail":"现金预算由可供使用现金、现金支出、现金多余或不足、现金的筹措和运用四部分构成，集中反映预算期现金余缺。"},{"point":"期末现金余额公式","detail":"期末现金余额=期初现金余额+现金收入−现金支出+借款−还款/利息，且必须保持不低于最低现金余额的约束。"},{"point":"与利润表预算的衔接","detail":"现金预算中的所得税费用应列入利润表预算；在编制程序上现金预算先于利润表预算，二者通过所得税和利润数据勾稽。"},{"point":"与资产负债表预算的衔接","detail":"现金取现金预算期末数；应收账款=本期销售额×(1−本期收现率)；应付账款=本期采购额×(1−本期付现率)；未分配利润=期初未分配利润+本期净利润−本期股利。"},{"point":"目标利润不一致的处理","detail":"若编制的财务报表预算与最初方针目标利润差异较大，应调整部门预算设法达到目标，体现预算的控制与协调作用。"}],"framework":"四构成—现金平衡—与两表勾稽","memo":"现金预算管资金，利润表管成果，资产负债表管状况。","tag":""}],"calc":[{"id":"c-cpach17-01","difficulty":1,"stem":"某企业预算期预计生产量为 1000 件，单位产品耗用材料 2 公斤，期末材料存货目标 400 公斤，期初材料存货 200 公斤。要求计算预计材料采购量（公斤）。","blanks":[{"label":"预计材料采购量（公斤）","answer":2200,"tolerance":0.1}],"steps":["第1步：计算生产需用量=预计生产量×单位耗用量=1000×2=2000 公斤","第2步：预计采购量=生产需用量+期末材料存货−期初材料存货=2000+400−200=2200 公斤"],"formula_card":"预计采购量=生产需用量+期末材料存货−期初材料存货","analysis":"先由生产量乘以单耗得到生产需用量 2000 公斤，再结合存货目标求得采购量 2200 公斤。该数据为直接材料预算的采购量基础，后续据以安排采购现金支出。","trap":"注意单位耗用量要先乘出生产需用量，不能直接用生产件数当作材料需用量；期末减期初的顺序不要颠倒。","tag":""},{"id":"c-cpach17-02","difficulty":2,"stem":"某企业分季度预计销售量：Q1 500 件、Q2 600 件、Q3 700 件、Q4 800 件；期末产成品存货按下期销售量 10% 确定，Q1 期初存货 50 件，假设下年 Q1 销售量回到 500 件。要求计算第三季度预计生产量及全年预计生产量（件）。","blanks":[{"label":"第三季度预计生产量（件）","answer":710,"tolerance":0.1},{"label":"全年预计生产量（件）","answer":2600,"tolerance":0.1}],"steps":["第1步：计算各季度期末存货=下期销售量×10%（Q1期末=600×10%=60；Q2期末=700×10%=70；Q3期末=800×10%=80；Q4期末=下年Q1×10%=50）","第2步：确定各季度期初存货=上期期末（Q1期初=50；Q2期初=60；Q3期初=70；Q4期初=80）","第3步：预计生产量=预计销售量+期末存货−期初存货（Q3=700+80−70=710；Q1=510、Q2=610、Q4=770；全年=510+610+710+770=2600）"],"formula_card":"预计生产量=预计销售量+预计期末存货−预计期初存货","analysis":"第三季度生产量 710 件由销量 700 加期末 80 减期初 70 得到；全年各季生产量加总为 2600 件。生产预算只反映实物量，是后续直接材料与直接人工预算的基础。","trap":"期初存货等于上期期末存货，容易把期初与期末搞反；第四季度期末需已知下年 Q1 销量才能计算，题目已给定。","tag":""},{"id":"c-cpach17-03","difficulty":3,"stem":"某公司预算期期初现金余额 8000 元，预算期现金收入 45000 元，现金支出合计 56800 元，最低现金余额要求 5000 元，银行借款年利率 12%（按单期计息，利息于期末支付）。要求计算：可供使用现金、需向银行借款金额、期末现金余额（元）。","blanks":[{"label":"可供使用现金（元）","answer":53000,"tolerance":0.1},{"label":"需向银行借款（元）","answer":10000,"tolerance":0.1},{"label":"期末现金余额（元）","answer":5000,"tolerance":0.1}],"steps":["第1步：可供使用现金=期初现金余额+现金收入=8000+45000=53000 元","第2步：现金多余或不足=可供使用现金−现金支出=53000−56800=−3800 元（即现金不足 3800 元）","第3步：设借款 L，期末=−3800+L−L×12%=−3800+0.88L；令其等于最低余额 5000，得 L=10000 元，利息=10000×12%=1200 元","第4步：期末现金余额=−3800+10000−1200=5000 元（达到最低余额要求）"],"formula_card":"期末现金余额=期初+现金收入−现金支出+借款−借款利息；借款利息=借款额×年利率（单期）","analysis":"可供使用现金 53000 元，扣除支出后仅余 −3800 元，低于最低余额 5000 元，需借款补足。考虑 12% 单期利息后，借款 10000 元可使期末恰好为 5000 元。若多余则用于归还借款或投资有价证券。","trap":"借款利息会减少期末现金，不能简单用（最低余额−多余或不足）作为借款额；利息按借款额×12% 在期末扣除，需试算使期末不低于最低余额。","tag":""}]},{"id":"cpa_ch18","group":"财务成本管理","name":"第18章 责任会计","qa":[{"id":"qa-cpach18-01","difficulty":1,"q":"简述成本中心、利润中心和投资中心的含义及其各自承担的责任范围。","answer_points":[{"point":"责任会计的定位","detail":"责任会计是现代管理会计的重要分支，是企业内部经济责任制下的内部会计控制制度，用于对责任中心业绩进行规划、控制与考核。"},{"point":"成本中心","detail":"只对成本或费用承担责任，通常没有或只有少量收入，分为标准成本中心和费用中心，是责任范围最小的中心。"},{"point":"利润中心","detail":"对利润负责，拥有供货来源和市场选择的经营决策权，分为自然利润中心和人为利润中心。"},{"point":"投资中心","detail":"经理除经营决策权外还拥有投资规模和类型决策权，需对利润和投资效果双重负责，责任范围最大。"},{"point":"划分意义","detail":"三类中心匹配不同层级的决策权限，考核指标随之不同，是实现分级分权管理和内部业绩评价的基础。"}],"framework":"定位—三类中心递进—划分意义","memo":"成本→利润→投资，责任范围逐步扩大。","tag":""},{"id":"qa-cpach18-02","difficulty":2,"q":"说明可控成本的含义与判别原则，并说明制造费用在责任中心之间分配的基本思路。","answer_points":[{"point":"可控成本定义","detail":"可控成本是指责任中心通过自己的行动能有效影响的成本；反之，无法有效影响的则为不可控成本。"},{"point":"判别原则一（能影响）","detail":"责任中心通过自身行动能有效影响成本数额的，应对该成本负责，这是可控性的最基本判断标准。"},{"point":"判别原则二（有权决定）","detail":"责任中心有权决定是否使用某种资产或劳务的，应对其相关成本负责，体现权责对等。"},{"point":"判别原则三（上级要求参与）","detail":"管理人员虽不直接决定某项成本，但上级要求其参与并对支出施加重要影响的，也承担责任。"},{"point":"固定成本并非都不可控","detail":"固定成本中也有可控部分（如酌量性固定成本），不能将所有固定成本一概视为不可控，需具体分析。"},{"point":"制造费用分配思路","detail":"先直接计入，再按责任基础、按受益基础分配，归入特定责任中心；确实不可分摊的固定成本不予分配，由上级承担。"}],"framework":"定义—三原则—成本性态注意—分配","memo":"可控=能影响；固定成本未必不可控。","tag":""},{"id":"qa-cpach18-03","difficulty":2,"q":"说明利润中心业绩评价的指标体系，以及各指标分别适用于评价什么对象。","answer_points":[{"point":"部门边际贡献","detail":"=部门销售收入−部门变动成本总额，反映部门对覆盖固定成本和创造利润的基本贡献。"},{"point":"部门可控边际贡献","detail":"=部门边际贡献−部门可控固定成本，扣除了经理可控制的固定成本，是评价部门经理业绩的首选指标。"},{"point":"部门税前经营利润","detail":"=部门可控边际贡献−部门不可控固定成本，包含不可控固定成本，适合评价部门对公司利润的总体贡献。"},{"point":"不以边际贡献评价经理","detail":"仅用边际贡献评价经理不够全面，因为它不区分可控与不可控固定成本，可能掩盖经理的真实管理责任。"},{"point":"剩余收益不用于利润中心","detail":"剩余收益属于投资中心的评价指标，利润中心一般只用前三层贡献类指标考核。"}],"framework":"三指标递进—适用对象—不适用情形","memo":"经理看可控，部门看税前经营利润。","tag":""},{"id":"qa-cpach18-04","difficulty":3,"q":"综合分析投资报酬率（ROI）与剩余收益的优缺点及适用场景，并说明为何剩余收益能克服次优化问题。","answer_points":[{"point":"ROI公式","detail":"部门投资报酬率=部门税前经营利润÷部门平均净经营资产，可进一步分解为投资周转率×部门经营利润率。"},{"point":"ROI优点","detail":"依据现有责任会计资料计算较为客观，可用于部门之间及不同行业比较，并能量化分解便于管理分析。"},{"point":"ROI缺点（次优化）","detail":"ROI是相对数，经理可能为维持本部门高 ROI 而放弃高于公司要求但低于当前 ROI 的项目，损害公司整体利益。"},{"point":"剩余收益公式","detail":"部门剩余收益=部门税前经营利润−部门平均净经营资产×要求的税前投资报酬率，是绝对数指标。"},{"point":"剩余收益优点","detail":"与公司目标协调一致，只要项目剩余收益为正（高于要求报酬率）就接受，避免了 ROI 导致的次优化行为。"},{"point":"剩余收益缺点","detail":"作为绝对数不便不同规模部门直接比较，但允许按各部门的 risk 调整资本成本率以体现差异。"}],"framework":"两公式—ROI优缺点—剩余收益优缺点—次优化","memo":"ROI看率易短视，剩余收益看额对齐公司。","tag":""},{"id":"qa-cpach18-05","difficulty":3,"q":"综合说明内部转移价格的类型、适用对象及协商型价格的合理区间，并解释制定内部转移价格的目的。","answer_points":[{"point":"制定目的","detail":"防止成本转移导致的责任转嫁、引导下级作出符合公司利益的决策、为各责任中心单独业绩评价提供依据。"},{"point":"市场型转移价格","detail":"以市场价格为基础制定，适用于拥有外部市场参照的利润中心，能体现竞争导向。"},{"point":"成本型转移价格","detail":"以完全成本或变动成本为基础制定，一般适用于成本中心，因其无外部市场可比价格。"},{"point":"协商型转移价格","detail":"适用于分权程度较高的企业，由双方协商确定，合理区间为不高于市场价、不低于单位变动成本。"},{"point":"协商价区间边界","detail":"协商价格的上限是市场价、下限是单位变动成本；既不能高于市价（否则不如外购），也不能低于变动成本（否则供方亏损）。"},{"point":"不直接决定对外售价","detail":"内部转移价格用于内部结算，并不决定企业的最终对外销售价格，二者需分别考虑。"}],"framework":"目的—三类型—协商区间—边界","memo":"协商价夹在单位变动成本与市价之间。","tag":""}],"calc":[{"id":"c-cpach18-01","difficulty":1,"stem":"某部门本期销售收入 200 万元，变动成本总额 120 万元。要求计算部门边际贡献（万元）。","blanks":[{"label":"部门边际贡献（万元）","answer":80,"tolerance":0.1}],"steps":["第1步：部门边际贡献=部门销售收入−部门变动成本总额=200−120=80 万元"],"formula_card":"部门边际贡献=部门销售收入−部门变动成本总额","analysis":"部门边际贡献仅扣除变动成本，反映部门对覆盖固定成本和创造利润的基本贡献，为 80 万元。后续还需扣除固定成本才能得到可控边际贡献与税前经营利润。","trap":"边际贡献尚未扣除任何固定成本，注意不要误减固定成本；它只是利润中心考核指标体系中的第一层。","tag":""},{"id":"c-cpach18-02","difficulty":2,"stem":"某部门销售收入 500 万元，变动成本 300 万元，可控固定成本 80 万元，不可控固定成本 40 万元。要求计算部门可控边际贡献与部门税前经营利润（万元）。","blanks":[{"label":"部门可控边际贡献（万元）","answer":120,"tolerance":0.1},{"label":"部门税前经营利润（万元）","answer":80,"tolerance":0.1}],"steps":["第1步：部门边际贡献=销售收入−变动成本=500−300=200 万元","第2步：部门可控边际贡献=部门边际贡献−可控固定成本=200−80=120 万元","第3步：部门税前经营利润=部门可控边际贡献−不可控固定成本=120−40=80 万元"],"formula_card":"可控边际贡献=边际贡献−可控固定成本；税前经营利润=可控边际贡献−不可控固定成本","analysis":"先得边际贡献 200 万元，扣除可控固定成本后得到评价经理业绩的 120 万元，再扣除不可控固定成本得到评价部门贡献的 80 万元。两层固定成本的区分是利润中心考核的核心。","trap":"必须区分可控与不可控固定成本；评价部门经理用可控边际贡献而非税前经营利润，后者含不可控部分。","tag":""},{"id":"c-cpach18-03","difficulty":3,"stem":"某投资中心本期税前经营利润 240 万元，平均净经营资产 1000 万元，公司要求的税前投资报酬率 15%。现有新项目需追加净经营资产 200 万元，可增加税前经营利润 36 万元。要求计算：(1)部门投资报酬率 ROI；(2)部门剩余收益；(3)新项目剩余收益（万元），并从两指标角度判断经理是否会接受该项目。","blanks":[{"label":"部门投资报酬率 ROI（%）","answer":24,"tolerance":0.01},{"label":"部门剩余收益（万元）","answer":90,"tolerance":0.1},{"label":"新项目剩余收益（万元）","answer":6,"tolerance":0.1}],"steps":["第1步：部门 ROI=税前经营利润÷平均净经营资产=240÷1000=24%","第2步：部门剩余收益=税前经营利润−平均净经营资产×要求报酬率=240−1000×15%=240−150=90 万元","第3步：新项目 ROI=36÷200=18%，高于公司要求 15%（对公司有利），但会使部门整体 ROI 降至(240+36)/(1000+200)=23%，低于原 24%","第4步：新项目剩余收益=36−200×15%=36−30=6 万元>0；接受后总剩余收益=90+6=96 万元增加"],"formula_card":"ROI=税前经营利润÷平均净经营资产；剩余收益=税前经营利润−平均净经营资产×要求报酬率","analysis":"部门 ROI 为 24%、剩余收益 90 万元。新项目 ROI 18% 虽高于公司要求 15%，却低于部门现有 24%，若以 ROI 考核，经理可能为保比率拒绝该项目（次优化）；而新项目剩余收益 6 万元为正，以剩余收益考核经理会接受，总剩余收益增至 96 万元，与公司目标一致。","trap":"ROI 是相对数，高 ROI 部门可能拒绝低于自身但高于要求报酬率的项目；剩余收益是绝对数可避免次优化，但不同规模部门不便直接比较。","tag":""}]},{"id":"cpa_ch19","group":"财务成本管理","name":"第19章 业绩评价","qa":[{"id":"qa-cpach19-01","difficulty":1,"q":"简述财务业绩评价与非财务业绩评价的区别及各自的侧重点。","answer_points":[{"point":"财务业绩评价","detail":"依据净利润、资产报酬率、经济增加值等财务信息评价管理者业绩，是传统且量化的评价方式。"},{"point":"非财务业绩评价","detail":"依据市场份额、客户满意度、及时送货率、员工满意度等非财务指标评价，反映经营过程与软实力。"},{"point":"财务评价侧重点","detail":"侧重反映短期经营成果，是结果导向，对达成结果的过程关注不足，存在一定滞后性。"},{"point":"非财务评价侧重点","detail":"体现长期发展视角和外部（客户、市场）对企业的整体评价，弥补财务评价的短视与滞后。"},{"point":"结合使用","detail":"两类方法各有优缺点，实务中应结合使用，以兼顾结果与驱动因素、短期与长期。"}],"framework":"定义—对比—结合","memo":"财务看过去成果，非财务看未来能力。","tag":""},{"id":"qa-cpach19-02","difficulty":2,"q":"说明关键绩效指标法（KPI）的指标分类、层级与权重设定，以及制定流程。","answer_points":[{"point":"指标分类","detail":"企业关键绩效指标一般分为结果类指标和动因类指标，前者衡量产出，后者驱动结果，二者相辅相成。"},{"point":"层级划分","detail":"KPI 体系分为企业级、所属单位（部门）级、岗位（员工）级三个层次，逐级分解落实战略目标。"},{"point":"数量与权重","detail":"每一层级指标一般不超过 10 个，单项关键绩效指标权重一般设定在 5%—30% 之间，避免过于分散。"},{"point":"制定流程","detail":"包括制定绩效计划、确定指标体系、分配指标权重、设定目标值、实施评价与激励五个步骤。"},{"point":"核心","detail":"KPI 法的核心在于制定和实施以关键绩效指标为核心的绩效计划，将价值创造与战略目标相联系。"}],"framework":"分类—层级—权重—流程","memo":"KPI 每层级≤10 个，单项权重 5%—30%。","tag":""},{"id":"qa-cpach19-03","difficulty":2,"q":"说明经济增加值（EVA）的含义、基本公式，以及披露 EVA 的典型会计调整项目。","answer_points":[{"point":"EVA含义","detail":"经济增加值是指税后净营业利润扣除全部投入资本成本后的剩余收益，衡量企业为股东真正创造价值的部分。"},{"point":"基本EVA公式","detail":"基本 EVA=税后净营业利润−报表平均总资产×加权平均资本成本，按未经调整的经营利润和总资产计算。"},{"point":"研发费用的调整","detail":"披露 EVA 通常将研发费用作为投资资本化，并在合理期限内摊销，而非一次性费用化，以鼓励创新投入。"},{"point":"战略投资利息资本化","detail":"对战略性投资的借款利息予以资本化，避免其减少当期经营利润，鼓励长期战略性投入。"},{"point":"品牌费用资本化与沉淀折旧","detail":"品牌建设费用资本化摊销；固定资产折旧多采用沉淀资金折旧法，以反映资产真实经济损耗而非会计损耗。"}],"framework":"含义—基本公式—四项调整","memo":"EVA=税后净营业利润−全部资本成本（绝对数）。","tag":""},{"id":"qa-cpach19-04","difficulty":3,"q":"综合分析平衡计分卡的四个维度及其核心问题，并说明其有效实施的要求。","answer_points":[{"point":"财务维度","detail":"回答股东如何看待我们，是其他维度的最终结果，通常用传统财务比率衡量企业价值实现。"},{"point":"客户维度","detail":"回答顾客如何看待我们，关注市场份额、客户满意度、及时送货率等外部评价与市场需求。"},{"point":"内部业务流程维度","detail":"回答我们的优势是什么，聚焦关键流程优化与核心竞争力建设，是创造价值的内在能力。"},{"point":"学习与成长维度","detail":"回答我们能否继续提高并创造价值，关注员工能力、信息系统与组织氛围等基础驱动要素。"},{"point":"实施要求一（因果挂钩）","detail":"四个方面指标之间必须存在因果联系，并与企业战略最终挂钩，形成从学习成长到财务结果的驱动链条。"},{"point":"实施要求二（指标与驱动结合）","detail":"既要设置结果衡量指标也要设置驱动因素指标，最终必须回归并联系到财务指标，不能仅用非财务指标。"}],"framework":"四维度—核心问题—实施要求","memo":"财务→客户→内部流程→学习成长，层层驱动。","tag":""},{"id":"qa-cpach19-05","difficulty":3,"q":"综合说明国资委简化 EVA 的计算框架（税后净营业利润、调整后资本、平均资本成本率），以及股权资本成本率的分档规定。","answer_points":[{"point":"简化EVA总公式","detail":"简化 EVA=税后净营业利润−调整后资本×平均资本成本率，是国资委考核中央企业业绩的核心指标。"},{"point":"税后净营业利润","detail":"=净利润+（利息支出+研究开发费用调整项）×（1−25%），将税后利息和研发加回，还原经营活动真实利润。"},{"point":"调整后资本","detail":"=平均所有者权益+平均带息负债−平均在建工程，剔除无息负债和尚未形成效益的在建工程占用。"},{"point":"平均资本成本率","detail":"=债权资本成本率×带息负债占比×（1−25%）+股权资本成本率×权益占比，债权、股权均为税后口径加权。"},{"point":"股权成本率分档","detail":"商业类充分竞争企业 6.5%、重要行业和关键领域企业 5.5%、公益类企业 4.5%，体现行业风险差异。"},{"point":"特殊调整","detail":"军工、电力、农业企业在上述基准上下浮 0.5 个百分点；资产负债率高于上年且在规定区间时，平均资本成本率上浮 0.2 或 0.5 个百分点。"}],"framework":"总公式—三要素—分档—特殊","memo":"税后 NOPAT−调整后资本×WACC=EVA。","tag":""}],"calc":[{"id":"c-cpach19-01","difficulty":1,"stem":"某公司税后净营业利润 500 万元，报表平均总资产 2000 万元，加权平均资本成本 10%。要求计算基本经济增加值（万元）。","blanks":[{"label":"基本经济增加值（万元）","answer":300,"tolerance":0.1}],"steps":["第1步：基本 EVA=税后净营业利润−报表平均总资产×加权平均资本成本=500−2000×10%=500−200=300 万元"],"formula_card":"基本 EVA=税后净营业利润−报表平均总资产×加权平均资本成本","analysis":"全部投入资本成本为 2000×10%=200 万元，税后净营业利润 500 万元扣除后得基本 EVA 300 万元，反映扣除资本成本后的真实剩余收益。","trap":"资本成本是全部投入资本成本，需用总资产乘以 WACC，不要漏乘 WACC 或只扣息税前利润。","tag":""},{"id":"c-cpach19-02","difficulty":2,"stem":"某公司在简化 EVA 下：净利润 300 万元，利息支出 40 万元，研究开发费用调整项 60 万元；另已知平均所有者权益 800 万元、平均带息负债 400 万元、平均在建工程 100 万元。要求计算税后净营业利润与调整后资本（万元）。","blanks":[{"label":"税后净营业利润（万元）","answer":375,"tolerance":0.1},{"label":"调整后资本（万元）","answer":1100,"tolerance":0.1}],"steps":["第1步：税后净营业利润=净利润+（利息支出+研发调整项）×（1−25%）=300+（40+60）×0.75=300+75=375 万元","第2步：调整后资本=平均所有者权益+平均带息负债−平均在建工程=800+400−100=1100 万元"],"formula_card":"税后NOPAT=净利润+（利息支出+研发调整项）×（1−25%）；调整后资本=平均所有者权益+平均带息负债−平均在建工程","analysis":"利息与研发调整项税后加回使经营利润升至 375 万元；资本占用扣除在建工程后净额为 1100 万元，二者将用于计算简化 EVA。","trap":"利息与研发调整项需先乘（1−25%）税后加回；在建工程从资本占用中扣除，不属于有效投入资本。","tag":""},{"id":"c-cpach19-03","difficulty":3,"stem":"某商业类充分竞争企业：净利润 400 万元，利息支出 50 万元，研发调整项 30 万元；平均所有者权益 1000 万元，平均带息负债 500 万元，平均在建工程 100 万元；股权资本成本率 6.5%（商业类充分竞争）。要求计算：(1)税后净营业利润；(2)调整后资本；(3)平均资本成本率（%）；(4)简化 EVA（万元）。","blanks":[{"label":"税后净营业利润（万元）","answer":460,"tolerance":0.1},{"label":"调整后资本（万元）","answer":1400,"tolerance":0.1},{"label":"平均资本成本率（%）","answer":6.83,"tolerance":0.01},{"label":"简化经济增加值（万元）","answer":364.33,"tolerance":0.1}],"steps":["第1步：税后净营业利润=400+（50+30）×（1−25%）=400+80×0.75=400+60=460 万元","第2步：调整后资本=1000+500−100=1400 万元","第3步：债权资本成本率=利息支出÷平均带息负债=50÷500=10%；平均资本成本率=10%×（1−25%）×（500/1500）+6.5%×（1000/1500）=2.5%+4.3333%=6.8333%","第4步：简化 EVA=税后净营业利润−调整后资本×平均资本成本率=460−1400×6.8333%=460−95.67=364.33 万元"],"formula_card":"税后NOPAT=净利润+（利息+研发）×（1−25%）；调整后资本=权益+带息负债−在建工程；WACC=债权成本×（1−25%）×债占比+股权成本×权占比","analysis":"税后净营业利润 460 万元，调整后资本 1400 万元，税后加权资本成本率约 6.83%，扣除资本成本 95.67 万元后得到简化 EVA 364.33 万元，为正说明创造了股东价值。","trap":"债权资本成本率要先由利息÷带息负债算出，且资本成本率均为税后口径（债权成本需乘 1−25%）；在建工程从资本中扣除后再乘 WACC。","tag":""}]},{"id":"f2_ch01","group":"保险公司财务管理","name":"第1章 保险公司财务管理概述","qa":[{"id":"qa-f2ch01-01","difficulty":1,"q":"简述保险公司财务管理相较于一般企业财务管理的特殊性主要体现在哪些方面。","answer_points":[{"point":"现金流特殊性","detail":"保险公司先收保费后承担赔付义务，现金流入先于流出，存在时间错配与滞后性；寿险现金流长期、持续、稳定，产险现金流短期、一次性且流出时间难以预料。"},{"point":"保费收入确认复杂","detail":"保费按权责发生制确认，需要提取未到期责任准备金，准备金提转差与利润此消彼长，不能简单以收到现金确认收入。"},{"point":"精算对利润影响大","detail":"责任准备金、保单红利等依赖精算假设计量，假设变动会显著影响当期利润，不同公司之间利润可比性较低。"},{"point":"动态现金流管理","detail":"需要对利率敏感现金流做持续监控，通过产品线分隔、资产与负债现金流预测、利率敏感度分析来管理资产负债匹配风险。"},{"point":"严格的外部监管约束","detail":"保险公司接受一般公认会计准则与法定会计准则双重会计标准约束，监管以偿付能力额度为核心，财务决策受资本、投资渠道等监管限制。"}],"framework":"按'现金流—收入确认—精算影响—动态管理—监管约束'五条逻辑展开，每条点出与一般企业的差异。","memo":"记忆钩子：'现保精动监'五字——现金流、保费收入、精算、动态、监管。易错：把保费直接当收入是常见误区。","tag":""},{"id":"qa-f2ch01-02","difficulty":2,"q":"对比利润最大化、股东利益最大化、公司价值最大化三个代表性目标，并说明利润最大化目标存在哪些缺陷。","answer_points":[{"point":"利润最大化","detail":"追求当期会计利润额最大，是早期代表性目标之一，关注绝对利润规模。"},{"point":"股东利益最大化","detail":"关注股东投入资本的回报率，强调为股东创造剩余收益，比利润最大化更重视资本效率。"},{"point":"公司价值最大化","detail":"以公司整体市场价值（债权市值加股权市值）最大为根本目标，综合协调所有者、保单持有人与监管方利益。"},{"point":"缺陷一：忽略时间价值","detail":"未考虑利润取得的时间，不同时点利润直接相加会失真，不能反映真实增值速度。"},{"point":"缺陷二：忽略投入资本","detail":"未考虑所获利润与投入资本规模的关系，同等利润下资本占用不同则效率不同。"},{"point":"缺陷三：忽略风险","detail":"未考虑所承担的风险水平，高利润可能伴随高风险，掩盖了真实经营质量。"},{"point":"缺陷四：诱发短期行为","detail":"片面追求当期利润容易诱发短期行为，牺牲长期价值换取眼前业绩。"}],"framework":"先并列说明三目标含义，再集中列出利润最大化的四类缺陷。","memo":"易错：股东利益最大化不等于公司价值最大化；利润最大化四缺陷是高频简答点。","tag":""},{"id":"qa-f2ch01-03","difficulty":2,"q":"说明保险公司财务管理目标的两个层次，并解释为何保证偿付能力是其基本目标。","answer_points":[{"point":"基本目标：保证偿付能力","detail":"偿付能力是保险公司拥有的资本超过法定资本最低水平的能力，是持续经营的前提。"},{"point":"根本目标：价值最大化","detail":"在协调各方利益基础上实现保险公司价值最大化，是财务管理的最终根本目标。"},{"point":"层次关系","detail":"偿付能力是价值最大化的前提与底线，无偿付能力公司无法存续，价值最大化无从谈起。"},{"point":"偿付能力含义","detail":"表现为资本对负债与风险的覆盖程度，监管以偿付能力额度为核心进行约束。"},{"point":"监管后果","detail":"偿付能力严重不足时，监管机构可采取限制资金运用渠道、限制高管薪酬、责令停业整顿乃至接管等措施。"},{"point":"实务含义","detail":"财务策略需在收益与偿付能力之间权衡，多数保险公司采取兼顾二者、以中立型为主的策略。"}],"framework":"先列两层次定义，再从前提关系、监管后果、策略权衡三层解释基本目标。","memo":"易错：基本目标是偿付能力、根本目标是价值最大化，二者不可混淆或颠倒。","tag":""},{"id":"qa-f2ch01-04","difficulty":3,"q":"综合分析保险公司财务管理与一般企业财务管理的异同，并说明精算师在保险公司财务管理中发挥的作用。","answer_points":[{"point":"相同点：对象与基本决策","detail":"对象均为资金及其流转，基本决策都包含筹资决策、投资决策、盈利分配决策三项。"},{"point":"不同点一：目标分层","detail":"保险公司目标分基本（保证偿付能力）与根本（价值最大化）两个层次，一般企业通常不强调偿付能力底线。"},{"point":"不同点二：双重监管","detail":"保险公司受一般公认会计准则与法定会计准则双重约束，以偿付能力监管为核心，一般企业监管侧重信息披露。"},{"point":"不同点三：利润受精算影响","detail":"责任准备金等依赖精算假设计量，假设变动显著影响利润，利润可比性弱于一般企业。"},{"point":"不同点四：现金流错配","detail":"保费流入先于赔付流出，寿险长期稳定、产险短期难料，需专门做利率敏感现金流管理。"},{"point":"精算师作用一：负债与定价","detail":"参与准备金评估与产品定价，直接决定负债规模与利润口径。"},{"point":"精算师作用二：资本与资产负债管理","detail":"参与资本管理、资产负债管理与监管沟通，并为投资决策提供精算支持。"},{"point":"角色转变","detail":"财务管理正从交易处理、报表编制向决策支持转变，精算师是连接精算与财务决策的桥梁。"}],"framework":"先同后异（目标、监管、利润、现金流四方面），再讲精算师两项职责与角色转变。","memo":"易错：精算师不仅计量准备金，也参与资本管理与投资决策；基本目标与根本目标勿混。","tag":""}],"calc":[{"id":"c-f2ch01-01","difficulty":1,"stem":"某财产保险公司本期保费收入1000万元，分出保费100万元，未到期责任准备金提转差150万元。计算本期已赚保费。","blanks":[{"label":"已赚保费（万元）","answer":750,"tolerance":0.5}],"steps":["第1步：写出公式 已赚保费=保费收入-分出保费-未到期责任准备金提转差","第2步：代入数据 已赚保费=1000-100-150","第3步：计算结果 已赚保费=750万元"],"formula_card":"已赚保费 = 保费收入 - 分出保费 - 未到期责任准备金提转差","analysis":"已赚保费反映本期实际承担保险责任对应的保费。1000-100-150=750万元，结果小于保费收入，因扣除了分出保费与尚未到期的责任准备金部分，符合权责发生制逻辑。","trap":"易把'未到期责任准备金提转差'误加而非减；注意提转差可正可负，此处按正数扣除。","tag":""},{"id":"c-f2ch01-02","difficulty":2,"stem":"某公司期末资产6000万元，负债4200万元，资本1200万元。分别计算所有者权益和资本率。","blanks":[{"label":"所有者权益（万元）","answer":1800,"tolerance":0.5},{"label":"资本率（%）","answer":20,"tolerance":0.5}],"steps":["第1步：所有者权益=资产-负债=6000-4200=1800万元","第2步：资本率=资本/资产=1200/6000=0.20","第3步：换算为百分比 0.20=20%"],"formula_card":"所有者权益 = 资产 - 负债；资本率 = 资本 / 资产","analysis":"所有者权益为1800万元，资本率为20%。资本率反映资本对资产的覆盖程度，20%说明资本占资产两成，偿付能力缓冲较充足。","trap":"资本率分母是资产而非所有者权益；勿用1200/1800算成约67%。","tag":""}]},{"id":"f2_ch02","group":"保险公司财务管理","name":"第2章 保险公司财务会计基本原理和报表体系概述","qa":[{"id":"qa-f2ch02-01","difficulty":1,"q":"简述我国企业会计信息的质量要求主要包括哪些内容。","answer_points":[{"point":"可靠性","detail":"以实际发生的交易或事项为依据，内容真实、金额可核，是会计信息的基础。"},{"point":"相关性","detail":"与使用者决策需要相关，有助于评价过去、预测未来，具备反馈与预测价值。"},{"point":"可理解性","detail":"会计信息应当清晰明了，便于使用者理解和使用。"},{"point":"可比性","detail":"同一企业不同期间口径一致，不同企业按统一标准列报，便于横向纵向比较。"},{"point":"实质重于形式","detail":"按经济实质而非仅法律形式核算，如融资租赁资产虽不拥有所有权仍应确认。"},{"point":"重要性","detail":"重要项目单独列报、充分披露，不重要项目可合并反映，避免信息冗余。"},{"point":"谨慎性","detail":"不高估资产或收益、不低估负债或费用，合理计提各项准备，但不计提秘密准备。"},{"point":"及时性","detail":"及时确认、计量和报告，不得提前或延后，保证信息时效。"}],"framework":"按'可靠、相关、可理解、可比、实质、重要、谨慎、及时'八项逐条展开。","memo":"记忆钩子：'可可靠相可实重谨及'。易错：谨慎性不等于可计提秘密准备。","tag":""},{"id":"qa-f2ch02-02","difficulty":2,"q":"说明保险公司财务报告体系的层次构成，并列举财务报表至少应包括的内容。","answer_points":[{"point":"财务报告","detail":"综合反映公司某一时点财务状况及某一期间经营成果、现金流量的书面报告，包括财务报表和财务状况说明书。"},{"point":"财务报表","detail":"财务报表是财务报告的核心，由报表本身与附注共同组成。"},{"point":"四表一注","detail":"根据《企业会计准则第30号》，财务报表至少包括资产负债表、利润表、现金流量表、所有者权益变动表和附注。"},{"point":"资产负债表","detail":"采用账户式结构，资产等于负债加所有者权益，左右双方平衡。"},{"point":"利润表","detail":"反映企业一定期间经营成果的动态报表，多采用多步式结构。"},{"point":"现金流量表","detail":"按收付实现制编制，将现金流量分为经营活动、投资活动和筹资活动三类。"},{"point":"所有者权益变动表","detail":"反映所有者权益各组成部分当期增减变动情况的报表。"},{"point":"附注","detail":"披露公司基本情况、编制基础、遵循准则声明、重要会计政策与估计、变更及差错更正、重要项目说明等。"}],"framework":"先画'财务报告＞财务报表＞报表加附注'层级，再列四表一注并逐一说明。","memo":"易错：财务报告不等于财务报表；附注是财务报表的必备组成部分而非补充。","tag":""},{"id":"qa-f2ch02-03","difficulty":2,"q":"对比权责发生制与收付实现制，并说明利润表与现金流量表分别基于何种会计基础编制。","answer_points":[{"point":"权责发生制","detail":"当期已经实现或已经发生、应负担的收入和费用计入当期，不论款项是否实际收付。"},{"point":"收付实现制","detail":"以款项的实际收付为标准确认收入和费用，收到即为收、付出即为付。"},{"point":"企业确认基础","detail":"我国企业会计的确认、计量和报告应当以权责发生制为基础。"},{"point":"利润表基础","detail":"利润表按权责发生制编制，反映应计制下的经营成果。"},{"point":"现金流量表基础","detail":"现金流量表按收付实现制编制，将权责发生制下的盈利信息调整为现金收支信息。"},{"point":"差异意义","detail":"二者结果常不一致，需以现金流量表验证利润的'含金量'，识别账面盈利与现金脱节。"}],"framework":"先定义两种会计基础，再分别对应利润表与现金流量表，最后点明差异意义。","memo":"易错：现金流量表用收付实现制，但企业整体确认基础仍是权责发生制。","tag":""},{"id":"qa-f2ch02-04","difficulty":3,"q":"结合保险公司经营特点，综合说明其资产负债表与利润表的主要特征。","answer_points":[{"point":"资产特征：投资资产占比大","detail":"保险公司存货比例很小，投资资产（有价证券、债权计划、不动产等）占资产比重很大。"},{"point":"金融资产占比高","detail":"金融资产和金融负债占资产、负债比重大，需按四分类列示，结构不同于工商企业。"},{"point":"负债特征：责任准备金为主","detail":"责任准备金是保险行业最主要的负债，寿险责任准备金一般占寿险公司总负债的70%以上。"},{"point":"资产负债表结构","detail":"采用账户式，左方列示资产、右方列示负债和所有者权益，金融企业可按流动性列示。"},{"point":"利润双构成","detail":"保险公司利润由承保利润与投资利润两部分组成，投资利润占比随承保业务积累逐年上升。"},{"point":"利润表项目","detail":"含已赚保费、投资收益、公允价值变动收益等，损失项目以'-'号填列，列示有专门要求。"},{"point":"列报特殊性","detail":"费用按功能分类为业务成本、管理、销售、财务费用等，保险公司报表项目有特殊列示规则。"}],"framework":"资产端、负债端讲资产负债表特征，再讲利润表双利润结构与列报特殊。","memo":"易错：责任准备金是负债不是资产；寿险准备金占总负债七成以上是高频考点。","tag":""}],"calc":[{"id":"c-f2ch02-01","difficulty":1,"stem":"某公司本期净利润800万元，其他综合收益（税后）120万元。计算综合收益总额。","blanks":[{"label":"综合收益总额（万元）","answer":920,"tolerance":0.5}],"steps":["第1步：写出公式 综合收益总额=净利润+其他综合收益（税后）","第2步：代入数据 综合收益总额=800+120","第3步：计算结果 综合收益总额=920万元"],"formula_card":"综合收益总额 = 净利润 + 其他综合收益（税后）","analysis":"综合收益总额920万元，涵盖已计入损益的净利润与直接计入权益的其他综合收益，完整反映本期权益总体变动。","trap":"其他综合收益须取税后金额；勿与利润表中净利润重复加总利润项目。","tag":""},{"id":"c-f2ch02-02","difficulty":2,"stem":"某公司本期营业收入2000万元，营业支出1400万元，营业外收入50万元，营业外支出30万元，所得税费用155万元。依次计算营业利润、利润总额、净利润。","blanks":[{"label":"营业利润（万元）","answer":600,"tolerance":0.5},{"label":"利润总额（万元）","answer":620,"tolerance":0.5},{"label":"净利润（万元）","answer":465,"tolerance":0.5}],"steps":["第1步：营业利润=营业收入-营业支出=2000-1400=600万元","第2步：利润总额=营业利润+营业外收入-营业外支出=600+50-30=620万元","第3步：净利润=利润总额-所得税费用=620-155=465万元"],"formula_card":"营业利润=营业收入-营业支出；利润总额=营业利润+营业外收入-营业外支出；净利润=利润总额-所得税费用","analysis":"营业利润600万元、利润总额620万元、净利润465万元，逐级扣减营业外收支与所得税，结果自洽合理。","trap":"营业外收支在营业利润之后计入利润总额；所得税费用仅减一次，勿在营业利润层提前扣除。","tag":""}]},{"id":"f2_ch03","group":"保险公司财务管理","name":"第3章 企业会计准则概况与保险公司经营实务","qa":[{"id":"qa-f2ch03-01","difficulty":1,"q":"简述中国企业会计准则体系的构成及施行时间。","answer_points":[{"point":"发布时间","detail":"财政部于2006年2月15日发布，包括1项基本准则、38项具体准则和首次发布的48项审计准则。"},{"point":"国际趋同","detail":"该体系与IFRS国际财务报告准则趋同，提升了我国会计准则的国际可比性。"},{"point":"施行时间","detail":"自2007年1月1日起在上市公司范围内施行，逐步推广至其他企业。"},{"point":"金融工具准则修订","detail":"2014年起陆续修订CAS22、CAS23、CAS24、CAS37等金融工具系列准则。"},{"point":"保险合同准则","detail":"CAS25《原保险合同》与CAS26《再保险合同》专门规范保险业务的会计处理。"}],"framework":"按'2006发布—2007施行—2014修订'时间线，并区分具体准则与审计准则数量。","memo":"易错：38项是具体准则而非审计准则；审计准则为48项，二者同期发布。","tag":""},{"id":"qa-f2ch03-02","difficulty":2,"q":"说明CAS22下金融资产的四分类及其后续计量基础。","answer_points":[{"point":"FVTPL（交易性）","detail":"以公允价值计量且其变动计入当期损益的金融资产，按公允价值计量，变动计入公允价值变动损益。"},{"point":"HTM持有至到期投资","detail":"有固定到期日、固定或可确定回收金额且企业有明确意图和能力持有至到期，按摊余成本计量。"},{"point":"L&R贷款和应收款项","detail":"贷款和应收款项类金融资产按摊余成本计量，采用实际利率法摊销。"},{"point":"AFS可供出售金融资产","detail":"按公允价值计量，公允价值变动计入所有者权益（其他综合收益），处置时转出计入投资收益。"},{"point":"金融负债分类","detail":"金融负债分为以公允价值计量且其变动计入当期损益的金融负债与其他金融负债两类。"},{"point":"重分类限制","detail":"持有至到期投资发生意图或能力改变时只能重分类为可供出售金融资产，重分类日公允价值与账面价值差额计入所有者权益。"}],"framework":"以'计量基础+损益归属'两维度列表说明四分类，并补金融负债与重分类规则。","memo":"易错：AFS变动进其他综合收益而非损益；HTM重分类仅能转为AFS。","tag":""},{"id":"qa-f2ch03-03","difficulty":2,"q":"对比保险公司四类原保险合同准备金的计提基础差异。","answer_points":[{"point":"未到期责任准备金UPR","detail":"为尚未终止的非寿险保险责任提取，按未到期风险计提，公式=（总保费收入-首日费用）×未到期天数/365。"},{"point":"未决赔款准备金OCR","detail":"为已发生尚未结案的赔款提取，包括已发生已报告赔款准备金和已发生未报告赔款准备金（IBNR），按精算结果计提。"},{"point":"寿险责任准备金","detail":"为承担寿险保险责任提取，按预期未来净现金流出的精算现值计量，是寿险公司最重要的负债。"},{"point":"长期健康险责任准备金","detail":"为承担长期健康险保险责任提取，同样按精算现值法计量。"},{"point":"共性特征","detail":"四类准备金均依赖精算假设计量，是保险行业最主要的负债，构成原保险合同准备金整体。"}],"framework":"按'非寿险流动、非寿险已发生、寿险、长期健康险'四类逐一说明计量方法。","memo":"易错：UPR按未到期风险用1/365法，OCR含IBNR，寿险用精算现值而非摊余成本。","tag":""},{"id":"qa-f2ch03-04","difficulty":3,"q":"综合说明保险公司原保险合同准备金的构成、保费收入确认条件，并解释再保险合同为何不解除原保险人的直接责任。","answer_points":[{"point":"准备金四类构成","detail":"原保险合同准备金包括未到期责任准备金、未决赔款准备金、寿险责任准备金、长期健康险责任准备金。"},{"point":"保费确认条件一","detail":"保险合同成立并承担相应保险责任，是确认保费收入的前提。"},{"point":"保费确认条件二","detail":"与保险合同相关的经济利益很可能流入企业。"},{"point":"保费确认条件三","detail":"与保险合同相关的收入和成本能够可靠地计量；投保人是否缴清全部保费并非必要条件。"},{"point":"确认时点差异","detail":"非寿险保费收入按合同约定分期确认，寿险保费收入通常于一次性或分期收取时确认。"},{"point":"再保险本质","detail":"再保险是分出人与接受人之间的补偿合同，转移的是赔付成本及其他费用，而非对被保险人的直接责任。"},{"point":"不解除直接责任","detail":"再保险合同不解除原保险人对被保险人的直接责任，原保险合同责任仍由分出人承担。"},{"point":"核算要求","detail":"分出人单独确认分出保费与应收分保账款，原保险合同与再保险合同损益不得相互抵销。"}],"framework":"先准备金四类和保费三条件，再聚焦再保险责任不解除及单独核算含义。","memo":"易错：保费确认不必缴清全款；再保转移的是风险成本而非直接责任。","tag":""}],"calc":[{"id":"c-f2ch03-01","difficulty":1,"stem":"某非寿险合同总保费收入3650万元，首日费用50万元，未到期天数73天（按1/365法）。计算未到期责任准备金。","blanks":[{"label":"未到期责任准备金（万元）","answer":720,"tolerance":0.5}],"steps":["第1步：写出公式 未到期责任准备金=（总保费收入-首日费用）×未到期天数/365","第2步：代入数据 （3650-50）×73/365=3600×73/365","第3步：计算结果 3600×73=262800；262800/365=720万元"],"formula_card":"未到期责任准备金 = （总保费收入 - 首日费用）× 未到期天数 / 365","analysis":"未到期责任准备金720万元，代表尚未终止的保险责任对应的负债，按1/365法分摊，数字干净为整数，符合源文件公式。","trap":"应以'总保费减首日费用'后的净额乘以未到期天数比例，勿直接用总保费3650乘；未到期天数指期间剩余天数。","tag":""},{"id":"c-f2ch03-02","difficulty":2,"stem":"再保险分出人本期分出保费200万元，摊回分保费用40万元，摊回分保赔款120万元，摊回分保准备金30万元；另应收分保未到期责任准备金150万元。分别计算再保险资产和再保险分出人对再保险接受人的应收款。","blanks":[{"label":"再保险资产（万元）","answer":250,"tolerance":0.5},{"label":"再保险分出人对接受人的应收款（万元）","answer":310,"tolerance":0.5}],"steps":["第1步：再保险资产=分出保费-摊回分保费用+摊回分保赔款-摊回分保准备金=200-40+120-30=250万元","第2步：应收款=分出保费+应收分保未到期责任准备金-已摊回分保费用=200+150-40=310万元","第3步：核对两式均含分出保费，口径一致、符号不同"],"formula_card":"再保险资产=分出保费-摊回分保费用+摊回分保赔款-摊回分保准备金；应收款=分出保费+应收分保未到期责任准备金-已摊回分保费用","analysis":"再保险资产250万元、应收款310万元，分别反映分入业务在资产端与应收端的净额，结果自洽。","trap":"两公式符号不同：摊回分保准备金在资产式中为减项，应收分保未到期责任准备金在收款式中为加项，勿混淆加减。","tag":""}]},{"id":"f2_ch04","group":"保险公司财务管理","name":"第4章 企业会计准则解释第2号执行实务","qa":[{"id":"qa-f2ch04-01","difficulty":1,"q":"简述重大保险风险测试的阈值规定及其在原保险合同与再保险合同适用上的差异。","answer_points":[{"point":"原保险合同阈值","detail":"原保险合同的保险风险比例达到或超过5%即视为转移了重大保险风险，应确认为保险合同。"},{"point":"再保险合同阈值","detail":"再保险合同的保险风险比例大于1%即视为重大保险风险，阈值较原保险更低。"},{"point":"差异原因","detail":"再保险转移的是原保险人已承担的赔付成本，风险集中度更高，故监管设定更低的阈值以严格约束。"},{"point":"保险风险比例定义","detail":"保险风险比例=（保险事故发生时保险人支付金额-不发生时支付金额）/不发生时支付金额。"},{"point":"不达标处理","detail":"未达阈值、不构成重大保险风险转移的合同，按金融工具或服务合同核算，不确认保费收入。"},{"point":"披露要求","detail":"保险公司应在附注中披露测试方法与分拆前后保费收入金额的对比。"}],"framework":"先给两项阈值，再解释差异原因及未达标的核算出路。","memo":"易错：原保险阈值≥5%、再保险阈值>1%，二者不等号方向不同，是高频易混点。","tag":""},{"id":"qa-f2ch04-02","difficulty":2,"q":"说明财务报告准备金的计量三原则及其构成。","answer_points":[{"point":"原则一：明确且当前估计","detail":"采用当前可获取的信息估计未来现金流，而非沿用历史假设，保证估计的现时性。"},{"point":"原则二：时间价值","detail":"对未来现金流进行折现，最佳估计负债使用无风险收益率折现以反映货币时间价值。"},{"point":"原则三：明确边际","detail":"准备金必须包含风险边际与剩余边际，使计量更谨慎、透明。"},{"point":"准备金构成","detail":"财务报告准备金=最佳估计负债+风险边际+剩余边际（残余边际）。"},{"point":"最佳估计负债BEL","detail":"基于当前信息与未来预期，对未来现金流现值的最佳估计，是准备金的核心部分。"},{"point":"三原则意义","detail":"使准备金计量区别于历史成本模式，更透明、可比，契合解释第2号的核心要求。"}],"framework":"三原则对应'估计—折现—边际'逻辑，再列三项构成相加。","memo":"易错：历史成本原则不属于三原则；BEL用无风险收益率而非预期市场收益率。","tag":""},{"id":"qa-f2ch04-03","difficulty":2,"q":"说明混合保险合同拆分与保费收入分拆的含义，以及不构成重大保险风险合同的核算方式。","answer_points":[{"point":"混合合同定义","detail":"同时包含保险风险与非保险风险（如投资风险、价格风险）多个合同要素的保险合同。"},{"point":"合同拆分","detail":"混合保险合同须进行拆分，将非保险风险部分作为独立的金融工具或服务合同单独核算。"},{"point":"保费收入分拆","detail":"将混合合同保费在保险风险与非保险风险之间分拆，分别确认为保费收入与其他业务收入。"},{"point":"纯保险合同","detail":"不含非保险风险的纯保险合同直接按原保险合同核算，无需拆分。"},{"point":"不达标合同核算","detail":"未通过重大保险风险测试的，不确认保费收入，按金融工具或服务合同核算。"},{"point":"案例印证","detail":"ABC公司某万能险保险风险比例8.5%大于5%，确认为保险合同并应进行混合合同拆分。"}],"framework":"先讲拆分概念，再区分达标（纯保险/保险合同）与不达标（金融工具/服务合同）两条出路。","memo":"易错：拆分针对混合合同；不达标合同不确认保费收入，易误当作保费处理。","tag":""},{"id":"qa-f2ch04-04","difficulty":3,"q":"综合列举风险边际的计量方法，说明剩余边际如何初始确认与摊销，并指出附注应披露哪些关键精算假设。","answer_points":[{"point":"风险边际方法","detail":"包括资本成本法、分位数法、置信区间法、情景对比法四种，企业可结合自身业务特点选择。"},{"point":"剩余边际初始确认","detail":"剩余边际=max(0,验证保费-最佳估计负债-风险边际)，在初始确认时锁定，不为负。"},{"point":"剩余边际摊销","detail":"在保险期内按系统合理的方法摊销，如与保险责任准备金现值或保费现值成比例摊销。"},{"point":"验证保费含义","detail":"验证保费反映保单未来预期利润或损失的现金流现值，用于验证剩余边际计算结果。"},{"point":"披露关键假设","detail":"附注应披露折现率、死亡率、退保率、费用率等关键精算假设。"},{"point":"披露其他内容","detail":"还应披露准备金计量方法、敏感性分析（如折现率变动50个基点、死亡率变动10%对负债的影响）。"},{"point":"首日费用处理","detail":"剩余边际在初始确认时吸收首日费用与预期亏损，是解释第2号规范利润释放的核心机制。"}],"framework":"分风险边际方法、剩余边际确认与摊销、披露假设三块综合展开。","memo":"易错：剩余边际取max(0,…)不会为负；平均年限法不是风险边际计量方法。","tag":""}],"calc":[{"id":"c-f2ch04-01","difficulty":1,"stem":"某原保险合同，保险事故发生时保险人支付108万元，不发生时支付100万元。计算保险风险比例，并判断是否属于重大保险风险合同。","blanks":[{"label":"保险风险比例（%）","answer":8,"tolerance":0.5}],"steps":["第1步：写出公式 保险风险比例=（事故发生时支付-不发生时支付）/不发生时支付","第2步：代入数据 （108-100）/100=8/100","第3步：计算结果 8%，因≥5%属于重大保险风险合同"],"formula_card":"保险风险比例 = （保险事故发生时支付金额 - 不发生时支付金额）/ 不发生时支付金额","analysis":"保险风险比例为8%，高于原保险合同5%阈值，应确认为保险合同并应进行混合合同拆分。","trap":"分母是'不发生时支付金额'而非'发生时支付金额'；原保险阈值5%、再保险阈值>1%，切勿混淆。","tag":""},{"id":"c-f2ch04-02","difficulty":2,"stem":"某保险合同最佳估计负债800万元，风险边际100万元，验证保费950万元。计算剩余边际初始金额与财务报告准备金。","blanks":[{"label":"剩余边际（万元）","answer":50,"tolerance":0.5},{"label":"财务报告准备金（万元）","answer":950,"tolerance":0.5}],"steps":["第1步：剩余边际=max(0,验证保费-最佳估计负债-风险边际)=max(0,950-800-100)=max(0,50)=50万元","第2步：财务报告准备金=最佳估计负债+风险边际+剩余边际=800+100+50=950万元","第3步：核对 报告准备金=验证保费，说明该合同初始无预期亏损"],"formula_card":"剩余边际=max(0,验证保费-最佳估计负债-风险边际)；财务报告准备金=最佳估计负债+风险边际+剩余边际","analysis":"剩余边际50万元、财务报告准备金950万元。验证保费等于准备金总额，表明合同初始无预期亏损，剩余边际为正待后续系统摊销。","trap":"剩余边际取max(0,…)不为负；勿把验证保费直接当准备金而漏减最佳估计负债与风险边际。","tag":""}]},{"id":"f2_ch05","group":"保险公司财务管理","name":"第5章 保险公司财务报告及分析","qa":[{"id":"qa-f2ch05-01","difficulty":1,"q":"保险公司开展财务分析的目的何在？哪些利益主体会使用其财务报告与分析结果？","answer_points":[{"point":"目的之一是了解过去","detail":"财务分析以财务报告和其他相关经济资料为依据，运用专门方法对保险公司历史财务状况与经营成果进行剖析，使各主体把握公司已发生的经营轨迹。"},{"point":"目的之二是评价现在","detail":"分析可评价公司当前的偿债能力、盈利能力和资产质量，为监管机构和投资人判断经营健康度提供量化依据。"},{"point":"目的之三是预测未来","detail":"在了解过去与评价现在的基础上，运用趋势与比率分析预测公司发展前景，辅助利益主体进行前瞻决策。"},{"point":"目的之四是改善决策","detail":"分析结果帮助经营管理当局、投保人、债权人等不同主体优化各自决策，但财务分析本身并不能直接创造保费收入。"},{"point":"主要使用者包括五类主体","detail":"分别为经营管理当局、监管机构、投资人、投保人与债权人，各自基于报告关注偿付能力、收益与风险等不同维度。"}],"framework":"从'目的四要素(过/现/未/策)'展开，再列举五类使用者，最后点明分析的三大作用(评价、监管、引导)。","memo":"目的记'过现未策'；使用者'管监投投保债'。","tag":""},{"id":"qa-f2ch05-02","difficulty":2,"q":"保险公司财务分析指标体系的设计应遵循哪些原则？请说明各原则的含义。","answer_points":[{"point":"规范性原则","detail":"指标的设置口径、计算方法和披露要求应符合会计准则与监管规范，保证不同公司之间可比、可监管。"},{"point":"实用性原则","detail":"指标须切合保险公司实际经营与管理需要，能真正反映业务和管理问题，而非流于形式或脱离实务。"},{"point":"敏感性原则","detail":"指标应对经营环境与业绩的变化足够敏感，能及时发出预警信号，便于管理层早期干预与纠偏。"},{"point":"互补性原则","detail":"各指标之间应相互补充、相互印证，形成有机整体，避免依赖单一指标而得出片面结论。"},{"point":"设计要求还需稳健适用","detail":"体系须反映不同利益主体需求、既覆盖经营全过程又体现各环节水平，并随管理水平提高而完善但保持相对稳定。"}],"framework":"先列四项原则逐一释义，再补'设计要求'三点收尾。","memo":"四原则记'规实敏补'。","tag":""},{"id":"qa-f2ch05-03","difficulty":2,"q":"产险公司计提未到期责任准备金有哪些方法？请对比其计提逻辑与适用场景。","answer_points":[{"point":"50%分法已被淘汰","detail":"假设保费在年度内均匀赚取，直接提取50%作为未赚保费准备金，方法粗放，已不再适用。"},{"point":"1/8法(季度法)适合再保实务","detail":"按季度权重1/8、3/8、5/8、7/8计提，假设风险在季度内均匀分布；因再保险公司多按季度接收分出保费，该法在再保中较适用。"},{"point":"1/24法(月度法)精度更高","detail":"按月度权重(2N-1)/24逐月计提，较季度法更细致，能更准地反映保费随时间赚取的实际进度。"},{"point":"方法演进体现精细化","detail":"从50%分法的粗放估计，到季度、月度法的逐步细化，未到期责任准备金的计提精度不断提高。"},{"point":"选用须匹配业务节奏","detail":"原保险公司多按月度或季度出单，再保业务按季分出，故方法选择要与保费流入的实际节奏相匹配。"}],"framework":"按'方法名称→计提逻辑→适用场景'逐一对比，最后总结演进与匹配。","memo":"50%淘汰，1/8季，1/24月。","tag":""},{"id":"qa-f2ch05-04","difficulty":3,"q":"试述保险公司偿付能力相关的财务分析指标体系，并说明各监管临界值的含义。","answer_points":[{"point":"资产负债率是核心指标(临界<75%)","detail":"资产负债率=负债总额÷资产总额×100%，反映长期偿债能力；非寿险公司正常应小于75%，寿险因负债结构不同可适当高些。"},{"point":"自留保费规模率衡量偿付风险(临界<400%)","detail":"自留保费规模率=本年自留保费÷(实收资本+公积金)×100%，自留保费不得超过资本金加公积金总和的4倍，指标越高承担风险越大。"},{"point":"流动比率反映短期偿付能力","detail":"与资产负债率、自留保费规模率同属偿付能力指标，用于监测公司对短期债务的支付保障程度。"},{"point":"不良资产风险率(临界<14%)","detail":"=不良资产余额÷年末所有者权益×100%，衡量资产质量，正常应小于14%，侧重于资产端风险而非直接偿付。"},{"point":"非认可资产与认可资产比(临界<10%)","detail":"限制不能用于清偿债务的非认可资产占比，比例越低说明资产真实偿债能力越强。"},{"point":"指标共同构成监管防线","detail":"上述指标从资本结构、规模风险、短期流动性与资产质量等不同维度监控资不抵债风险，是偿付能力监管的核心量化工具，需综合研判。"}],"framework":"以'核心(资产负债)+规模(自留保费)+短期(流动)+质量(不良/非认可)'为主线，逐项给公式与临界值，最后综合。","memo":"四临界值记'75 / 400 / 14 / 10'。","tag":""}],"calc":[{"id":"c-f2ch05-01","difficulty":1,"stem":"某寿险公司本年退保金支出为4亿元，年初长期险责任准备金为60亿元，本年长期险保费收入为40亿元。请计算该公司退保率，并判断其是否处于正常区间。","blanks":[{"label":"退保率(%)","answer":4.0,"tolerance":0.5}],"steps":["第1步：公式 退保率=本年退保金支出÷(年初长期险责任准备金+本年长期险保费收入)×100%","第2步：代入 退保率=4÷(60+40)×100%=4÷100×100%","第3步：结果 退保率=4.0%，对照正常区间应小于5%，处于达标区间"],"formula_card":"退保率=本年退保金支出÷(年初长期险责任准备金+本年长期险保费收入)×100%","analysis":"计算得退保率=4.0%，低于5%的正常临界值，说明该公司信用状况及续期保费管理绩效良好。退保率主要考察寿险公司的续期管理质量，数值越低越优。","trap":"分母为'年初长期险责任准备金+本年长期险保费收入'，不能误用年末数或只取保费收入；指标对照的是5%而非其他临界值。","tag":""},{"id":"c-f2ch05-02","difficulty":3,"stem":"某产险公司(开业5年)本年自留保费1300万元，未到期责任准备金150万元，长期责任准备金100万元，寿险提转差50万元，综合费用280万元，综合赔款支出620万元。请计算综合费用率与综合赔付率，并判断是否符合监管标准。","blanks":[{"label":"综合费用率(%)","answer":28.0,"tolerance":0.5},{"label":"综合赔付率(%)","answer":62.0,"tolerance":0.5}],"steps":["第1步：计算分母=自留保费-未到期责任准备金-长期责任准备金-寿险提转差=1300-150-100-50=1000万元","第2步：综合费用率=综合费用÷分母×100%=280÷1000×100%=28.0%","第3步：综合赔付率=综合赔款支出÷分母×100%=620÷1000×100%=62.0%","第4步：判断：开业3年以上公司综合费用率应<35%、综合赔付率应<65%，两项均达标"],"formula_card":"综合费用率=综合费用÷(自留保费-未到期责任准备金-长期责任准备金-寿险提转差)×100%；综合赔付率=综合赔款支出÷同分母×100%","analysis":"分母=1000万元；综合费用率28.0%低于35%临界值，费用控制良好；综合赔付率62.0%低于65%临界值，业务质量达标。两项均符合开业3年以上公司的监管要求。","trap":"分母不能直接用自留保费，必须扣除未到期责任准备金、长期责任准备金和寿险提转差；开业不足3年公司的综合费用率临界值为50%而非35%。","tag":""}]},{"id":"f2_ch06","group":"保险公司财务管理","name":"第6章 保险公司盈利及其管理","qa":[{"id":"qa-f2ch06-01","difficulty":1,"q":"保险公司的利润主要来自哪些方面？寿险公司利源分析中的'三差'分别指什么？","answer_points":[{"point":"保险利润由承保与投资两线构成","detail":"对产险而言，保险利润=承保利润+投资利润，二者共同构成盈利来源，体现承保与投资并重的盈利模式。"},{"point":"寿险盈利主要依赖投资收益","detail":"寿险业务期限长、负债久期长，其利源主要通过三差体现，投资收益往往是主要贡献。"},{"point":"死差：死亡率差异损益","detail":"死差来自实际死亡率与预期死亡率之间的差异，实际低于预期的死亡给付减少即形成死差益。"},{"point":"费差：费用率差异损益","detail":"费差来自实际费用率与预定费用率之间的差异，实际费用低于预算形成费差益。"},{"point":"利差：投资收益率差异损益","detail":"利差来自实际投资收益率与预定利率之间的差异，实际收益高于预定利率形成利差益。"},{"point":"三差共同构成寿险利源","detail":"寿险公司通过死差、费差、利差三者的组合实现利润，是寿险盈利管理与分析的核心框架。"}],"framework":"先说明利润两大来源，再分别释义三差(死/费/利)并收束到利源分析。","memo":"利润'承+投'；三差'死费利'。","tag":""},{"id":"qa-f2ch06-02","difficulty":2,"q":"杜邦分析体系以什么为核心指标？它是如何通过三层关系分解净资产收益率(ROE)的？","answer_points":[{"point":"核心指标是ROE","detail":"杜邦分析体系以净资产收益率(利润÷所有者权益)为核心，其他比率均围绕ROE层层展开与分解。"},{"point":"第一层：销售利润率反映盈利结构","detail":"销售利润率=利润÷销售收入，衡量单位收入转化为利润的能力，体现公司的盈利结构与定价水平。"},{"point":"第二层：资产周转率反映资产管理效率","detail":"资产周转率=销售收入÷总资产，衡量资产创造收入的效率，体现公司运用资产的运营能力。"},{"point":"第三层：财务杠杆系数反映杠杆运用","detail":"财务杠杆系数=总资产÷所有者权益，衡量公司利用负债放大股东回报的程度与财务风险。"},{"point":"三者连乘得ROE","detail":"ROE=销售利润率×资产周转率×财务杠杆系数，任一环节改善均可提升股东回报；产险公司常用此体系(由史密斯体系调整而来)。"}],"framework":"先点明核心ROE，再按'盈利结构→资产效率→财务杠杆'三层释义，最后给连乘公式。","memo":"ROE=销×周×杠。","tag":""},{"id":"qa-f2ch06-03","difficulty":2,"q":"影响保险公司盈利的因素有哪些？请从外部与内部两个层面进行分析。","answer_points":[{"point":"外部因素之一：宏观经济环境","detail":"宏观经济增长与利率走势直接影响保险需求、保费规模及资产端收益，是盈利的底层背景。"},{"point":"外部因素之二：资本市场","detail":"资本市场表现决定投资收益水平，而投资收益是保险公司(尤其寿险)盈利的重要来源。"},{"point":"外部因素之三：区域市场环境","detail":"区域市场的竞争强度、保险深度与密度影响承保利润空间和业务拓展成本。"},{"point":"外部因素之四：税收环境","detail":"2008年起内外资企业所得税税率统一为25%，营业税按保费等收入的5%征收，直接作用于税后利润。"},{"point":"外部因素之五：监管与会计制度","detail":"保险监管、偿付能力要求及会计准则变化会改变准备金计提与利润确认规则，传导至盈利。"},{"point":"内部因素：组织架构、业务结构与风险管理","detail":"组织架构(扁平化、后援集中、事业部制)、业务结构优劣与风险管理水平决定成本与承保质量，是盈利的内生驱动。"}],"framework":"分外部(宏观/资本/区域/税收/监管会计)与内部(组织/业务/风险)两层逐条展开。","memo":"外：宏观资本区域税收监管会计；内：组织业务风险。","tag":""},{"id":"qa-f2ch06-04","difficulty":3,"q":"保险公司盈利模式有哪些特点？我国保险业经历了哪些盈利模式的演变？","answer_points":[{"point":"特点一：更注重安全性","detail":"保险公司是负债经营企业，先收保费后担风险，必须优先保障偿付能力，安全性的权重高于一般工商企业。"},{"point":"特点二：更注重营销和服务","detail":"保险产品具有无形性与保障性，客户难以事前感知质量，故营销网络与理赔服务等成为竞争关键。"},{"point":"特点三：成本核算建立在估计基础上","detail":"由于风险具有不确定性，保单成本无法实时精确实测，只能依靠精算与大数法则进行估计。"},{"point":"模式一：渠道倍增模式","detail":"在保险供不应求时期，通过快速扩张代理人等渠道、做大保费规模实现盈利，是典型的粗放增长模式。"},{"point":"模式二：从产品到品牌模式","detail":"当供给趋丰，公司转向差异化产品设计与品牌建设，以产品与品牌溢价获取利润。"},{"point":"模式三：趋同模式","detail":"国际大型综合保险金融集团(如安联、AIG)普遍采用，表现为供应商、产品与辅助产品趋同，通过综合经营提升盈利。"},{"point":"演变路径清晰","detail":"整体路径为'渠道倍增→产品到品牌→趋同'，反映行业从规模驱动向价值与综合经营驱动的递进。"}],"framework":"先列三大特点，再按时间顺序梳理三种盈利模式，最后归纳演变路径。","memo":"特点'安全营销估计'；模式'渠道品牌趋同'。","tag":""}],"calc":[{"id":"c-f2ch06-01","difficulty":1,"stem":"某产险公司本年保费收入为600亿元，所有者权益为200亿元。请计算肯尼系数(保费收入与所有者权益比率)，并判断其偿付能力风险水平。","blanks":[{"label":"肯尼系数","answer":3.0,"tolerance":0.1}],"steps":["第1步：公式 肯尼系数=保费收入÷所有者权益","第2步：代入 肯尼系数=600÷200","第3步：结果 肯尼系数=3.0，对照美国标准3左右处于合理区间"],"formula_card":"肯尼系数=保费收入÷所有者权益","analysis":"计算得肯尼系数=3.0，与美国保险市场公认的合理标准(约3)一致，偿付能力风险处于合理水平；欧洲市场通常允许6-8。该系数越低资本越雄厚，过高则偿付能力风险增大。","trap":"分子是保费收入而非总资产， denominator是所有者权益而非总资产；肯尼系数与资产负债率口径不同，勿混淆。","tag":""},{"id":"c-f2ch06-02","difficulty":3,"stem":"某公司本年利润40亿元，销售收入800亿元，总资产400亿元，所有者权益200亿元。请用杜邦分析法分解ROE，计算销售利润率、资产周转率、财务杠杆系数及ROE，并相互验证。","blanks":[{"label":"销售利润率(%)","answer":5.0,"tolerance":0.5},{"label":"资产周转率(次)","answer":2.0,"tolerance":0.1},{"label":"财务杠杆系数","answer":2.0,"tolerance":0.1},{"label":"净资产收益率ROE(%)","answer":20.0,"tolerance":0.5}],"steps":["第1步：销售利润率=利润÷销售收入=40÷800×100%=5.0%","第2步：资产周转率=销售收入÷总资产=800÷400=2.0次","第3步：财务杠杆系数=总资产÷所有者权益=400÷200=2.0","第4步：ROE=销售利润率×资产周转率×财务杠杆系数=5.0%×2.0×2.0=20.0%；验证：利润÷所有者权益=40÷200=20.0%，结果一致"],"formula_card":"ROE=销售利润率×资产周转率×财务杠杆系数=(利润/销售收入)×(销售收入/总资产)×(总资产/所有者权益)","analysis":"三层分解显示：盈利结构偏薄(销售利润率仅5.0%)，但凭借较高的资产运营效率(2.0次)和适度财务杠杆(2.0)，ROE达到20.0%。直接法40÷200=20.0%与分解法一致，验证无误。","trap":"资产周转率与财务杠杆系数均用到总资产，注意分子分母区分；销售利润率为百分比，参与连乘后ROE亦为百分比，勿漏乘100%。","tag":""}]},{"id":"f2_ch08","group":"保险公司财务管理","name":"第8章 保险资金投资及其管理","qa":[{"id":"qa-f2ch08-01","difficulty":1,"q":"保险资金具有哪三大基本特性？请说明其含义，并指出首要特性。","answer_points":[{"point":"负债性是首要特性","detail":"保费收入中的纯保费部分本质上是负债，须以准备金形式提留用于未来赔付，保险资金来源具有鲜明的负债属性。"},{"point":"长期性","detail":"寿险等负债期限很长，对应的保险资金可长期运用，便于配置长久期资产以获取稳定收益。"},{"point":"稳定性","detail":"保费收入持续、规律地流入，使保险资金规模总体稳定，有利于开展中长期资产配置。"},{"point":"准备金是资金主体","detail":"各项保险准备金在保险资金中占主体地位，资本金占比虽不大但被称为资金运用的'灵魂'。"}],"framework":"直接列出负债性、长期性、稳定性三大特性并释义，强调负债性为首，补'准备金主体'要点。","memo":"三特性'负长稳'，负债性首要。","tag":""},{"id":"qa-f2ch08-02","difficulty":2,"q":"保险资金投资应遵循哪些原则？其中'三性兼顾、安全第一'对安全性、流动性、收益性如何定位？","answer_points":[{"point":"匹配原则是首要原则","detail":"由保险资金来源的负债性与长期性决定，资产与负债在金额、期限、现金流上需匹配，是投资运用的首要约束。"},{"point":"安全性是前提","detail":"在'三性兼顾、安全第一'中，安全性是投资运用的前提，只有保住本金才能谈收益，关乎偿付能力。"},{"point":"流动性是基础","detail":"流动性是基础，保证资产能及时变现以应对赔付与退保等现金需求，维持正常经营。"},{"point":"收益性是目标","detail":"收益性是目标，在安全与流动得到满足后追求合理回报，提升公司价值与偿付能力。"},{"point":"其他投资原则","detail":"还包括以投资级固定收益工具为主要对象、适度配置高风险证券或非证券资产，以及根据多因素确定账户投资策略。"}],"framework":"先点明匹配首要，再按'安全前/流基/收目'定位三性，最后补其余原则。","memo":"匹配首要；安前流基收目。","tag":""},{"id":"qa-f2ch08-03","difficulty":2,"q":"资产战略配置与战术性资产配置有何区别？请从多个维度进行比较。","answer_points":[{"point":"考虑期限不同","detail":"战略配置着眼长期(通常3-5年以上)，确定大类资产比例；战术配置是中短期安排，对配置进行灵活微调。"},{"point":"关注重点不同","detail":"战略配置关注股票、债券、基金等不同大类资产间的比例分配；战术配置更强调同类资产中不同证券或品种的选择与转换。"},{"point":"调整难度不同","detail":"战略配置涉及核心比例，调整成本高、难度大；战术配置在类型内部操作，实施相对容易。"},{"point":"对收益影响程度不同","detail":"战略配置决定了组合的风险收益骨架，对长期收益影响更大；战术配置主要影响短期超额收益。"},{"point":"概念界定","detail":"战略配置是对全部资金的初次分配及后续调整，战术配置是在资产类型内部或子类型间的中短期调整，二者相辅相成。"}],"framework":"按'期限/重点/难度/影响'四维度对比，最后回扣概念界定。","memo":"区别看'期限重点难度影响'。","tag":""},{"id":"qa-f2ch08-04","difficulty":3,"q":"保险资金投资绩效评估应包含哪些内容？请说明收益、风险及风险调整收益三类衡量指标。","answer_points":[{"point":"收益衡量是基础","detail":"绩效评估首先要衡量收益，包括绝对收益与相对收益，用以反映投资组合的获利水平。"},{"point":"风险衡量不可或缺","detail":"风险可用标准差、VaR(正常市况下给定置信水平与时段的最大可能损失)及β系数等指标衡量。"},{"point":"风险调整收益消除风险不可比","detail":"单纯收益无法跨风险比较，需用风险调整收益指标，使不同风险水平的组合具有可比性。"},{"point":"夏普指数用总风险","detail":"夏普指数S_p=(r_p−r_f)/σ_p，以总风险(标准差)为分母，衡量每单位总风险获得的超额收益。"},{"point":"特雷诺指数用系统风险","detail":"特雷诺指数T_p=(r_p−r_f)/β_p，以系统风险β为分母，衡量每单位系统风险的超额收益。"},{"point":"詹森指数看与SML的偏差","detail":"詹森指数J_p=r_p−[r_f+(r_m−r_f)β_p]，衡量组合实际收益与证券市场线期望收益之差，大于0表示跑赢市场。"}],"framework":"按'收益→风险→风险调整收益'三层展开，重点区分夏普(总风险)、特雷诺(系统风险)、詹森(超额差)三指标。","memo":"夏普总、特雷诺系、詹森差。","tag":""}],"calc":[{"id":"c-f2ch08-01","difficulty":1,"stem":"某投资组合年化收益率为12%，无风险利率为3%，收益率标准差为6%。请计算该组合的夏普指数。","blanks":[{"label":"夏普指数","answer":1.5,"tolerance":0.1}],"steps":["第1步：公式 夏普指数S_p=(r_p−r_f)/σ_p","第2步：代入 S_p=(12%−3%)÷6%=9%÷6%","第3步：结果 S_p=1.5"],"formula_card":"S_p=(r_p−r_f)/σ_p","analysis":"计算得夏普指数为1.5，表示每承担1单位总风险可获得1.5单位超额收益，风险调整后收益较好。该指数越高，单位风险的补偿越优。","trap":"分母为总风险(标准差σ_p)而非系统风险β；分子须用超额收益(r_p−r_f)，收益率口径(小数或百分比)须统一。","tag":""},{"id":"c-f2ch08-02","difficulty":3,"stem":"某保险公司上年末总资产为2000亿元，其中投资连结保险产品资产200亿元、万能保险产品资产100亿元。监管要求：传统保险产品投资股票余额按成本价计算，不得超过上年末总资产扣除投连、万能资产后的5%。若该公司传统险股票投资成本余额为90亿元，请判断是否合规。","blanks":[{"label":"可投资基数(亿元)","answer":1700.0,"tolerance":0.1},{"label":"股票投资上限(亿元)","answer":85.0,"tolerance":0.1}],"steps":["第1步：可投资基数=上年末总资产-投连资产-万能资产=2000-200-100=1700亿元","第2步：股票投资上限=可投资基数×5%=1700×5%=85亿元","第3步：判断：实际传统险股票投资余额90亿元>85亿元上限，超出5亿元，不合规"],"formula_card":"传统险股票投资上限=(上年末总资产-投连资产-万能资产)×5%","analysis":"可投资基数为1700亿元，法定股票投资上限为85亿元，而公司实际持有90亿元，超限5亿元，违反监管比例，需减仓至85亿元以内方能合规。","trap":"基数须先扣除投连与万能产品资产，不能直接用总资产2000×5%=100亿元；传统险(5%)与投连险(可100%)、万能险(可80%)的持股比例规定不同，勿混淆。","tag":""}]},{"id":"f2_ch10","group":"保险公司财务管理","name":"第10章 保险公司偿付能力及监管","qa":[{"id":"qa-f2ch10-01","difficulty":1,"q":"简述保险公司偿付能力的概念，并说明衡量偿付能力时需要关注哪些关键资本指标。","answer_points":[{"point":"偿付能力的定义","detail":"偿付能力是保险公司偿付到期债务（特别是赔款和给付）的能力，是公司稳健经营的基础，直接关系到保单持有人利益能否实现。"},{"point":"实际资本","detail":"实际资本等于认可资产减去认可负债的差额，反映保险公司可用于抵偿损失的资本规模，是判断公司真实偿付实力的分子项。"},{"point":"最低资本","detail":"最低资本是由监管部门规定的、保险公司必须保持的最低偿付能力额度，是偿付能力的及格线，实际资本低于该线将面临监管干预。"},{"point":"偿付能力充足率","detail":"偿付能力充足率等于实际资本除以最低资本，是衡量偿付能力是否达标的核心比率；低于100%即被认定为不足类公司。"},{"point":"经济资本","detail":"经济资本是在一定置信水平（如欧II要求的99.95%）下为抵偿非预期损失所需的资本，比法定最低资本更贴合公司真实风险轮廓。"}],"framework":"从定义出发，按实际资本、最低资本、充足率、经济资本逐层展开，先讲静态概念再讲风险量化口径。","memo":"易混：偿付能力≠盈利能力；充足率=实际资本÷最低资本（分子是实际资本）。","tag":""},{"id":"qa-f2ch10-02","difficulty":2,"q":"对比美国RBC体系与欧盟Solvency II在偿付能力监管思路上的主要差异。","answer_points":[{"point":"美国RBC采用风险资本系数乘数模型","detail":"将风险分为C0资产、C1保险、C2利率、C3业务、C4其他五类，按固定系数加权汇总为风险资本总额R，再与调整后资本比较得出风险资本比率。"},{"point":"RBC按比率划分五个监管行动等级","detail":"200%以上无行动，150%-200%提交RBC计划，100%-150%公司行动，70%-100%监管行动，70%以下强制行动；监管介入随比率下降而递增。"},{"point":"欧盟Solvency II采用三支柱全面框架","detail":"第一支柱定量（技术准备金、MCR、SCR、投资规则），第二支柱监管检查流程（SRP），第三支柱信息披露（SFCR），覆盖定量与治理全维度。"},{"point":"Solvency II以经济资本和VaR为基础","detail":"MCR和SCR均采用99.95%一年期VaR，资本要求直接挂钩公司自身风险分布，而非固定系数，更强调风险敏感性。"},{"point":"监管哲学差异：RBC偏规则导向，Solvency II偏原则与风险导向","detail":"RBC用相对简单的乘数快速识别弱公司；Solvency II要求公司自行建模并自证偿付能力，注重内部风险管理与监管评估结合。"},{"point":"两者均配套动态测试工具","detail":"美国有CFT现金流测试，欧盟要求ORSA自我风险与偿付能力评估，目的都是检验不利情景下未来期间的持续偿付能力。"}],"framework":"分风险量化方法、监管触发机制、框架结构、资本计量基础、监管理念、动态测试六点对比。","memo":"易错：RBC五个等级阈值是70/100/150/200；Solvency II置信水平为99.95%VaR。","tag":""},{"id":"qa-f2ch10-03","difficulty":2,"q":"说明中国偿付能力监管的分类标准及各分类对应的监管含义。","answer_points":[{"point":"分类依据为偿付能力充足率","detail":"充足率=实际资本÷最低资本，是衡量达标的核心比率；监管据此将公司划分为三类并采取差异化措施。"},{"point":"不足类：充足率<100%","detail":"实际资本已不足以覆盖最低资本要求，监管会限制业务范围、责令增资、限制高管薪酬乃至接管或撤销许可，是最严厉的干预等级。"},{"point":"充足I类：100%≤充足率≤150%","detail":"公司达标但安全边际有限，监管重点关注资本补充与业务扩张的匹配，要求持续监测防止滑向不足类。"},{"point":"充足II类：充足率>150%","detail":"资本充裕、安全边际高，监管以常规监测为主，公司有较大空间开展新业务和运用财务杠杆。"},{"point":"一代监管借鉴Solvency I比率模型","detail":"中国一代偿付能力以实际资本和最低资本计算比率，方法上接近欧盟Solvency I，尚未充分挂钩风险。"},{"point":"二代监管沿用三支柱框架","detail":"中国偿二代保留三支柱结构，逐步从比率模型过渡到风险模型，并规划引入经济资本，提升风险敏感性。"}],"framework":"以比率公式、三类阈值、每类监管措施、代际演进为顺序组织答案。","memo":"阈值100%和150%是分界线；注意区间是含还是不含（充足I类为100%-150%）。","tag":""},{"id":"qa-f2ch10-04","difficulty":3,"q":"综合分析：保险公司为何需要动态偿付能力测试（CFT/DCAT），它与静态监管比率之间存在什么关系？","answer_points":[{"point":"静态比率只能反映当前时点的偿付能力","detail":"实际资本÷最低资本是存量指标，无法揭示未来利率、赔付、退保等情景变化下资本是否仍充足，存在时点盲区。"},{"point":"动态测试检验不利情景下的持续偿付能力","detail":"美国CFT四步骤（确定情景、评估反应、计算现金流、汇总结果）和加拿大DCAT五步骤，均在未来多年期不利假设下模拟现金流，提前暴露脆弱性。"},{"point":"揭示风险的交互作用","detail":"如GA公司案例所示，利率风险与流动性风险会叠加放大；静态比率难以捕捉多风险联动，动态测试能展现复合冲击下的资本消耗。"},{"point":"支持资本与业务规划","detail":"动态测试结果用于评估新业务增长、再保险安排和红利政策的可持续性，是资本需求评估（RBC、情景分析、概率评估）的重要输入。"},{"point":"与静态监管互补而非替代","detail":"静态充足率是日常监管门槛和分类依据，动态测试是前瞻性压力工具；二者结合形成当前达标加未来可持续的完整监管闭环。"},{"point":"已成为国际监管趋势","detail":"美国CFT、加拿大DCAT、欧盟ORSA均属动态测试，中国2007年发布动态偿付能力测试指南，体现从比率模型向风险模型过渡的方向。"}],"framework":"先点出静态比率局限，再展开动态测试功能、风险交互、规划支持，最后落到互补与国际趋势的综合结论。","memo":"CFT由美国CDA于1990年代提出；DCAT为加拿大；易混CFT四步与DCAT五步。","tag":""}],"calc":[{"id":"c-f2ch10-01","difficulty":1,"stem":"某保险公司经评估，认可资产为200亿元，认可负债为80亿元，监管规定的最低资本为100亿元。要求计算该公司的实际资本与偿付能力充足率，并判断其监管分类。","blanks":[{"label":"实际资本（亿元）","answer":120,"tolerance":0.5},{"label":"偿付能力充足率（%）","answer":120,"tolerance":0.5}],"steps":["第1步：实际资本 = 认可资产 − 认可负债 = 200 − 80 = 120（亿元）","第2步：偿付能力充足率 = 实际资本 ÷ 最低资本 × 100% = 120 ÷ 100 × 100% = 120（%）","第3步：判定分类：充足率120%落在100%-150%区间，属充足I类"],"formula_card":"实际资本 = 认可资产 − 认可负债；偿付能力充足率 = 实际资本 ÷ 最低资本 × 100%","analysis":"实际资本为120亿元，充足率为120%，高于100%及格线但低于150%，监管分类为充足I类，安全边际有限需持续监测。","trap":"易把充足率算成最低资本÷实际资本（颠倒分子分母）；注意单位区分亿元与百分比。","tag":""},{"id":"c-f2ch10-02","difficulty":2,"stem":"某财险公司本年度自留保费收入为3亿元，自留赔款支出为0.6亿元，实际资本为0.8亿元。按中国偿付能力监管规定，分别用保费法和赔款法计算最低资本，并据保费法结果计算偿付能力充足率、判定监管分类。","blanks":[{"label":"最低资本（保费法，亿元）","answer":0.5,"tolerance":0.5},{"label":"最低资本（赔款法，亿元）","answer":0.156,"tolerance":0.5},{"label":"偿付能力充足率（保费法，%）","answer":160,"tolerance":0.5}],"steps":["第1步：保费法最低资本 = 1亿×18% + (3−1)亿×16% = 0.18 + 0.32 = 0.50（亿元）","第2步：赔款法最低资本 = 0.6亿×26%（全部在7000万以下档）= 0.156（亿元）","第3步：充足率 = 实际资本 ÷ 保费法最低资本 × 100% = 0.8 ÷ 0.5 × 100% = 160%，>150%属充足II类"],"formula_card":"保费法：1亿以下×18% + 1亿以上×16%；赔款法：7000万以下×26% + 7000万以上×23%；充足率 = 实际资本 ÷ 最低资本","analysis":"保费法最低资本0.50亿元、赔款法0.156亿元（法定最低资本取两法较大者，本题保费法更大），按保费法充足率160%，属充足II类，资本充裕。","trap":"赔款法需先判断赔款落在哪个分档（0.6亿<7000万，全按26%）；充足率以法定最低资本（两法取大）为分母，本题取保费法0.5亿元。","tag":""}]},{"id":"f2_ch11","group":"保险公司财务管理","name":"第11章 保险公司的资本和盈余管理","qa":[{"id":"qa-f2ch11-01","difficulty":1,"q":"简述保险公司资本管理的目的，以及资本管理需要回答的核心问题有哪些。","answer_points":[{"point":"目的具有双重性","detail":"在满足偿付能力监管约束的前提下提升资本效率，既要守住风险底线，又要平衡股东与保单持有人利益，追求资本价值最大化。"},{"point":"核心问题一：需要多少资本（规模）","detail":"评估必备资本（支撑现有业务）与成长资本（支持新业务）之和，并设定高于二者的目标资本作为战略缓冲。"},{"point":"核心问题二：资本从哪里来（来源）","detail":"分为内部来源（留存收益、隐藏资本等）和外部来源（股权、次级债、再保险等），需权衡成本与可行性。"},{"point":"核心问题三：资本结构与成本","detail":"通过杠杆配置债务与股权比例，利用财务杠杆提升ROE，同时控制资本成本并管理风险放大效应。"},{"point":"核心问题四：资本如何分配（盈余）","detail":"涉及股利政策和留存比例决策，需兼顾再投资需求、股东偏好、税收与偿付能力约束。"}],"framework":"先讲目的双重性，再按规模、来源、结构/成本、分配五个问题展开（来源、结构、成本、分配）。","memo":"资本管理五问：规模、来源、结构、成本、分配；目的=偿付能力达标+资本效率。","tag":""},{"id":"qa-f2ch11-02","difficulty":2,"q":"比较保险公司内部资本来源与外部资本来源的主要方式及各自适用特征。","answer_points":[{"point":"内部来源之一：留存收益","detail":"包括未分配盈余，是成本最低、最稳定的资本补充方式，但受当期盈利水平限制，快速扩张期可能不足。"},{"point":"内部来源之二：隐藏资本（或有资本）","detail":"通过会计政策选择或科目重分类隐含在报表中的资本，可优化资本结构、延迟外部注资，但透明度较低。"},{"point":"内部来源之三：减少风险暴露与优化资产配置","detail":"缩减高风险业务、剥离高风险资产可降低资本需求，等同释放资本，属于节流型来源。"},{"point":"外部来源之一：股权融资","detail":"公开发行或私募股票资本成本较高但不增加偿债压力，适合大规模长期资本补充，会稀释原股东股权。"},{"point":"外部来源之二：次级债与混合资本工具","detail":"次级债期限≥5年、受偿序位于保单责任后股权前，兼具债与资本属性；还有混合资本债、保险资产证券化等。"},{"point":"外部来源之三：再保险安排","detail":"财务再保险可将部分风险与资本转移给再保人，释放承保能力，属于特殊外部资本工具，受专门监管。"}],"framework":"按内部（留存、隐藏、减风险）与外部（股权、次级债、再保险）分组，每组点出成本与适用特征。","memo":"公开发行股票属外部（易错归为内部）；隐藏资本靠会计安排而非真实现金流入。","tag":""},{"id":"qa-f2ch11-03","difficulty":2,"q":"说明财务再保险的概念、主要类型及其与传统再保险的根本区别。","answer_points":[{"point":"财务再保险以改善财务报表为目的","detail":"其核心特征是以财务目标（平衡利润、税务、业务扩大、资金流向）为主，而非分散承保风险，这是与传统再保险的根本区别。"},{"point":"类型一：财务成数比例再保险","detail":"原保险人将部分保费和赔款按比例转移给再保人，改善资本结构或释放承保能力，原理上盈余变化=分入保费−分入赔款。"},{"point":"类型二：时间和距离再保险","detail":"按时间或距离维度转移赔款责任，常跨越多个会计年度安排，用于平滑利润波动。"},{"point":"类型三：赔款责任转移再保险","detail":"将存量赔款责任转移以释放资本，案例显示保费/盈余比由3.33:1改善为2.32:1，直接优化报表比率。"},{"point":"其他类型：追溯与预期超额赔款再保险","detail":"还包括追溯累计超额赔款、预期再保险（含预期累计超额赔款）等，均侧重于财务效果而非风险分散。"},{"point":"受专门监管规范","detail":"如台湾地区2002年发布处理要点，要求签约前评估财务影响、确认交易公平性并披露信息，防范滥用报表操纵。"}],"framework":"先定义与核心特征，再列主要类型，最后落到与传统再保险的区别及监管。","memo":"根本区别：财务再保险重报表、传统再保险重风险分散；信用再保险不属于财务再保险。","tag":""},{"id":"qa-f2ch11-04","difficulty":3,"q":"综合分析：保险公司运用财务杠杆提升ROE的机理、收益与风险，并说明资本结构决策应考虑的因素。","answer_points":[{"point":"杠杆提升ROE的机理","detail":"公式ROE1=ROIC+(ROIC−r0')×(D/E)表明，当资产回报率ROIC高于负债利率r0'时，举债放大股东回报，正的财务杠杆提升ROE。"},{"point":"杠杆同时放大风险","detail":"公式Var(ROE1)=(1+D/E)²×Var(ROIC)显示，负债比例越高ROE波动越大；当D/E=1时方差放大为原ROIC方差的4倍。"},{"point":"收益与风险并存需权衡","detail":"杠杆在ROIC>r0'时增厚收益，但市场恶化时ROIC下滑会使杠杆转为负向，资本结构决策须兼顾期望回报与波动承受度。"},{"point":"受偿付能力约束上限","detail":"杠杆不能突破监管资本红线，次级债等工具虽补充资本但受偿序靠后，过度负债会侵蚀实际资本与安全边际。"},{"point":"结合资本来源与成本","detail":"需在股权（贵但稳）与次级债/借款（廉但有偿还压力）间权衡，参考RBC风险系数（如不动产18%）评估资本消耗。"},{"point":"与盈余分配政策协调","detail":"杠杆释放的资本应用于高回报业务或留存补充，股利政策须匹配再投资需求与偿付能力约束，避免分红削弱资本。"}],"framework":"从机理（公式11-3）、风险（公式11-5）、权衡、监管约束、来源成本、盈余协调综合论述，体现公式支撑。","memo":"关键公式：ROE1=ROIC+(ROIC−r0')·(D/E)；Var(ROE1)=(1+D/E)²·Var(ROIC)；注意ROIC>r0'才加杠杆。","tag":""}],"calc":[{"id":"c-f2ch11-01","difficulty":1,"stem":"某保险公司资本回报率ROIC为12%，负债利率r0'为8%，目前资产负债比D/E=0.5。按杠杆后ROE公式，计算举债后的ROE。","blanks":[{"label":"杠杆后ROE（%）","answer":14,"tolerance":0.5}],"steps":["第1步：套用公式 ROE1 = ROIC + (ROIC − r0') × (D/E)","第2步：代入 ROE1 = 12% + (12% − 8%) × 0.5 = 12% + 4% × 0.5","第3步：计算 ROE1 = 12% + 2% = 14%"],"formula_card":"ROE1 = ROIC + (ROIC − r0') × (D/E)","analysis":"因ROIC(12%)>r0'(8%)，正财务杠杆使ROE由无杠杆的12%升至14%，举债增厚了股东回报。","trap":"注意D/E是负债权益比而非资产负债率；括号内先算(ROIC−r0')再乘D/E，别漏掉杠杆项。","tag":""},{"id":"c-f2ch11-02","difficulty":2,"stem":"某保险公司资产回报率ROIC为10%，负债利率r0'为6%，资产负债比D/E=1，ROIC的方差Var(ROIC)=0.04。要求计算杠杆后ROE及其方差，并说明风险放大倍数。","blanks":[{"label":"杠杆后ROE（%）","answer":14,"tolerance":0.5},{"label":"杠杆后ROE方差","answer":0.16,"tolerance":0.5}],"steps":["第1步：ROE1 = ROIC + (ROIC − r0') × (D/E) = 10% + (10% − 6%) × 1 = 14%","第2步：Var(ROE1) = (1 + D/E)² × Var(ROIC) = (1 + 1)² × 0.04 = 4 × 0.04","第3步：计算 Var(ROE1) = 0.16；放大倍数 = 0.16 ÷ 0.04 = 4倍（D/E=1时恰为4倍）"],"formula_card":"ROE1 = ROIC + (ROIC − r0') × (D/E)；Var(ROE1) = (1 + D/E)² × Var(ROIC)","analysis":"杠杆后ROE为14%，方差由0.04升至0.16，放大4倍，印证杠杆在增厚收益的同时等倍放大风险。","trap":"方差公式含(1+D/E)²而非(1+D/E)；D/E=1时放大系数恰为4，但一般情形需用平方计算。","tag":""}]},{"id":"f2_ch13","group":"保险公司财务管理","name":"第13章 保险公司全面预算和绩效管理","qa":[{"id":"qa-f2ch13-01","difficulty":1,"q":"简述保险公司全面预算的概念、构成内容及编制起点。","answer_points":[{"point":"全面预算的概念","detail":"它是企业在一年或既定期间内经营、财务、投资等价值流的总体计划，是公司战略目标和年度计划的细化，预算管理则是将这些计划量化并动态控制的方法。"},{"point":"构成之一：经营预算","detail":"在销售预算基础上编制，涵盖生产、存货、成本、费用、资本支出、现金等日常经营财务预算，是预算的执行主体。"},{"point":"构成之二：报表预算","detail":"以预算资产负债表、预算损益表、预算现金流量表反映，将经营结果汇总为三张预算报表，便于与战略对标。"},{"point":"编制起点是销售预算","detail":"经营预算以销售预算为源头，先确定销售规模再推导生产、成本与现金流，体现以销定产的预算逻辑。"},{"point":"编制程序五环节","detail":"下达目标→编制上报→审查平衡→审议批准→下达执行，遵循上下结合、分级编制、逐级汇总原则，由董事会或总经理办公会提出目标。"}],"framework":"概念、两大构成（经营/报表）、起点、程序，由总到分组织。","memo":"起点是销售预算（非生产预算）；报表预算含三张表。","tag":""},{"id":"qa-f2ch13-02","difficulty":2,"q":"说明保险公司KPI设定的步骤、好的KPI应具备的特点及权重设计的要点。","answer_points":[{"point":"KPI设定的三个步骤","detail":"先明确公司价值树，再找出对价值有重大影响且相对可控的指标，最后将指标层层细分到业务单位、职能部门和个人。"},{"point":"好的KPI四个特点","detail":"可衡量性（易量化）、重大影响（关联价值驱动）、可操作性（可控可算公正）、平衡性（整体平衡支持各职能），四者共同保证指标有效。"},{"point":"权重数量控制","detail":"KPI一般设5-10个，过多失焦、过少片面；数量适中才能兼顾全面与可执行。"},{"point":"单个权重上下限","detail":"单个权重不高于30%（防抓大放小、考核风险集中），不低于5%（防缺少影响力），且取5的整数倍简化计算。"},{"point":"KPI是绩效管理的灵魂","detail":"KPI分解自公司战略与中期业务目标并随其演化修正，是连接战略与薪酬激励的核心纽带，体现以价值为驱动原则。"}],"framework":"步骤（价值树、筛选、细分）、特点四性、权重（数量/上下限/取5倍数）、灵魂定位。","memo":"上限30%、下限5%、取5整数倍；KPI数量5-10；灵魂是KPI。","tag":""},{"id":"qa-f2ch13-03","difficulty":2,"q":"比较保险公司五种预算编制方法及其适用情形。","answer_points":[{"point":"固定预算","detail":"按正常可实现的某一业务量水平编制，适用于固定费用或数额稳定的项目，缺乏弹性但简单易行。"},{"point":"弹性预算","detail":"按成本习性分类、依量本利依存关系编制，适用于与业务量相关的成本、费用及利润，能随业务量调整。"},{"point":"滚动预算","detail":"随时间和市场变化自行延伸同步调整，适用于季度编制的销售、生产预算，保持预算持续前瞻。"},{"point":"零基预算","detail":"以零为基点逐项审议收支必要性与数额，适用于不常发生或基础变化大的项目（如对外投资、对外捐赠），抑制惯性浪费。"},{"point":"概率预算","detail":"对不确定项目估计各种变化概率并算期望值，适用于销售新产品、开拓新业务等难预测变动趋势的项目。"},{"point":"编制方式以上下结合式最佳","detail":"上下结合、分级编制、逐级汇总的方式运行效果最好、应用最多，兼顾战略导向与基层可执行性。"}],"framework":"逐一说明五种方法定义与适用，最后补编制方式优劣。","memo":"概率预算对应新产品/新业务；零基预算对应对外投资/捐赠；滚动预算对应季度销售生产。","tag":""},{"id":"qa-f2ch13-04","difficulty":3,"q":"综合分析：保险公司如何通过全面预算与绩效管理的闭环将战略目标落地，并说明各环节如何衔接。","answer_points":[{"point":"战略通过全面预算细化为年度计划","detail":"全面预算将公司战略目标量化为经营与报表预算，为各单位确立共同努力目标和共同遵守的行为规范，是战略落地的第一步。"},{"point":"预算编制与执行形成控制闭环","detail":"程序上下达目标→编制上报→审查平衡→审议批准→执行，执行中每月初下达指标、期间监督、月末评价调整，确保预算刚性。"},{"point":"绩效管理以KPI为灵魂承接预算目标","detail":"KPI分解自战略与年度计划，通过价值树筛选重大指标并细分到个人，使预算目标转化为可考核的业绩指标。"},{"point":"四个过程实现目标闭环管理","detail":"目标建立→目标分解→目标控制→目标评定，将预算执行追踪、考核与反馈纳入统一流程，发现偏差及时纠正。"},{"point":"业绩监测与反馈三系统支撑","detail":"业绩达成报告、业绩达成分析会议、必要时采取新行动计划，按月/季/半年节奏（如每季董事会报告）保持动态调整。"},{"point":"薪酬激励完成闭环","detail":"基于中长期计划与KPI建立薪酬体系，可变薪酬与业绩挂钩、鼓励长期利益，使绩效结果反哺战略与个人行为，形成战略—预算—执行—绩效—激励完整闭环。"}],"framework":"以战略、预算、绩效(KPI)、过程控制、监测反馈、薪酬激励主线串联，强调前后衔接与闭环。","memo":"灵魂是KPI；四过程顺序不可乱（建立、分解、控制、评定）；业绩审核每季、年终评估半年。","tag":""}],"calc":[{"id":"c-f2ch13-01","difficulty":1,"stem":"某公司为部门设定5个KPI，权重分别为25%、25%、20%、15%、15%（均取5%整数倍）。要求计算权重合计，并判断单个权重是否符合不低于5%且不高于30%、取5%整数倍的设计要求。","blanks":[{"label":"权重合计（%）","answer":100,"tolerance":0.5}],"steps":["第1步：权重合计 = 25% + 25% + 20% + 15% + 15% = 100%","第2步：逐个核对：25、25、20、15、15均在[5,30]区间内且均为5的整数倍","第3步：判定：合计100%且单个均合规，权重设计达标"],"formula_card":"权重合计 = Σ各KPI权重；单个权重 ∈ [5%,30%] 且为5%整数倍","analysis":"权重合计100%，每个权重介于5%-30%且为5%整数倍，符合教材权重设计要点，设计有效。","trap":"易漏检单个上限30%（过高抓大放小）；合计须正好100%，权重应取5的整数倍便于计算。","tag":""},{"id":"c-f2ch13-02","difficulty":2,"stem":"某保险公司员工共200人，年度绩效评分按参考分布比例评定：超级明星15%、中坚力量30%、表现高佳者30%、业绩不佳者20%、失败者5%（合计100%）。分别计算超级明星与中坚力量的合计人数，以及失败者人数，并判断分布是否处于教材参考区间。","blanks":[{"label":"超级明星+中坚力量合计人数（人）","answer":90,"tolerance":0.5},{"label":"失败者人数（人）","answer":10,"tolerance":0.5}],"steps":["第1步：超级明星 = 200 × 15% = 30（人）；中坚力量 = 200 × 30% = 60（人）；合计 = 30 + 60 = 90（人）","第2步：失败者 = 200 × 5% = 10（人）","第3步：核对区间：超级明星10-15%✓、中坚力量25-30%✓、表现高佳者25-40%✓、业绩不佳者15-25%✓、失败者5-10%✓，均合规"],"formula_card":"各类人数 = 员工总数 × 该类参考比例","analysis":"超级明星+中坚力量合计90人，失败者10人；五类比例均落在教材参考区间（超级明星10-15%等），分布设计合理。","trap":"先确认五类比例合计为100%再乘总数；注意各类比例有区间，选用值须在区间内（如失败者恰取下限5%）。","tag":""}]},{"id":"fm_docs_14_21","group":"财务管理制度","name":"财务管理制度（偿付能力管理与绩效评价等8份）","qa":[{"id":"qa-doc14-01","difficulty":1,"q":"保险公司偿付能力是否达标，应从哪几个维度进行判断？","answer_points":[{"point":"核心偿付能力充足率不低于50%","detail":"核心偿付能力充足率等于核心资本除以最低资本，反映高质量资本对风险的覆盖程度，达标线为50%。"},{"point":"综合偿付能力充足率不低于100%","detail":"综合偿付能力充足率等于实际资本除以最低资本，反映资本总体充足状况，达标线为100%。"},{"point":"风险综合评级在B类及以上","detail":"风险综合评级由银保监会结合充足率与各类风险评价确定，分为A、B、C、D四类，达标要求为B类及以上。"},{"point":"三项条件须同时满足","detail":"只有当上述三项指标同时达标时，保险公司才被认定为偿付能力达标公司，任一项不满足即不达标。"}],"framework":"三条达标线——核心≥50%、综合≥100%、评级≥B，三者同时成立。","memo":"易错：重点核查对象是核心<60%或综合<120%，阈值高于达标线，属于预警标准而非达标线。","tag":"偿付能力管理规定"},{"id":"qa-doc14-02","difficulty":2,"q":"《偿付能力管理规定》确立的偿付能力监管框架由哪三部分构成？","answer_points":[{"point":"定量资本要求（第一支柱）","detail":"通过最低资本、实际资本、核心资本等量化指标，对可量化的保险风险、市场风险、信用风险等提出资本要求。"},{"point":"定性监管要求（第二支柱）","detail":"包括偿付能力风险管理能力评估（SARMRA）、风险综合评级、压力测试等，对难以量化的风险进行监管。"},{"point":"市场约束机制（第三支柱）","detail":"通过偿付能力信息公开披露，发挥市场监督作用，强化保单持有人和投资者等利益相关方的约束。"},{"point":"是偿二代制度体系的纲领性文件","detail":"该规定是银保监会2021年第1号令，自2021年3月1日起施行，确立三支柱框架并统领各监管规则。"}],"framework":"三支柱=定量资本+定性监管+市场约束。","memo":"易错：三支柱具体名称易混淆，注意“定性监管要求”不是“定性风险”，且由管理规定而非单条规则确立。","tag":"偿付能力管理规定"},{"id":"qa-doc14-03","difficulty":3,"q":"对偿付能力不达标的保险公司，监管措施应如何分类适用？","answer_points":[{"point":"核心<50%或综合<100%须同时采取第（一）至（四）项","detail":"包括监管谈话、要求提交预防充足率恶化或完善风险管理的计划、限制董监高薪酬水平、限制向股东分红四项强制措施。"},{"point":"第（五）至（十二）项视充足率下降原因选择适用","detail":"在强制四项基础上，银保监会根据导致不达标的具体原因，有针对性地选用其余措施。"},{"point":"未明显改善或恶化的可依法接管或申请破产","detail":"采取监管措施后偿付能力未明显改善或进一步恶化的，可依法采取接管、申请破产等更严厉措施。"},{"point":"风险综合评级为C类、D类亦触发差别化措施","detail":"除充足率不达标外，评级落入C、D类的公司也将被采取相应差别化监管措施。"},{"point":"还与重点核查对象机制衔接","detail":"核心充足率低于60%或综合低于120%的公司被列为重点核查对象，与措施适用形成预警到处置的闭环。"}],"framework":"强制四项（一～四）必用 + 五～十二选因适用 + 恶化可接管/破产。","memo":"易错：第（一）至（四）项是“同时采取”而非“选择采取”；“限制分红”是强制四项之一。","tag":"偿付能力管理规定"},{"id":"qa-doc15-01","difficulty":1,"q":"实际资本的概念及其在偿付能力评估中的计算口径是什么？","answer_points":[{"point":"实际资本=认可资产−认可负债","detail":"实际资本是认可资产减去认可负债后的余额，是保险公司在持续经营或破产清算状态下可以吸收损失的财务资源。"},{"point":"基于母公司财务报表而非合并报表","detail":"实际资本评估以母公司财务报表为基础，资产与负债的评估原则应当保持一致。"},{"point":"与非认可资产/负债相区分","detail":"无形资产（土地使用权除外）、待摊费用等属于非认可资产；农业保险大灾风险准备金、合格次级债等属于非认可负债。"},{"point":"实际资本是综合偿付能力充足率的分子","detail":"综合偿付能力充足率=实际资本÷最低资本，实际资本直接决定资本总体充足状况。"}],"framework":"实际资本=认可资产−认可负债，母公司口径。","memo":"易错：实际资本是“持续经营或破产清算”均可吸收损失，而核心资本要求“两种状态下均”——表述差一字，含义不同。","tag":"实际资本"},{"id":"qa-doc15-02","difficulty":2,"q":"保险公司资本的分级结构及各项资本的限额标准是什么？","answer_points":[{"point":"资本分为核心资本与附属资本","detail":"核心资本在持续经营和破产清算状态下均可吸收损失，附属资本仅在破产清算状态下可吸收损失；核心资本又分核心一、二级，附属分附属一、二级。"},{"point":"附属资本不得超过核心资本的100%","detail":"这是总限额，超过限额的部分应确认为资本性负债，以超额金额作为该负债的认可价值。"},{"point":"计入核心资本的保单未来盈余不得超过核心资本的35%","detail":"保单未来盈余按剩余期限分级计入各级资本，其计入核心资本部分设35%上限。"},{"point":"核心二级资本不得超过核心资本的30%","detail":"核心二级资本工具余额超过核心资本30%的，超额部分计入资本性负债（相互保险组织除外）。"},{"point":"附属二级资本不得超过核心资本的25%","detail":"附属二级资本工具同样设25%的限额，超额部分按资本性负债处理。"}],"framework":"四级资本 + 四道限额（附属100%、保单盈余35%、核心二级30%、附属二级25%）。","memo":"易错：附属资本总限额是核心的100%，不是各项分别100%；相互保险组织核心二级30%限额豁免。","tag":"实际资本"},{"id":"qa-doc16-01","difficulty":2,"q":"流动性风险的含义是什么？其三项监管指标分别是什么？","answer_points":[{"point":"流动性风险是无法及时获得充足资金支付到期债务的风险","detail":"指保险公司无法及时获得充足资金，或无法及时以合理成本获得充足资金，以支付到期债务或履行其他支付义务的风险。"},{"point":"监管指标一：流动性覆盖率（LCR）","detail":"包括LCR1（基本情景）、LCR2（压力情景含资产变现）、LCR3（压力情景不含资产变现），评估未来一年流动性水平。"},{"point":"监管指标二：经营活动净现金流回溯不利偏差率（RDR）","detail":"RDR反映基本情景下净现金流预测值与实际值的不利偏差，最近两个季度不得连续低于-30%。"},{"point":"监管指标三：净现金流","detail":"反映过去两个会计年度及当年累计的净现金流状况，不得连续小于零，口径与现金流量表一致。"},{"point":"以母公司财务报表为基础计算","detail":"流动性风险监管指标以母公司财务报表而非合并财务报表为基础，与实际资本评估口径一致。"}],"framework":"定义（资金可获得性） + 三指标（LCR、RDR、净现金流）。","memo":"易错：规模保费同比增速、综合退保率是“监测指标”不是“监管指标”；二者易混。","tag":"流动性风险"},{"id":"qa-doc16-02","difficulty":3,"q":"流动性覆盖率（LCR）的三种计算口径及各自的达标要求是什么？","answer_points":[{"point":"LCR1=基本情景（流入+现金及现金等价物）/流出×100%","detail":"基本情景下公司整体流动性覆盖率，分子含现金及现金等价物但不含资产变现，达标要求不低于100%。"},{"point":"LCR2分子另加流动性资产储备变现金额","detail":"压力情景下考虑流动性资产储备（如国债、股票等按折算系数变现）后的覆盖率，达标要求同样不低于100%。"},{"point":"LCR3不考虑资产变现情况","detail":"压力情景下仅以现金及现金等价物和现金流入覆盖流出，达标要求不低于50%，显著低于LCR1、LCR2。"},{"point":"流动性资产储备有折算系数","detail":"如货币市场基金/国债100%、可提前支取定存90%、上市股票50%，非标债权、长期股权投资等不得计入。"},{"point":"测试频率为至少每季度一次","detail":"现金流测试区间为报告期末起未来12个月，按季度划分为四个测试期间。"}],"framework":"LCR1/2≥100%，LCR3≥50%；差别在是否含资产变现。","memo":"易错：LCR3是“不低于50%”而非100%；流动性资产储备不含长期股权投资、非标债权。","tag":"流动性风险"},{"id":"qa-doc17-01","difficulty":2,"q":"资本规划的编制应遵循哪些原则？报送与审批程序有何要求？","answer_points":[{"point":"四项原则：充足性、审慎性、前瞻性、可行性","detail":"充足性确保持续满足监管；审慎性要求审慎选取参数假设；前瞻性与长期发展战略相符；可行性要求目标措施与实际相符。"},{"point":"每年滚动编制未来三年资本规划","detail":"管理目标至少包括综合与核心偿付能力充足率未来三年的目标。"},{"point":"经董事会批准并经股东（大）会审议","detail":"程序上董事会批准在前、股东（大）会审议在后，公司应明确管理部门及职责分工。"},{"point":"每年5月31日前报送银保监会","detail":"调整资本规划的，应经董事会审议批准后10个工作日内报送调整后的规划。"},{"point":"优先内源性资本补充","detail":"制定资本补充方案时应优先考虑提升盈利、优化产品与资产结构等内源性措施。"}],"framework":"四原则 + 三年滚动 + 董事会批/股东会审 + 5月31日报送。","memo":"易错：报送时限5月31日（资本规划），区别于绩效评价5月15日、4季度报告审计4月30日。","tag":"资本规划"},{"id":"qa-doc17-02","difficulty":3,"q":"保险公司资本补充方案中的内源性与外源性措施分别包括哪些？","answer_points":[{"point":"内源性措施以提升自身资本为主","detail":"包括提升盈利能力、制定合理利润分配政策、优化产品结构、优化资产结构、提升风险管理能力等。"},{"point":"应优先考虑内源性措施","detail":"规则要求制定资本补充方案时优先考虑内源性，以降低对外部融资的依赖。"},{"point":"外源性措施包括增资扩股等","detail":"涵盖增资扩股、发行资本补充工具、保单责任证券化、再保险及符合监管规定的其他工具。"},{"point":"外源应优先补充核心资本","detail":"外源性资本补充应优先补充核心资本、合理补充附属资本，优化资本结构。"},{"point":"资本规划是资本工具发行审批依据","detail":"银保监会对资本补充工具发行审批时，将资本规划作为重要依据，发行与规划不一致的审慎考虑。"}],"framework":"内源（盈利/分红/产品/资产/风控）优先；外源（增资/资本工具/证券化/再保）。","memo":"易错：增资扩股属“外源”非“内源”；保单责任证券化、再保险均属外源措施。","tag":"资本规划"},{"id":"qa-doc18-01","difficulty":2,"q":"偿付能力信息公开披露的渠道、形式与基本原则有哪些？","answer_points":[{"point":"披露渠道为公司官网和保险行业协会网站","detail":"协会官网设立专栏统一披露，保险公司应在自身官网同步披露季度报告摘要等信息。"},{"point":"形式分定期披露与日常披露","detail":"定期披露指偿付能力季度报告摘要；日常披露包括投保提示书、向股东披露、应询答复等场景。"},{"point":"五项原则：充分性、及时性、真实性、可理解性、公平性","detail":"不包括保密性原则，强调信息真实、及时、易懂且公平对待各方使用者。"},{"point":"董事会对披露负最终责任","detail":"保险公司董事会对偿付能力信息公开披露负最终责任，管理层负责具体执行。"},{"point":"摘要保留至少10年","detail":"季度报告摘要在公司网站应保留至少10年，以保证信息长期可查。"}],"framework":"两渠道（官网+协会） + 两形式（定期+日常） + 五原则。","memo":"易错：披露原则含“公平性”不含“保密性”；保留期是10年不是5年。","tag":"信息披露"},{"id":"qa-doc18-02","difficulty":3,"q":"偿付能力季度报告摘要的披露时点如何区分？补充披露的触发条件是什么？","answer_points":[{"point":"非上市保险公司每季度结束后30日内披露","detail":"非上市保险公司应在每季度结束后30日内披露偿付能力季度报告摘要。"},{"point":"上市保险公司第1、3季度30日内，第2、4季度随财报披露","detail":"上市险企第1、3季度结束后30日内披露，第2、4季度分别与半年报、年报同时披露。"},{"point":"延迟披露不得超过15日","detail":"不能按时披露的，应在规定期限前在官网首页公布原因及预计时间，延迟不得超过15日。"},{"point":"补充披露触发：充足率变动超3个百分点","detail":"经审计的第4季度信息中，核心或综合充足率变动超过3个百分点须自审计报告出具之日起10日内补充披露。"},{"point":"补充披露触发：实际/最低资本变动超1%","detail":"审计后实际资本或最低资本变动比例超过1%同样触发补充披露，与3个百分点的阈值需分别记忆。"}],"framework":"非上市30日、上市1/3季30日+2/4季随报；补充触发（充足率±3pp或资本±1%）。","memo":"易错：补充披露两个阈值不同——充足率变动是“3个百分点”，资本变动是“1%”，勿混。","tag":"信息披露"},{"id":"qa-doc19-01","difficulty":2,"q":"保险公司向银保监会报送的偿付能力报告有哪些类型？主要报送时限是什么？","answer_points":[{"point":"三类：季度报告、季度快报、临时报告","detail":"偿付能力报告包括季度报告、季度快报和临时报告，不存在单独的年度报告类型。"},{"point":"季度快报每季度结束后12日内报送","detail":"快报仅含基本信息和主要指标两部分，由董事长或总经理签字。"},{"point":"季度报告每季度结束后25日内报送","detail":"季度报告由七类高管签字并盖章，第4季度报告须经会计师事务所审计。"},{"point":"4季度报告审计次年4月30日前报送","detail":"每年4月30日前报送上一年度第4季度报告的审计报告和经审计的季度报告。"},{"point":"临时报告按事项5个工作日或3日","detail":"偿付能力不足及重大不利影响事项5个工作日内报告，重大流动性风险3日内报告。"}],"framework":"三类型 + 快报12日/报告25日/4季审计4月30日。","memo":"易错：快报12日、报告25日，别颠倒；临时报告流动性风险3日、其他重大不利5日。","tag":"偿付能力报告"},{"id":"qa-doc19-02","difficulty":1,"q":"偿付能力报告中“重大事项”的认定标准主要有哪些比例门槛？","answer_points":[{"point":"重大再保险合同：保额或保费超5%","detail":"分入（分出）保额超本季度末有效保额5%，或分入（分出）保费超报告期保费收入5%的单项再保险合同。"},{"point":"重大投资损失：损失超净资产5%","detail":"单项股权、不动产、基础设施、信托、资产证券化等投资损失金额超报告期末净资产总额5%。"},{"point":"重大融资事项：单笔融资超净资产10%","detail":"增资扩股、发行债务性资本工具等单笔融资金额超报告期末净资产10%的融资活动。"},{"point":"重大赔付与重大诉讼另有标准","detail":"赔付金额居前五位为重大赔付事项，诉讼标的金额排名前三位为重大诉讼。"},{"point":"阈值差异需区分记忆","detail":"再保险/投资损失为5%，融资为10%，认定口径各不相同，不可套用同一比例。"}],"framework":"再保险5%（保额/保费）、投资损失5%（净资产）、融资10%（净资产）。","memo":"易错：重大投资损失是超净资产5%，重大融资是超净资产10%，两处5%与10%易记反。","tag":"偿付能力报告"},{"id":"qa-doc20-01","difficulty":1,"q":"商业保险公司绩效评价从哪四个维度开展？各维度权重如何？","answer_points":[{"point":"服务国家发展目标和实体经济","detail":"评价险企服务实体经济、响应国家宏观政策的成效，是绩效评价的首要导向维度。"},{"point":"发展质量","detail":"关注经济增加值率、人工成本利润率、人均净利润等反映高质量发展的指标。"},{"point":"风险防控","detail":"含综合偿付能力充足率、风险综合评级、流动性覆盖率等7个指标，防控金融风险。"},{"point":"经营效益","detail":"含资本保值增值率、净资产收益率、分红上缴比例3个指标。"},{"point":"四个维度各占25%权重","detail":"四个维度合计100分，权重均等，综合评价结果作为负责人薪酬和工资总额主要依据。"}],"framework":"四维度（服务/质量/风控/效益）各25%。","memo":"易错：四个维度权重均为25%，不是按指标数量分配；风险防控含7个指标但权重仍25%。","tag":"绩效评价办法"},{"id":"qa-doc20-02","difficulty":3,"q":"商业保险公司绩效评价的结果档次与级别如何划分？分档分数线是什么？","answer_points":[{"point":"五档：优（A）、良（B）、中（C）、低（D）、差（E）","detail":"以80、65、50、40分作为分档分数线，A≥80、B为65~80、C为50~65、D为40~50、E<40。"},{"point":"十级：AAA至E细分","detail":"档次内再分为AAA（≥95）、AA、A、BBB、BB、B、CC、C、D、E共十个级别。"},{"point":"得分百分制最高100分","detail":"绩效评价得分用百分制表示，最高100分（不含加减分事项的额外增减）。"},{"point":"加减分事项各1~5分","detail":"落实重大决策可加1~5分；风险事件、违规处罚、信息质量问题等减1~5分，情节严重可下调级别。"},{"point":"保值增值不达标可下调一档","detail":"未实现国有资本保值增值且保值增值率低于行业标准值中等值的，下调一档确认档次。"}],"framework":"五档（80/65/50/40线） + 十级 + 百分制100封顶。","memo":"易错：分档线是80、65、50、40四个数；“十级”是在五档内细分，不是另立体系。","tag":"绩效评价办法"},{"id":"qa-doc21-01","difficulty":1,"q":"无固定期限资本债券的定义及其资本补充属性是什么？","answer_points":[{"point":"是没有固定期限的资本补充债券","detail":"保险公司发行的没有固定期限、含有减记或转股条款、在持续经营和破产清算状态下均可吸收损失的资本补充债券。"},{"point":"用于补充核心二级资本","detail":"无固定期限资本债券补充核心二级资本，债券余额不得超过核心资本的30%。"},{"point":"含有减记或转股条款","detail":"触发事件发生时应当实施减记或转股，以吸收损失。"},{"point":"保险集团（控股）公司不得发行","detail":"仅保险公司（财险、人身险、再保险）可按规定申请，集团控股公司被排除。"}],"framework":"无期限+减记/转股+补核心二级+余额≤核心30%。","memo":"易错：补的是“核心二级”资本（非附属）；余额上限是核心资本的30%，与资本分级限额呼应。","tag":"无固定期限资本债券"},{"id":"qa-doc21-02","difficulty":2,"q":"无固定期限资本债券的触发事件分为哪两类？各自触发条件是什么？","answer_points":[{"point":"持续经营触发事件：核心充足率低于30%","detail":"指保险公司核心偿付能力充足率低于30%时触发，区别于达标线（核心50%）。"},{"point":"无法生存触发事件：监管或相关部门认定","detail":"包括银保监会认为不减速记/转股将无法生存，或相关部门认定不注资/支持将无法生存。"},{"point":"会计分类决定触发事件设置","detail":"分类为权益工具的设定无法生存触发事件；分类为金融负债的须同时设定两类触发事件。"},{"point":"触发即实施减记或转股","detail":"触发事件发生时，无固定期限资本债券应当实施减记或转股以吸收损失。"},{"point":"付息后不达标则取消当期利息","detail":"支付利息后偿付能力充足率不达标的，当期利息支付义务应当取消。"}],"framework":"持续经营（核心<30%） + 无法生存（监管/政府认定）。","memo":"易错：持续经营触发是核心充足率<30%（不是综合<100%，也不是核心<50%达标线）。","tag":"无固定期限资本债券"}],"calc":[{"id":"c-doc14-01","difficulty":1,"stem":"某保险公司报告期末实际资本为200亿元，最低资本为160亿元，其中核心资本为96亿元。假设其风险综合评级为B类。请计算该公司的综合偿付能力充足率与核心偿付能力充足率，并判断其偿付能力是否达标。","blanks":[{"label":"综合偿付能力充足率(%)","answer":125.0,"tolerance":0.5},{"label":"核心偿付能力充足率(%)","answer":60.0,"tolerance":0.5}],"steps":["综合偿付能力充足率=实际资本÷最低资本=200÷160=1.25，即125.0%。","核心偿付能力充足率=核心资本÷最低资本=96÷160=0.60，即60.0%。","达标判断：核心充足率60%≥50%、综合充足率125%≥100%、评级B类及以上，三项同时满足，达标。"],"formula_card":"综合充足率=实际资本÷最低资本；核心充足率=核心资本÷最低资本；达标=核心≥50%且综合≥100%且评级≥B","analysis":"综合充足率=200/160=125.0%；核心充足率=96/160=60.0%。三项达标条件：核心≥50%（60%满足）、综合≥100%（125%满足）、风险综合评级B类及以上（已知B类满足），故偿付能力达标。","trap":"达标需三项同时成立；核心/综合达标线分别为50%/100%，别与重点核查线60%/120%混淆。","tag":"偿付能力管理规定"},{"id":"c-doc15-01","difficulty":1,"stem":"某保险公司母公司口径下，认可资产为500亿元，认可负债为320亿元。请计算其实际资本金额。","blanks":[{"label":"实际资本(亿元)","answer":180.0,"tolerance":0.5}],"steps":["实际资本=认可资产−认可负债。","代入：500−320=180亿元。"],"formula_card":"实际资本=认可资产−认可负债（以母公司财务报表为基础）","analysis":"实际资本=500−320=180亿元，即该公司在持续经营或破产清算状态下可吸收损失的财务资源为180亿元。","trap":"评估基础是母公司财务报表而非合并报表；认可资产/负债已剔除非认可项目，不是总资产减总负债。","tag":"实际资本"},{"id":"c-doc16-01","difficulty":2,"stem":"某保险公司基本情景下，未来一年现金流入为90亿元，现金及现金等价物账面价值为30亿元，基本情景现金流出为100亿元。请计算其基本情景流动性覆盖率LCR1，并判断是否满足监管要求。","blanks":[{"label":"LCR1(%)","answer":120.0,"tolerance":0.5}],"steps":["LCR1=（基本情景现金流入＋现金及现金等价物账面价值）÷基本情景现金流出×100%。","分子=90+30=120亿元。","LCR1=120÷100×100%=120.0%。","监管要求LCR1不低于100%，120%≥100%，满足要求。"],"formula_card":"LCR1=(基本情景现金流入+现金及现金等价物)÷基本情景现金流出×100%；达标线≥100%","analysis":"LCR1=(90+30)/100=120.0%。因LCR1监管达标要求为不低于100%，该公司基本情景流动性覆盖率达标。","trap":"LCR1达标线为100%；LCR3才是50%。分子含现金及现金等价物但不含流动性资产储备变现（那是LCR2）。","tag":"流动性风险"},{"id":"c-doc19-01","difficulty":2,"stem":"某保险公司本年度净利润为12亿元，期初净资产为100亿元，期末净资产为140亿元。请计算其净资产收益率（ROE）。","blanks":[{"label":"净资产收益率ROE(%)","answer":10.0,"tolerance":0.5}],"steps":["平均净资产=（期初净资产＋期末净资产）÷2=（100+140）÷2=120亿元。","净资产收益率=净利润÷平均净资产×100%=12÷120×100%=10.0%。"],"formula_card":"ROE=净利润÷[(期初净资产+期末净资产)/2]×100%","analysis":"平均净资产=(100+140)/2=120亿元，ROE=12/120=10.0%。该指标用于反映公司资本回报水平，属偿付能力报告主要经营指标。","trap":"分母是期初与期末净资产的平均值，不是期末净资产单值；结果以百分比表示。","tag":"偿付能力报告"},{"id":"c-doc16-02","difficulty":3,"stem":"某保险公司压力情景下，现金流入为150亿元，现金及现金等价物为100亿元，现金流出为200亿元。其流动性资产储备包括：国债40亿元（折算系数100%）、上市股票20亿元（折算系数50%）。请计算上市股票折算金额、流动性资产储备合计可变现金额，以及压力情景下含资产变现的流动性覆盖率LCR2。","blanks":[{"label":"上市股票折算金额(亿元)","answer":10.0,"tolerance":0.5},{"label":"流动性资产储备合计可变现金额(亿元)","answer":50.0,"tolerance":0.5},{"label":"LCR2(%)","answer":150.0,"tolerance":0.5}],"steps":["上市股票折算金额=20×50%=10亿元。","流动性资产储备合计变现=国债40×100%+股票10=40+10=50亿元。","LCR2分子=现金流入150+现金及现金等价物100+储备变现50=300亿元。","LCR2=300÷200×100%=150.0%。"],"formula_card":"LCR2=(现金流入+现金及现金等价物+流动性资产储备变现)÷现金流出×100%；储备按折算系数（国债100%、股票50%）计入","analysis":"股票折算=20×50%=10亿元；储备合计=40×100%+10=50亿元；LCR2=(150+100+50)/200=150.0%。LCR2监管达标要求为不低于100%，该公司满足。","trap":"流动性资产储备须按折算系数计入，不能直接用账面价值；长期股权投资、非标债权不得计入储备。LCR2与LCR1达标线同为100%，LCR3才是50%。","tag":"流动性风险"},{"id":"c-doc20-01","difficulty":3,"stem":"某绩效评价指标满分10分，行业标准值中优秀值为1.0、良好值为0.8（对应标准系数分别为1.0和0.8）。该公司该指标实际值为0.9，介于优秀值与良好值之间。采用功效系数法计算：本档为基础分（本档标准系数×满分），调整分=功效系数×（上档基础分−本档基础分），功效系数=(实际值−本档标准值)/(上档标准值−本档标准值)。请计算功效系数及该指标得分。","blanks":[{"label":"功效系数","answer":0.5,"tolerance":0.5},{"label":"该指标单项得分(分)","answer":9.0,"tolerance":0.5}],"steps":["功效系数=(0.9−0.8)/(1.0−0.8)=0.5。","本档基础分=本档标准系数0.8×满分10=8分；上档基础分=1.0×10=10分。","调整分=0.5×(10−8)=1分。","单项得分=本档基础分8+调整分1=9.0分。"],"formula_card":"单项得分=本档基础分+调整分；调整分=功效系数×(上档基础分−本档基础分)；功效系数=(实际值−本档值)/(上档值−本档值)","analysis":"功效系数=(0.9−0.8)/(1.0−0.8)=0.5；本档基础分=0.8×10=8，上档基础分=10，调整分=0.5×2=1，得分=8+1=9.0分。","trap":"功效系数分母是(上档标准值−本档标准值)，本档是实际值落入的较低档（良好值0.8），上档是优秀值1.0；基础分=标准系数×指标满分而非直接乘100。","tag":"绩效评价办法"}]},{"id":"fm_docs_1_7","group":"财务管理制度","name":"财务管理制度（原保险合同/再保险/费用分摊/新准则等7份）","qa":[{"id":"qa-doc1-01","difficulty":1,"q":"保险人应当如何判断其与投保人签订的合同是否属于原保险合同？划分寿险与非寿险原保险合同又依据什么标准？","answer_points":[{"point":"判断基础：单项合同、是否承担保险风险","detail":"应当在单项合同的基础上，根据合同条款判断保险人是否承担了保险风险，而非以合同组合、保费金额或监管认定为准。"},{"point":"承担保险风险的认定","detail":"若发生保险事故可能导致保险人承担赔付保险金责任的，应当确定保险人承担了保险风险，该合同属于原保险合同范畴。"},{"point":"混合风险合同的分拆规则","detail":"既承担保险风险又承担其他风险的合同，能够区分且能单独计量的进行分拆；不能区分或不能单独计量的，整个合同确定为原保险合同。"},{"point":"寿险与非寿险的划分依据","detail":"按原保险合同延长期内是否承担赔付保险金责任划分：承担的为寿险原保险合同，不承担的为非寿险原保险合同。"},{"point":"原保险合同延长期的定义","detail":"指投保人自上一期保费到期日未交纳保费，而保险人仍承担赔付保险金责任的期间，是寿险与非寿险划分的关键时间窗口。"}],"framework":"先答判断基础（单项合同/保险风险）→再答混合风险分拆规则→最后答寿险与非寿险划分依据（延长期是否担责）。","memo":"易错：划分寿险/非寿险看‘延长期内是否担责’，不是看期限长短，也不是看标的为财产还是人身。","tag":"25号-原保险合同"},{"id":"qa-doc1-02","difficulty":2,"q":"原保险合同保费收入的确认应满足哪些条件？在确认保费收入与提取准备金方面，寿险与非寿险有何不同规定？","answer_points":[{"point":"保费收入确认三条件","detail":"原保险合同成立并承担相应保险责任；与合同相关的经济利益很可能流入；与合同相关的收入能够可靠地计量。"},{"point":"非寿险保费收入计量","detail":"非寿险合同按合同约定的保费总额确定保费收入，在确认保费收入当期按精算金额提取未到期责任准备金作为调整。"},{"point":"寿险保费收入计量","detail":"寿险合同分期收取保费的按当期应收取保费确定，一次性收取保费的按一次性应收取保费确定。"},{"point":"四项准备金构成","detail":"原保险合同准备金包括未到期责任准备金、未决赔款准备金、寿险责任准备金、长期健康险责任准备金。"},{"point":"充足性测试规定","detail":"至少于每年年度终了，对未决赔款、寿险、长期健康险责任准备金进行充足性测试；重算金额超过已提取余额的按差额补提，小于已提取余额的不调整。"},{"point":"未到期责任准备金的调整机制","detail":"未到期责任准备金通过资产负债表日重算差额调整，不纳入上述三类准备金的充足性测试范围。"}],"framework":"三条件→寿险/非寿险计量差异→准备金提取（未到期责任准备金当期调整）→充足性测试（只补不冲）。","memo":"易错：未到期责任准备金仅在确认非寿险保费收入当期提取；充足性测试‘只补不冲’，重算小于余额时不调整。","tag":"25号-原保险合同"},{"id":"qa-doc1-03","difficulty":3,"q":"原保险合同成本涉及哪些项目？请说明手续费佣金、损余物资、应收代位追偿款的会计处理，并列举利润表应单独列示的相关项目。","answer_points":[{"point":"手续费佣金的处理","detail":"保险人在取得原保险合同过程中发生的手续费、佣金，应当在发生时计入当期损益，不得递延或资本化摊销。"},{"point":"赔付成本的构成","detail":"赔付成本包括支付的赔款、给付，以及理赔过程中发生的律师费、诉讼费、损失检验费、理赔人员薪酬等理赔费用。"},{"point":"损余物资的处理","detail":"按同类或类似资产的市场价格计算确定金额确认为资产，并冲减当期赔付成本。"},{"point":"应收代位追偿款的处理","detail":"确认条件为相关经济利益很可能流入且金额能够可靠计量，确认时冲减当期赔付成本；准则未要求债务人书面承诺还款。"},{"point":"理赔费用准备金","detail":"为已发生尚未结案赔案可能发生的律师费、诉讼费、损失检验费、相关理赔人员薪酬等费用提取的准备金，属未决赔款准备金的一项。"},{"point":"利润表单列项目","detail":"利润表应单独列示保费收入、退保费、提取未到期责任准备金、已赚保费、手续费支出、赔付成本等九项相关项目。"},{"point":"附注披露要求","detail":"应披露代位追偿款、损余物资的有关情况，各项准备金的增减变动，以及提取准备金和进行充足性测试的主要精算假设与方法。"}],"framework":"成本项目分类→具体会计处理（费用化/资产确认/冲减）→列报与披露。","memo":"易错：手续费佣金‘发生时费用化’不可递延；代位追偿款无书面承诺要求；未决赔款准备金含三项（已报、未报、理赔费用），不含未到期责任准备金。","tag":"25号-原保险合同"},{"id":"qa-doc2-01","difficulty":1,"q":"再保险分出人在分出业务中应如何处理分出保费、摊回分保费用与应收分保准备金？有哪些禁止性规定？","answer_points":[{"point":"分出保费的确认时点与处理","detail":"再保险分出人应在确认原保险合同保费收入的当期，按再保险合同约定计算确定分出保费，计入当期损益。"},{"point":"摊回分保费用（纯益手续费）","detail":"在能够计算确定应向再保险接受人收取的纯益手续费时，将其作为摊回分保费用计入当期损益。"},{"point":"应收分保准备金的确认","detail":"在提取原保险合同各项准备金的当期，计算确定应摊回的相应准备金，确认为应收分保准备金资产。"},{"point":"非寿险的特别处理","detail":"原保险合同为非寿险的，还应确认应收分保未到期责任准备金资产，并据以冲减提取未到期责任准备金。"},{"point":"禁止抵销之一","detail":"再保险分出人不得将再保险合同形成的资产与有关原保险合同形成的负债相互抵销。"},{"point":"禁止抵销之二","detail":"不得将再保险合同形成的收入或费用与有关原保险合同形成的费用或收入相互抵销。"}],"framework":"分出保费（时点）→摊回费用→应收分保准备金→两条禁止抵销红线。","memo":"易错：分出保费确认时点是‘确认原保费收入当期’，不是收到分保账单时；严禁资产与负债、收入与费用相互抵销。","tag":"26号-再保险合同"},{"id":"qa-doc2-02","difficulty":2,"q":"再保险接受人（分入人）在收到分保业务账单时应如何进行会计处理？资产负债表和利润表应单独列示哪些再保险相关项目？","answer_points":[{"point":"分保费收入确认三条件","detail":"再保险合同成立并承担相应保险责任；相关经济利益很可能流入；相关收入能够可靠地计量。"},{"point":"收到账单的收入费用调整","detail":"分入人收到分保业务账单时，按账单标明金额对分保费收入、分保费用进行调整，调整金额计入当期损益。"},{"point":"分保赔付成本的处理","detail":"收到分保业务账单当期，按账单标明的分保赔付款项金额作为分保赔付成本计入当期损益，同时冲减相应的分保准备金余额。"},{"point":"分保保证金的确认","detail":"分出人发出账单时确认存入分保保证金，分入人收到账单时确认为存出分保保证金，二者方向相反，利息按期计入当期损益。"},{"point":"资产负债表单列六项","detail":"应收分保账款、应收分保未到期责任准备金、应收分保未决赔款准备金、应收分保寿险责任准备金、应收分保长期健康险责任准备金、应付分保账款。"},{"point":"利润表单列九项","detail":"分保费收入、分出保费、摊回分保费用、分保费用、摊回赔付成本、分保赔付成本及摊回未决赔款、寿险、长期健康险责任准备金。"}],"framework":"分入确认条件→账单调整处理→保证金→表内单独列示项目。","memo":"易错：分入人收入调整时点是‘收到账单当期’；转分保合同比照26号准则处理。","tag":"26号-再保险合同"},{"id":"qa-doc3-01","difficulty":2,"q":"《保险公司费用分摊指引》中如何界定专属费用与共同费用？请结合归属对象说明同一费用可能呈现不同属性，并列举人力成本、资产占用费的内容。","answer_points":[{"point":"专属费用定义","detail":"专门为某一归属对象发生、能够全部归属于该归属对象的费用，如可直接对应到某险种的专属人力投入。"},{"point":"共同费用定义","detail":"不是专门为某一归属对象发生、不能全部归属于该归属对象的费用，需要在多个归属对象间分摊。"},{"point":"费用属性随归属对象变化","detail":"核算险种大类损益时，车险承保管理人员薪酬是车险专属费用；核算交强险损益（细化到具体险种）时，该薪酬变为共同费用，需在交强险、车损险等险种间分摊。"},{"point":"人力成本内容","detail":"包括职工工资、福利费、教育费、住房公积金、社会统筹保险费、补充养老保险费等职工薪酬及相关支出。"},{"point":"资产占用费内容","detail":"包括固定资产折旧和租赁费、电子设备运转费、无形资产摊销、土地使用税、房产税、长期待摊费用等因资产占用发生的费用。"},{"point":"其他营业费用内容","detail":"除人力成本和资产占用费之外的其他共同性营业费用，如业务招待费、会议费、差旅费、水电费等。"},{"point":"适用范围边界","detail":"向保监会报送和对外披露的报告（偿付能力、财务会计、交强险、分红专题及统计系统数据）应参照本指引；内部管理目的的分摊可以不适用。"}],"framework":"定义→属性随对象变化举例→三类费用内容→适用边界。","memo":"易错：同一费用属性随归属对象变化；投资管理部门费用‘整块’计入投资收益，不进入直接业务部门分摊。","tag":"费用分摊指引"},{"id":"qa-doc3-02","difficulty":3,"q":"共同费用向险种或业务类别分摊需经过哪三步？请阐述每步内容，并说明IBNR的分摊公式与基本逻辑。","answer_points":[{"point":"第一步：资产占用费分摊到各部门","detail":"先将资产占用费按一定基础分摊到公司各部门，作为后续分摊的起点。"},{"point":"第二步：后援管理部门分摊到直接业务部门","detail":"将后援管理部门（投资管理部门除外）的费用分摊到直接业务部门；投资管理部门费用全部计入投资收益，不分摊至直接业务部门。"},{"point":"第三步：归集费用分摊到险种或业务类别","detail":"将直接业务部门归集的费用、其他营业费用、投资收益，按分摊标准分摊到险种或业务类别。"},{"point":"IBNR分摊公式","detail":"某险种IBNR＝各险种分摊比例×（该险种滚动至少12个月分保后已决赔款＋报告期末分保后已发生已报案未决赔款准备金）。"},{"point":"分摊比例的确定逻辑","detail":"以各险种‘分保后已决赔款＋分保后已报未决赔款准备金’占全部险种合计的比例作为分摊比例。"},{"point":"实际可运用资金量","detail":"＝期初实际可运用资金量＋报告期实际收到保费－实际支付的赔款给付，按收付实现制以日、周或月为基础确认计量。"},{"point":"投资收益的分摊","detail":"按资产负债匹配要求分摊，匹配要求相同的资金按实际可运用资金量比例分摊。"}],"framework":"三步流程（资产占用费→后援部门→险种）→IBNR公式与比例→资金量与投资收益分摊。","memo":"易错：第一步是资产占用费分摊；投资管理部门‘整块’进投资收益，不进入直接业务部门。","tag":"费用分摊指引"},{"id":"qa-doc4-01","difficulty":1,"q":"保险混合合同在什么情况下应分拆、什么情况下整体确定为保险合同？重大保险风险测试应在何时、以什么基础进行？","answer_points":[{"point":"分拆的前提条件","detail":"合同既承担保险风险又承担其他风险，且保险风险部分与其他风险部分能够区分并能够单独计量的，应当进行分拆。"},{"point":"不能分拆且保险风险重大","detail":"保险风险部分与其他风险部分不能区分或不能单独计量的，若保险风险重大，应当将整个合同确定为保险合同。"},{"point":"不能分拆且保险风险不重大","detail":"不能区分或不能单独计量且保险风险不重大的，不确定为保险合同，按金融工具准则处理。"},{"point":"后续适用准则","detail":"确定为保险合同的按25号、26号准则处理；不确定为保险合同的按22号、37号金融工具准则处理。"},{"point":"测试时点","detail":"重大保险风险测试应当在合同初始确认日进行，而非资产负债表日或赔付发生时。"},{"point":"测试基础","detail":"以单项合同为基础进行测试；保险风险同质的，可以按照合同组合为基础进行。"}],"framework":"分拆前提→不能分拆时的整体认定（重大/不重大）→测试时点与基础。","memo":"易错：测试在‘初始确认日’，不是资产负债表日；整体认定关键看保险风险是否重大。","tag":"保险合同相关会计处理规定"},{"id":"qa-doc4-02","difficulty":2,"q":"保险合同准备金计量的基本要求有哪些？特别是折现率的确定、首日利得损失的确认以及禁止计提的准备金类型。","answer_points":[{"point":"计量基础","detail":"以履行保险合同相关义务所需支出的合理估计金额（预期未来净现金流出）为基础，按各种情形的可能结果及相关概率计算确定。"},{"point":"边际因素","detail":"保险人应考虑边际因素并单独计量，在保险期间内采用系统、合理的方法将边际计入当期损益。"},{"point":"首日损益处理","detail":"初始确认日不应当确认首日利得；发生首日损失的，应当予以确认并计入当期损益。"},{"point":"折现率确定原则","detail":"货币时间价值影响重大的应对未来现金流量折现；折现率以资产负债表日可获取的当前信息为基础确定，不得锁定。"},{"point":"折现率确定方法","detail":"未来保险利益不受资产组合投资收益影响的合同，按与负债现金流出期限和风险相当的市场利率确定；随投资收益变化的，按对应资产组合预期未来投资收益率确定。"},{"point":"禁止计提的项目","detail":"不得计提以平滑收益为目的的巨灾准备金、平衡准备金、平滑准备金等。"},{"point":"现金流分别估计","detail":"原保险合同现金流量和与其相关的再保险合同现金流量应当分别估计，从再保险分入人摊回的准备金确认为资产。"}],"framework":"计量基础（净现金流出）→边际→首日损益→折现率（不锁定）→禁止项目。","memo":"易错：折现率‘不得锁定’是区别于原精算规定的重要点；首日只认损失、不认利得。","tag":"保险合同相关会计处理规定"},{"id":"qa-doc5-01","difficulty":1,"q":"根据《关于做好企业会计准则解释第2号实施工作的通知》，非寿险业务准备金的折现率假设与风险边际应如何确定？","answer_points":[{"point":"折现率基准","detail":"以中央国债登记结算有限责任公司编制的750个工作日国债收益率曲线的移动平均为基准，加合理的溢价确定。"},{"point":"溢价上限","detail":"溢价幅度暂不得高于150个基点。"},{"point":"风险边际测算方法","detail":"财产保险公司与再保险公司测算非寿险业务准备金风险边际的方法限定为资本成本法和75%分位数法。"},{"point":"风险边际比例区间","detail":"风险边际与未来现金流现值无偏估计的比例不得超出2.5%－15.0%的区间。"},{"point":"无数据基础的兜底","detail":"无数据基础的，未到期责任准备金风险边际按未来现金流现值无偏估计的3.0%确定，未决赔款准备金按2.5%确定。"}],"framework":"折现率基准（750日曲线+溢价≤150bp）→风险边际两法→比例区间→无数据基础兜底。","memo":"易错：溢价≤150bp；无数据基础时未到期3.0%、未决2.5%，二者不同。","tag":"解释第2号"},{"id":"qa-doc5-02","difficulty":2,"q":"原保险保单与再保险保单的保险风险比例如何计算？确认保险合同、再保险合同的阈值分别为多少？","answer_points":[{"point":"原保险风险比例公式","detail":"（1－保险事故不发生情景下保险公司支付的金额÷保险事故发生情景下保险公司支付的金额）×100%。"},{"point":"非年金保单确认阈值","detail":"保险风险比例在保单存续期一个或多个时点大于等于5%的，确认为保险合同。"},{"point":"年金保单例外","detail":"转移了长寿风险的年金保单，通常可确认为保险合同。"},{"point":"再保险风险比例公式","detail":"（Σ再保险分入人发生净损失情形下损失金额的现值×发生概率÷再保险分入人预期保费收入的现值）×100%。"},{"point":"再保险确认阈值","detail":"再保险保单保险风险比例大于1%的，确认为再保险合同。"},{"point":"非寿险保单的简化","detail":"非寿险保单通常显而易见满足转移重大保险风险条件，往往可以不计算保险风险比例直接判定为保险合同。"}],"framework":"原保险公式+5%阈值→年金例外→再保险公式+1%阈值→非寿险直接判定。","memo":"易错：原保险是‘大于等于’5%、再保险是‘大于’1%，二者表述不同，注意临界值。","tag":"解释第2号"},{"id":"qa-doc5-03","difficulty":3,"q":"未通过重大保险风险测试的保单及各类投资型产品负债应如何计量？准备金计量的责任如何划分？","answer_points":[{"point":"公允价值计量类","detail":"投资连结保险分拆后的独立账户负债、非预定收益型非寿险投资型产品的保户投资金负债，按公允价值计量，交易费用计入当期损益。"},{"point":"摊余成本计量类","detail":"未通过重大保险风险测试的保单、万能保险分拆后的投资账户负债、预定收益型非寿险投资型产品的负债，采用实际利率法按摊余成本计量，交易费用计入初始确认金额。"},{"point":"责任主体","detail":"公司法定代表人对准备金会计信息的真实性负责，准备金计量工作由公司董事会负总责。"},{"point":"决策程序","detail":"准备金计量涉及的重大会计政策和会计估计，应经总精算师（精算责任人）和财务负责人同意后，提交董事会或总经理办公会研究决定。"},{"point":"纠正与拒绝签字机制","detail":"董事会或管理层决定违反准则规定的，总精算师和财务负责人应提出纠正建议；未被采纳的应向保监会报告，并有权拒绝签字。"},{"point":"报送时限","detail":"2009年年度财务报告、分红及偿付能力备考报告等可延至2010年5月15日前报送；2010年第1季度偿付能力报告于2010年4月15日前报送。"}],"framework":"负债计量二分（公允/摊余）→责任划分（法定代表人/董事会/总精算师）→时限。","memo":"易错：万能账户→摊余成本；投连/非预定收益型→公允价值；法定代表人负责真实性，董事会负总责。","tag":"解释第2号"},{"id":"qa-doc6-01","difficulty":1,"q":"什么是保险公司次级定期债务？申请募集次级债应满足哪些主要条件？","answer_points":[{"point":"次级债定义","detail":"保险公司为弥补临时性或者阶段性资本不足，经批准募集、期限在五年以上（含五年），且本金和利息的清偿顺序列于保单责任和其他负债之后、先于股权资本的债务。"},{"point":"偿付能力条件","detail":"偿付能力充足率低于150%或者预计未来两年内将低于150%的，才可以申请募集次级债。"},{"point":"经营年限条件","detail":"保险公司开业时间应超过三年。"},{"point":"净资产门槛","detail":"经审计的上年度末净资产不低于人民币5亿元。"},{"point":"累计限额条件","detail":"募集后累计未偿付的次级债本息额不超过上年度末经审计净资产的50%。"},{"point":"其他条件","detail":"还应具备偿债能力、良好的公司治理结构和内部控制、资产未被违规占用，且最近两年内未受到重大行政处罚。"}],"framework":"定义（期限/清偿顺序）→申请条件（充足率/年限/净资产/限额/其他）。","memo":"易错：期限‘五年以上含五年’；充足率门槛是150%而非100%；重大行政处罚单次罚款≥150万元。","tag":"次级定期债务管理办法"},{"id":"qa-doc6-02","difficulty":2,"q":"次级债在募集对象、股东持有比例、赎回与偿还方面有哪些限制性规定？","answer_points":[{"point":"募集期限","detail":"应在保监会批准次级债募集之日起6个月内完成募集（可分期），逾期原批准文件自动失效，需另行申请。"},{"point":"合格投资者","detail":"应向具备独立分析能力和风险承受能力的境内外法人募集，但募集人控制的公司以及与其受同一第三方控制的公司除外。"},{"point":"股东持有比例限制","detail":"单个股东和其控制方持有次级债不得超过单次或累计募集额的10%，且持有比例不得为最高；全部股东及控制方累计不得超过20%。"},{"point":"赎回设定","detail":"赎回权应设定在次级债募集五年后；提前赎回后偿付能力充足率不得低于100%；合同中不得规定债权人具有回售权。"},{"point":"偿还前提","detail":"只有在确保偿还次级债本息后偿付能力充足率不低于100%的前提下才能偿付；不能按时偿付本息期间不得向股东分配利润。"},{"point":"资金用途禁止","detail":"次级债募集资金不得用于投资股权、不动产和基础设施，也不得用于弥补日常经营损失。"}],"framework":"募集期→合格投资者→股东比例→赎回五年后/无回售权→偿还前提→用途禁止。","memo":"易错：募集6个月、赎回5年后；偿还后充足率≥100%；用途禁投股权、不动产、基建。","tag":"次级定期债务管理办法"},{"id":"qa-doc6-03","difficulty":3,"q":"次级债存续期间，保险公司需履行哪些信息披露与向保监会的报告义务？请列举主要时限与重大事项告知情形。","answer_points":[{"point":"招募说明书披露","detail":"发行时通过招募说明书披露期限、利率、清偿顺序等核心条款，保障债权人知情权。"},{"point":"年度专题财务报告","detail":"募集人应在每个会计年度结束后四个月内，向次级债债权人披露上一年度的次级债专题财务报告。"},{"point":"年度专题报告","detail":"每年4月30日之前向保监会提交次级债专题报告。"},{"point":"募集结束报告","detail":"募集结束后十个工作日内向保监会报告募集情况，并报送合同复印件。"},{"point":"季度专项报告","detail":"登记托管的，于每季度结束后十五个工作日内提交次级债专项报告。"},{"point":"重大事项告知","detail":"出现偿付能力重大不利变动、预计难以偿付、重大亏损超净资产10%、重大仲裁诉讼或减资合并解散等情形，应及时告知债权人并同时报告保监会。"},{"point":"延期报告","detail":"次级债延期的，应在签订延期协议后五个工作日内向保监会报告。"}],"framework":"招募说明书→年度/季度报告时限→募集/延期报告→重大事项告知。","memo":"易错：年报对债权人是‘4个月’、对保监会专题报告是‘4月30日’；季度专项报告是‘15个工作日’。","tag":"次级定期债务管理办法"},{"id":"qa-doc7-01","difficulty":2,"q":"上市保险公司发行的次级可转换债券是什么？其在转换为股份前的资本属性与发行条件如何规定？","answer_points":[{"point":"次级可转债定义","detail":"保险公司依程序发行、期限5年以上（含5年）、破产清偿时本金和利息清偿顺序列于保单责任和其他普通负债之后、一定期限内可转换成公司股份的债券。"},{"point":"资本属性","detail":"转换为股份前可以计入公司的附属资本，计入附属资本的比例和标准由保监会另行规定。"},{"point":"清偿顺序","detail":"破产清偿时，次级可转债本金和利息的清偿顺序列于保单责任和其他普通负债之后。"},{"point":"发行主体","detail":"发行主体限于上市保险公司和上市保险集团公司。"},{"point":"抵质押禁止","detail":"发行人不得以公司的资产为抵押或质押来发行次级可转债。"},{"point":"促进转股与回售限制","detail":"条款设计应有利于促进债券持有人将可转债转换为股票；除证券监管部门规定的情形外，不得另外赋予持有人主动回售的权利。"}],"framework":"定义（期限/清偿顺序/转股）→资本属性（附属资本）→发行主体与条件。","memo":"易错：期限‘5年以上含5年’（与次级债一致）；转换前计附属资本；不得以公司资产抵质押。","tag":"次级可转债通知"},{"id":"qa-doc7-02","difficulty":3,"q":"次级可转债的发行申请需履行哪些程序？在后续管理（募集资金、报告时限、注册资本变更）方面有何要求？","answer_points":[{"point":"申请程序","detail":"向保监会提交书面申请及股东大会决议、发行方案、可行性研究报告、已募集附属资本工具情况等文件，并取得保监会监管意见。"},{"point":"可行性研究内容","detail":"应提供公司未来三年的资本规划、转股可行性分析及促进转股的具体方案、募集资金用途（含集团向子公司注资的金额和比例）。"},{"point":"提交证券申请时限","detail":"应在保监会批准发行之日起6个月内向证券监管部门提交发行申请，逾期原批准文件自动失效。"},{"point":"发行与赎回报告时限","detail":"发行结束后十个工作日内向保监会报告发行情况；提前赎回、债权人回售、到期支付全部本息后同样为十个工作日内报告。"},{"point":"专户管理","detail":"募集资金实施专户管理，严格按股东大会决议、可行性研究报告及募集说明书约定的用途使用。"},{"point":"注册资本变更","detail":"因转股影响注册资本的，应向保监会申请变更注册资本和修改公司章程；并在季度和年度偿付能力报告中说明赎回、回售和转股情况及其影响。"}],"framework":"申请程序（文件+监管意见）→可行性内容→证券申请6个月→发行/赎回报告10日→专户与注资变更。","memo":"易错：证券申请6个月、发行报告10个工作日；转股影响注册资本须申请变更。","tag":"次级可转债通知"}],"calc":[{"id":"c-doc3-01","difficulty":1,"stem":"某保险公司对A、B、C三个险种合并评估IBNR为150万元。A险种滚动12个月分保后已决赔款300万元、已发生已报案未决赔款准备金100万元；B险种分别为600万元、200万元；C险种分别为900万元、300万元。按分摊比例将合并IBNR分配至各险种（分摊比例＝合并IBNR÷各险种‘已决赔款＋已报未决赔款准备金’合计数）。","blanks":[{"label":"A险种应分摊IBNR（万元）","answer":25,"tolerance":0.5},{"label":"B险种应分摊IBNR（万元）","answer":50,"tolerance":0.5},{"label":"C险种应分摊IBNR（万元）","answer":75,"tolerance":0.5}],"steps":["第1步：计算各险种基数＝分保后已决赔款＋分保后已报未决赔款准备金：A＝300＋100＝400，B＝600＋200＝800，C＝900＋300＝1200。","第2步：计算分摊比例＝150÷（400＋800＋1200）＝150÷2400＝6.25%。","第3步：各险种分摊IBNR＝基数×6.25%：A＝400×6.25%＝25，B＝800×6.25%＝50，C＝1200×6.25%＝75；合计25＋50＋75＝150，与合并IBNR一致。"],"formula_card":"某险种IBNR＝合并IBNR×（该险种分保后已决赔款＋分保后已报未决赔款准备金）÷∑各险种（分保后已决赔款＋分保后已报未决赔款准备金）","analysis":"基线合计＝400＋800＋1200＝2400万元，分摊比例＝150÷2400＝6.25%。A＝400×6.25%＝25万元，B＝800×6.25%＝50万元，C＝1200×6.25%＝75万元，三险种合计150万元与合并IBNR相符。","trap":"基数是‘已决赔款＋已报未决赔款准备金’之和，不是单用已决赔款；注意C险种基数最大，占比50%。","tag":"费用分摊指引"},{"id":"c-doc6-01","difficulty":1,"stem":"某保险公司上年度末经审计净资产为80亿元，已发行且尚未偿付的次级债本息余额为20亿元。该公司拟新募集次级债，问：计入附属资本的次级债金额上限为多少亿元？募集后累计未偿付本息额是否超过限额？","blanks":[{"label":"计入附属资本的次级债金额上限（亿元）","answer":40,"tolerance":0.5}],"steps":["第1步：计入附属资本的次级债金额不得超过净资产的50%，上限＝80×50%＝40亿元。","第2步：募集后累计未偿付次级债本息额不得超过上年度末净资产的50%，即同样不得超过40亿元。","第3步：已未偿付20亿元，若新募集不超过20亿元则不超限；无论募集多少，计入附属资本的上限均为40亿元。"],"formula_card":"计入附属资本的次级债金额≤净资产×50%；募集后累计未偿付次级债本息额≤上年度末经审计净资产×50%","analysis":"净资产80亿元，50%为40亿元，即计入附属资本上限与累计未偿付本息上限均为40亿元。已未偿付20亿元尚在限额内，新募集空间最多20亿元。","trap":"两个50%口径相同（均按净资产），但分别约束‘计入附属资本额’与‘累计未偿付本息额’；勿将两者混算。","tag":"次级定期债务管理办法"},{"id":"c-doc5-01","difficulty":2,"stem":"某两全保险保单，保险事故发生情景下保险公司支付100万元，保险事故不发生情景下支付80万元。计算该原保险保单的保险风险比例，并判断是否确认为保险合同（非年金保单阈值：存续期一个或多个时点比例≥5%）。","blanks":[{"label":"保险风险比例（%）","answer":20,"tolerance":0.5},{"label":"是否确认为保险合同（1＝是，0＝否）","answer":1,"tolerance":0.5}],"steps":["第1步：原保险风险比例＝（1－不发生情景支付÷发生情景支付）×100%＝（1－80÷100）×100%。","第2步：80÷100＝0.8，1－0.8＝0.2，比例＝0.2×100%＝20%。","第3步：非年金保单阈值≥5%，20%≥5%，故确认为保险合同。"],"formula_card":"原保险保单保险风险比例＝（1－保险事故不发生情景下支付÷保险事故发生情景下支付）×100%；确认阈值≥5%","analysis":"（1－80/100）×100%＝20%，大于5%的确认阈值，该保单确认为保险合同。","trap":"注意是‘不发生÷发生’再被1减；阈值是‘大于等于’5%，临界5%即确认，勿误用大于。","tag":"解释第2号"},{"id":"c-doc5-02","difficulty":2,"stem":"某财产保险公司某未决赔款准备金未来现金流现值无偏估计为4000万元，且公司无数据基础进行风险边际测算。计算该未决赔款准备金应采用的风险边际金额（万元）。","blanks":[{"label":"风险边际金额（万元）","answer":100,"tolerance":0.5}],"steps":["第1步：无数据基础的，未决赔款准备金风险边际按未来现金流现值无偏估计的2.5%确定。","第2步：风险边际＝4000×2.5%＝100万元。","第3步：校验比例＝100÷4000＝2.5%，恰为下限，符合2.5%－15.0%区间要求。"],"formula_card":"无数据基础时：未决赔款准备金风险边际＝未来现金流现值无偏估计×2.5%；未到期责任准备金为×3.0%","analysis":"4000×2.5%＝100万元，该风险边际占无偏估计比例恰为2.5%，处于允许区间下限。","trap":"无数据基础时未决赔款是2.5%、未到期责任准备金是3.0%，二者不同，勿混淆；且此比例须落在2.5%－15%区间内。","tag":"解释第2号"},{"id":"c-doc1-01","difficulty":3,"stem":"某非寿险公司本年度按合同约定保费总额确认保费收入5000万元。期初未到期责任准备金余额800万元，期末未到期责任准备金余额1200万元（按保险精算确定，作为当期保费收入的调整）。计算：本期提取（净增）未到期责任准备金金额，以及本期已赚保费（万元）。","blanks":[{"label":"本期提取未到期责任准备金（万元）","answer":400,"tolerance":0.5},{"label":"本期已赚保费（万元）","answer":4600,"tolerance":0.5}],"steps":["第1步：确认非寿险保费收入当期，按精算确定金额提取未到期责任准备金，作为保费收入的调整，提取净额＝期末－期初。","第2步：提取未到期责任准备金＝1200－800＝400万元。","第3步：已赚保费＝保费收入－（期末未到期－期初未到期）＝5000－400＝4600万元。"],"formula_card":"本期提取未到期责任准备金＝期末未到期责任准备金－期初未到期责任准备金；已赚保费＝保费收入－（期末未到期－期初未到期）","analysis":"提取净额＝1200－800＝400万元；已赚保费＝5000－400＝4600万元，逻辑自洽。","trap":"未到期责任准备金是‘当期净提取’＝期末减期初，不是直接用期末数；已赚保费=保费收入减当期净提取额，勿误减期初或期末单一数值。","tag":"25号-原保险合同"},{"id":"c-doc6-02","difficulty":3,"stem":"某保险公司单次募集次级债50亿元。根据股东持有比例限制，计算：单个股东及其控制方最多可持有多少亿元？全部股东及控制方累计最多可持有多少亿元？","blanks":[{"label":"单个股东及控制方最多持有（亿元）","answer":5,"tolerance":0.5},{"label":"全部股东及控制方累计最多持有（亿元）","answer":10,"tolerance":0.5}],"steps":["第1步：单个股东和股东控制方持有次级债不得超过单次或累计募集额的10%，即50×10%＝5亿元，且持有比例不得为最高。","第2步：全部股东和所有股东控制方累计持有不得超过单次或累计募集额的20%，即50×20%＝10亿元。","第3步：校验：单个上限5亿元＜累计上限10亿元，约束相容；5亿元恰好为累计上限的一半。"],"formula_card":"单个股东及控制方持有≤募集额×10%（且不得为最高）；全部股东及控制方累计持有≤募集额×20%","analysis":"50×10%＝5亿元，50×20%＝10亿元，二者均符合办法规定。","trap":"单个10%与累计20%是两个独立上限，单个5亿元必须小于累计10亿元且不得成为最高持有比例；募集人控制的公司不计入合格投资者。","tag":"次级定期债务管理办法"}]},{"id":"fm_docs_8_13","group":"财务管理制度","name":"财务管理制度（金融工具/保险合同修订等6份）","qa":[{"id":"qa-22-01","difficulty":1,"q":"企业应当依据什么标准对金融资产进行分类？分类的结果有哪些？","answer_points":[{"point":"以管理金融资产的业务模式为标准之一","detail":"业务模式反映企业如何管理金融资产以产生现金流量，即现金流量来源于收取合同现金流量、出售该资产还是两者兼有，这是分类的首要判断维度。"},{"point":"以金融资产的合同现金流量特征（SPPI）为标准之二","detail":"合同现金流量必须仅为对本金和未偿付本金金额为基础利息的支付，其中利息包含货币时间价值、信用风险以及其他基本借贷风险、成本和利润的对价。"},{"point":"分类结果一：以摊余成本计量（AMC）","detail":"当业务模式为收取合同现金流量且通过SPPI测试时，分类为以摊余成本计量，后续按实际利率法摊销并计提损失准备。"},{"point":"分类结果二：以公允价值计量且其变动计入其他综合收益（FVOCI）","detail":"当业务模式既以收取合同现金流量又以出售该金融资产为目标且通过SPPI测试时，分类为FVOCI，公允价值变动计入其他综合收益。"},{"point":"分类结果三：以公允价值计量且其变动计入当期损益（FVTPL）","detail":"除上述两类之外的金融资产，或企业为消除会计错配在初始确认时指定的，分类为FVTPL，公允价值变动直接计入损益。"}],"framework":"判断业务模式 → 进行SPPI测试 → 映射到三分类（AMC/FVOCI/FVTPL）。","memo":"双标准缺一不可；SPPI不通过一律归入FVTPL。","tag":"22号-金融工具确认和计量"},{"id":"qa-22-02","difficulty":2,"q":"预期信用损失法下，金融资产损失准备如何按三阶段计量？各阶段的判断关键点是什么？","answer_points":[{"point":"阶段一：信用风险自初始确认后未显著增加","detail":"按相当于未来12个月内预期信用损失的金额计量损失准备，利息收入按账面余额和实际利率计算，是最轻的计量档。"},{"point":"阶段二：信用风险已显著增加但尚未减值","detail":"信用风险自初始确认后已显著增加时，按相当于整个存续期内预期信用损失的金额计量，但资产尚未发生实际信用减值。"},{"point":"阶段三：已发生信用减值","detail":"资产负债表日已发生信用减值的金融资产，按整个存续期预期信用损失计量，且利息收入改按摊余成本和经信用调整的实际利率计算。"},{"point":"30日推定规则","detail":"通常情况下逾期超过30日表明信用风险已显著增加，除非企业有合理依据证明仍未显著增加，该规则是实务中常用的判断抓手。"},{"point":"显著增加的判断看相对变化","detail":"比较违约风险的相对变化而非绝对数值，同一绝对变化下初始违约风险较低者变化更显著，体现相对性要求。"},{"point":"POCI采用经信用调整的实际利率","detail":"购买或源生的已发生信用减值的金融资产，自初始确认起采用经信用调整的实际利率确认利息收入，该利率在确定时考虑初始预期信用损失。"}],"framework":"判断信用风险是否显著增加 → 判断是否已减值 → 选定阶段 → 确定ECL计量期间与适用利率。","memo":"阶段一计12个月、阶段二三计整个存续期；区分“显著增加”与“已减值”。","tag":"22号-金融工具确认和计量"},{"id":"qa-22-03","difficulty":3,"q":"金融资产与金融负债在重分类、指定以及嵌入衍生工具处理上分别有哪些限制性规定？","answer_points":[{"point":"金融资产仅在业务模式变更时重分类","detail":"企业改变管理金融资产的业务模式时，应对受影响的金融资产重分类，并采用未来适用法，不追溯重述以前期间的利得损失。"},{"point":"金融负债不得重分类","detail":"无论管理层意图如何变化，金融负债均不得进行重分类，这是与金融资产重分类的明确区别。"},{"point":"指定一经做出不得撤销","detail":"如非交易性权益工具投资指定为FVOCI、或金融资产或负债指定为FVTPL，该指定一经做出不得撤销。"},{"point":"FVTPL指定须满足消除会计错配等条件","detail":"企业将金融资产或负债指定为FVTPL应满足消除或显著减少会计错配等条件，并非可任意指定。"},{"point":"主合同为资产的混合合同不拆分嵌入衍生工具","detail":"嵌入衍生工具所在主合同属于本准则规范的资产的，企业不应分拆嵌入衍生工具，而是作为整体适用金融资产分类。"},{"point":"主合同非资产需评估分拆","detail":"主合同不属于本准则规范的资产且嵌入衍生工具经济特征与主合同不紧密相关时，应当分拆并按相应会计准则处理。"},{"point":"企业合并或有对价构成金融资产的限制","detail":"企业合并中或有对价构成金融资产的，应分类为FVTPL，不得指定为FVOCI，避免损益操纵。"}],"framework":"金融资产重分类条件（仅业务模式变、未来适用）→ 指定撤销限制 → 嵌入衍生分拆规则（主合同为资产不拆分）。","memo":"负债不可重分类；指定不可逆；主合同为资产不拆分嵌入衍生。","tag":"22号-金融工具确认和计量"},{"id":"qa-23-01","difficulty":1,"q":"金融资产转移后，企业应在何种情形下终止确认该金融资产？","answer_points":[{"point":"情形一：转移了几乎所有风险和报酬","detail":"企业转移了金融资产所有权上几乎所有风险和报酬的，应当终止确认该金融资产，这是最彻底的终止确认情形。"},{"point":"情形二：合同权利终止或满足终止确认规定","detail":"收取该金融资产现金流量的合同权利终止，或金融资产已转移且转移满足CAS23关于终止确认的规定时，应予终止确认。"},{"point":"保留几乎所有风险和报酬则继续确认","detail":"如固定价格或售价加回报回购、证券出借、全额补偿信用损失、重大价内期权等，表明保留几乎所有风险报酬，应继续确认。"},{"point":"既未转移也未保留时按控制判断","detail":"当企业既未转移也未保留几乎所有风险和报酬时，需进一步判断是否保留控制，从而决定终止确认还是继续涉入。"},{"point":"控制判断标准","detail":"若转入方能够单方面将金融资产整体出售给不相关第三方且无额外条件限制，则企业未保留控制，通常可终止确认。"}],"framework":"评估风险报酬转移程度 → 判断是否保留控制 → 得出终止确认/继续确认/继续涉入结论。","memo":"几乎全转移→终止；几乎全保留→继续确认；中间情形→看控制。","tag":"23号-金融资产转移"},{"id":"qa-23-02","difficulty":2,"q":"金融资产整体满足终止确认条件时，相关会计处理和损益如何确定？","answer_points":[{"point":"账面价值与对价差额计入损益","detail":"被转移金融资产在终止确认日的账面价值，减去因转移收到的对价及原计入其他综合收益对应部分之和，其差额计入当期损益。"},{"point":"FVOCI累计额随终止确认转入损益","detail":"FVOCI类金融资产对应的原计入其他综合收益的公允价值变动累计额中对应终止确认部分，与收到对价共同计算差额并计入当期损益。"},{"point":"保留服务权确认服务资产或负债","detail":"企业保留向金融资产提供相关收费服务权利时，应就该服务合同确认一项服务资产或服务负债。"},{"point":"新取得金融资产或负债以公允价值初始计量","detail":"因转移导致整体终止确认同时获得新金融资产或新金融负债的，应在转移日以公允价值进行初始计量。"},{"point":"部分终止确认的条件","detail":"金融资产一部分仅包括特定可辨认现金流量，或与全部现金流量完全成比例的部分时，终止确认规定适用于该部分。"}],"framework":"终止确认日账面值 − 收到对价 − OCI对应部分 = 当期损益；同时处理OCI、服务权、新工具。","memo":"OCI累计额随终止确认转入损益，不留存所有者权益。","tag":"23号-金融资产转移"},{"id":"qa-23-03","difficulty":2,"q":"企业转移金融资产但未终止确认（继续涉入）时，常见的计量模式有哪些？","answer_points":[{"point":"继续确认的整体情形","detail":"保留几乎所有风险和报酬时，继续确认被转移金融资产，且金融资产与相关金融负债不得相互抵销。"},{"point":"担保方式继续涉入","detail":"以担保方式继续涉入的，按金融资产账面价值与担保金额两者的较低者继续确认资产，并按担保金额与担保合同公允价值之和确认相关负债。"},{"point":"看涨或看跌期权继续涉入（摊余成本计量）","detail":"被转移金融资产以摊余成本计量时，按可能回购金额继续确认被转移金融资产，相关负债按对应摊余成本计量。"},{"point":"公允价值计量下的继续涉入","detail":"被转移金融资产以公允价值计量时，相关负债按行权价格扣除期权时间价值等计量，资产与负债后续变动一致处理。"},{"point":"保留次级权益信用增级","detail":"保留次级权益或提供信用担保仅转移部分风险报酬且保留控制的，应按其继续涉入程度确认被转移金融资产。"},{"point":"继续涉入资产与负债不得抵销","detail":"继续涉入情形下相关资产与负债不得相互抵销，且以公允价值计量的后续变动应保持一致处理。"}],"framework":"判断是否保留控制 → 继续确认或继续涉入 → 选定计量模式（担保/期权/次级权益）。","memo":"担保方式取“账面值与担保额较低者”；相关资产与负债不得抵销。","tag":"23号-金融资产转移"},{"id":"qa-37-01","difficulty":1,"q":"企业应如何区分金融负债与权益工具？区分所依据的原则是什么？","answer_points":[{"point":"依据合同条款及经济实质而非法律形式","detail":"企业应当根据所发行金融工具的合同条款及其反映的经济实质，结合定义进行分类，不能仅凭法律形式判断。"},{"point":"权益工具的定义","detail":"权益工具是能证明拥有某个企业在扣除所有负债后的资产中剩余权益的合同，代表对剩余资产的索取权。"},{"point":"权益工具的两项条件","detail":"一是不包括交付现金或其他金融资产的合同义务；二是将来须用或可用自身权益工具结算时，非衍生工具不应包括交付可变数量自身权益工具的义务，衍生工具只能以固定数量自身权益工具交换固定金额现金或其他金融资产。"},{"point":"复合金融工具先分负债成分","detail":"发行复合金融工具时先确定金融负债成分公允价值（含其中非权益性嵌入衍生工具），再从整体公允价值中扣除负债成分作为权益成分价值。"},{"point":"交易费用在负债与权益间分摊","detail":"发行复合金融工具发生的交易费用，应在金融负债成分和权益工具成分之间按各自占总发行价款的比例进行分摊。"}],"framework":"合同条款+经济实质 → 是否满足权益两项条件 → 负债/权益/复合工具拆分。","memo":"实质重于形式；复合工具“先负债后权益”。","tag":"37号-金融工具列报"},{"id":"qa-37-02","difficulty":2,"q":"金融资产与金融负债在资产负债表内相互抵销须满足哪些条件？哪些情形不得抵销？","answer_points":[{"point":"条件一：具有法定权利且当前可执行","detail":"企业具有抵销已确认金额的法定权利，且该法定权利在当前是可执行的，这是抵销的前提条件。"},{"point":"条件二：计划净额结算或同时结算","detail":"企业计划以净额结算，或者在变现金融资产的同时清偿该金融负债，两项满足其一即可抵销。"},{"point":"合成工具不得抵销","detail":"使用多项不同金融工具仿效单项金融工具特征（合成工具）的，通常认为不满足抵销条件。"},{"point":"不同交易对手不得抵销","detail":"金融资产和金融负债虽具有相同主要风险敞口但涉及不同交易对手方的，不得相互抵销。"},{"point":"无追索权负债与担保物不得抵销","detail":"无追索权金融负债与作为其担保物的金融资产或其他资产，通常不得相互抵销。"},{"point":"总互抵协议须表格披露","detail":"对总互抵协议下的已确认金融工具，应以表格形式披露总额、抵销金额、净额、协议未抵销金额及最终净额。"}],"framework":"两条件同时具备方可抵销 → 列举典型不得抵销情形 → 总互抵协议披露。","memo":"两条件须同时具备；同风险不同对手不可抵销。","tag":"37号-金融工具列报"},{"id":"qa-37-03","difficulty":3,"q":"可回售工具分类为权益工具须同时满足哪些特征？库存股应如何处理？","answer_points":[{"point":"特征一：清算时按比例获得净资产","detail":"该工具赋予持有方在企业清算时按比例份额获得该企业净资产的权利，体现剩余权益属性。"},{"point":"特征二：类别次于其他所有工具","detail":"该工具所属类别次于其他所有工具类别，归属于该类别前无须转换为另一种工具，且在清算时对企业资产没有优先于其他工具的要求权。"},{"point":"特征三：类别内工具特征相同","detail":"该类别内所有工具具有相同的特征，确保同类工具会计处理一致。"},{"point":"特征四：不再满足金融负债其他特征","detail":"除满足可回售特征外，该工具不再同时满足金融负债定义中的其他特征。"},{"point":"特征五：现金流量实质基于损益和净资产","detail":"该工具在存续期内的预计现金流量总额，实质上基于企业的损益、已确认净资产的变动。"},{"point":"库存股减少所有者权益","detail":"回购自身权益工具支付的对价和交易费用应当减少所有者权益，不得确认金融资产，库存股在资产负债表中单独列示。"},{"point":"合并报表中少数股东部分的处理","detail":"符合可回售工具条件但在合并财务报表中对应的少数股东权益部分，应当分类为金融负债而非权益工具。"}],"framework":"可回售五项特征逐条核对 → 库存股权益扣减 → 合并层面例外处理。","memo":"五项特征全满足才是权益；合并报表少数股东部分转负债。","tag":"37号-金融工具列报"},{"id":"qa-capbond-01","difficulty":1,"q":"根据银保监发〔2020〕17号，保险资金可以投资哪些银行资本补充债券？投资后应如何分类？","answer_points":[{"point":"可投资品种一：二级资本债券","detail":"保险资金可以投资银行发行的二级资本债券，该类债券满足商业银行资本管理办法规定的二级资本工具特征，可计入银行二级资本。"},{"point":"可投资品种二：无固定期限资本债券","detail":"保险资金可以投资无固定期限资本债券（永续债），其无固定到期日、发行人可自主决定是否赎回，是资本补充债券的一种。"},{"point":"分类原则：按发行人会计分类","detail":"保险资金投资的上述债券，应当按照发行人对其权益工具或债务工具的分类，相应确认为权益类资产或固定收益类资产。"},{"point":"纳入相应监管比例管理","detail":"相关资产按发行人分类结果纳入相应的保险资金运用监管比例管理，而非由保险机构自行确定类别。"}],"framework":"两类品种（二级资本债、永续债）→ 按发行人会计分类 → 归入对应监管比例。","memo":"仅限两类债券；分类看发行人而非监管单方面认定。","tag":"投资银行资本补充债券"},{"id":"qa-capbond-02","difficulty":2,"q":"保险机构投资银行资本补充债券需要满足哪些资质与持续监管要求？","answer_points":[{"point":"信用风险管理能力达标","detail":"保险机构的信用风险管理能力应当达到银保监会规定的标准，方可开展此类投资。"},{"point":"偿付能力充足率门槛120%","detail":"上季度末偿付能力充足率不得低于120%，这是保险机构开展投资的资格红线。"},{"point":"发行人三项核心条件","detail":"发行人应当符合公司治理良好、经营稳健、资本充足率符合监管规定三项核心要求。"},{"point":"持有期间持续监控","detail":"持有资本补充债券期间，若偿付能力充足率低于120%，应当及时调整投资策略、采取有效措施控制相关风险。"},{"point":"重大风险报告义务","detail":"投资的债券发生重大风险或引发触发事件的，保险机构应当及时向银保监会报告。"}],"framework":"资质（能力达标+120%红线）→ 发行人条件 → 持续监控与报告。","memo":"上季末偿付能力≥120%；低于即须调策略并报风险。","tag":"投资银行资本补充债券"},{"id":"qa-25-01","difficulty":2,"q":"保险合同组在初始确认和后续计量上有哪些核心规定？","answer_points":[{"point":"初始计量=履约现金流量+合同服务边际","detail":"企业应在合同组初始确认时按履约现金流量与合同服务边际之和对保险合同负债进行初始计量。"},{"point":"履约现金流量由三部分组成","detail":"包括与履行保险合同直接相关的未来现金流量估计、货币时间价值及金融风险调整、非金融风险调整，且估计不考虑企业自身的不履约风险。"},{"point":"合同组三档分组","detail":"同一合同组合在初始确认时至少分为亏损合同组、无显著亏损可能性合同组、以及该组合中剩余合同组成的合同组三档。"},{"point":"确认时点取三者最早","detail":"合同组在责任期开始日、保单持有人首付款到期日（或实际收到日）、发生亏损时三者中的最早时点确认。"},{"point":"后续计量分两项负债","detail":"资产负债表日按未到期责任负债与已发生赔款负债之和对保险合同负债进行后续计量。"},{"point":"投资成分不计入服务收入","detail":"确认保险服务收入和保险服务费用时，不得包含保险合同中的投资成分，投资成分单独处理。"}],"framework":"初始计量（履约现金流+CSM）→ 三档分组 → 确认时点 → 后续两项负债。","memo":"负债=履约现金流+CSM；服务收入须剔除投资成分。","tag":"修订25号-保险合同"},{"id":"qa-25-02","difficulty":3,"q":"保险合同计量中“合同服务边际（CSM）”的确认、调整与亏损处理有哪些关键规则？","answer_points":[{"point":"CSM是未来确认的未赚利润","detail":"合同服务边际是企业因在未来提供保险合同服务而将于未来确认的未赚利润，代表预期利润的储备。"},{"point":"初始现金净流入确认为CSM","detail":"初始确认时各项现金流量之和反映为现金净流入的，确认为合同服务边际；反映为现金净流出的，作为首日亏损计入当期损益。"},{"point":"CSM的五项调整（不具分红特征）","detail":"期初CSM经当期归入合同影响、计提利息、与未来服务相关履约现金流量变动、汇兑差额、当期摊销五项进行调整。"},{"point":"CSM计息利率的确定","detail":"CSM计息采用合同组内合同确认时不随基础项目回报变动的现金流量所适用的加权平均利率。"},{"point":"亏损确认的触发","detail":"与未来服务相关的估计变更使履约现金流量增加额超过CSM账面价值，或具分红特征合同基础项目企业份额减少额超过CSM时，确认亏损计入当期损益。"},{"point":"金融变动额会计政策选择","detail":"保险合同金融变动额可在合同组合层面选择全额计入当期保险财务损益，或分解计入损益与其他综合收益，且须一致应用。"},{"point":"分入分出再保险不适用分红特殊规定","detail":"分入和分出的再保险合同不适用具有直接参与分红特征合同的特殊规定，避免计量错配。"}],"framework":"CSM定义 → 初始确认（净流入→CSM）→ 五项调整 → 亏损触发 → 政策选择。","memo":"净流入→CSM，净流出→首日亏损；未来服务变动超CSM即亏损。","tag":"修订25号-保险合同"},{"id":"qa-25-03","difficulty":3,"q":"新保险合同准则下计量方法有哪些？保费分配法（PAA）的适用条件是什么？","answer_points":[{"point":"通用模型法（BBA）","detail":"采用履约现金流量加合同服务边际的通用计量模型，适用于大多数不具有直接参与分红特征的保险合同。"},{"point":"浮动收费法","detail":"对具有直接参与分红特征的保险合同，按基础项目公允价值减去浮动收费计量履约现金流量。"},{"point":"保费分配法（PAA）简化","detail":"对短期合同允许采用保费分配法简化计量，以已收和预计保费分配为基础，降低核算复杂度。"},{"point":"PAA条件一：结果无重大差异","detail":"企业能合理预计采用PAA与一般模型计量未到期责任负债结果无重大差异；若履约现金流量在赔案发生前将发生重大变化则不符合。"},{"point":"PAA条件二：责任期不超过一年","detail":"该合同组内各项合同的责任期不超过一年，是适用保费分配法的时间门槛。"},{"point":"PAA下获取现金流量的处理","detail":"采用PAA时保险获取现金流量可选择在发生时计入费用，未选择的应随时间摊销计入保险服务费用。"}],"framework":"三方法（BBA/浮动收费/PAA）→ PAA两条件（无重大差异+责任期≤1年）。","memo":"PAA仅限短期（≤1年）且结果无重大差异；分红合同用浮动收费法。","tag":"修订25号-保险合同"},{"id":"qa-25-04","difficulty":3,"q":"修订后保险合同准则在执行日期、适用范围与风险分拆上有哪些关键变化？","answer_points":[{"point":"分两批执行日期","detail":"境内外同时上市或境外上市采用IFRS/CAS的企业自2023年1月1日起执行；其他执行企业会计准则的企业自2026年1月1日起执行，并允许提前执行。"},{"point":"保险风险定义变化","detail":"保险风险定义为从保单持有人转移至签发人的除金融风险之外的风险，与原准则显著不同，凸显保险本质。"},{"point":"投资成分分拆","detail":"企业应将保险合同中的投资成分分拆，不确认为保险合同服务收入与费用，单独进行会计处理。"},{"point":"嵌入衍生工具分拆","detail":"保险合同中嵌入衍生工具的，应按规定进行分拆，分别适用相应会计准则。"},{"point":"合同合并与分组限制","detail":"不得将签发时间间隔超过一年的合同归入同一合同组，确保组内风险同质性。"},{"point":"与金融工具准则衔接","detail":"准则与IFRS17趋同，建立基于履约现金流量和合同服务边际的新计量模型，与CAS22等金融工具准则体系衔接。"}],"framework":"执行日期（2023/2026）→ 保险风险定义 → 成分分拆 → 合并分组限制。","memo":"其他企业2026年执行；保险风险=除金融风险之外的风险。","tag":"修订25号-保险合同"},{"id":"qa-notice-01","difficulty":1,"q":"财会〔2020〕22号对尚未执行新金融工具准则企业的执行时间作了哪些安排？","answer_points":[{"point":"非上市企业原则2021年执行","detail":"执行企业会计准则的非上市企业原则上应自2021年1月1日起执行新金融工具相关会计准则（指CAS22、23、24、37）。"},{"point":"适用资本办法的非上市企业可推迟至2022年","detail":"适用商业银行资本管理办法的非上市企业执行确有困难的，可以推迟至2022年1月1日起执行。"},{"point":"资产管理产品推迟至2022年","detail":"适用资管业务指导意见的资产管理产品，执行日期可推迟至2022年1月1日。"},{"point":"保险公司暂缓至CAS25同步","detail":"符合特定条件的保险公司执行新准则的日期允许暂缓至执行CAS25（财会〔2020〕20号）的日期。"},{"point":"推迟须报备并披露","detail":"推迟执行的企业应在2021年4月30日前向财政部和银保监会报备并说明原因，并在2020、2021年度报告中披露推迟情况。"}],"framework":"非上市2021 → 银行/资管2022 → 保险与CAS25同步 → 报备披露。","memo":"新准则指CAS22/23/24/37；保险与25号准则同步执行。","tag":"新金融工具会计准则通知"},{"id":"qa-notice-02","difficulty":2,"q":"非上市银行采用监管资本过渡安排时，调整基数加回比例如何规定？已加回准备有何限制？","answer_points":[{"point":"调整基数的定义","detail":"指非上市银行首次执行日因采用预期信用损失法增提贷款损失准备导致的核心一级资本减少额，剔除递延所得税影响并扣减原准则下贷款损失准备缺口后的金额。"},{"point":"五年退坡加回比例","detail":"第一年和第二年按100%加回，第三年75%，第四年50%，第五年25%，即100%/100%/75%/50%/25%逐步退坡。"},{"point":"不得计入二级资本","detail":"已加回核心一级资本的贷款损失准备，不得纳入同期“超额贷款损失准备”计入二级资本。"},{"point":"不得扣减风险加权资产","detail":"该已加回准备不得在同期信用风险加权资产计算中用于扣减相应资产账面价值。"},{"point":"不计入杠杆率分母","detail":"已加回核心一级资本的贷款损失准备及其对应递延所得税资产，不得用于同期杠杆率计算的调整后表内外资产余额。"}],"framework":"调整基数 → 五年退坡比例 → 三项禁止用途（二级资本/加权资产/杠杆率）。","memo":"加回比例100/100/75/50/25；加回额不得入二级资本、不扣加权资产。","tag":"新金融工具会计准则通知"}],"calc":[{"id":"c-22-01","difficulty":1,"stem":"企业2023年初购入某公司3年期债券，面值1000万元，票面年利率6%，每年末付息、到期还本；初始确认金额（含交易费用）为948.51万元，经测算实际利率为8%（与购入价格一致），该债券分类为以摊余成本计量。求第一年末该债券的摊余成本（万元）。","blanks":[{"label":"第一年末摊余成本（万元）","answer":964.39,"tolerance":0.5}],"steps":["第一步：期初摊余成本=初始确认金额=948.51万元。","第二步：第一年利息收入=期初摊余成本×实际利率=948.51×8%=75.8808万元（取75.88万元）。","第三步：第一年收到现金利息=面值×票面利率=1000×6%=60万元。","第四步：第一年末摊余成本=948.51+75.88−60=964.39万元。"],"formula_card":"摊余成本（期末）=期初摊余成本+实际利息−实收现金利息；实际利息=期初摊余成本×实际利率。","analysis":"以摊余成本计量时，每期按实际利率确认利息收入，现金利息与实际利息的差额调整摊余成本。期初948.51万元，第一年实际利息75.88万元，现金利息60万元，溢价（实际为折价，因价格低于面值）摊销使摊余成本上升，期末=948.51+75.88−60=964.39万元。验算二遍：948.51×0.08=75.8808≈75.88；948.51+75.8808−60=964.3908≈964.39，一致。","trap":"初始确认金额含交易费用，直接作为期初摊余成本；实际利息按摊余成本而非面值计提，切勿用面值×实际利率。","tag":"22号-金融工具确认和计量"},{"id":"c-37-01","difficulty":1,"stem":"企业发行可转换公司债券，发行收款（整体公允价值）5000万元。经评估，其中不含转股权、类似普通公司债券的金融负债成分公允价值为4750万元。求其中权益工具成分的公允价值（万元）。","blanks":[{"label":"权益工具成分公允价值（万元）","answer":250,"tolerance":0.5}],"steps":["第一步：确定复合金融工具整体公允价值=5000万元。","第二步：先确定金融负债成分公允价值=4750万元（含其中非权益性嵌入衍生工具）。","第三步：权益工具成分价值=整体公允价值−负债成分公允价值=5000−4750=250万元。"],"formula_card":"权益工具成分价值=复合金融工具公允价值−金融负债成分公允价值（负债成分先按公允价值确定）。","analysis":"复合金融工具拆分遵循“先负债后权益”原则：先确定负债成分公允价值，剩余部分归为权益。5000−4750=250万元。验算二遍：4750+250=5000，一致；负债成分给定，拆分结果唯一。","trap":"必须从整体公允价值中扣除负债成分，而非按面值或票面比例分摊；交易费用还需在负债与权益间按比例分摊，但本题仅问公允价值拆分。","tag":"37号-金融工具列报"},{"id":"c-22-02","difficulty":2,"stem":"沿用上题债券（面值1000万元，票面6%，实际利率8%，第一年末摊余成本964.39万元）。求第二年末摊余成本（万元）及第二年利息收入（万元）。","blanks":[{"label":"第二年末摊余成本（万元）","answer":981.54,"tolerance":0.5},{"label":"第二年利息收入（万元）","answer":77.15,"tolerance":0.5}],"steps":["第一步：第二年期初摊余成本=第一年末摊余成本=964.39万元。","第二步：第二年利息收入=964.39×8%=77.1512万元（取77.15万元）。","第三步：第二年收到现金利息=1000×6%=60万元。","第四步：第二年末摊余成本=964.39+77.15−60=981.54万元。"],"formula_card":"期末摊余成本=期初摊余成本+实际利息−现金利息；实际利息=期初摊余成本×实际利率。","analysis":"在上年末摊余成本基础上继续按实际利率法摊销。964.39×8%=77.1512≈77.15；期末=964.39+77.1512−60=981.5412≈981.54。验算二遍：步骤一至四重复计算，结果981.54与77.15一致；且摊余成本逐步向面值1000靠拢，趋势合理。","trap":"第二期期初摊余成本必须用第一年末的摊余成本（964.39），不能用面值或初始价格；保留两位小数后尾差不影响结果。","tag":"22号-金融工具确认和计量"},{"id":"c-notice-01","difficulty":2,"stem":"某非上市银行首次执行新金融工具准则的调整基数为100亿元。监管资本过渡安排规定：第一年、第二年按100%加回，第三年75%，第四年50%，第五年25%。求该行第三年与第五年可加回核心一级资本的金额（亿元）。","blanks":[{"label":"第三年加回金额（亿元）","answer":75,"tolerance":0.5},{"label":"第五年加回金额（亿元）","answer":25,"tolerance":0.5}],"steps":["第一步：确定调整基数=100亿元。","第二步：第三年加回比例=75%，加回金额=100×75%=75亿元。","第三步：第五年加回比例=25%，加回金额=100×25%=25亿元。"],"formula_card":"当年加回金额=调整基数×当年加回比例；比例序列为第1、2年100%，第3年75%，第4年50%，第5年25%。","analysis":"资本加回采用五年退坡安排。100×75%=75亿元，100×25%=25亿元。验算二遍：100×0.75=75，100×0.25=25，一致；前两年各100、第四年50，五年合计100+100+75+50+25=350亿元。","trap":"注意前两年均为100%而非递减；已加回的准备不得计入二级资本、不得扣减风险加权资产、不计入杠杆率分母。","tag":"新金融工具会计准则通知"},{"id":"c-25-01","difficulty":3,"stem":"某保险合同组在初始确认日，与履行保险合同直接相关的未来现金流量估计净流出800万元，货币时间价值及金融风险调整+50万元，非金融风险调整+30万元；初始确认时各项现金流量之和为现金净流入120万元，确认为合同服务边际（CSM）。求履约现金流量（万元）及保险合同负债初始计量金额（万元）。","blanks":[{"label":"履约现金流量（万元）","answer":880,"tolerance":0.5},{"label":"保险合同负债初始计量金额（万元）","answer":1000,"tolerance":0.5}],"steps":["第一步：履约现金流量=未来现金流量估计+货币时间价值及金融风险调整+非金融风险调整。","第二步：履约现金流量=800+50+30=880万元。","第三步：保险合同负债初始计量金额=履约现金流量+合同服务边际=880+120=1000万元。"],"formula_card":"履约现金流量=未来现金流量估计+货币时间价值及金融风险调整+非金融风险调整；保险合同负债（初始）=履约现金流量+CSM。","analysis":"履约现金流量由三项组成，不含企业自身不履约风险。880万元加现金净流入形成的CSM120万元，得负债1000万元。验算二遍：800+50+30=880；880+120=1000，一致。","trap":"履约现金流量估计不考虑企业自身不履约风险；初始现金净流入确认为CSM（净流出才作为首日亏损），注意正负方向。","tag":"修订25号-保险合同"},{"id":"c-25-02","difficulty":3,"stem":"某不具有直接参与分红特征的保险合同组，期初合同服务边际（CSM）账面价值200万元；当期新归入合同使CSM增加30万元；按适用利率5%对CSM计提利息=200×5%=10万元；与未来服务相关的履约现金流量估计变更使CSM减少25万元（增加负债）；汇兑差额使CSM增加5万元；当期CSM摊销（计入保险服务收入）40万元。求期末CSM账面价值（万元）。","blanks":[{"label":"期末合同服务边际账面价值（万元）","answer":180,"tolerance":0.5}],"steps":["第一步：期初CSM=200万元。","第二步：加当期归入合同影响+30万元，得230万元。","第三步：加CSM计提利息+10万元，得240万元。","第四步：减与未来服务相关的履约现金流量变动−25万元，得215万元。","第五步：加汇兑差额+5万元，得220万元。","第六步：减当期摊销−40万元，得期末CSM=180万元。"],"formula_card":"期末CSM=期初CSM+归入影响+计息+未来服务相关履约现金流量变动+汇兑差额−当期摊销（不具分红特征合同五项调整）。","analysis":"对不具直接参与分红特征合同组，CSM在期初余额基础上经五项调整。200+30+10−25+5−40=180万元。验算二遍：200+30=230；+10=240；−25=215；+5=220；−40=180，一致。","trap":"与未来服务相关的履约现金流量增加（负债增加）会减少CSM，与摊销同为减项；区分“未来服务相关”与“过去服务相关（已发生赔款）”变动，后者不调整CSM。","tag":"修订25号-保险合同"}]}],"challenge":{"qa":[{"id":"qa-chfm-01","difficulty":3,"title":"某上市制造企业报表分析、杜邦分解与可持续增长综合评估","stem":"蓝天科技为A股上市制造企业，主营工业自动化设备。近三年营业收入增速放缓，董事会要求财务部结合最新年报评估增长质量：公司本年营业收入6000万元，净利润420万元，总资产3000万元，股东权益1200万元，流动资产900万元，流动负债450万元，存货300万元，利息支出80万元，息税前利润500万元，利润留存率50%，且不增发新股。","parts":[{"q":"（1）计算流动比率、速动比率并评价短期偿债能力，说明为何速动比率更具可信度时还需关注应收账款质量。","answer_points":[{"point":"流动比率＝900÷450＝2.0","detail":"流动资产对流动负债覆盖两倍，表面上短期偿债能力较强，高于经验值1。"},{"point":"速动比率＝(900－300)÷450＝1.33","detail":"剔除存货后速动资产600万元仍能覆盖流动负债1.33倍，短期偿债压力不大。"},{"point":"速动资产主要为应收款项，其变现能力决定比率可信度","detail":"若应收账款账龄长、坏账比例高，账面速动比率会高估真实偿债能力，需结合账龄分析与坏账准备计提情况判断。"},{"point":"应补充现金流量比率交叉验证","detail":"以经营活动现金流量净额÷流动负债，用真金白银验证静态比率的可靠性，避免被应计项目误导。"}]},{"q":"（2）沿杜邦体系计算营业净利率、总资产周转次数、权益乘数与权益净利率，并指出ROE的三个驱动因素。","answer_points":[{"point":"营业净利率＝420÷6000＝7%","detail":"反映盈利能力，每百元收入净赚7元，是杜邦链条的第一驱动。"},{"point":"总资产周转次数＝6000÷3000＝2次，权益乘数＝3000÷1200＝2.5","detail":"周转次数反映资产运营效率；权益乘数衡量财务杠杆，2.5倍对应资产负债率60%。"},{"point":"权益净利率＝7%×2×2.5＝35%","detail":"也可用净利润÷股东权益＝420÷1200直接验证，两条路径结果一致。"},{"point":"三因素分别对应盈利、效率、杠杆","detail":"杜邦体系把ROE拆为营业净利率×总资产周转次数×权益乘数，便于定位ROE变动的具体来源。"}]},{"q":"（3）计算利息保障倍数，并说明计算时分母的口径要求。","answer_points":[{"point":"利息保障倍数＝500÷80＝6.25","detail":"息税前利润500万元是全部利息支出80万元的6.25倍，付息能力充裕。"},{"point":"分母为全部利息支出，含费用化与资本化利息","detail":"只计入财务费用中的费用化利息会低估债务负担，资本化利息同样需要企业用经营利润支付。"},{"point":"可辅以现金流量利息保障倍数","detail":"用经营活动现金流量净额替代息税前利润作分子，比权责发生制口径更可靠。"}]},{"q":"（4）在经营效率与财务政策不变、不增发新股的假设下计算可持续增长率，并说明若明年计划销售增长20%将产生什么融资后果。","answer_points":[{"point":"可持续增长率＝7%×2×2.5×50%＝17.5%","detail":"期初股东权益法：营业净利率×总资产周转次数×权益乘数×利润留存率，即不依赖外部股权融资时的稳态增速。"},{"point":"计划增速20%高于可持续增长率17.5%","detail":"超速增长将打破稳态，留存收益增量不足以支撑资产扩张。"},{"point":"缺口只能靠增加外部融资弥补","detail":"按外部融资额＝经营资产增加－经营负债增加－可动用金融资产－留存收益增加测算；或提高留存率、营业净利率、周转速度，否则需增发新股或追加负债，从而改变资本结构、推高财务风险。"}]}],"framework":"先算短期偿债比率评价流动性→再做杜邦三因素分解定位ROE来源→补充利息保障倍数评估付息安全→最后用可持续增长率判断20%的销售目标是否可持续并引出外部融资需求。","memo":"易错：速动资产应剔除存货；权益乘数用期末数口径（3000÷1200）；可持续增长率用源文件的期初股东权益法乘积式，勿与内含增长率混淆；利息保障倍数分母含资本化利息。"},{"id":"qa-chfm-02","difficulty":3,"title":"某重型装备公司扩产融资方案选择：杠杆测算与资本结构决策","stem":"恒力重工计划投资一条大型铸锻件生产线，需筹资8000万元。财务部提交两套方案：甲方案发行年利率8%的公司债券，乙方案按每股20元增发400万股普通股。公司现有长期债务5000万元（年利率8%），普通股1000万股，所得税税率25%。扩产后预计年销量80台，单价500万元，单位变动成本350万元，固定经营成本6000万元。","parts":[{"q":"（1）计算扩产后的息税前利润，并据此说明本量利分析与资本结构决策的衔接关系。","answer_points":[{"point":"EBIT＝80×(500－350)－6000＝6000（万元）","detail":"由基本损益方程式求得，单位边际贡献150万元、边际贡献总额12000万元，扣除固定经营成本后EBIT为6000万元。"},{"point":"EBIT是衔接两个章节的桥梁","detail":"本量利分析产出EBIT，而杠杆系数、每股收益无差别点、财务杠杆效应均以EBIT为起点，先定经营盈利再论融资结构。"},{"point":"经营决策先于融资决策","detail":"销量、价格、成本结构决定经营风险（DOL），融资方式决定财务风险（DFL），两者共同放大股东收益波动（DTL）。"}]},{"q":"（2）分别计算现有资本结构（不含新筹资）下的经营杠杆系数、财务杠杆系数与联合杠杆系数。","answer_points":[{"point":"DOL＝(EBIT＋F)÷EBIT＝12000÷6000＝2","detail":"固定经营成本6000万元的存在使销量变动1%引起EBIT同向变动2%，经营风险中等偏高。"},{"point":"DFL＝EBIT÷(EBIT－I)＝6000÷(6000－400)＝1.07","detail":"现有利息＝5000×8%＝400万元，固定融资成本使EBIT变动1%引起EPS变动约1.07%，财务杠杆温和。"},{"point":"DTL＝DOL×DFL＝2×1.07＝2.14","detail":"联合杠杆反映销量变动对每股收益的总放大倍数，是经营风险与财务风险的乘积效应。"}]},{"q":"（3）用每股收益无差别点法判断：预计EBIT为6000万元时应选择甲方案还是乙方案？","answer_points":[{"point":"建立EPS等式求解无差别点","detail":"甲方案：[(EBIT－400－640)×75%]÷1000；乙方案：[(EBIT－400)×75%]÷1400，令两式相等。"},{"point":"解得无差别点EBIT＝3040万元","detail":"1000×(EBIT－1040)＝1400×(EBIT－400)化简得400EBIT＝480000×10即EBIT＝3040万元，此时两方案EPS均为1.5元。"},{"point":"预计EBIT6000万元＞无差别点3040万元，选甲方案（债券）","detail":"EBIT高于无差别点时负债经营的EPS更高，债务的税盾与杠杆优势得以体现。"},{"point":"但应提示无差别点法的局限","detail":"该法只比较每股收益、未直接考虑风险差异；甲方案使年利息增至1040万元，DFL升至6000÷4960≈1.21，财务风险加大，需结合企业价值比较法与偿债指标综合判断。"}]},{"q":"（4）从资本结构理论角度（优序融资理论、权衡理论）评价两方案，说明董事会决策时还应考虑的因素。","answer_points":[{"point":"优序融资理论视角","detail":"信息不对称下企业融资应遵循内源→债务→股权的顺序，若公司留存收益充足，应优先内源融资；两方案中债务优先于股权，与理论顺序一致。"},{"point":"权衡理论视角","detail":"企业价值＝无负债价值＋利息抵税现值－财务困境成本现值；发行债券增加抵税收益但也推高负债率与困境成本，存在最优负债区间而非越多越好。"},{"point":"还应考虑的因素","detail":"包括经营现金流稳定性（决定偿债保障）、行业周期性与订单波动、现有资产负债率与再融资空间、控制权影响（增发稀释股权）、市场利率环境等。"},{"point":"结论表述","detail":"在EBIT高于无差别点、现金流稳定的前提下可选债券方案，但应监控杠杆水平避免滑入财务困境区间。"}]}],"framework":"先用本量利方程算出扩产后EBIT→以EBIT为基础算三级杠杆刻画风险→再用EPS无差别点法做融资方式取舍→最后上升至优序融资与权衡理论作规范性评价。","memo":"易错：DFL计算含优先股时公式为EBIT÷[EBIT－I－PD÷(1－T)]，本题无优先股；无差别点比较基准是EBIT而非销售额；高EBIT选债务方案的前提是经营差异率为正，且不要忽略风险因素直接下结论。"},{"id":"qa-chfm-03","difficulty":3,"title":"某食品企业本量利分析、经营安全评估与提价决策","stem":"味佳食品产销一种休闲卤制品，单价40元，单位变动成本24元，年固定成本160万元，预计年销量18万件。公司拟通过提价或促销提升利润，财务总监要求先摸清保本与安全状况，再做敏感分析与经营决策。所得税税率25%。","parts":[{"q":"（1）计算边际贡献率、保本销售量与保本销售额，并解释边际贡献与利润的关系。","answer_points":[{"point":"单位边际贡献＝40－24＝16元，边际贡献率＝16÷40＝40%","detail":"变动成本率＝24÷40＝60%，与边际贡献率互补为1，收入被分为自身耗费与贡献两部分。"},{"point":"保本量＝160÷16＝10万件，保本额＝160÷40%＝400万元","detail":"两条路径结果勾稽：10万件×40元＝400万元，此时息税前利润为零。"},{"point":"边际贡献先补固定成本、后形成利润","detail":"销量超过保本点后，每多卖一件的16元边际贡献全部转化为利润，因此利润＝安全边际量×单位边际贡献。"}]},{"q":"（2）计算预计利润、安全边际额、安全边际率与销售息税前利润率，并评价经营安全程度。","answer_points":[{"point":"预计EBIT＝18×16－160＝128万元","detail":"也可用安全边际法验证：安全边际额×边际贡献率＝320×40%＝128万元，两式恒等。"},{"point":"安全边际额＝(18－10)×40＝320万元，安全边际率＝8÷18≈44.44%","detail":"安全边际率＝1－盈亏临界点作业率＝1－10÷18，表示销量可下降44.44%仍不亏损，安全性较高。"},{"point":"销售息税前利润率＝安全边际率×边际贡献率＝44.44%×40%≈17.78%","detail":"该式把盈利水平拆为经营安全程度与单位贡献能力两个因素，等于128÷720直接验证一致。"}]},{"q":"（3）公司目标息税前利润为160万元，计算保利销售量；若所得税后目标利润为120万元，保利量又是多少？","answer_points":[{"point":"息税前口径保利量＝(160＋160)÷16＝20万件","detail":"保利量＝(固定成本＋目标EBIT)÷单位边际贡献，比保本量多10万件。"},{"point":"税后口径需先还原：120÷(1－25%)＝160万元","detail":"税后目标利润÷(1－所得税税率)换算为息税前目标利润，再代入同一公式，结果仍为20万件。"},{"point":"口径差异是常见丢分点","detail":"题目给税后利润时必须先做纳税调整，否则保利量会被低估25%。"}]},{"q":"（4）计算单价、销量各自的敏感系数；若市场部提出提价5%将使销量下降10%，该方案是否可行？","answer_points":[{"point":"单价敏感系数＝40×18÷128＝5.625","detail":"单价变动1%，利润同向变动5.625%，是四因素中最敏感的，因为它同时作用于收入与边际贡献。"},{"point":"销量敏感系数＝(40－24)×18÷128＝2.25","detail":"销量变动1%，利润同向变动2.25%；固定成本与单位变动成本敏感系数分别为－1.25、－3，负号表示反向影响。"},{"point":"提价方案测算：新EBIT＝18×0.9×(42－24)－160＝131.6万元","detail":"提价后单位边际贡献＝42－24＝18元，销量16.2万件，边际贡献291.6万元，利润较128万元增加3.6万元。"},{"point":"方案可行但幅度有限","detail":"利润仅增约2.8%，因提价收益部分被销量下滑抵消；提价前还需评估价格弹性、竞争者反应与客户流失的长期影响，敏感系数高意味着单价管理必须谨慎。"}]}],"framework":"先算边际贡献与保本点界定盈亏分界→再用安全边际体系评估经营安全→按息税前与税后两种口径做保利分析→最后用敏感系数排序识别关键变量，并以提价方案做增量验证。","memo":"易错：保本额用边际贡献率作分母；税后目标利润必须÷(1－税率)还原；敏感系数是利润变动百分比÷参数变动百分比，单价敏感系数绝对值最大；利润＝安全边际额×边际贡献率而非×单价。"},{"id":"qa-chfm-04","difficulty":3,"title":"某连锁零售企业营运资本管理：现金、信用政策与存货综合诊断","stem":"惠民商贸为区域性连锁零售企业，门店扩张后流动资金趋紧：现金收支波动难以预测，赊销比重上升且回款变慢，门店存货占用偏高。财务部拟对现金持有、信用政策与存货采购三项做系统诊断。公司资本成本10%，一年按360天计算，变动成本率70%。","parts":[{"q":"（1）公司现金需求难以预知，应选择成本分析模式还是随机模式？简述随机模式下控制线的含义。","answer_points":[{"point":"应选随机模式","detail":"成本分析模式适用于现金流出量稳定可测的情形；零售企业日现金流波动大、难以预知，随机模式据此设置控制区间更合适。"},{"point":"随机模式设定回归线R、下限L与上限H","detail":"H＝3R－2L；现金余额达到上限时买入有价证券回落至R，跌至下限时卖出证券补足至R。"},{"point":"参数含义","detail":"R＝∛(3bσ²/4i)＋L，b为每次有价证券固定转换成本，σ为日现金余额波动标准差，i为日利率；波动越大、转换成本越高，控制区间越宽。"}]},{"q":"（2）公司现按1/10、n/30向客户提供现金折扣条件，多数客户放弃折扣。计算放弃现金折扣的成本，并说明其决策含义。","answer_points":[{"point":"放弃折扣成本＝1%÷(1－1%)×360÷(30－10)≈18.18%","detail":"客户放弃折扣相当于以18.18%的隐含年利率占用卖方资金20天。"},{"point":"对客户而言：只要资金成本低于18.18%就应享受折扣","detail":"若客户能以低于该成本的利率取得借款，付款享受折扣更划算；反之放弃折扣、拖延至第30天付款。"},{"point":"对惠民自身而言：成本即收益","detail":"作为卖方，该隐含利率是其提供商业信用获得的报酬；若客户普遍放弃折扣，说明公司赊销资金被无偿占用，应检讨信用条件是否过于宽松或收账不力。"}]},{"q":"（3）公司拟将信用期由30天延长至60天以刺激销售：年赊销额由720万元增至1080万元，收账费用增加5万元，坏账损失率由1%升至2%。从增量角度评价是否应延长信用期。","answer_points":[{"point":"收益端：增加边际贡献(1080－720)×30%＝108万元","detail":"变动成本率70%，故边际贡献率为30%，新增销售直接带来边际贡献增量。"},{"point":"成本端：应收账款应计利息增加8.4万元","detail":"原占用＝720÷360×30×70%×10%＝4.2万元；新占用＝1080÷360×60×70%×10%＝12.6万元；增加12.6－4.2＝8.4万元，注意应用变动成本率折算占用资金。"},{"point":"坏账与收账费用增量19.4万元","detail":"坏账增加＝1080×2%－720×1%＝21.6－7.2＝14.4万元，加上收账费用5万元，合计19.4万元。"},{"point":"净增量＝108－8.4－19.4＝80.2万元＞0，应延长信用期","detail":"扩大销售的边际收益显著超过资金占用、坏账与收账的边际成本；但需持续监控客户结构与账龄，防止坏账率继续攀升。"}]},{"q":"（4）针对门店存货占用偏高，说明经济订货量模型的适用前提，并指出保险储备与再订货点如何配合使用。","answer_points":[{"point":"EOQ基本模型的前提","detail":"需求量稳定可测、能集中到货（非陆续入库）、无缺货、单价与订货提前期固定且资金充裕；Q*＝√(2KD/Kc)。"},{"point":"按EOQ订货可平衡订货成本与储存成本","detail":"订货批次增加抬高订货变动成本，批量加大抬高储存成本，经济订货量使二者之和最低，直接压缩存货占用资金。"},{"point":"再订货点解决订早订晚问题","detail":"R＝平均交货时间×平均日需求＋保险储备，存货降至R即发单补货，保证交货期内不断货。"},{"point":"保险储备防需求波动，但本身有代价","detail":"保险储备总成本＝单位缺货成本×一次订货期望缺货量×年订货次数＋保险储备量×单位储存成本；应选取使缺货损失与储备成本之和最小的B值，避免盲目加大库存。"}]}],"framework":"按'现金—应收—存货'三大流动资产主线逐一诊断：先按现金波动特征选随机模式→再算放弃折扣成本评估商业信用→用增量收益法决策信用期变更→最后以EOQ、再订货点与保险储备优化存货，全案体现风险与收益的权衡。","memo":"易错：应收账款应计利息要用变动成本率折算占用资金；信用期延长决策比较的是增量收益与增量成本而非总额；随机模式的H＝3R－2L；EOQ基本模型不适用陆续供货与允许缺货情形（需用扩展模型）。"},{"id":"qa-chfm-05","difficulty":3,"title":"某国有装备集团业绩评价体系重构：责任中心、剩余收益与EVA","stem":"华正装备集团为国有独资企业，下设两个投资中心：甲中心经营稳健，乙中心规模扩张较快但盈利平平。集团拟引入EVA考核替代单纯的利润考核，并对乙中心拟上新项目做投资评价。要求结合责任会计与业绩评价框架给出分析与建议。按国资委简化EVA口径，商业类充分竞争企业股权资本成本率6.5%，所得税税率25%。","parts":[{"q":"（1）集团内的甲、乙投资中心与各生产车间分别属于何种责任中心？各类责任中心的考核指标应如何选择？","answer_points":[{"point":"投资中心：甲、乙中心","detail":"既有收入成本控制权又有投资决策权，是最高层次的责任中心，应考核部门投资报酬率（ROI）、剩余收益等综合性指标。"},{"point":"利润中心：销售分公司、有独立收支的事业部","detail":"考核部门可控边际贡献评价经理业绩，用部门税前经营利润评价部门对公司利润的贡献。"},{"point":"成本中心：各生产车间","detail":"只对可控成本负责，考核可控成本差异；不可控成本不应纳入其考核，防止责任转嫁。"},{"point":"指标层次要与权责匹配","detail":"考核指标必须落在被考核者可控行为范围内，'可控性原则'是责任中心划分与指标选择的第一标准。"}]},{"q":"（2）为什么单纯用部门投资报酬率（ROI）考核乙中心经理可能诱发次优化决策？剩余收益指标如何改进？其自身有何局限？","answer_points":[{"point":"ROI诱发次优化的机理","detail":"ROI＝部门税前经营利润÷部门平均净经营资产；当某项目报酬率高于公司要求报酬率但低于部门现有ROI时，经理为保住个人ROI排名会放弃该项目，损害公司整体价值。"},{"point":"乙中心ROI偏低，次优化风险尤其突出","detail":"扩张期中心资产基数大、利润未释放，ROI被摊薄，经理更倾向于拒绝对公司有利的新项目。"},{"point":"剩余收益＝部门税前经营利润－部门平均净经营资产×要求的税前投资报酬率","detail":"只要项目收益超过要求报酬率，剩余收益必然增加，经理接受项目与公司利益一致，可引导正确投资行为。"},{"point":"剩余收益的局限","detail":"它是绝对数指标，不便于不同规模部门之间比较；且要求报酬率需要按部门风险分别设定，带有主观性。"}]},{"q":"（3）按国资委简化EVA口径说明：哪些项目要作调整？为什么研发费用要加回、在建工程要剔除？","answer_points":[{"point":"税后净营业利润＝净利润＋(利息支出＋研究开发费用调整项)×(1－25%)","detail":"利息支出已在净利中扣除但属于资本成本，研发投入视为投资而非费用，两者税后加回归还经营利润。"},{"point":"调整后资本＝平均所有者权益＋平均带息负债－平均在建工程","detail":"在建工程尚未形成产能、不产生当期回报，从资本占用中剔除以免惩罚战略性投入。"},{"point":"研发费用加回的政策导向","detail":"鼓励企业加大创新投入，避免当期利润与资本占用双受压导致管理层削减研发、牺牲长期竞争力。"},{"point":"披露EVA的其他典型调整","detail":"还包括研发费用资本化摊销、战略投资利息资本化、品牌建设费用资本化及沉淀资金折旧法等，目的是还原真实经营业绩。"}]},{"q":"（4）与净利润、ROI相比，EVA考核有什么优点与不足？应如何与平衡计分卡结合构建完整的业绩评价体系？","answer_points":[{"point":"EVA的优点：考虑全部资本成本","detail":"EVA＝税后净营业利润－全部资本成本，真正反映股东财富增量；利润为正的企业EVA可能为负，它揭穿了'有利润不等于创造价值'的假象。"},{"point":"EVA的不足","detail":"绝对数指标不便于不同规模企业比较；成长期企业投入大、EVA偏低可能被误判；会计调整项目多、计算复杂。"},{"point":"与平衡计分卡互补","detail":"平衡计分卡从财务、客户、内部业务流程、学习与成长四维度设置因果链条的指标，弥补财务指标只看结果的缺陷。"},{"point":"体系构建建议","detail":"以EVA为财务维度核心结果指标，用客户满意度、流程效率、员工培训等动因类KPI驱动EVA改善；财务结果与非财务驱动因素结合，最终都挂钩到价值创造。"}]}],"framework":"先按权责范围划分责任中心并匹配考核指标→剖析ROI次优化缺陷并引入剩余收益→再按国资委口径梳理EVA的调整逻辑与政策导向→最后把EVA嵌入平衡计分卡四维度，形成'结果＋动因'的评价体系。","memo":"易错：剩余收益用税前口径（部门税前经营利润与要求的税前投资报酬率）；EVA分子中利息与研发调整要乘(1－25%)；在建工程从资本占用中减去而非加进；平衡计分卡四维度不含'供应商'。"}],"calc":[{"id":"c-chfm-01","difficulty":3,"title":"华源制造：财务比率—杜邦分解—可持续增长率全链条测算","stem":"华源制造公司2026年度报表显示：营业收入6000万元，净利润420万元，总资产3000万元，股东权益1200万元，本年利润留存率50%，计划不增发新股、不改变经营效率与财务政策。要求沿'比率→杜邦→可持续增长'链条完成下列计算。","parts":[{"q":"（1）计算营业净利率、总资产周转次数与权益乘数（期末口径）。","blanks":[{"label":"营业净利率（%）","answer":7,"tolerance":0.01},{"label":"总资产周转次数（次）","answer":2,"tolerance":0.01},{"label":"权益乘数","answer":2.5,"tolerance":0.01}],"steps":["第1步：营业净利率＝净利润÷营业收入×100%＝420÷6000×100%＝7.00%。","第2步：总资产周转次数＝营业收入÷总资产＝6000÷3000＝2.00（次）。","第3步：权益乘数＝总资产÷股东权益＝3000÷1200＝2.50。"],"formula_card":"营业净利率＝净利润÷营业收入×100%；总资产周转次数＝营业收入÷总资产；权益乘数＝总资产÷股东权益"},{"q":"（2）用杜邦体系计算权益净利率。","blanks":[{"label":"权益净利率（%）","answer":35,"tolerance":0.01}],"steps":["第1步：权益净利率＝营业净利率×总资产周转次数×权益乘数＝7%×2×2.5＝35.00%。","第2步：验证：净利润÷股东权益＝420÷1200＝35.00%，两法一致。"],"formula_card":"权益净利率＝营业净利率×总资产周转次数×权益乘数"},{"q":"（3）计算可持续增长率，并说明其经济含义。","blanks":[{"label":"可持续增长率（%）","answer":17.5,"tolerance":0.01}],"steps":["第1步：可持续增长率＝营业净利率×总资产周转次数×权益乘数×利润留存率（期初股东权益法）＝7%×2×2.5×50%＝17.50%。","第2步：含义：在经营效率与财务政策不变、不增发新股条件下，销售每年最高可持续增长17.5%。"],"formula_card":"可持续增长率（期初股东权益法）＝营业净利率×总资产周转次数×权益乘数×利润留存率"}],"analysis":"公司盈利能力7%、资产两年周转一次、杠杆2.5倍，三者相乘得ROE为35%；在留存率50%的财务政策下，可持续增长率为17.5%，即销售增速若超过该水平就必须追加外部融资或改变财务政策。","trap":"权益乘数用期末总资产÷期末股东权益，勿用资产负债率倒数之外的错误口径；可持续增长率是四个因素的乘积（期初股东权益法），勿漏乘留存率，也不要与内含增长率（外部融资为0）混为一谈。"},{"id":"c-chfm-02","difficulty":3,"title":"恒达公司：杠杆系数—EPS无差别点—资本结构决策","stem":"恒达公司拟追加筹资800万元扩大产能。现有资本结构：长期负债1000万元，年利率8%；普通股200万股。扩产后预计年边际贡献600万元，固定经营成本120万元，预计息税前利润480万元。所得税税率25%。追加筹资方案：甲方案按10%利率发行债券800万元；乙方案以每股20元增发40万股普通股。要求完成下列计算并作出决策。","parts":[{"q":"（1）计算现有资本结构下的经营杠杆系数、财务杠杆系数与联合杠杆系数。","blanks":[{"label":"经营杠杆系数DOL","answer":1.25,"tolerance":0.01},{"label":"财务杠杆系数DFL","answer":1.2,"tolerance":0.01},{"label":"联合杠杆系数DTL","answer":1.5,"tolerance":0.01}],"steps":["第1步：DOL＝(EBIT＋F)÷EBIT＝(480＋120)÷480＝600÷480＝1.25。","第2步：现有利息I＝1000×8%＝80万元；DFL＝EBIT÷(EBIT－I)＝480÷(480－80)＝1.20。","第3步：DTL＝DOL×DFL＝1.25×1.2＝1.50。"],"formula_card":"DOL＝(EBIT＋F)÷EBIT；DFL＝EBIT÷(EBIT－I)；DTL＝DOL×DFL"},{"q":"（2）计算甲、乙两方案的每股收益无差别点（EBIT）及无差别点时的每股收益。","blanks":[{"label":"每股收益无差别点EBIT（万元）","answer":560,"tolerance":0.1},{"label":"无差别点每股收益EPS（元/股）","answer":1.5,"tolerance":0.01}],"steps":["第1步：甲方案年利息＝80＋800×10%＝160万元；乙方案年利息仍为80万元。","第2步：令EPS相等：(EBIT－160)×75%÷200＝(EBIT－80)×75%÷240。","第3步：解得240×(EBIT－160)＝200×(EBIT－80)，即40EBIT＝22400，EBIT＝560万元。","第4步：代入得EPS＝(560－160)×75%÷200＝300÷200＝1.50（元/股）。"],"formula_card":"EPS＝[(EBIT－I)×(1－T)]÷N；无差别点令两方案EPS相等求解EBIT"},{"q":"（3）预计EBIT为480万元时应选择哪个方案？并说明决策依据。","blanks":[{"label":"应选择的方案（填甲或乙）对应的无差别点与预计EBIT之差（万元）","answer":80,"tolerance":0.1}],"steps":["第1步：预计EBIT480万元＜无差别点560万元，应选择股权融资的乙方案。","第2步：验证：乙方案EPS＝(480－80)×75%÷240＝300÷240＝1.25元；甲方案EPS＝(480－160)×75%÷200＝240÷200＝1.20元，乙方案更高。","第3步：差值＝560－480＝80万元，即预计EBIT低于无差别点80万元。"],"formula_card":"预计EBIT＜无差别点时选股权方案；预计EBIT＞无差别点时选债务方案"}],"analysis":"公司现有三级杠杆为1.25、1.2、1.5，经营与财务风险均属温和；由于预计EBIT480万元低于无差别点560万元，发行债券会摊薄每股收益（1.20元＜1.25元），应选乙方案增发股票，待盈利跨越无差别点后再考虑利用债务的税盾优势。","trap":"无差别点计算中甲方案利息为160万元（原80万＋新增80万），勿漏加；两方案股数分别为200万股与240万股；EBIT低于无差别点时应选股权融资，方向判断不能反；DTL是乘积关系不是加总。"},{"id":"c-chfm-03","difficulty":3,"title":"蓝天文具：本量利—保本点—目标利润—敏感性分析","stem":"蓝天文具公司产销一种中性笔，单价50元，单位变动成本30元，年固定成本240000元，预计年销量18000件。公司董事会下达目标息税前利润180000元。要求完成下列计算（结果保留两位小数，金额精确到元）。","parts":[{"q":"（1）计算保本销售量与保本销售额、安全边际率。","blanks":[{"label":"保本销售量（件）","answer":12000,"tolerance":0.01},{"label":"保本销售额（元）","answer":600000,"tolerance":0.1},{"label":"安全边际率（%）","answer":33.33,"tolerance":0.01}],"steps":["第1步：单位边际贡献＝50－30＝20（元/件），边际贡献率＝20÷50＝40%。","第2步：保本量＝固定成本÷单位边际贡献＝240000÷20＝12000（件）。","第3步：保本额＝240000÷40%＝600000（元），即12000×50，两法一致。","第4步：安全边际率＝(18000－12000)÷18000×100%≈33.33%。"],"formula_card":"保本量＝固定成本÷单位边际贡献；保本额＝固定成本÷边际贡献率；安全边际率＝（预计销量－保本量）÷预计销量×100%"},{"q":"（2）计算预计息税前利润；为实现目标息税前利润180000元，保利销售量应为多少件？","blanks":[{"label":"预计息税前利润（元）","answer":120000,"tolerance":0.1},{"label":"保利销售量（件）","answer":21000,"tolerance":0.01}],"steps":["第1步：预计EBIT＝18000×(50－30)－240000＝360000－240000＝120000（元）。","第2步：保利量＝(固定成本＋目标EBIT)÷单位边际贡献＝(240000＋180000)÷20＝21000（件）。","第3步：验证：21000×20－240000＝180000元，达到目标。"],"formula_card":"EBIT＝销量×单位边际贡献－固定成本；保利量＝（固定成本＋目标利润）÷单位边际贡献"},{"q":"（3）计算单价与销量的敏感系数，并求公司能忍受的单价最小值。","blanks":[{"label":"单价敏感系数","answer":7.5,"tolerance":0.01},{"label":"销量敏感系数","answer":3,"tolerance":0.01},{"label":"单价最小值（元/件）","answer":43.33,"tolerance":0.01}],"steps":["第1步：单价敏感系数＝基期收入÷基期EBIT＝50×18000÷120000＝7.5，即单价每变动1%利润同向变动7.5%。","第2步：销量敏感系数＝边际贡献÷EBIT＝360000÷120000＝3，即销量每变动1%利润同向变动3%。","第3步：单价最小值＝单位变动成本＋固定成本÷销量＝30＋240000÷18000≈30＋13.33＝43.33（元/件），此时利润恰好为零。"],"formula_card":"敏感系数＝目标值变动百分比÷参数值变动百分比；单价最小值＝单位变动成本＋固定成本÷销量"}],"analysis":"公司保本量12000件、保本额60万元，安全边际率33.33%，经营较安全；预计EBIT12万元，实现18万元目标需销量达21000件；单价敏感系数7.5、销量敏感系数3，单价是最敏感变量，价格管理稍有失误利润即大幅波动，价格底线为43.33元/件。","trap":"保利量与保本量的分母都是单位边际贡献；单价敏感系数用'收入÷EBIT'、销量敏感系数用'边际贡献÷EBIT'直接求，不必逐次试算；单价最小值是使利润为零的临界价，等于单位变动成本加固定成本分摊额。"},{"id":"c-chfm-04","difficulty":3,"title":"华信公司：经济订货量—最佳现金持有量—信用政策增量分析","stem":"华信公司经营某标准件产品，一年按360天计算，资本成本10%。资料如下：①存货：年需求量45000件，每次订货变动成本1000元，单位储存变动成本10元/件，单价100元；②现金：全年现金需求量500000元，每次有价证券转换成本1000元；③信用政策：现行信用期30天，年赊销额720万元，变动成本率70%，收账费用30万元，坏账损失率1%。拟将信用期延长至60天，预计年赊销额增至1080万元，收账费用35万元，坏账损失率2%。要求完成下列计算。","parts":[{"q":"（1）计算存货的经济订货量、最佳订货次数与经济订货量占用资金。","blanks":[{"label":"经济订货量Q*（件）","answer":3000,"tolerance":0.01},{"label":"最佳订货次数（次）","answer":15,"tolerance":0.01},{"label":"经济订货量占用资金（元）","answer":150000,"tolerance":0.1}],"steps":["第1步：Q*＝√(2KD/Kc)＝√(2×1000×45000÷10)＝√9000000＝3000（件）。","第2步：最佳订货次数N*＝D÷Q*＝45000÷3000＝15（次）。","第3步：占用资金I*＝(Q*÷2)×U＝1500×100＝150000（元）。"],"formula_card":"Q*＝√(2KD/Kc)；N*＝D/Q*；I*＝(Q*/2)×U"},{"q":"（2）用成本分析模式（存货模式）计算最佳现金持有量。","blanks":[{"label":"最佳现金持有量（元）","answer":100000,"tolerance":0.1}],"steps":["第1步：C*＝√(2TF/K)＝√(2×500000×1000÷0.10)＝√10000000000＝100000（元）。","第2步：验证：机会成本＝(C*÷2)×K＝50000×10%＝5000元，交易成本＝(T÷C*)×F＝5×1000＝5000元，两者相等，确认C*为最优；全年需转换次数＝500000÷100000＝5次。"],"formula_card":"最佳现金持有量C*＝√(2TF/K)，T为现金总需求量，F为每次交易成本，K为机会成本率"},{"q":"（3）计算信用期由30天延长至60天的增量净收益，并判断是否应变更信用政策。","blanks":[{"label":"应收账款应计利息增加额（万元）","answer":8.4,"tolerance":0.01},{"label":"信用政策变更的增量净收益（万元）","answer":80.2,"tolerance":0.1}],"steps":["第1步：增加边际贡献＝(1080－720)×(1－70%)＝360×30%＝108（万元）。","第2步：原应计利息＝720÷360×30×70%×10%＝4.2（万元）；新应计利息＝1080÷360×60×70%×10%＝12.6（万元）；增加12.6－4.2＝8.4（万元）。","第3步：坏账损失增加＝1080×2%－720×1%＝21.6－7.2＝14.4（万元）；收账费用增加＝35－30＝5（万元）。","第4步：增量净收益＝108－8.4－14.4－5＝80.2（万元）＞0，应延长信用期。"],"formula_card":"应收账款应计利息＝日销售额×收现期×变动成本率×资本成本；增量净收益＝增加边际贡献－增加应计利息－增加坏账损失－增加收账费用"}],"analysis":"存货方面经济订货量3000件、年订货15次、平均占用资金15万元，实现订货与储存成本平衡；现金方面最佳持有量10万元；信用政策方面延长信用期净增收益80.2万元，边际收益远超资金占用、坏账与收账的增量成本，三管齐下可显著优化营运资本配置。","trap":"应收账款应计利息必须乘变动成本率70%折算占用资金，直接用全额销售额是经典错误；EOQ根号内是2KD÷Kc；信用期决策比较增量而非新旧总额；占用资金用(Q*/2)×U而非Q*×U。"},{"id":"c-chfm-05","difficulty":3,"title":"华正集团：投资中心ROI、剩余收益与集团EVA测算","stem":"华正集团下设甲、乙两个投资中心，2026年数据如下：甲中心部门税前经营利润480万元，部门平均净经营资产4000万元；乙中心部门税前经营利润540万元，部门平均净经营资产6000万元。集团要求的税前投资报酬率为10%。乙中心现拟新增一个项目：投资1000万元，预计年增加税前经营利润130万元。另按国资委简化EVA口径测算集团整体（商业类充分竞争企业）：集团净利润1500万元，利息支出560万元，研究开发费用调整项240万元，平均所有者权益7000万元，平均带息负债7000万元，平均在建工程1000万元，股权资本成本率6.5%，所得税税率25%。","parts":[{"q":"（1）计算甲、乙两中心的投资报酬率（ROI）与剩余收益。","blanks":[{"label":"甲中心ROI（%）","answer":12,"tolerance":0.01},{"label":"甲中心剩余收益（万元）","answer":80,"tolerance":0.1},{"label":"乙中心剩余收益（万元）","answer":-60,"tolerance":0.1}],"steps":["第1步：甲ROI＝480÷4000＝12%；乙ROI＝540÷6000＝9%。","第2步：甲剩余收益＝480－4000×10%＝80（万元）。","第3步：乙剩余收益＝540－6000×10%＝－60（万元）。"],"formula_card":"部门ROI＝部门税前经营利润÷部门平均净经营资产；部门剩余收益＝部门税前经营利润－部门平均净经营资产×要求的税前投资报酬率"},{"q":"（2）从剩余收益角度判断乙中心是否应接受新项目；该项目会使乙中心ROI上升还是下降？","blanks":[{"label":"新项目带来的剩余收益增加额（万元）","answer":30,"tolerance":0.1},{"label":"接受项目后乙中心ROI（%）","answer":9.57,"tolerance":0.01}],"steps":["第1步：项目剩余收益增量＝130－1000×10%＝30（万元）＞0，应接受。","第2步：接受后乙ROI＝(540＋130)÷(6000＋1000)＝670÷7000≈9.57%。","第3步：项目ROI13%高于要求报酬率10%但低于乙中心现有ROI9%？否——现有ROI为9%，项目ROI13%高于现有ROI，接受后ROI由9%升至9.57%。"],"formula_card":"项目剩余收益增量＝项目税前经营利润－投资额×要求报酬率；新ROI＝（原利润＋项目利润）÷（原资产＋投资额）"},{"q":"（3）按国资委简化EVA口径计算集团平均资本成本率、税后净营业利润与EVA。","blanks":[{"label":"平均资本成本率（%）","answer":6.25,"tolerance":0.01},{"label":"税后净营业利润（万元）","answer":2100,"tolerance":0.1},{"label":"经济增加值EVA（万元）","answer":1287.5,"tolerance":0.1}],"steps":["第1步：债权资本成本率＝利息支出总额÷平均带息负债＝560÷7000＝8%。","第2步：平均资本成本率＝8%×7000÷14000×(1－25%)＋6.5%×7000÷14000＝3%＋3.25%＝6.25%。","第3步：税后净营业利润＝1500＋(560＋240)×(1－25%)＝1500＋600＝2100（万元）。","第4步：调整后资本＝7000＋7000－1000＝13000（万元）；资本成本＝13000×6.25%＝812.5（万元）。","第5步：EVA＝2100－812.5＝1287.5（万元）。"],"formula_card":"税后净营业利润＝净利润＋（利息支出＋研发费用调整项）×(1－25%)；调整后资本＝平均所有者权益＋平均带息负债－平均在建工程；EVA＝税后净营业利润－调整后资本×平均资本成本率"}],"analysis":"甲中心ROI12%、剩余收益80万元均优于乙中心（ROI9%、剩余收益－60万元）；乙中心新项目ROI13%高于要求报酬率10%，剩余收益增加30万元，尽管会拉低其ROI排名仍应接受，体现剩余收益抑制次优化的价值；集团层面税后净营业利润2100万元、平均资本成本率6.25%，EVA为1287.5万元，为正说明集团在扣除全部资本成本后仍在创造价值。","trap":"剩余收益用税前口径计算，公式中不涉及所得税；EVA中利息与研发调整须乘(1－25%)，在建工程从资本占用中扣减；平均资本成本率中债权成本率要乘(1－25%)抵税而股权成本率不抵税；接受项目后ROI由9%升至9.57%而非下降，判断方向要基于数字而非直觉。"}]}}}};